{{- else }}
{{- $members = set $members $pm (append (get $members $pm | default list) $id) }}
{{- end }}
{{- end }}
{{- end }}
{{- range $pools }}
{{- if empty (get $members (.name)) }}
{{- fail (printf "config.matrix.pools: pool %q has no members" .name) }}
{{- end }}
{{- end }}
{{- end }}
    routing:
      router:
        use: matrix
        settings:
          matrix:
{{- with .evict_costs }}
            evict_costs:
{{- range $k, $v := . }}
              {{ $k }}: {{ $v }}
{{- end }}
{{- end }}
            sets:
{{- if eq $builder "gpu-budget" }}
              gpu_pool: ({{ $gpu | join " | " }})
{{- if $cpu }}
              cpu_pool: ({{ $cpu | join " & " }})
{{- end }}
{{- $refs := list }}
{{- range $i := until $budget }}
{{- $refs = append $refs "+gpu_pool" }}
{{- end }}
              all: {{ $refs | join " & " }}{{ if $cpu }} & +cpu_pool{{ end }}
{{- else }}
{{- range $pools }}
{{- $pn := .name }}
{{- $pbRaw := .budget | default 0 }}
{{- if not (or (kindIs "float64" $pbRaw) (kindIs "int" $pbRaw)) }}
{{- fail (printf "config.matrix.pools: pool %q budget must be a number, got %s" $pn (kindOf $pbRaw)) }}
{{- end }}
{{- $pb := int $pbRaw }}
{{- if or (lt (float64 $pbRaw) 0.0) (ne (float64 $pbRaw) (float64 $pb)) }}
{{- fail (printf "config.matrix.pools: pool %q budget must be a non-negative integer, got %v" $pn $pbRaw) }}
{{- end }}
{{- $ids := get $members $pn }}
{{- if gt $pb 0 }}
              {{ $pn }}: ({{ $ids | join " | " }})
{{- else }}
              {{ $pn }}: ({{ $ids | join " & " }})
{{- end }}
{{- end }}
{{- $refs := list }}
{{- range $pools }}
{{- $pn := .name }}
{{- $pb := int (.budget | default 0) }}
{{- if gt $pb 0 }}
{{- range $i := until $pb }}
{{- $refs = append $refs (printf "+%s" $pn) }}
{{- end }}
{{- else }}
{{- $refs = append $refs (printf "+%s" $pn) }}
{{- end }}
{{- end }}
              all: {{ $refs | join " & " }}
{{- end }}
{{- range $exclusive }}
{{- /* Exclusive models run alone: their own single-member set, and they
      are left out of the generated pools above so they never count
      against a budget. */}}
              alone-{{ . }}: {{ . }}
{{- end }}
{{- end }}
{{- end }}
    models:
{{- range $m := .Values.config.models }}
{{- /* The id is required: it names the config key, the --model argument
      and the cmdStop default. Validate once and fail rendering instead of
      emitting an empty key or a missing --model value. */}}
{{- $id := index $m "id" }}
{{- if not $id }}
{{- fail (printf "config.models: an entry is missing a non-empty id: %v" $m) }}
{{- end }}
{{- /* merged = defaults with the model entry on top; a key present on
      the model wins, including an empty list (e.g. gpu: [] for a
      CPU-only model). Kube keys are consumed by the chart, every other
      merged key renders as a bornite model field. */}}
{{- $merged := mergeOverwrite (deepCopy $defaults) $m }}
{{- $kubeKeys := list "id" "image" "command" "gpu" "volumes" "port" "extraKubeArgs" "startupTimeout" "healthPath" "livenessPath" "checkPath" "args" "proxy" "cmdStop" "pool" }}
      {{ $id | quote }}:
{{- with index $merged "proxy" | default "http://127.0.0.1:${PORT}" }}
        proxy: {{ if kindIs "string" . }}{{ tpl . $ | quote }}{{ else }}{{ tpl (toYaml .) $ | nindent 12 }}{{ end }}
{{- end }}
        cmd: >-
          kubeswap serve
          --listen 127.0.0.1:${PORT}
          --model '{{ replace "'" "'\\''" $id }}'
          --namespace {{ $ns }}
          --image {{ index $merged "image" }}
{{- with index $merged "command" }}
          --command {{ . }}
{{- end }}
{{- range index $merged "gpu" }}
          --gpu {{ . }}
{{- end }}
{{- range index $merged "volumes" }}
          --volume {{ . }}
{{- end }}
{{- with index $merged "port" }}
          --port {{ . }}
{{- end }}
{{- with index $merged "startupTimeout" }}
          --startup-timeout {{ . }}
{{- end }}
{{- with index $merged "healthPath" }}
          --health-path {{ . }}
{{- end }}
{{- with index $merged "livenessPath" }}
          --liveness-path {{ . }}
{{- end }}
{{- with index $merged "checkPath" }}
          --check-path {{ . }}
{{- end }}
{{- range index $merged "extraKubeArgs" }}
          {{ . }}
{{- end }}
          --
{{- with index $merged "args" }}
{{ . | indent 12 }}
{{- end }}
{{- with index $merged "cmdStop" | default (printf "kubeswap delete --model '%s' --namespace %s --wait 60s" (replace "'" "'\\''" $id) $ns) }}
        cmdStop: {{ . | quote }}
{{- end }}
{{- range $k, $v := $merged }}
{{- if not (has $k $kubeKeys) }}
{{- /* scalars render inline (block style would make YAML read ttl: 1800
      as the string "1800"); collections render as indented blocks */}}
{{- $kind := kindOf $v }}
{{- if or (eq $kind "string") (eq $kind "invalid") }}
        {{ $k }}: {{ tpl $v $ | quote }}
{{- else if or (eq $kind "slice") (eq $kind "map") }}
        {{ $k }}:
{{ trim (tpl (toYaml $v) $) | indent 12 }}
{{- else }}
        {{ $k }}: {{ trim (tpl (toYaml $v) $) }}
{{- end }}
{{- end }}
{{- end }}
{{- end }}
{{- else }}
{{- with .Values.config.inline }}
{{- tpl . $ | nindent 4 }}
{{- end }}
{{- end }}
{{- range $name, $content := .Values.config.extraFiles }}
  {{ $name }}: |
{{- tpl $content $ | nindent 4 }}
{{- end }}
{{- end }}

{{- /* replicas must be exactly 1 (float64: Helm 3.19 loads values as
      float64, and a numeric template function must see a matched kind);
      zero/negative/fractional would render an invalid or useless
      Deployment, and >1 would run two head-ends over one set of
      backends. */}}
{{- if ne (.Values.replicas | float64) 1.0 }}
{{- fail "replicas must be 1: never two head-ends per namespace (each one manages the whole namespace's backends)" }}
{{- end }}
apiVersion: apps/v1
kind: Deployment
metadata:
  name: {{ include "bornite.fullname" . }}
  namespace: {{ .Release.Namespace }}
  labels:
    {{- include "bornite.labels" . | nindent 4 }}
spec:
  replicas: {{ .Values.replicas }}
  strategy:
    type: {{ .Values.strategy.type }}
  selector:
    matchLabels:
      {{- include "bornite.selectorLabels" . | nindent 6 }}
  template:
    metadata:
      {{- /* Restart the head-end when the rendered config changes. The
            pod already hot-reloads via -watch-config, but a failed
            reload only logs a warning and keeps serving the old config;
            the annotation makes drift visible as a rollout. Skipped for
            config.existing — the chart cannot hash a ConfigMap it does
            not render. */}}
      {{- /* deepCopy: merge mutates its first argument, so without a
            copy the generated checksum would be injected into
            .Values.podAnnotations itself; mergeOverwrite then lets the
            generated checksum/config win over any user-supplied value
            (a stale user value would hide config drift) while leaving
            the original values untouched. */}}
      {{- $annotations := deepCopy (.Values.podAnnotations | default dict) }}
      {{- if not .Values.config.existing }}
      {{- $annotations = mergeOverwrite $annotations (dict "checksum/config" (include (print $.Template.BasePath "/configmap.yaml") . | sha256sum)) }}
      {{- end }}
      {{- with $annotations }}
      annotations:
        {{- toYaml . | nindent 8 }}
      {{- end }}
      labels:
        {{- include "bornite.selectorLabels" . | nindent 8 }}
        {{- with .Values.podLabels }}
        {{- toYaml . | nindent 8 }}
        {{- end }}
    spec:
      {{- with .Values.imagePullSecrets }}
      imagePullSecrets:
        {{- toYaml . | nindent 8 }}
      {{- end }}
      serviceAccountName: {{ include "bornite.serviceAccountName" . }}
      {{- with .Values.priorityClassName }}
      priorityClassName: {{ . }}
      {{- end }}
      {{- with .Values.podSecurityContext }}
      securityContext:
        {{- toYaml . | nindent 8 }}
      {{- end }}
      {{- if or .Values.gcInitContainer.enabled .Values.initContainers }}
      initContainers:
        {{- if .Values.gcInitContainer.enabled }}
        # One-shot gc per head-end start: deletes backend workloads whose
        # models are no longer in the config.
        - name: kubeswap-gc
          image: {{ include "bornite.image" . }}
          imagePullPolicy: {{ .Values.image.pullPolicy }}
          command:
            - /usr/local/bin/kubeswap
            - gc
            - --namespace
            - {{ .Release.Namespace }}
            - --config
            - /etc/bornite/config/config.yaml
          volumeMounts:
            - name: config
              mountPath: /etc/bornite/config
              readOnly: true
          {{- with .Values.gcInitContainer.securityContext }}
          securityContext:
            {{- toYaml . | nindent 12 }}
          {{- end }}
        {{- end }}
        {{- with .Values.initContainers }}
        {{- toYaml . | nindent 8 }}
        {{- end }}
      {{- end }}
      containers:
        - name: bornite
          image: {{ include "bornite.image" . }}
          imagePullPolicy: {{ .Values.image.pullPolicy }}
          {{- with .Values.securityContext }}
          securityContext:
            {{- toYaml . | nindent 12 }}
          {{- end }}
          command: ["/usr/local/bin/bornite"]
          args:
            - -config
            - /etc/bornite/config/config.yaml
            - -watch-config
          ports:
            - name: http
              containerPort: 8080
          readinessProbe:
            {{- toYaml .Values.readinessProbe | nindent 12 }}
          livenessProbe:
            {{- toYaml .Values.livenessProbe | nindent 12 }}
          {{- with .Values.envFrom }}
          envFrom:
            {{- toYaml . | nindent 12 }}
          {{- end }}
          {{- with .Values.env }}
          env:
            {{- toYaml . | nindent 12 }}
          {{- end }}
          {{- with .Values.resources }}
          resources:
            {{- toYaml . | nindent 12 }}
          {{- end }}
          volumeMounts:
            - name: config
              mountPath: /etc/bornite/config
              readOnly: true
            {{- with .Values.extraVolumeMounts }}
            {{- toYaml . | nindent 12 }}
            {{- end }}
        {{- with .Values.extraContainers }}
        {{- toYaml . | nindent 8 }}
        {{- end }}
      {{- with .Values.nodeSelector }}
      nodeSelector:
        {{- toYaml . | nindent 8 }}
      {{- end }}
      {{- with .Values.tolerations }}
      tolerations:
        {{- toYaml . | nindent 8 }}
      {{- end }}
      {{- with .Values.affinity }}
      affinity:
        {{- toYaml . | nindent 8 }}
      {{- end }}
      volumes:
        - name: config
          configMap:
            name: {{ include "bornite.configMapName" . }}
        {{- with .Values.extraVolumes }}
        {{- toYaml . | nindent 8 }}
        {{- end }}

{{- if .Values.gateway.enabled }}
{{- $fullname := include "bornite.fullname" . -}}
{{- $gwName := .Values.gateway.gateway.name -}}
{{- $parentRefs := .Values.gateway.route.parentRefs -}}
{{- if and (not $gwName) (not $parentRefs) }}
{{- fail "gateway: gateway.gateway.name and gateway.route.parentRefs are both empty. Set gateway.gateway.name (and gateway.gateway.className) to have the chart create a Gateway, or set gateway.route.parentRefs to attach the HTTPRoute to an existing Gateway" }}
{{- end }}
{{- if $gwName }}
{{- if not .Values.gateway.gateway.className }}
{{- fail "gateway: gateway.gateway.className is required when gateway.gateway.name is set (Gateway.spec.gatewayClassName is a required field)" }}
{{- end }}
apiVersion: gateway.networking.k8s.io/v1
kind: Gateway
metadata:
  name: {{ $gwName }}
  namespace: {{ .Release.Namespace }}
  labels:
    {{- include "bornite.labels" . | nindent 4 }}
spec:
  gatewayClassName: {{ .Values.gateway.gateway.className }}
  listeners:
    {{- toYaml .Values.gateway.gateway.listeners | nindent 4 }}
---
{{- end }}
{{- /* With a name, an empty parentRefs defaults to the Gateway rendered
      above; without one, parentRefs is guaranteed non-empty by the check
      at the top. */ -}}
{{- if not $parentRefs }}
{{- $parentRefs = list (dict "name" $gwName "namespace" .Release.Namespace) -}}
{{- end }}
apiVersion: gateway.networking.k8s.io/v1
kind: HTTPRoute
metadata:
  name: {{ .Values.gateway.route.name | default $fullname }}
  namespace: {{ .Release.Namespace }}
  labels:
    {{- include "bornite.labels" . | nindent 4 }}
spec:
  parentRefs:
    {{- toYaml $parentRefs | nindent 4 }}
  {{- with .Values.gateway.route.hostnames }}
  hostnames:
    {{- toYaml . | nindent 4 }}
  {{- end }}
  rules:
    - backendRefs:
        - name: {{ $fullname }}
          port: {{ .Values.service.port }}
{{- end }}

{{- if .Values.ingress.enabled }}
apiVersion: networking.k8s.io/v1
kind: Ingress
metadata:
  name: {{ include "bornite.fullname" . }}
  namespace: {{ .Release.Namespace }}
  labels:
    {{- include "bornite.labels" . | nindent 4 }}
  {{- with .Values.ingress.annotations }}
  annotations:
    {{- toYaml . | nindent 4 }}
  {{- end }}
spec:
  {{- with .Values.ingress.className }}
  ingressClassName: {{ . }}
  {{- end }}
  {{- with .Values.ingress.tls }}
  tls:
    {{- toYaml . | nindent 4 }}
  {{- end }}
  rules:
    {{- range .Values.ingress.hosts }}
    {{- if not .paths }}
    {{- fail (printf "ingress: host %s has no paths (add paths: [{path: /, pathType: Prefix}])" .host) }}
    {{- end }}
    {{- $host := .host }}
    - host: {{ .host | quote }}
      http:
        paths:
          {{- range .paths }}
          {{- if not .pathType }}
          {{- fail (printf "ingress: path %s on host %s has no pathType (required by networking.k8s.io/v1: Exact, Prefix or ImplementationSpecific)" .path $host) }}
          {{- end }}
          - path: {{ .path }}
            pathType: {{ .pathType }}
            backend:
              service:
                name: {{ include "bornite.fullname" $ }}
                port:
                  name: http
          {{- end }}
    {{- end }}
{{- end }}

{{- if .Values.rbac.create }}
apiVersion: rbac.authorization.k8s.io/v1
kind: Role
metadata:
  name: {{ include "bornite.fullname" . }}
  namespace: {{ .Release.Namespace }}
  labels:
    {{- include "bornite.labels" . | nindent 4 }}
rules:
  {{- toYaml .Values.rbac.rules | nindent 2 }}
---
apiVersion: rbac.authorization.k8s.io/v1
kind: RoleBinding
metadata:
  name: {{ include "bornite.fullname" . }}
  namespace: {{ .Release.Namespace }}
  labels:
    {{- include "bornite.labels" . | nindent 4 }}
roleRef:
  apiGroup: rbac.authorization.k8s.io
  kind: Role
  name: {{ include "bornite.fullname" . }}
subjects:
  - kind: ServiceAccount
    name: {{ include "bornite.serviceAccountName" . }}
    namespace: {{ .Release.Namespace }}
{{- end }}

apiVersion: v1
kind: Service
metadata:
  name: {{ include "bornite.fullname" . }}
  namespace: {{ .Release.Namespace }}
  labels:
    {{- include "bornite.labels" . | nindent 4 }}
  {{- with .Values.service.annotations }}
  annotations:
    {{- toYaml . | nindent 4 }}
  {{- end }}
spec:
  type: {{ .Values.service.type }}
  ports:
    - name: http
      port: {{ .Values.service.port }}
      targetPort: http
      protocol: TCP
  selector:
    {{- include "bornite.selectorLabels" . | nindent 4 }}
  {{- if eq .Values.service.type "LoadBalancer" }}
  {{- with .Values.service.loadBalancerIP }}
  loadBalancerIP: {{ . }}
  {{- end }}
  {{- with .Values.service.loadBalancerSourceRanges }}
  loadBalancerSourceRanges:
    {{- toYaml . | nindent 4 }}
  {{- end }}
  {{- end }}
  {{- with .Values.service.externalTrafficPolicy }}
  externalTrafficPolicy: {{ . }}
  {{- end }}

{{- if .Values.serviceAccount.create }}
apiVersion: v1
kind: ServiceAccount
metadata:
  name: {{ include "bornite.serviceAccountName" . }}
  namespace: {{ .Release.Namespace }}
  labels:
    {{- include "bornite.labels" . | nindent 4 }}
  {{- with .Values.serviceAccount.annotations }}
  annotations:
    {{- toYaml . | nindent 4 }}
  {{- end }}
{{- end }}

package main

import (
	"context"
	"errors"
	"net/http"
	"os"
	"strings"
	"testing"
	"time"

	appsv1 "k8s.io/api/apps/v1"
	corev1 "k8s.io/api/core/v1"
	apierrors "k8s.io/apimachinery/pkg/api/errors"
	metav1 "k8s.io/apimachinery/pkg/apis/meta/v1"
	"k8s.io/apimachinery/pkg/labels"
	"k8s.io/apimachinery/pkg/runtime"
	"k8s.io/apimachinery/pkg/runtime/schema"
	"k8s.io/apimachinery/pkg/types"
	"k8s.io/apimachinery/pkg/util/intstr"
	"k8s.io/client-go/kubernetes/fake"
	k8stesting "k8s.io/client-go/testing"
)

// newFakeClient Returns a fresh fake client-go clientset.
func newFakeClient() *fake.Clientset { return fake.NewClientset() }

// makeDep Creates the config's backend resources against the fake client via ensureResources.
func makeDep(cfg *serveConfig, client *fake.Clientset) (*serveConfig, error) {
	_, err := ensureResources(client, cfg)
	return cfg, err
}

// TestKubeswap_EnsureResourcesCreates Verifies a missing backend gets its Deployment and Service created.
func TestKubeswap_EnsureResourcesCreates(t *testing.T) {
	client := newFakeClient()
	cfg := testConfig()
	res, err := ensureResources(client, cfg)
	if err != nil {
		t.Fatalf("ensureResources: %v", err)
	}
	if res.Adopted {
		t.Error("fresh namespace should not be adopted")
	}
	created := map[string]bool{}
	for _, c := range res.Created {
		created[c] = true
	}
	for _, want := range []string{"pvc/bornite-models", "deployment/" + cfg.DepName, "service/" + cfg.SvcName} {
		if !created[want] {
			t.Errorf("expected %q to be created, got %v", want, res.Created)
		}
	}

	// Objects exist with the right labels.
	dep, err := client.AppsV1().Deployments("bornite").Get(context.Background(), cfg.DepName, metav1.GetOptions{})
	if err != nil {
		t.Fatalf("deployment: %v", err)
	}
	if dep.Labels[labelModel] != "author-model-tag" {
		t.Errorf("labels: %v", dep.Labels)
	}
	if _, err := client.CoreV1().Services("bornite").Get(context.Background(), cfg.SvcName, metav1.GetOptions{}); err != nil {
		t.Errorf("service: %v", err)
	}
	if _, err := client.CoreV1().PersistentVolumeClaims("bornite").Get(context.Background(), "bornite-models", metav1.GetOptions{}); err != nil {
		t.Errorf("pvc: %v", err)
	}
}

// TestKubeswap_EnsureResourcesAdopts Verifies an existing Deployment is adopted, not replaced.
func TestKubeswap_EnsureResourcesAdopts(t *testing.T) {
	client := newFakeClient()
	cfg := testConfig()
	if _, err := ensureResources(client, cfg); err != nil {
		t.Fatal(err)
	}
	// Second invocation adopts instead of failing on AlreadyExists.
	res, err := ensureResources(client, cfg)
	if err != nil {
		t.Fatalf("second ensureResources: %v", err)
	}
	if !res.Adopted {
		t.Error("second invocation should adopt")
	}
	if len(res.Created) != 0 {
		t.Errorf("second invocation should create nothing, got %v", res.Created)
	}
}

// TestKubeswap_EnsureResourcesStrictReplace Verifies --strict deletes and recreates a drifted Deployment.
func TestKubeswap_EnsureResourcesStrictReplace(t *testing.T) {
	client := newFakeClient()
	cfg := testConfig()
	if _, err := ensureResources(client, cfg); err != nil {
		t.Fatal(err)
	}

	// Simulate drift: someone changed the image.
	ctx := context.Background()
	dep, _ := client.AppsV1().Deployments("bornite").Get(ctx, cfg.DepName, metav1.GetOptions{})
	dep.Spec.Template.Spec.Containers[0].Image = "someone-else:latest"
	if _, err := client.AppsV1().Deployments("bornite").Update(ctx, dep, metav1.UpdateOptions{}); err != nil {
		t.Fatal(err)
	}

	// Non-strict: adopt as-is.
	res, err := ensureResources(client, cfg)
	if err != nil {
		t.Fatal(err)
	}
	if !res.Adopted {
		t.Error("non-strict should adopt drifted deployment")
	}

	// Strict: replace.
	cfg.Strict = true
	res, err = ensureResources(client, cfg)
	if err != nil {
		t.Fatal(err)
	}
	if res.Adopted {
		t.Error("strict should replace drifted deployment")
	}
	got, err := client.AppsV1().Deployments("bornite").Get(ctx, cfg.DepName, metav1.GetOptions{})
	if err != nil {
		t.Fatal(err)
	}
	if got.Spec.Template.Spec.Containers[0].Image != cfg.Image {
		t.Errorf("image after replace: %s", got.Spec.Template.Spec.Containers[0].Image)
	}
}

// TestKubeswap_EnsureResourcesUpdatesDriftedService Verifies a Service whose
// selector or ports drifted (a changed --port or --service-port) is updated
// in place, keeping its identity, while an unchanged Service is left alone.
func TestKubeswap_EnsureResourcesUpdatesDriftedService(t *testing.T) {
	client := newFakeClient()
	cfg := testConfig()
	if _, err := ensureResources(client, cfg); err != nil {
		t.Fatal(err)
	}

	ctx := context.Background()
	svc, err := client.CoreV1().Services(cfg.Namespace).Get(ctx, cfg.SvcName, metav1.GetOptions{})
	if err != nil {
		t.Fatal(err)
	}
	uid := svc.UID
	sameVersion := svc.ResourceVersion

	// Unchanged Service: no update (resourceVersion stays).
	if _, err := ensureResources(client, cfg); err != nil {
		t.Fatal(err)
	}
	svc, _ = client.CoreV1().Services(cfg.Namespace).Get(ctx, cfg.SvcName, metav1.GetOptions{})
	if svc.ResourceVersion != sameVersion {
		t.Error("unchanged service should not be updated")
	}

	// Simulate a changed --port: the old Service still points at the old
	// port/selector. ensureResources must adopt the desired spec.
	cfg.Port = 9090
	svc.Spec.Ports = []corev1.ServicePort{{Name: "http", Port: 8080, TargetPort: intstr.FromInt32(8080)}}
	if _, err := client.CoreV1().Services(cfg.Namespace).Update(ctx, svc, metav1.UpdateOptions{}); err != nil {
		t.Fatal(err)
	}

	res, err := ensureResources(client, cfg)
	if err != nil {
		t.Fatal(err)
	}
	if !res.Adopted || len(res.Created) != 0 {
		t.Errorf("drifted service should be updated in place, not recreated: %+v", res)
	}

	svc, _ = client.CoreV1().Services(cfg.Namespace).Get(ctx, cfg.SvcName, metav1.GetOptions{})
	if len(svc.Spec.Ports) != 1 || svc.Spec.Ports[0].Port != 9090 || svc.Spec.Ports[0].TargetPort.IntValue() != 9090 {
		t.Errorf("ports after update: %v", svc.Spec.Ports)
	}
	if svc.UID != uid {
		t.Error("update must keep the Service UID")
	}
	if svc.Annotations[annotationModelID] != cfg.Model {
		t.Errorf("annotations after update: %v", svc.Annotations)
	}
}

// TestKubeswap_EnsureResourcesAdoptsExistingPVC Verifies an existing PVC is adopted rather than recreated.
func TestKubeswap_EnsureResourcesAdoptsExistingPVC(t *testing.T) {
	client := newFakeClient()
	// Pre-create the PVC without kubeswap labels (user-managed shared cache).
	userPVC := &corev1.PersistentVolumeClaim{
		ObjectMeta: metav1.ObjectMeta{Name: "bornite-models", Namespace: "bornite"},
	}
	if _, err := client.CoreV1().PersistentVolumeClaims("bornite").Create(context.Background(), userPVC, metav1.CreateOptions{}); err != nil {
		t.Fatal(err)
	}
	cfg := testConfig()
	if _, err := ensureResources(client, cfg); err != nil {
