// TestKubeswap_GCCollectsStaleWorkloads Verifies gc collects the workloads of models no longer allowed.
func TestKubeswap_GCCollectsStaleWorkloads(t *testing.T) {
	client := newFakeClient()
	cfgA := testConfig()
	cfgA.Model = "model-a"
	cfgA.Sanitized = "model-a"
	cfgA.DepName, _ = deploymentName(cfgA.Model)
	cfgA.SvcName, _ = serviceName(cfgA.Model)
	cfgB := testConfig()
	cfgB.Model = "model-b"
	cfgB.Sanitized = "model-b"
	cfgB.DepName, _ = deploymentName(cfgB.Model)
	cfgB.SvcName, _ = serviceName(cfgB.Model)
	if _, err := ensureResources(client, cfgA); err != nil {
		t.Fatal(err)
	}
	if _, err := ensureResources(client, cfgB); err != nil {
		t.Fatal(err)
	}

	// model-b was removed from config: only model-a survives.
	allowed := map[string]bool{"model-a": true}
	ctx := context.Background()
	deleted, err := gcCollect(client, "bornite", allowed, false, false)
	if err != nil {
		t.Fatalf("gcCollect: %v", err)
	}
	if len(deleted) != 1 || deleted[0] != "model-b" {
		t.Errorf("deleted: %v", deleted)
	}
	if _, err := client.AppsV1().Deployments("bornite").Get(ctx, cfgA.DepName, metav1.GetOptions{}); err != nil {
		t.Errorf("model-a should survive: %v", err)
	}
	if _, err := client.AppsV1().Deployments("bornite").Get(ctx, cfgB.DepName, metav1.GetOptions{}); !apierrors.IsNotFound(err) {
		t.Errorf("model-b should be collected, err=%v", err)
	}
	if _, err := client.CoreV1().Services("bornite").Get(ctx, cfgB.SvcName, metav1.GetOptions{}); !apierrors.IsNotFound(err) {
		t.Errorf("model-b service should be collected, err=%v", err)
	}

	// A managed object without the model-id annotation cannot be matched
	// against the config (the allowed set holds original IDs) nor deleted
	// by name: gc must skip it, not claim it.
	stale, _ := cfgA.renderDeployment()
	stale.Name = "stale-no-annotation"
	stale.Annotations = map[string]string{}
	stale.Labels = map[string]string{labelManagedBy: managedByValue, labelModel: "stale"}
	if _, err := client.AppsV1().Deployments("bornite").Create(ctx, stale, metav1.CreateOptions{}); err != nil {
		t.Fatal(err)
	}
	deleted, err = gcCollect(client, "bornite", allowed, false, false)
	if err != nil {
		t.Fatalf("gcCollect (second pass): %v", err)
	}
	if len(deleted) != 0 {
		t.Errorf("second pass should collect nothing, got %v", deleted)
	}
	if _, err := client.AppsV1().Deployments("bornite").Get(ctx, "stale-no-annotation", metav1.GetOptions{}); err != nil {
		t.Errorf("unannotated deployment should be skipped, not deleted: %v", err)
	}
}

// TestKubeswap_FindPod Verifies pod lookup by the deployment's unique label.
func TestKubeswap_FindPod(t *testing.T) {
	client := newFakeClient()
	cfg := testConfig()
	s := newServer(cfg, client, "", true, time.Millisecond, 300*time.Second)
	ctx := context.Background()

	// No pods at all.
	dep, _ := cfg.renderDeployment()
	st := s.findPod(ctx, dep)
	if st.ready || st.pod != nil {
		t.Errorf("expected not ready with no pod, got %+v", st)
	}

	// Pending pod.
	pending := &corev1.Pod{
		ObjectMeta: metav1.ObjectMeta{
			Name: "p1", Namespace: "bornite",
			Labels: podLabels(cfg.Sanitized, cfg.DepName),
			UID:    types.UID("u1"),
		},
		Status: corev1.PodStatus{Phase: corev1.PodPending},
	}
	if _, err := client.CoreV1().Pods("bornite").Create(ctx, pending, metav1.CreateOptions{}); err != nil {
		t.Fatal(err)
	}
	st = s.findPod(ctx, dep)
	if st.ready {
		t.Error("pending pod should not be ready")
	}

	// Ready pod with an IP.
	ready := &corev1.Pod{
		ObjectMeta: metav1.ObjectMeta{
			Name: "p1", Namespace: "bornite",
			Labels: podLabels(cfg.Sanitized, cfg.DepName),
			UID:    types.UID("u1"),
		},
		Status: corev1.PodStatus{
			Phase: corev1.PodRunning,
			PodIP: "10.0.0.5",
			Conditions: []corev1.PodCondition{{
				Type:   corev1.PodReady,
				Status: corev1.ConditionTrue,
			}},
		},
	}
	if _, err := client.CoreV1().Pods("bornite").Update(ctx, ready, metav1.UpdateOptions{}); err != nil {
		t.Fatal(err)
	}
	st = s.findPod(ctx, dep)
	if !st.ready || st.pod == nil || st.pod.Status.PodIP != "10.0.0.5" {
		t.Errorf("expected ready pod with IP, got %+v", st)
	}
}

// TestKubeswap_PollOnceRequestsStopOnDeletion Verifies the poll loop stops the wrapper when its Deployment is deleted.
// TestKubeswap_PollOnceBoundedByContext verifies a failing API call
// (what a hung control plane produces once the per-call timeout fires)
// surfaces as a not-ready reason instead of stalling the poller. The
// fake client ignores context deadlines, so the failure is simulated
// with a reactor returning a server error on the deployment Get.
func TestKubeswap_PollOnceBoundedByContext(t *testing.T) {
	client := newFakeClient()
	cfg := testConfig()
	if _, err := ensureResources(client, cfg); err != nil {
		t.Fatal(err)
	}
	old := apiCallTimeout
	apiCallTimeout = 50 * time.Millisecond
	defer func() { apiCallTimeout = old }()
	client.PrependReactor("get", "deployments", func(action k8stesting.Action) (bool, runtime.Object, error) {
		return true, nil, apierrors.NewGenericServerResponse(
			http.StatusInternalServerError, "get", schema.GroupResource{Resource: "deployments"}, "", "boom", 0, false)
	})
	s := newServer(cfg, client, "", true, time.Millisecond, 300*time.Second)
	start := time.Now()
	s.pollOnce(context.Background())
	if time.Since(start) > 5*time.Second {
		t.Error("pollOnce should not block long on an API failure")
	}
	if s.ready.Load() {
		t.Fatal("expected not ready")
	}
	reason := s.readyReason.Load().(string)
	if !strings.Contains(reason, "error getting deployment") {
		t.Errorf("reason should report the API failure, got %q", reason)
	}
}

func TestKubeswap_PollOnceRequestsStopOnDeletion(t *testing.T) {
	client := newFakeClient()
	cfg := testConfig()
	if _, err := ensureResources(client, cfg); err != nil {
		t.Fatal(err)
	}
	s := newServer(cfg, client, "", true, time.Millisecond, 300*time.Second)
	ctx := context.Background()

	// Deployment exists: no stop requested, not-ready (no pod) reported.
	s.pollOnce(ctx)
	select {
	case <-s.stopCh:
		t.Fatal("stop requested while deployment exists")
	default:
	}
	if s.ready.Load() {
		t.Error("should not be ready without a pod")
	}
	if reason := s.readyReason.Load().(string); reason == "" {
		t.Error("expected a not-ready reason")
	}

	// Delete the deployment: serve must request a stop.
	if err := client.AppsV1().Deployments("bornite").Delete(ctx, cfg.DepName, metav1.DeleteOptions{}); err != nil {
		t.Fatal(err)
	}
	s.pollOnce(ctx)
	select {
	case <-s.stopCh:
	default:
		t.Fatal("stop not requested after deployment deletion")
	}
}

// TestKubeswap_PodReason verifies the status REASON column summarizes the
// common not-ready causes.
func TestKubeswap_PodReason(t *testing.T) {
	// Ready: no reason.
	ready := &corev1.Pod{}
	ready.Status.Conditions = []corev1.PodCondition{{Type: corev1.PodReady, Status: corev1.ConditionTrue}}
	if got := podReason(ready); got != "" {
		t.Errorf("ready pod: got %q, want empty", got)
	}

	// Unscheduled: the scheduler's verdict, e.g. no GPU capacity.
	pending := &corev1.Pod{}
	pending.Status.Phase = corev1.PodPending
	pending.Status.Conditions = []corev1.PodCondition{{
		Type: corev1.PodScheduled, Status: corev1.ConditionFalse,
		Message: "0/9 nodes are available: 9 Insufficient amd.com/gpu",
	}}
	if got := podReason(pending); !strings.Contains(got, "Insufficient amd.com/gpu") {
		t.Errorf("pending pod: got %q, want the scheduler message", got)
	}

	// CrashLoopBackOff: the container waiting state.
	crashed := &corev1.Pod{}
	crashed.Status.ContainerStatuses = []corev1.ContainerStatus{{
		State: corev1.ContainerState{Waiting: &corev1.ContainerStateWaiting{
			Reason: "CrashLoopBackOff", Message: "back-off 5m0s restarting failed container=server",
		}},
	}}
	if got := podReason(crashed); !strings.Contains(got, "CrashLoopBackOff") {
		t.Errorf("crashlooping pod: got %q, want CrashLoopBackOff", got)
	}

	// Just crashed: Terminated with a reason and exit code, reported
	// before the waiting state (which only appears once the backoff
	// starts) and before the starting fallback.
	justCrashed := &corev1.Pod{}
	justCrashed.Status.ContainerStatuses = []corev1.ContainerStatus{{
		State: corev1.ContainerState{Terminated: &corev1.ContainerStateTerminated{
			ExitCode: 1, Reason: "Error",
		}},
	}}
	if got := podReason(justCrashed); got != "Error (exit code 1)" {
		t.Errorf("terminated pod: got %q, want %q", got, "Error (exit code 1)")
	}
	oom := &corev1.Pod{}
	oom.Status.ContainerStatuses = []corev1.ContainerStatus{{
		State: corev1.ContainerState{Terminated: &corev1.ContainerStateTerminated{
			ExitCode: 137, Reason: "OOMKilled",
		}},
	}}
	if got := podReason(oom); got != "OOMKilled (exit code 137)" {
		t.Errorf("OOM-killed pod: got %q, want %q", got, "OOMKilled (exit code 137)")
	}

	// Running but not ready: probes still passing.
	starting := &corev1.Pod{}
	starting.Status.ContainerStatuses = []corev1.ContainerStatus{{
		State: corev1.ContainerState{Running: &corev1.ContainerStateRunning{}},
	}}
	if got := podReason(starting); got != "starting" {
		t.Errorf("running pod: got %q, want starting", got)
	}

	// Running but not ready, container started recently: still a normal
	// model load, not "stuck".
	loading := &corev1.Pod{}
	loading.Status.ContainerStatuses = []corev1.ContainerStatus{{
		State: corev1.ContainerState{Running: &corev1.ContainerStateRunning{
			StartedAt: metav1.NewTime(time.Now().Add(-time.Minute)),
		}},
	}}
	if got := podReason(loading); got != "starting" {
		t.Errorf("recently started running pod: got %q, want starting", got)
	}

	// Running but not ready for a long time: the probe cannot be passing
	// (the classic cause is a backend bound to loopback); say so. No
	// startup probe in the spec, so the fallback window applies.
	stuck := &corev1.Pod{}
	stuck.Status.ContainerStatuses = []corev1.ContainerStatus{{
		State: corev1.ContainerState{Running: &corev1.ContainerStateRunning{
			StartedAt: metav1.NewTime(time.Now().Add(-10 * time.Minute)),
		}},
	}}
	if got := podReason(stuck); !strings.Contains(got, "still not ready") {
		t.Errorf("long-running not-ready pod: got %q, want a stuck reason", got)
	}

	// Running beyond the generic window but INSIDE a configured startup
	// window (the spec's startup probe allows ten minutes): a slow model
	// load is still normal, not stuck.
	slowLoad := &corev1.Pod{}
	slowLoad.Spec.Containers = []corev1.Container{{
		Name: "server",
		StartupProbe: &corev1.Probe{
			PeriodSeconds:    5,
			FailureThreshold: 120, // 120 × 5s = 10m startup window
		},
	}}
	slowLoad.Status.ContainerStatuses = []corev1.ContainerStatus{{
		Name: "server",
		State: corev1.ContainerState{Running: &corev1.ContainerStateRunning{
			StartedAt: metav1.NewTime(time.Now().Add(-7 * time.Minute)),
		}},
	}}
	if got := podReason(slowLoad); got != "starting" {
		t.Errorf("slow load inside its startup window: got %q, want starting", got)
	}

	// ... and the same pod past the window is stuck again.
	slowLoad.Status.ContainerStatuses[0].State.Running.StartedAt = metav1.NewTime(time.Now().Add(-11 * time.Minute))
	if got := podReason(slowLoad); !strings.Contains(got, "still not ready") {
		t.Errorf("load past its startup window: got %q, want a stuck reason", got)
	}
}

// TestKubeswap_PodNotReadyReason verifies the wrapper's readiness reason
// describes a running container neutrally inside the startup window and
// only offers the loopback diagnosis once the window has elapsed.
func TestKubeswap_PodNotReadyReason(t *testing.T) {
	window := 10 * time.Minute

	pod := &corev1.Pod{}
	pod.Name = "smollm2-abc"
	pod.Status.Phase = corev1.PodRunning
	pod.Status.ContainerStatuses = []corev1.ContainerStatus{{
		Name: "server",
		State: corev1.ContainerState{Running: &corev1.ContainerStateRunning{
			StartedAt: metav1.NewTime(time.Now().Add(-time.Minute)),
		}},
	}}
	if got := podNotReadyReason(pod, window); strings.Contains(got, "probes not passing") {
		t.Errorf("running pod inside the startup window: got %q, want no stuck diagnosis", got)
	}

	// Past the window: the loopback diagnosis is the point of the hint.
	pod.Status.ContainerStatuses[0].State.Running.StartedAt = metav1.NewTime(time.Now().Add(-11 * time.Minute))
	got := podNotReadyReason(pod, window)
	if !strings.Contains(got, "server running but probes not passing") || !strings.Contains(got, "0.0.0.0") {
		t.Errorf("running pod past the startup window: got %q, want the probe/loopback hint", got)
	}
}

// TestKubeswap_RunLogs verifies log tailing: a model with no pod gets a
// clean error, a model with a pod streams, and a sibling model's pod
// (same sanitized label, different deployment) is out of reach.
func TestKubeswap_RunLogs(t *testing.T) {
	client := newFakeClient()
	cfg := testConfig()
	if _, err := ensureResources(client, cfg); err != nil {
		t.Fatal(err)
	}

	if err := runLogs(context.Background(), client, "bornite", cfg.Model, 10, false); err == nil || !strings.Contains(err.Error(), "no pod") {
		t.Fatalf("expected a no-pod error, got %v", err)
	}

	pod := &corev1.Pod{ObjectMeta: metav1.ObjectMeta{
		Name: "m1", Namespace: "bornite",
		Labels: podSelectorLabels(cfg.Sanitized, cfg.DepName),
	}}
	if _, err := client.CoreV1().Pods("bornite").Create(context.Background(), pod, metav1.CreateOptions{}); err != nil {
		t.Fatal(err)
	}
	if err := runLogs(context.Background(), client, "bornite", cfg.Model, 10, false); err != nil {
		t.Fatalf("runLogs with a pod: %v", err)
	}

	// A pod carrying only the coarse model label for a DIFFERENT deployment
	// must not be picked up.
	sibling := &corev1.Pod{ObjectMeta: metav1.ObjectMeta{
		Name: "m2", Namespace: "bornite",
		Labels: podSelectorLabels(cfg.Sanitized, "some-other-deployment"),
	}}
	if _, err := client.CoreV1().Pods("bornite").Create(context.Background(), sibling, metav1.CreateOptions{}); err != nil {
		t.Fatal(err)
	}
	found, err := findModelPod(context.Background(), client, "bornite", cfg.Sanitized, cfg.DepName)
	if err != nil || found == nil || found.Name != "m1" {
		t.Fatalf("findModelPod: got %v, err %v; want pod m1", found, err)
	}

	// A canceled context in follow mode is a normal stop (the Ctrl+C
	// path): it must not surface as an error.
	fctx, fcancel := context.WithCancel(context.Background())
	go func() {
		time.Sleep(20 * time.Millisecond)
		fcancel()
	}()
	if err := runLogs(fctx, client, "bornite", cfg.Model, 10, true); err != nil {
		t.Errorf("canceled follow should exit quietly, got %v", err)
	}
	fcancel()
}

