// TestKubeswap_StatusWatchSurvivesTransientError verifies the watch loop
// prints a tick error instead of dying: the second API call fails, the
// loop keeps going, and ctx cancellation stops it cleanly.
func TestKubeswap_StatusWatchSurvivesTransientError(t *testing.T) {
	client := newFakeClient()
	cfg := testConfig()
	if _, err := ensureResources(client, cfg); err != nil {
		t.Fatal(err)
	}
	calls := 0
	client.PrependReactor("list", "deployments", func(action k8stesting.Action) (bool, runtime.Object, error) {
		calls++
		if calls == 2 {
			return true, nil, errors.New("boom")
		}
		return false, nil, nil
	})
	ctx, cancel := context.WithCancel(context.Background())
	done := make(chan error, 1)
	go func() {
		done <- runStatusWithClient(ctx, client, "bornite", true, 10*time.Millisecond)
	}()
	time.Sleep(100 * time.Millisecond)
	cancel()
	select {
	case err := <-done:
		if err != nil {
			t.Fatalf("watch should survive the transient error and stop on ctx cancel, got %v", err)
		}
	case <-time.After(5 * time.Second):
		t.Fatal("watch did not stop on ctx cancel")
	}
	if calls < 2 {
		t.Errorf("expected at least 2 list calls, got %d", calls)
	}
}

// kubeswap is a cmd/cmdStop wrapper that lets bornite manage inference
// backends in a Kubernetes namespace the same way it manages docker backends:
// the model's cmd launches `kubeswap serve`, which creates (or adopts) a
// Deployment + Service for the model and proxies a local port to it; the
// model's cmdStop runs `kubeswap delete` to tear the objects down.
//
// Subcommands:
//
//	serve   long-running: lifecycle + local proxy (used as a model's cmd)
//	start   one-shot: ensure a model's backend resources exist (pre-warm)
//	delete  one-shot: delete a model's managed objects (used as cmdStop)
//	gc      one-shot: delete managed objects for models not in the config
//	status  one-shot: print the managed workloads
//	logs    one-shot: print (or --follow) a model's backend logs
package main

import (
	"errors"
	"flag"
	"fmt"
	"os"
	"runtime"
	"sort"
	"strconv"
	"strings"

	"k8s.io/apimachinery/pkg/api/resource"
	content "k8s.io/apimachinery/pkg/api/validate/content"
	kvalidation "k8s.io/apimachinery/pkg/util/validation"
)

const (
	defaultNamespace      = "bornite"
	containerName         = "server"
	defaultPort           = 8080
	defaultStartupTimeout = int64(600) // seconds of model loading the startup probe tolerates
)

// Set at build time via -ldflags (see the Makefile kubeswap target and
// docker/unified/install-kubeswap.sh).
var (
	version   = "dev"
	buildTime = ""
)

// printVersion Prints the kubeswap version (plus build time, when set) and exits.
func printVersion() {
	suffix := ""
	if buildTime != "" {
		suffix = ", built " + buildTime
	}
	fmt.Printf("kubeswap %s (go %s%s)\n", version, runtime.Version(), suffix)
}

// managed-object labels/annotations. Every object kubeswap creates carries
// these so `gc` and adoption can find them later.
const (
	labelManagedBy    = "bornite.io/managed-by"
	labelModel        = "bornite.io/model"
	labelDeployment   = "bornite.io/deployment"
	labelAppName      = "app.kubernetes.io/name"
	managedByValue    = "bornite"
	appNameValue      = "bornite-backend"
	annotationModelID = "bornite.io/model-id"
)

// main is the entry point: it parses the subcommand and its arguments and dispatches to serve, start, delete, gc, status, logs or version.
func main() {
	if len(os.Args) < 2 {
		usage(os.Stderr)
		os.Exit(2)
	}
	var err error
	switch os.Args[1] {
	case "serve":
		err = serveCmd(os.Args[2:])
	case "start":
		err = startCmd(os.Args[2:])
	case "delete":
		err = deleteCmd(os.Args[2:])
	case "gc":
		err = gcCmd(os.Args[2:])
	case "status":
		err = statusCmd(os.Args[2:])
	case "logs":
		err = logsCmd(os.Args[2:])
	case "version":
		printVersion()
		return
	case "help", "-h", "--help":
		usage(os.Stdout)
		return
	default:
		fmt.Fprintf(os.Stderr, "kubeswap: unknown command %q\n\n", os.Args[1])
		usage(os.Stderr)
		os.Exit(2)
	}
	if err != nil {
		fmt.Fprintf(os.Stderr, "kubeswap %s: %v\n", os.Args[1], err)
		var ee *exitError
		if errors.As(err, &ee) {
			os.Exit(ee.code)
		}
		os.Exit(1)
	}
}

// usage Writes the command-line usage text to w.
func usage(w *os.File) {
	fmt.Fprint(w, `kubeswap - manage bornite inference backends in a Kubernetes namespace

Usage:
  kubeswap serve [flags] -- <container args...>
  kubeswap start [flags] -- <container args...>
  kubeswap delete --model <id> [flags]
  kubeswap gc [flags]
  kubeswap status [flags]
  kubeswap logs --model <id> [flags]
  kubeswap version

Commands:
  serve    Start as a forward proxy for a model's backend (a model's cmd).
           Creates or adopts the model's Deployment + Service and proxies
           --listen to the backend pod until stopped. SIGTERM exits without
           deleting anything (the backend is kept for adoption on restart).
  start    Like serve without the proxy: create (or adopt) the model's
           backend resources and exit. Pre-warms a model so the first
           request is fast, or manages a backend by hand.
  delete   Delete a model's Deployment/Service (and PVCs with
           --delete-volumes). Used as a model's cmdStop; a running serve
           process exits on its own when it observes the deletion.
  gc       Delete managed workloads whose model is not in the given list
           (--models or --config pointing at a bornite config.yaml).
  status   Print the managed workloads in the namespace, including why a
           not-ready pod is not ready.
  logs     Print a model's backend container logs (--tail, --follow);
           the quick way to see why a model fails to load.
  version  Print version and build information.

Run "kubeswap <command> -h" for command flags.
`)
}

// stringList is a repeatable flag value: --env K=V --env K2=V2.
type stringList []string

// String String implements flag.Value, returning the entries comma-joined.
func (s *stringList) String() string { return strings.Join(*s, ",") }

// Set Set implements flag.Value, appending an entry to the repeatable flag.
func (s *stringList) Set(v string) error { *s = append(*s, v); return nil }

// newFlagSet builds a per-command flag set with the shared kube flags.
func newFlagSet(name string) *flag.FlagSet {
	fs := flag.NewFlagSet(name, flag.ExitOnError)
	fs.Usage = func() {
		fmt.Fprintf(os.Stderr, "Usage: kubeswap %s [flags]\n\nFlags:\n", name)
		fs.PrintDefaults()
	}
	return fs
}

// addKubeFlags Adds the --namespace and --kubeconfig flags shared by every subcommand.
func addKubeFlags(fs *flag.FlagSet, namespace, kubeconfig *string) {
	fs.StringVar(namespace, "namespace", defaultNamespace, "Kubernetes namespace to manage")
	fs.StringVar(kubeconfig, "kubeconfig", "", "Path to a kubeconfig (default: in-cluster config, then KUBECONFIG / ~/.kube/config)")
}

// parseEnvVars parses "K=V" entries (V may contain '='), validating K
// with the API server's own rule (IsEnvVarName) so bad names fail at
// flag parse instead of at Deployment creation.
func parseEnvVars(entries []string) (out []envVar, err error) {
	for _, e := range entries {
		k, v, ok := strings.Cut(e, "=")
		if !ok || len(kvalidation.IsEnvVarName(k)) > 0 {
			return nil, fmt.Errorf("invalid --env %q (name must be a valid environment variable name: letters, digits, '_', '-', or '.', not starting with a digit)", e)
		}
		out = append(out, envVar{Key: k, Value: v})
	}
	return out, nil
}

// envVar is a plain key/value so the renderer stays decoupled from corev1 in
// parse code paths (it is converted in the renderer).
type envVar struct {
	Key   string
	Value string
}

// parseKeyValues parses repeated "K=V" entries, validating K and V with
// the API server's own label rules (content.IsLabelKey / IsLabelValue)
// so bad entries fail at flag parse instead of at Deployment creation.
// Values are label values: no '=', so a K=V with '=' in the value is
// rejected here (env vars use parseEnvVars, whose values are free-form).
func parseKeyValues(entries []string, what string) (map[string]string, error) {
	out := map[string]string{}
	for _, e := range entries {
		k, v, ok := strings.Cut(e, "=")
		if !ok {
			return nil, fmt.Errorf("invalid --%s %q (want key=value)", what, e)
		}
		if errs := content.IsLabelKey(k); len(errs) > 0 {
			return nil, fmt.Errorf("invalid --%s key %q: %v", what, k, errs)
		}
		if errs := content.IsLabelValue(v); len(errs) > 0 {
			return nil, fmt.Errorf("invalid --%s value %q for key %q: %v", what, v, k, errs)
		}
		out[k] = v
	}
	return out, nil
}

// parseGPUs parses "resource=count" entries like "amd.com/gpu=1"; the count
// is a positive whole number — GPUs are exclusive, non-shareable devices, so
// fractions and words like "many" are errors, not quantities.
func parseGPUs(entries []string) (map[string]string, error) {
	out := map[string]string{}
	for _, e := range entries {
		res, count, ok := strings.Cut(e, "=")
		if !ok || res == "" || count == "" {
			return nil, fmt.Errorf("invalid --gpu %q (want resource=count, e.g. amd.com/gpu=1)", e)
		}
		n, err := strconv.ParseInt(count, 10, 32)
		if err != nil || n < 1 {
			return nil, fmt.Errorf("invalid --gpu %q: count %q must be a positive whole number", e, count)
		}
		out[res] = count
	}
	return out, nil
}

// parseResources parses repeated "name=quantity" entries for resource
// requests or limits, validating the quantities up front.
func parseResources(entries []string, what string) (map[string]string, error) {
	m, err := parseKeyValues(entries, what)
	if err != nil {
		return nil, err
	}
	for k, v := range m {
		if _, err := resource.ParseQuantity(v); err != nil {
			return nil, fmt.Errorf("invalid --%s quantity %s=%q: %v", what, k, v, err)
		}
	}
	return m, nil
}

// servicePortSpec is one parsed --service-port entry: name:port.
type servicePortSpec struct {
	Name string
	Port int32
}

// parseServicePorts parses "name:port" entries, rejecting duplicate names.
// Container port names must be unique within the container, so the same
// name on a different port is a duplicate too — renderPorts would emit
// two ports with one name and the API server would reject the Deployment.
func parseServicePorts(entries []string) ([]servicePortSpec, error) {
	out := make([]servicePortSpec, 0, len(entries))
	seen := map[string]bool{}
	for _, e := range entries {
		name, portS, ok := strings.Cut(e, ":")
		if !ok || portS == "" {
			return nil, fmt.Errorf("invalid --service-port %q (want name:port)", e)
		}
		if len(kvalidation.IsValidPortName(name)) > 0 {
			return nil, fmt.Errorf("invalid --service-port name %q (IANA_SVC_NAME: up to 15 lowercase alphanumerics and hyphens, at least one letter, no consecutive or edge hyphens)", name)
		}
		port, err := strconv.Atoi(portS)
		if err != nil || port < 1 || port > 65535 {
			return nil, fmt.Errorf("invalid --service-port port %q (want 1-65535)", portS)
		}
		if seen[name] {
			return nil, fmt.Errorf("duplicate --service-port %q", e)
		}
		seen[name] = true
		out = append(out, servicePortSpec{Name: name, Port: int32(port)})
	}
	return out, nil
}

// parseTolerations parses "key:operator:value:effect" entries, validating
// against the values Kubernetes accepts: operator is Equal or Exists (empty
// defaults to Equal), effect is NoSchedule, PreferNoSchedule or NoExecute —
// or empty, which tolerates every effect (e.g. "dedicated:Exists::" or the
// tolerate-everything "::Exists:"). An empty key is only valid with Exists
// (an Equal toleration without a key can never match a taint); a value is an
// error with operator Exists. Invalid fields are rejected here, before
// renderTolerations turns them into corev1 types ("All" was never a valid
// effect).
func parseTolerations(entries []string) ([]toleration, error) {
	out := make([]toleration, 0, len(entries))
	for _, e := range entries {
		parts := strings.Split(e, ":")
		if len(parts) != 4 {
			return nil, fmt.Errorf("invalid --toleration %q (want key:operator:value:effect)", e)
		}
		key, op, value, effect := parts[0], parts[1], parts[2], parts[3]
		if op == "" {
			op = "Equal"
		}
		// A toleration value is a label value (only reachable with
		// operator Equal; Exists requires an empty value below).
		if value != "" {
			if errs := content.IsLabelValue(value); len(errs) > 0 {
				return nil, fmt.Errorf("invalid --toleration %q: value %q: %v", e, value, errs)
			}
		}
		switch op {
		case "Equal", "Exists":
		default:
			return nil, fmt.Errorf("invalid --toleration %q: operator %q (want Equal or Exists)", e, op)
		}
		switch effect {
		case "", "NoSchedule", "PreferNoSchedule", "NoExecute":
		default:
			return nil, fmt.Errorf("invalid --toleration %q: effect %q (want NoSchedule, PreferNoSchedule, NoExecute, or empty for any effect)", e, effect)
		}
		if op == "Equal" && key == "" {
			return nil, fmt.Errorf("invalid --toleration %q: key must not be empty when operator is Equal", e)
		}
		if op == "Exists" && value != "" {
			return nil, fmt.Errorf("invalid --toleration %q: value must be empty when operator is Exists", e)
		}
		out = append(out, toleration{
			Key: key, Operator: op, Value: value, Effect: effect,
		})
	}
	return out, nil
}

type toleration struct {
	Key      string
	Operator string
	Value    string
	Effect   string
}

// volumeKind is a parsed --volume kind prefix.
type volumeKind string

const (
	volPVC      volumeKind = "pvc"
	volEmptyDir volumeKind = "emptydir"
	volHostPath volumeKind = "hostpath"
)

// volumeSpec is one parsed --volume entry: kind:name:path[:ro].
type volumeSpec struct {
	Kind     volumeKind
	Name     string
	Path     string
	ReadOnly bool
}

// parseVolumes parses "kind:name:path[:ro]" entries. kind is pvc, emptydir or
// hostpath; for hostpath the "name" field is the path on the host.
func parseVolumes(entries []string) ([]volumeSpec, error) {
	out := make([]volumeSpec, 0, len(entries))
	for _, e := range entries {
		fields := strings.Split(e, ":")
		if len(fields) < 3 || len(fields) > 4 {
			return nil, fmt.Errorf("invalid --volume %q (want pvc|emptydir|hostpath:name:path[:ro])", e)
		}
		kind := volumeKind(fields[0])
		switch kind {
		case volPVC, volEmptyDir, volHostPath:
		default:
			return nil, fmt.Errorf("invalid --volume kind %q (want pvc, emptydir or hostpath)", fields[0])
		}
		if fields[1] == "" || fields[2] == "" {
			return nil, fmt.Errorf("invalid --volume %q (name and mount path are required)", e)
		}
		spec := volumeSpec{Kind: kind, Name: fields[1], Path: fields[2]}
		if len(fields) == 4 {
			if fields[3] != "ro" {
				return nil, fmt.Errorf("invalid --volume %q (access mode must be 'ro')", e)
			}
			spec.ReadOnly = true
		}
		out = append(out, spec)
	}
	return out, nil
}

// sortedKeys returns keys in stable order (deterministic manifests).
func sortedKeys[V any](m map[string]V) []string {
	keys := make([]string, 0, len(m))
	for k := range m {
		keys = append(keys, k)
	}
	sort.Strings(keys)
	return keys
}

package main

import (
	"context"
	"errors"
	"fmt"
	"io"
	"log"
	"os"
	"os/signal"
	"strings"
	"syscall"
	"time"

	corev1 "k8s.io/api/core/v1"
	apierrors "k8s.io/apimachinery/pkg/api/errors"
	metav1 "k8s.io/apimachinery/pkg/apis/meta/v1"
	"k8s.io/apimachinery/pkg/labels"
	"k8s.io/client-go/kubernetes"
	"sigs.k8s.io/yaml"
)

type manageFlags struct {
	namespace     string
	kubeconfig    string
	deleteVolumes bool
	wait          time.Duration
}

// deleteModel removes a model's managed objects. It is idempotent: missing
// objects are not an error. A running `kubeswap serve` observes the
// deployment deletion and exits on its own.
func deleteModel(ctx context.Context, client kubernetes.Interface, namespace, model string, deleteVolumes bool, wait time.Duration) error {
	// The user's --wait plus headroom for the API calls, derived from the
	// caller's context: a hung control plane must not hang the CLI
	// (rest.Config has no request timeout), and a gc pass stays inside
	// its own overall budget rather than 2 minutes per model.
	ctx, cancel := context.WithTimeout(ctx, 2*time.Minute+wait)
	defer cancel()
	sanitized, err := sanitizeModelID(model)
	if err != nil {
		return err
	}

	depName, err := deploymentName(model)
	if err != nil {
		return err
	}
	svcName, err := serviceName(model)
	if err != nil {
		return err
	}

	// Lookups are by exact name, never by the coarse model label, so
	// sibling models that sanitize to the same string are out of reach.
	deleted := false
	dep, err := client.AppsV1().Deployments(namespace).Get(ctx, depName, metav1.GetOptions{})
	switch {
	case apierrors.IsNotFound(err):
		// not loaded
	case err != nil:
		return fmt.Errorf("getting deployment %s: %w", depName, err)
	default:
		if err := verifyOwnership(dep, model); err != nil {
			return err
		}
		if err := client.AppsV1().Deployments(namespace).Delete(ctx, depName, metav1.DeleteOptions{}); err != nil && !apierrors.IsNotFound(err) {
			return fmt.Errorf("deleting deployment %s: %w", depName, err)
		}
		log.Printf("deleted deployment %s/%s", namespace, depName)
		deleted = true
	}

	svc, err := client.CoreV1().Services(namespace).Get(ctx, svcName, metav1.GetOptions{})
	switch {
	case apierrors.IsNotFound(err):
		// no service to delete
	case err != nil:
		return fmt.Errorf("getting service %s: %w", svcName, err)
	default:
		if err := verifyOwnership(svc, model); err != nil {
			return err
		}
		if err := client.CoreV1().Services(namespace).Delete(ctx, svcName, metav1.DeleteOptions{}); err != nil && !apierrors.IsNotFound(err) {
			return fmt.Errorf("deleting service %s: %w", svcName, err)
		}
		log.Printf("deleted service %s/%s", namespace, svcName)
		deleted = true
	}

	if deleteVolumes {
		// Only PVCs kubeswap itself created carry the model label;
		// user-managed claims (e.g. a shared model cache) are untouched.
		selector := labels.Set(managedLabels(sanitized)).String()
		pvcs, err := client.CoreV1().PersistentVolumeClaims(namespace).List(ctx, metav1.ListOptions{LabelSelector: selector})
		if err != nil {
			return fmt.Errorf("listing PVCs: %w", err)
		}
		for i := range pvcs.Items {
			if err := verifyOwnership(&pvcs.Items[i], model); err != nil {
				return err
			}
			if err := client.CoreV1().PersistentVolumeClaims(namespace).Delete(ctx, pvcs.Items[i].Name, metav1.DeleteOptions{}); err != nil && !apierrors.IsNotFound(err) {
				return fmt.Errorf("deleting PVC %s: %w", pvcs.Items[i].Name, err)
			}
			log.Printf("deleted PVC %s/%s", namespace, pvcs.Items[i].Name)
			deleted = true
		}
	}

	if !deleted {
		log.Printf("nothing to delete for model %q in %s", model, namespace)
		return nil
	}

	if wait > 0 {
		if err := waitForPodsGone(ctx, client, namespace, sanitized, depName, wait); err != nil {
			return err
		}
	}
	return nil
}

// waitForPodsGone polls until no pod objects for the model remain (the
// deployment deletion cascades, but we wait so cmdStop returns after the
// GPU is free). A pod that merely has a deletion timestamp is still
// terminating and may still hold the GPU, so we wait for the objects
// themselves to disappear. The selector includes the deployment name so
// sibling models that sanitize to the same label are not counted.
func waitForPodsGone(ctx context.Context, client kubernetes.Interface, namespace, sanitized, depName string, timeout time.Duration) error {
	selector := labels.Set(podSelectorLabels(sanitized, depName)).String()
	deadline := time.Now().Add(timeout)
	for {
		// Per-iteration bound: a hung List must not stall the loop past
		// its deadline.
		callCtx, cancel := context.WithTimeout(ctx, apiCallTimeout)
		pods, err := client.CoreV1().Pods(namespace).List(callCtx, metav1.ListOptions{LabelSelector: selector})
		cancel()
		if err != nil {
			return fmt.Errorf("listing pods: %w", err)
		}
		count := len(pods.Items)
		if count == 0 {
			return nil
		}
		if time.Now().After(deadline) {
			return fmt.Errorf("timed out after %s waiting for %d pods to terminate", timeout, count)
		}
		time.Sleep(500 * time.Millisecond)
	}
}

// deleteCmd Implements the delete subcommand: tears down a model's backend Deployment and Service (and, with --delete-volumes, the PVCs kubeswap created).
func deleteCmd(args []string) error {
	var (
		model string
		f     manageFlags
	)
	fs := newFlagSet("delete")
	fs.StringVar(&model, "model", "", "bornite model ID (required)")
	addKubeFlags(fs, &f.namespace, &f.kubeconfig)
	fs.BoolVar(&f.deleteVolumes, "delete-volumes", false, "also delete PVCs that kubeswap created for this model")
	fs.DurationVar(&f.wait, "wait", 30*time.Second, "how long to wait for pods to terminate (0 = do not wait)")
	fs.Parse(args)

	if model == "" {
		return errors.New("--model is required")
	}
	client, err := buildClient(f.kubeconfig)
	if err != nil {
		return err
	}
	return deleteModel(context.Background(), client, f.namespace, model, f.deleteVolumes, f.wait)
}

type gcFlags struct {
	namespace     string
	kubeconfig    string
	models        stringList
	config        string
	deleteVolumes bool
	dryRun        bool
}

// gcAllowedModels builds the set of model IDs from --models entries and,
// optionally, the keys of the models map in a bornite config.yaml.
// --models is repeatable and each value may be comma-separated
// (model-a,model-b); the entries are split so both forms work.
func gcAllowedModels(models []string, configPath string) (map[string]bool, error) {
	allowed := map[string]bool{}
	for _, m := range models {
		for _, id := range strings.Split(m, ",") {
			if id = strings.TrimSpace(id); id != "" {
				allowed[id] = true
			}
		}
	}
	if configPath != "" {
		data, err := os.ReadFile(configPath)
		if err != nil {
			return nil, fmt.Errorf("reading config %s: %w", configPath, err)
		}
		var doc struct {
			Models map[string]interface{} `yaml:"models"`
		}
		if err := yaml.Unmarshal(data, &doc); err != nil {
			return nil, fmt.Errorf("parsing config %s: %w", configPath, err)
		}
		for id := range doc.Models {
			allowed[id] = true
		}
	}
	if len(allowed) == 0 {
		return nil, errors.New("no models to keep: use --models or --config")
	}
	return allowed, nil
}

// gcCmd Implements the gc subcommand: deletes backend workloads whose models are no longer allowed by the config.
func gcCmd(args []string) error {
	var f gcFlags
	fs := newFlagSet("gc")
	addKubeFlags(fs, &f.namespace, &f.kubeconfig)
	fs.Var(&f.models, "models", "comma-separated model IDs that should survive GC (repeatable)")
	fs.StringVar(&f.config, "config", "", "path to a bornite config.yaml; its models keep surviving GC")
	fs.BoolVar(&f.deleteVolumes, "delete-volumes", false, "also delete PVCs that kubeswap created for collected models")
	fs.BoolVar(&f.dryRun, "dry-run", false, "report what would be collected without deleting anything")
	fs.Parse(args)

	client, err := buildClient(f.kubeconfig)
	if err != nil {
		return err
	}
	allowed, err := gcAllowedModels(f.models, f.config)
	if err != nil {
		return err
	}

	deleted, err := gcCollect(client, f.namespace, allowed, f.deleteVolumes, f.dryRun)
	if err != nil {
		return err
	}
	if f.dryRun {
		log.Printf("gc complete (dry run): would collect %v", deleted)
	} else {
		log.Printf("gc complete: collected %v", deleted)
	}
	return nil
}

// gcCollect deletes managed workloads whose model ID is not in allowed and
// returns the collected model IDs. With dryRun the workloads are only
// reported, so the operator can see the plan before letting it run.
func gcCollect(client kubernetes.Interface, namespace string, allowed map[string]bool, deleteVolumes, dryRun bool) ([]string, error) {
	ctx, cancel := context.WithTimeout(context.Background(), 5*time.Minute)
	defer cancel()
	managed := labels.Set(map[string]string{labelManagedBy: managedByValue}).String()
	deps, err := client.AppsV1().Deployments(namespace).List(ctx, metav1.ListOptions{LabelSelector: managed})
	if err != nil {
		return nil, fmt.Errorf("listing managed deployments: %w", err)
	}

	var deleted []string
	for i := range deps.Items {
		dep := &deps.Items[i]
		modelID := dep.Annotations[annotationModelID]
		if modelID == "" {
			// No annotation: the allowed set holds ORIGINAL model IDs
			// (the label carries only the sanitized form, which several
			// distinct IDs share) and the deployment name hashes the
			// original ID, so such an object can neither be matched
			// against the config nor deleted by name. Skip it with a
			// loud log instead of guessing: every Deployment kubeswap
			// creates carries the annotation.
			log.Printf("skipping %s/%s: no %s annotation (not a kubeswap object?)", namespace, dep.Name, annotationModelID)
			continue
		}
		if allowed[modelID] {
			log.Printf("keeping %s/%s (model %q)", namespace, dep.Name, modelID)
			continue
		}
		if dryRun {
			log.Printf("would collect %s/%s (model %q not in config)", namespace, dep.Name, modelID)
			deleted = append(deleted, modelID)
			continue
		}
		log.Printf("collecting %s/%s (model %q not in config)", namespace, dep.Name, modelID)
		if err := deleteModel(ctx, client, namespace, modelID, deleteVolumes, 0); err != nil {
			return deleted, fmt.Errorf("collecting model %q: %w", modelID, err)
		}
		deleted = append(deleted, modelID)
	}
	return deleted, nil
}

// statusCmd Implements the status subcommand: reports on the namespace's managed workloads.
func statusCmd(args []string) error {
	var (
		namespace  string
		kubeconfig string
		watch      bool
		interval   time.Duration
	)
	fs := newFlagSet("status")
	addKubeFlags(fs, &namespace, &kubeconfig)
	fs.BoolVar(&watch, "watch", false, "keep refreshing the table (for interactive use; Ctrl-C to stop)")
	fs.DurationVar(&interval, "interval", 5*time.Second, "refresh interval for --watch")
	fs.Parse(args)
	// time.NewTicker panics on a non-positive duration; reject at parse
	// time like the other flag validation instead of crashing after the
	// initial status print.
	if watch && interval <= 0 {
		return fmt.Errorf("invalid --interval %s (must be positive with --watch)", interval)
	}
	return runStatus(namespace, kubeconfig, watch, interval)
}

// runStatus Lists the managed Deployments, their pods and the models they serve.
func runStatus(namespace, kubeconfig string, watch bool, interval time.Duration) error {
	client, err := buildClient(kubeconfig)
	if err != nil {
		return err
	}
	return runStatusWithClient(context.Background(), client, namespace, watch, interval)
}

func runStatusWithClient(ctx context.Context, client kubernetes.Interface, namespace string, watch bool, interval time.Duration) error {
	bounded, cancel := context.WithTimeout(ctx, apiCallTimeout)
	err := statusOnce(bounded, client, namespace)
	cancel()
	if err != nil {
		return err
	}
	if !watch {
		return nil
	}
	ticker := time.NewTicker(interval)
	defer ticker.Stop()
	for {
		select {
		case <-ctx.Done():
			return nil
		case <-ticker.C:
			bounded, cancel := context.WithTimeout(ctx, apiCallTimeout)
			err := statusOnce(bounded, client, namespace)
			cancel()
			if err != nil {
				fmt.Println("status:", err)
			}
		}
	}
}

// runStatusWithClient prints the status table and, with watch, refreshes it
// on a ticker until ctx is done. A transient API error in the loop is
// printed but does not kill the watch; the initial print failing is an
// error (there is nothing to watch yet).
func statusOnce(ctx context.Context, client kubernetes.Interface, namespace string) error {
	managed := labels.Set(map[string]string{labelManagedBy: managedByValue}).String()
	deps, err := client.AppsV1().Deployments(namespace).List(ctx, metav1.ListOptions{LabelSelector: managed})
	if err != nil {
		return fmt.Errorf("listing managed deployments: %w", err)
	}
	if len(deps.Items) == 0 {
		fmt.Printf("no managed workloads in namespace %s\n", namespace)
		return nil
	}

	pods, err := client.CoreV1().Pods(namespace).List(ctx, metav1.ListOptions{LabelSelector: managed})
	if err != nil {
		return fmt.Errorf("listing pods: %w", err)
	}
	podByModel := map[string]*corev1.Pod{}
	for i := range pods.Items {
		p := &pods.Items[i]
		if p.DeletionTimestamp != nil {
			continue
		}
		// Key by the deployment label (unique per model); fall back to the
		// coarse model label for pods rendered before the deployment label
		// existed (there the deployment name IS the model label value).
		key := p.Labels[labelDeployment]
		if key == "" {
			key = p.Labels[labelModel]
		}
		if _, ok := podByModel[key]; !ok {
			podByModel[key] = p
		}
	}

	// Column widths adapt to the content: model IDs and the
	// hash-suffixed deployment/pod names can run to 60+ characters and
	// are printed in full (REASON stays a bounded summary; the full
	// text is one `kubeswap logs` away).
	type statusRow struct{ model, dep, pod, ready, age, reason string }
	rows := make([]statusRow, 0, len(deps.Items))
	for i := range deps.Items {
		dep := &deps.Items[i]
		model := dep.Annotations[annotationModelID]
		if model == "" {
			model = dep.Labels[labelModel]
		}
		age := "new"
		if !dep.CreationTimestamp.IsZero() {
			age = time.Since(dep.CreationTimestamp.Time).Round(time.Second).String()
		}
		pod, ok := podByModel[dep.Name]
		podName, ready, reason := "-", "-", ""
		if ok {
			podName = pod.Name
			ready = "no"
			if podIsReady(pod) {
				ready = "yes"
			} else {
				reason = podReason(pod)
			}
		}
		rows = append(rows, statusRow{model, dep.Name, podName, ready, age, reason})
	}

	headers := []string{"MODEL", "DEPLOYMENT", "POD", "READY", "AGE", "REASON"}
	widths := make([]int, len(headers))
	for i, h := range headers {
		widths[i] = len(h)
	}
	for _, r := range rows {
		vals := []string{r.model, r.dep, r.pod, r.ready, r.age, r.reason}
		for i, v := range vals {
			if len(v) > widths[i] {
				widths[i] = len(v)
			}
		}
	}
	printRow := func(vals ...string) {
		for i, v := range vals {
			if i < len(vals)-1 {
				fmt.Printf("%-*s ", widths[i], v)
			} else {
				fmt.Printf("%s\n", v)
			}
		}
	}
	printRow(headers...)
	for _, r := range rows {
		printRow(r.model, r.dep, r.pod, r.ready, r.age, r.reason)
	}
	return nil
}

// podReason summarizes why a pod is not ready (empty when it is): the
// container waiting state (CrashLoopBackOff, ImagePullBackOff, ...) when
// there is one, the scheduler's verdict when the pod is unscheduled, or
// "starting" when the container is up but the probes have not passed.
func podReason(p *corev1.Pod) string {
	if podIsReady(p) {
		return ""
	}
	// A container that just crashed is Terminated (reason + exit code)
	// until the kubelet's backoff starts and flips it to Waiting —
	// report it rather than the "starting" fallback.
	for _, cs := range p.Status.ContainerStatuses {
		if t := cs.State.Terminated; t != nil {
			return fmt.Sprintf("%s (exit code %d)", t.Reason, t.ExitCode)
		}
	}
	for _, cs := range p.Status.ContainerStatuses {
		if w := cs.State.Waiting; w != nil && w.Reason != "" {
			if w.Message != "" {
				return truncate(w.Reason+": "+w.Message, 64)
			}
			return w.Reason
		}
	}
	for _, cond := range p.Status.Conditions {
		if cond.Type == corev1.PodScheduled && cond.Status == corev1.ConditionFalse && cond.Message != "" {
			return truncate("unscheduled: "+cond.Message, 64)
		}
	}
	// A running but not-ready container inside the configured startup
	// window is still loading a model (probes are expected to fail until
	// the backend is up). Past the window it is stuck: the probe cannot be
	// passing, most often because the backend bound to loopback (engines
	// default to 127.0.0.1 without an explicit host flag) or the health
	// path is wrong.
	for _, cs := range p.Status.ContainerStatuses {
		if r := cs.State.Running; r != nil && !r.StartedAt.Time.IsZero() {
			if age := time.Since(r.StartedAt.Time); age > startupWindowFromSpec(p, cs.Name) {
				return fmt.Sprintf("running %s, still not ready (probe failing?)", age.Truncate(time.Minute))
			}
		}
	}
	return "starting"
}

// startupWindowFromSpec reports the startup window configured for the
// named container from the pod spec (the startup probe's
// failureThreshold × periodSeconds — the exact load time the wrapper
// allows before restarting the pod). A container without a startup probe
// gets the generic fallback.
func startupWindowFromSpec(p *corev1.Pod, container string) time.Duration {
	for _, c := range p.Spec.Containers {
		if c.Name != container {
			continue
		}
		if sp := c.StartupProbe; sp != nil && sp.PeriodSeconds > 0 {
			return time.Duration(sp.FailureThreshold*sp.PeriodSeconds) * time.Second
		}
	}
	return stuckRunningThreshold
}

// stuckRunningThreshold Fallback window for a pod that carries no startup
// probe: how long a container may be running while the pod stays not-ready
// before the status reason escalates from "starting" (normal model load)
// to "still not ready" (something is wrong).
const stuckRunningThreshold = 5 * time.Minute

// logsCmd Implements the logs subcommand: prints (and, with --follow, streams) the backend container logs of a model's pod.
func logsCmd(args []string) error {
	var (
		model  string
		f      manageFlags
		tail   int
		follow bool
	)
	fs := newFlagSet("logs")
	fs.StringVar(&model, "model", "", "bornite model ID (required)")
	addKubeFlags(fs, &f.namespace, &f.kubeconfig)
	fs.IntVar(&tail, "tail", 100, "number of lines to start from (0 = all lines)")
	fs.BoolVar(&follow, "follow", false, "keep streaming until the pod or container stops")
	fs.Parse(args)

	if model == "" {
		return errors.New("--model is required")
	}
	client, err := buildClient(f.kubeconfig)
	if err != nil {
		return err
	}
	return runLogs(context.Background(), client, f.namespace, model, tail, follow)
}

// runLogs finds the model's pod and copies the backend container's logs to
// stdout under the caller's context. Non-follow reads run under a bounded
// timeout (a stalled stream must not hang the CLI); follow mode runs under
// a signal-cancelled context, so Ctrl+C cancels the stream, the copy stops,
// and the exit is quiet — a canceled follow is a normal stop, not a failure.
func runLogs(ctx context.Context, client kubernetes.Interface, namespace, model string, tail int, follow bool) error {
	var streamCtx context.Context
	if follow {
		var cancel context.CancelFunc
		streamCtx, cancel = signal.NotifyContext(ctx, os.Interrupt, syscall.SIGTERM)
		defer cancel()
	} else {
		var cancel context.CancelFunc
		streamCtx, cancel = context.WithTimeout(ctx, apiCallTimeout)
		defer cancel()
	}
	sanitized, err := sanitizeModelID(model)
	if err != nil {
		return err
	}
	depName, err := deploymentName(model)
	if err != nil {
		return err
	}
	pod, err := findModelPod(streamCtx, client, namespace, sanitized, depName)
	if err != nil {
		if follow && streamCtx.Err() != nil {
			return nil
		}
		return err
	}
	if pod == nil {
		return fmt.Errorf("no pod found for model %q in namespace %s (is it loaded?)", model, namespace)
	}
	opts := &corev1.PodLogOptions{Container: containerName, Follow: follow}
	if tail > 0 {
		n := int64(tail)
		opts.TailLines = &n
	}
	stream, err := client.CoreV1().Pods(namespace).GetLogs(pod.Name, opts).Stream(streamCtx)
	if err != nil {
		if follow && streamCtx.Err() != nil {
			return nil
		}
		return fmt.Errorf("opening logs for pod %s: %w", pod.Name, err)
	}
	defer stream.Close()
	if _, err := io.Copy(os.Stdout, stream); err != nil {
		if follow && streamCtx.Err() != nil {
			return nil
		}
		return fmt.Errorf("reading logs for pod %s: %w", pod.Name, err)
	}
	return nil
}

// findModelPod returns the model's current pod (preferring a ready one, then
// the newest), or nil if the model has no live pod. The deployment name in
// the selector keeps sibling models that sanitize to the same label out of
// reach.
func findModelPod(ctx context.Context, client kubernetes.Interface, namespace, sanitized, depName string) (*corev1.Pod, error) {
	selector := labels.Set(podSelectorLabels(sanitized, depName)).String()
	callCtx, cancel := context.WithTimeout(ctx, apiCallTimeout)
	defer cancel()
	pods, err := client.CoreV1().Pods(namespace).List(callCtx, metav1.ListOptions{LabelSelector: selector})
	if err != nil {
		return nil, fmt.Errorf("listing pods: %w", err)
	}
	var best *corev1.Pod
	for i := range pods.Items {
		p := &pods.Items[i]
		if p.DeletionTimestamp != nil {
			continue
		}
		if best == nil ||
			(podIsReady(p) && !podIsReady(best)) ||
			(podIsReady(p) == podIsReady(best) && p.CreationTimestamp.After(best.CreationTimestamp.Time)) {
			best = p
		}
	}
	return best, nil
}

// truncate Shortens s to at most n characters, appending an ellipsis when it cuts.
func truncate(s string, n int) string {
	if len(s) <= n {
		return s
	}
	if n < 4 {
		return s[:n]
	}
	return s[:n-3] + "..."
}

package main

import (
	"crypto/sha256"
	"encoding/hex"
	"fmt"
	"strings"
)

// sanitizeModelID translates a model ID into a DNS-1123 label: lowercase
// alphanumerics and dashes, max 63 chars. The original ID is preserved in
// the bornite.io/model-id annotation on every created object.
func sanitizeModelID(id string) (string, error) {
	var b strings.Builder
	prevDash := false
	for _, r := range id {
		switch {
		case (r >= 'a' && r <= 'z') || (r >= '0' && r <= '9'):
			b.WriteRune(r)
			prevDash = false
		case r >= 'A' && r <= 'Z':
			b.WriteRune(r - 'A' + 'a')
			prevDash = false
		default:
			if b.Len() > 0 && !prevDash {
				b.WriteRune('-')
				prevDash = true
			}
		}
	}
	s := strings.Trim(b.String(), "-")
	if len(s) > 63 {
		s = strings.Trim(s[:63], "-")
	}
	if s == "" {
		return "", fmt.Errorf("model ID %q has no usable characters for a Kubernetes name", id)
	}
	return s, nil
}

// idHash is a short fingerprint of the ORIGINAL model ID. Distinct IDs can
// sanitize to the same string (Model_A and model-a) or share a long prefix,
// so object names carry a hash of the original ID to stay collision-free.
func idHash(id string) string {
	sum := sha256.Sum256([]byte(id))
	return hex.EncodeToString(sum[:4])
}

// deploymentName is the name of the model's Deployment: the sanitized ID
// (up to 50 chars) plus "-" plus the original-ID hash. The result is
// deterministic and at most 59 chars.
func deploymentName(modelID string) (string, error) {
	s, err := sanitizeModelID(modelID)
	if err != nil {
		return "", err
	}
	if len(s) > 50 {
		s = strings.TrimRight(s[:50], "-")
	}
	return s + "-" + idHash(modelID), nil
}

// serviceName is the name of the model's Service: the deployment name plus
// "-svc" (at most 63 chars).
func serviceName(modelID string) (string, error) {
	dep, err := deploymentName(modelID)
	if err != nil {
		return "", err
	}
	return dep + "-svc", nil
}

// managedLabels are the coarse ownership labels objects kubeswap creates
// carry. The sanitized model ID (not the original) is used so labels stay
// valid. NOTE: the sanitized ID is NOT unique across models (Model_A and
// model-a share it), so pod selection must use podSelectorLabels.
func managedLabels(sanitized string) map[string]string {
	return map[string]string{
		labelManagedBy: managedByValue,
		labelModel:     sanitized,
	}
}

// podSelectorLabels uniquely identify one model's pods: the deployment
// name carries the original-ID hash, so distinct model IDs never share a
// selector. Used for the Deployment/Service selectors and for finding
// pods (proxy upstream, readiness, logs, delete waits).
func podSelectorLabels(sanitized, depName string) map[string]string {
	labels := managedLabels(sanitized)
	labels[labelDeployment] = depName
	return labels
}

// podLabels are the pod template labels: a superset of podSelectorLabels
// so the Deployment and Service selectors match them.
func podLabels(sanitized, depName string) map[string]string {
	labels := map[string]string{
		labelAppName: appNameValue,
	}
	for k, v := range podSelectorLabels(sanitized, depName) {
		labels[k] = v
	}
	return labels
}

