package astmatrix

// liveCatalogReader — thin reader for the live catalog JSON exported by the
// TS package (@toxicwind/mimetite ModelCatalog.writeLiveCatalog).
//
// This file contains NO catalog logic. It does not discover, prune, or
// quarantine anything. The TS package is the brain: it owns the provider
// definitions, the /models adapters, live discovery, and the two-strike
// quarantine state machine. It writes the ANSWER (derived serving sets) to a
// JSON file; this reader loads that file and hands the serving sets to the
// provider table. Transpiling the logic into Go is a trap (Tern's
// 2026-09-30 verdict); the JSON catalog is the contract, the TS package is
// the brain.
//
// Contract: pens-mimetite/live-catalog/v1
//   { "contract": ..., "generatedAt": ..., "deadIds": [...],
//     "providers": { "<name>": { "serving": [...], "quarantined": [...],
//                               "discovered": bool } } }
//
// When the live file is absent or unreadable, providers fall back to their
// generated cold-start seeds (dead-filtered). The file is re-read whenever
// its mtime changes, so a TS-side quarantine propagates to bornite without a
// restart and without any polling timer on our side.

import (
	"bytes"
	"encoding/json"
	"log"
	"net/http"
	"os"
	"sync"
	"time"
)

// LiveCatalogPath resolves the live catalog file path: env override first,
// then the TS router's default state location.
func LiveCatalogPath() string {
	if p := os.Getenv("pens-scripts_LIVE_CATALOG"); p != "" {
		return p
	}
	return "/home/toxic/pens/pens/var/state/provider-catalog.live.json"
}

type liveCatalogProvider struct {
	Serving     []string `json:"serving"`
	Quarantined []string `json:"quarantined"`
	Discovered  bool     `json:"discovered"`
}

const (
	liveCatalogContract       = "pens-mimetite/live-catalog/v1"
	legacyLiveCatalogContract = "pens-scripts-providers/live-catalog/v1" // pre-rename backward-compat alias
)

type liveCatalogData struct {
	Contract    string                         `json:"contract"`
	GeneratedAt string                         `json:"generatedAt"`
	DeadIDs     []string                       `json:"deadIds"`
	Providers   map[string]liveCatalogProvider `json:"providers"`
}

// LiveCatalogReader reads the TS-exported live catalog file. Pure data.
type LiveCatalogReader struct {
	path  string
	mu    sync.RWMutex
	mtime time.Time
	data  *liveCatalogData
}

func NewLiveCatalogReader(path string) *LiveCatalogReader {
	if path == "" {
		path = LiveCatalogPath()
	}
	return &LiveCatalogReader{path: path}
}

// Path returns the file this reader watches.
func (r *LiveCatalogReader) Path() string { return r.path }

// refreshIfStale re-reads the file when its mtime changed. Returns the
// current data, or nil when the file is absent/unreadable/invalid. Never
// returns an error: a bad file is simply treated as "no live data".
func (r *LiveCatalogReader) refreshIfStale() *liveCatalogData {
	fi, err := os.Stat(r.path)
	if err != nil {
		return nil
	}
	mt := fi.ModTime()

	r.mu.RLock()
	cached := r.data
	cachedMt := r.mtime
	r.mu.RUnlock()
	if cached != nil && !mt.After(cachedMt) {
		return cached
	}

	raw, err := os.ReadFile(r.path)
	if err != nil {
		return nil
	}
	var d liveCatalogData
	if err := json.Unmarshal(raw, &d); err != nil {
		return nil
	}
	if d.Contract != liveCatalogContract && d.Contract != legacyLiveCatalogContract {
		// Silently returning nil here is what let a pre-rename contract file sit
		// on disk while every consumer quietly fell back to cold-start seeds.
		// The mismatch is now loud, and the legacy name is accepted on read so
		// the pens keeps working across the roost rename.
		log.Printf("[live-catalog] %s declares unknown contract %q; expected %s", r.path, d.Contract, liveCatalogContract)
		return nil
	}
	if d.Contract == legacyLiveCatalogContract {
		log.Printf("[live-catalog] %s declares the pre-rename contract %s; accepting it, but rewrite with %s", r.path, legacyLiveCatalogContract, liveCatalogContract)
	}
	if d.Providers == nil {
		d.Providers = map[string]liveCatalogProvider{}
	}

	r.mu.Lock()
	r.data = &d
	r.mtime = mt
	r.mu.Unlock()
	return &d
}

// ServingModels returns the live serving list for a provider.
// ok=false means no live data (file absent/invalid or provider not listed);
// callers fall back to generated cold-start seeds.
func (r *LiveCatalogReader) ServingModels(provider string) (models []string, ok bool) {
	d := r.refreshIfStale()
	if d == nil {
		return nil, false
	}
	p, found := d.Providers[provider]
	if !found {
		return nil, false
	}
	out := make([]string, len(p.Serving))
	copy(out, p.Serving)
	return out, true
}

// SyncProviderModels overlays the live serving sets onto a provider table.
// Providers with live data get their models replaced verbatim; providers
// without live data keep whatever they had (generated seeds). Pure data
// overlay — no discovery, no quarantine decisions here.
func (r *LiveCatalogReader) SyncProviderModels(providers map[string]*provider) {
	d := r.refreshIfStale()
	if d == nil {
		return
	}
	for name, p := range providers {
		live, ok := d.Providers[name]
		if !ok {
			continue
		}
		p.models = append([]string(nil), live.Serving...)
	}
}

// ------------------------------------------------------------------
// 404 event reporting — bornite reports, the TS brain decides.
// ------------------------------------------------------------------

// serve404Endpoint is the TS router's 404 intake. Override with
// pens-scripts_CATALOG_404_URL. Empty disables reporting.
func serve404Endpoint() string {
	if u := os.Getenv("pens-scripts_CATALOG_404_URL"); u != "" {
		return u
	}
	return "http://127.0.0.1:25104/admin/catalog/serve-404"
}

// reportServe404 posts a serve-time 404 to the TS catalog brain. Best-effort:
// short timeout, failures are logged and dropped, never retried, never
// blocking. The TS side quarantines the id and rewrites the live catalog
// file; bornite picks the new serving set up on its next read.
func reportServe404(provider, model string) {
	url := serve404Endpoint()
	if url == "" {
		return
	}
	body, _ := json.Marshal(map[string]string{"provider": provider, "model": model})
	req, err := http.NewRequest("POST", url, bytes.NewReader(body))
	if err != nil {
		return
	}
	req.Header.Set("Content-Type", "application/json")
	if tok := os.Getenv("pens-scripts_CATALOG_ADMIN_TOKEN"); tok != "" {
		req.Header.Set("Authorization", "Bearer "+tok)
	}
	client := &http.Client{Timeout: 5 * time.Second}
	resp, err := client.Do(req)
	if err != nil {
		return
	}
	resp.Body.Close()
}

package astmatrix

import (
	"fmt"
	"math"
	"math/rand"
	"os"
	"sync"
	"time"
)

// Matrix holds the runtime state for all providers: ELO scores, circuit
// breakers, fail counters, and the health database.
type Matrix struct {
	mu               sync.RWMutex
	providers        map[string]*provider
	live             *LiveCatalogReader // TS-exported live serving sets (data, not logic)
	fail             map[string]int     // consecutive failures per provider
	lastFail         map[string]float64 // last failure timestamp
	elo              map[string]float64
	circuit          map[string]string // "closed" | "open" | "half"
	circuitOpenUntil map[string]float64
	fifoDepth        int
	health           *HealthDB
	rateLimiter      *PerProviderRateLimiter
	config           *AstMatrixConfig
}

// NewMatrix creates a Matrix from config, loading secrets from env.
func NewMatrix(cfg *AstMatrixConfig) (*Matrix, error) {
	cfg.Defaults()

	providers := defaultProviders()

	// Provider→models membership comes from the TS package brain. Providers
	// start on their generated cold-start seeds; the live serving sets are
	// overlaid from the TS-exported live catalog file when present. This is
	// a synchronous file read — no discovery, no network, no goroutine, no
	// race. When the TS side quarantines or re-admits a model it rewrites
	// the file and the next read picks it up.
	live := NewLiveCatalogReader("")
	live.SyncProviderModels(providers)

	// Override provider configs from YAML if provided
	for name, pcfg := range cfg.Providers {
		if p, ok := providers[name]; ok {
			if pcfg.BaseURL != "" {
				p.base = pcfg.BaseURL
			}
			if pcfg.KeyEnv != "" {
				p.keyEnv = pcfg.KeyEnv
			}
			if pcfg.KeyEnvAlt != "" {
				p.keyEnvAlt = pcfg.KeyEnvAlt
			}
			if pcfg.NoAuth {
				p.noAuth = true
			}
		} else {
			providers[name] = &provider{
				base:      pcfg.BaseURL,
				keyEnv:    pcfg.KeyEnv,
				keyEnvAlt: pcfg.KeyEnvAlt,
				noAuth:    pcfg.NoAuth,
			}
		}
	}

	health, err := NewHealthDB(cfg.DbPath)
	if err != nil {
		return nil, err
	}

	elo := make(map[string]float64)
	circuit := make(map[string]string)
	for name := range providers {
		elo[name] = 1000
		circuit[name] = "closed"
	}

	m := &Matrix{
		rateLimiter:      NewRateLimiter(),
		providers:        providers,
		live:             live,
		fail:             make(map[string]int),
		lastFail:         make(map[string]float64),
		elo:              elo,
		circuit:          circuit,
		circuitOpenUntil: make(map[string]float64),
		health:           health,
		config:           cfg,
	}
	return m, nil
}

// SyncLiveCatalog re-reads the TS-exported live catalog file and overlays
// the serving sets onto the live provider table. Call this from admin
// handlers or SIGHUP-style triggers — never on a timer. Discovery itself
// lives in the TS package; this only picks up the new answer.
func (m *Matrix) SyncLiveCatalog() {
	if m.live == nil {
		return
	}
	m.mu.Lock()
	defer m.mu.Unlock()
	m.live.SyncProviderModels(m.providers)
}

// LiveCatalog exposes the TS-exported live serving-set reader.
func (m *Matrix) LiveCatalog() *LiveCatalogReader {
	return m.live
}

// Record updates ELO scores and circuit breakers after a request completes.
func (m *Matrix) Record(model, prov string, status int, lat float64, winner int, strategy, session string) {
	latMs := lat * 1000
	m.health.RecordRequest(prov, model, status, latMs, strategy, winner, session)

	m.mu.Lock()
	defer m.mu.Unlock()

	now := float64(time.Now().UnixMilli()) / 1000.0
	if status == 200 {
		old := m.circuit[prov]
		m.elo[prov] += 16
		m.fail[prov] = 0
		m.lastFail[prov] = now
		m.circuit[prov] = "closed"
		if old != "closed" {
			m.health.RecordHealing(prov, model, "circuit_recovered", old, "closed", "")
		}
	} else if status == 429 {
		m.health.RecordRateLimit(prov, model, status)
		m.elo[prov] = math.Max(100, m.elo[prov]-8)
		m.fail[prov]++
		m.lastFail[prov] = now
	} else {
		m.fail[prov]++
		m.lastFail[prov] = now
		m.elo[prov] = math.Max(100, m.elo[prov]-32)
		if m.fail[prov] >= 3 {
			old := m.circuit[prov]
			m.circuit[prov] = "open"
			m.circuitOpenUntil[prov] = now + 60
			m.health.RecordHealing(prov, model, "circuit_opened", old, "open",
				fmt.Sprintf("%d consecutive failures", m.fail[prov]))
		}
	}
}

// StickyGet retrieves session affinity via HealthDB.
func (m *Matrix) StickyGet(sessionID string) (string, string) {
	return m.health.StickyGet(sessionID, m.config.StickyTTL)
}

// StickySet stores session affinity via HealthDB.
func (m *Matrix) StickySet(sessionID, provider, model string) {
	m.health.StickySet(sessionID, provider, model)
}

// CircuitOk reports whether the provider's circuit breaker allows requests.
func (m *Matrix) CircuitOk(p string) bool {
	m.mu.Lock()
	defer m.mu.Unlock()

	st := m.circuit[p]
	if st == "closed" || st == "half" {
		return true
	}
	if st == "open" {
		now := float64(time.Now().UnixMilli()) / 1000.0
		if now > m.circuitOpenUntil[p] {
			m.circuit[p] = "half"
			return true
		}
		return false
	}
	return true
}

// ELO returns the current ELO score for a provider.
func (m *Matrix) ELO(p string) float64 {
	m.mu.RLock()
	defer m.mu.RUnlock()
	return m.elo[p]
}

// CircuitState returns the circuit breaker state for a provider.
func (m *Matrix) CircuitState(p string) string {
	m.mu.RLock()
	defer m.mu.RUnlock()
	return m.circuit[p]
}

// Providers returns the provider map (read-only snapshot).
func (m *Matrix) Providers() map[string]*provider {
	return m.providers
}

// Health returns the health database.
func (m *Matrix) Health() *HealthDB {
	return m.health
}

// Close closes the health database.
func (m *Matrix) Close() error {
	return m.health.Close()
}

// PickWeighted selects up to n providers weighted by ELO + jitter.
// The live catalog is synced first (request-triggered, not timer-polled):
// if the TS brain rewrote the serving sets, the next routing decision sees
// it. The sync is cheap when the file mtime is unchanged, and it runs
// before the read lock is taken so there is no lock-upgrade deadlock.
func (m *Matrix) PickWeighted(n int) [][2]string {
	m.SyncLiveCatalog()
	m.mu.RLock()
	defer m.mu.RUnlock()

	type scored struct {
		score float64
		name  string
		model string
	}
	var all []scored
	for name := range m.providers {
		if !m.keyOkLocked(name) || !m.circuitOkLocked(name) {
			continue
		}
		mid := firstModelFor(name)
		if mid == "" {
			continue
		}
		jitter := rand.Float64() * 10
		all = append(all, scored{m.elo[name] + jitter, name, mid})
	}
	// Sort descending by score
	for i := 0; i < len(all); i++ {
		for j := i + 1; j < len(all); j++ {
			if all[j].score > all[i].score {
				all[i], all[j] = all[j], all[i]
			}
		}
	}
	seen := make(map[string]bool)
	var result [][2]string
	for _, s := range all {
		if seen[s.name] {
			continue
		}
		seen[s.name] = true
		result = append(result, [2]string{s.name, s.model})
		if len(result) >= n {
			break
		}
	}
	return result
}

// keyOkLocked checks if the provider has a valid API key (caller holds lock).
func (m *Matrix) keyOkLocked(name string) bool {
	p, ok := m.providers[name]
	if !ok {
		return false
	}
	if p.noAuth {
		return true
	}
	if os.Getenv(p.keyEnv) != "" {
		return true
	}
	if p.keyEnvAlt != "" && os.Getenv(p.keyEnvAlt) != "" {
		return true
	}
	return false
}

// circuitOkLocked is the non-mutating version (caller holds lock).
func (m *Matrix) circuitOkLocked(p string) bool {
	st := m.circuit[p]
	if st == "closed" || st == "half" {
		return true
	}
	if st == "open" {
		now := float64(time.Now().UnixMilli()) / 1000.0
		return now > m.circuitOpenUntil[p]
	}
	return true
}

// firstModelFor returns the default model for a provider.
func firstModelFor(p string) string {
	if p == "bornite" {
		return "local-quality"
	}
	providers := defaultProviders()
	if prov, ok := providers[p]; ok && len(prov.models) > 0 {
		return prov.models[0]
	}
	return ""
}

// KeyOk checks if a provider has a valid API key (public, no lock).
func (m *Matrix) KeyOk(name string) bool {
	m.mu.RLock()
	defer m.mu.RUnlock()
	return m.keyOkLocked(name)
}

// GetKey returns the API key for a provider.
func (m *Matrix) GetKey(p string) string {
	prov, ok := m.providers[p]
	if !ok {
		return ""
	}
	if prov.noAuth {
		return "not-required-for-local"
	}
	if k := os.Getenv(prov.keyEnv); k != "" {
		return k
	}
	if prov.keyEnvAlt != "" {
		if k := os.Getenv(prov.keyEnvAlt); k != "" {
			return k
		}
	}
	return ""
}

package astmatrix

import (
	"os"
	"regexp"
	"sort"
	"strings"
)

// provider holds runtime state for one upstream provider.
type provider struct {
	base      string
	keyEnv    string
	keyEnvAlt string
	noAuth    bool
	models    []string
}

// defaultProviders builds the provider table from the GENERATED canonical
// catalog (providers_generated.go — DO NOT EDIT BY HAND; source of truth is
// packages/providers/src/data.ts in the TS package, which is the brain).
// No model IDs are hardcoded here.
//
// Cold start: providers carry their generated seeds, dead-ID filtered. The
// Matrix overlays the LIVE serving sets from the TS-exported live catalog
// file (LiveCatalogReader.SyncProviderModels) — the answer, which is data.
// No discovery or quarantine logic lives in this binary.
//
// The extended registry (registry.go) merges in afterwards in deterministic
// (sorted) order: core catalog wins on collision, non-openai formats and
// empty BaseURLs are skipped.
func defaultProviders() map[string]*provider {
	dead := deadIDSet()
	providers := make(map[string]*provider, len(ProviderCatalogDefs))
	for _, d := range ProviderCatalogDefs {
		if !d.Enabled || d.RouterLocal {
			continue
		}
		providers[d.Name] = &provider{
			base:      d.BaseURL,
			keyEnv:    d.KeyEnv,
			keyEnvAlt: d.KeyEnvAlt,
			noAuth:    d.NoAuth,
			models:    filterDeadIDs(ProviderCatalogSeeds[d.Name], dead),
		}
	}

	// Merge extended providers from registry (skip duplicates, skip non-openai, skip empty BaseURL)
	ids := make([]string, 0, len(RegistryProviders))
	for id := range RegistryProviders {
		ids = append(ids, id)
	}
	sort.Strings(ids)
	for _, id := range ids {
		reg := RegistryProviders[id]
		if _, exists := providers[id]; exists {
			continue // core provider takes precedence
		}
		if reg.BaseURL == "" || reg.Format != "openai" {
			continue // can only route openai-format providers
		}
		var models []string
		for _, m := range reg.Models {
			models = append(models, m.ID)
		}
		providers[id] = &provider{
			base:   reg.BaseURL,
			keyEnv: keyEnvFor(id),
			noAuth: reg.NoAuth,
			models: models,
		}
	}
	return providers
}

// deadIDSet builds the dead-tier set from the generated list.
func deadIDSet() map[string]bool {
	set := make(map[string]bool, len(ProviderCatalogDeadIDs))
	for _, id := range ProviderCatalogDeadIDs {
		set[id] = true
	}
	return set
}

// filterDeadIDs removes permanently-dead ids from a seed list.
func filterDeadIDs(ids []string, dead map[string]bool) []string {
	out := make([]string, 0, len(ids))
	for _, id := range ids {
		if !dead[id] {
			out = append(out, id)
		}
	}
	return out
}

// aliasTargetServable reports whether an alias target is currently servable:
// not on the permanent dead list, and present in the provider's current
// serving set (which comes from the live catalog file, or generated seeds at
// cold start). Quarantined models are absent from the serving set, so this
// single membership check covers both guards. Data check, not logic.
func aliasTargetServable(providers map[string]*provider, prov, model string) bool {
	if deadIDSet()[model] {
		return false
	}
	p, ok := providers[prov]
	if !ok {
		return false
	}
	for _, id := range p.models {
		if id == model {
			return true
		}
	}
	return false
}

// codingAlias maps friendly alias -> [provider, model] or nil for auto/fcm.
// codingAlias is the merged alias table: the canonical generated aliases
// (ProviderCatalogAliases — source of truth is the TS package) plus
// bornite-local extras. Bornite-local wins on key collision.
var codingAlias = func() map[string][2]string {
	m := make(map[string][2]string, len(ProviderCatalogAliases)+len(herdLocalAliases))
	for k, v := range ProviderCatalogAliases {
		m[k] = v
	}
	for k, v := range herdLocalAliases {
		m[k] = v
	}
	return m
}()

// herdLocalAliases are bornite-specific aliases with NO canonical equivalent.
// Canonical aliases live in ProviderCatalogAliases (generated from @toxicwind/mimetite);
// anything duplicated there was removed 2026-09-30 - this map holds only true extras:
// strategy directives, local-role shortcuts, and extended-registry aliases
// (whose providers live in registry.go, not the core catalog).
var herdLocalAliases = map[string][2]string{
	// Auto routing (nil means use strategy)
	"auto": {},
	"fcm":  {},
	// Local-first ranked roles
	"fast":          {"bornite", "local-fast"},
	"local-fast":    {"bornite", "local-fast"},
	"quality":       {"bornite", "local-quality"},
	"local-quality": {"bornite", "local-quality"},
	"longctx":       {"bornite", "local-longctx"},
	"local-longctx": {"bornite", "local-longctx"},
	"local-auto":    {"bornite", "local-quality"},
	// OpenRouter free aliases (verified working 2026-07-28)
	"gpt-oss-20b": {"openrouter", "openai/gpt-oss-20b:free"},
	// NVIDIA NIM aliases
	"nim-llama-3.3-70b": {"nvidia", "meta/llama-3.3-70b-instruct"},
	// Extended provider aliases from registry
	"opencode":           {"opencode", "opencode"},
	"xai-grok-4":         {"xai", "grok-4"},
	"xai-grok-3":         {"xai", "grok-3"},
	"mimo-auto":          {"mimo-free", "mimo-auto"},
	"perplexity-sonar":   {"perplexity", "sonar-pro"},
	"together-llama-3.3": {"together", "meta-llama/Llama-3.3-70B-Instruct-Turbo"},
}

// localPatterns matches known local GGUF model ID prefixes.
var localPatterns = regexp.MustCompile(`^(beellama|mradermacher|jackrong|turboquant|ik_llama|ik_turboquant|holo|qwen/|gemma-4|exaone)`)

// isLocalSwapModelId returns true for model IDs that should route to the local bornite.
func isLocalSwapModelId(model string) bool {
	if model == "" || model == "auto" || model == "fcm" {
		return false
	}
	if target, ok := codingAlias[model]; ok && len(target) > 0 && target[0] == "bornite" {
		return true
	}
	return localPatterns.MatchString(model)
}

// resolveModel resolves a model name to (provider, modelID).
func resolveModel(model string, providers map[string]*provider) (string, string) {
	// Check coding aliases (guarded: dead or non-serving targets refused).
	if target, ok := codingAlias[model]; ok {
		if len(target) > 0 && target[0] != "" {
			if aliasTargetServable(providers, target[0], target[1]) {
				return target[0], target[1]
			}
		}
	}
	// Check if it's a local GGUF model ID
	if isLocalSwapModelId(model) {
		return "bornite", model
	}
	// Auto/fcm: search all providers by weighted ELO
	if model == "auto" || model == "fcm" {
		// Find first provider with a key and circuit ok
		for pname, p := range providers {
			if pname == "bornite" {
				continue
			}
			if p.noAuth || os.Getenv(p.keyEnv) != "" {
				if len(p.models) > 0 {
					return pname, p.models[0]
				}
			}
		}
		return "bornite", "local-quality"
	}
	// Search provider model lists
	for pname, p := range providers {
		for _, m := range p.models {
			if m == model {
				return pname, model
			}
		}
	}
	// Fallback: openrouter -> nvidia -> bornite
	if _, ok := providers["openrouter"]; ok {
		return "openrouter", model
	}
	if _, ok := providers["nvidia"]; ok {
		return "nvidia", model
	}
	return "bornite", "local-quality"
}

// isExplicit returns true if the model maps to a specific provider via coding aliases.
func isExplicit(model string) bool {
	target, ok := codingAlias[model]
	if !ok {
		return false
	}
	return len(target) > 0 && target[0] != ""
}

// astRe detects code/AST content in responses.
var astRe = regexp.MustCompile(`(def |class |import |from |function |const |let |var |#include|package |fn |pub |struct |impl |async |await |\.ts|\.py|\.rs|\.js|AST|tree-sitter|syntax|` + "```" + `)`)

func isAST(text string) bool {
	if text == "" {
		return false
	}
	if strings.Contains(text, "```") {
		return true
	}
	sample := text
	if len(sample) > 5000 {
		sample = sample[:5000]
	}
	return astRe.MatchString(sample)
}

package astmatrix

import (
	"math/rand"
	"os/exec"
	"strconv"
	"strings"
	"sync"
	"time"
)

// PerProviderRateLimiter tracks request rates per provider and implements
// exponential backoff when 429s are received from upstream APIs (notably
// NVIDIA NIM which returns 429 with no body when rate-limited).
type PerProviderRateLimiter struct {
	mu sync.Mutex

	// per-provider state
	requestTimestamps map[string][]time.Time   // rolling window of request timestamps
	backoffUntil      map[string]time.Time     // provider is prohibited until this time
	backoffDuration   map[string]time.Duration // current backoff duration (exponential)
	rateLimitCount    map[string]int           // consecutive 429 count per provider

	// GPU memory pressure (nvidia-smi) — when VRAM is tight, NIM may throttle
	lastGpuCheck time.Time
	gpuFreeMB    int
	gpuTotalMB   int

	// configuration
	windowDuration time.Duration // rolling window (default: 60s)
	maxRequests    int           // max requests per window (default: 60, NIM free tier)
	minBackoff     time.Duration // initial backoff (default: 5s)
	maxBackoff     time.Duration // max backoff (default: 120s)
	backoffFactor  float64       // exponential factor (default: 2.0)
	gpuThrottlePct float64       // GPU mem threshold % that triggers backoff (default: 90)
}

// NewRateLimiter creates a rate limiter with sensible defaults for NVIDIA NIM.
func NewRateLimiter() *PerProviderRateLimiter {
	return &PerProviderRateLimiter{
		requestTimestamps: make(map[string][]time.Time),
		backoffUntil:      make(map[string]time.Time),
		backoffDuration:   make(map[string]time.Duration),
		rateLimitCount:    make(map[string]int),
		windowDuration:    60 * time.Second,
		maxRequests:       200, // Higher limit for non-NVIDIA providers
		minBackoff:        5 * time.Second,
		maxBackoff:        120 * time.Second,
		backoffFactor:     2.0,
		gpuThrottlePct:    90.0,
	}
}

// CanRequest returns true if the provider can accept a request right now.
func (r *PerProviderRateLimiter) CanRequest(provider string) bool {
	r.mu.Lock()
	defer r.mu.Unlock()

	now := time.Now()

	// Check active backoff
	if until, ok := r.backoffUntil[provider]; ok {
		if now.Before(until) {
			return false
		}
		// backoff expired naturally — keep backoffDuration
		// so exponential growth persists across consecutive 429s
		delete(r.backoffUntil, provider)
	}

	// Prune old timestamps
	cutoff := now.Add(-r.windowDuration)
	if timestamps, ok := r.requestTimestamps[provider]; ok {
		pruned := timestamps[:0]
		for _, t := range timestamps {
			if t.After(cutoff) {
				pruned = append(pruned, t)
			}
		}
		r.requestTimestamps[provider] = pruned
	}

	// Check if within limit
	count := len(r.requestTimestamps[provider])
	if count >= r.maxRequests {
		return false
	}

	// Check GPU memory pressure for NVIDIA NIM
	if provider == "nvidia" {
		if now.Sub(r.lastGpuCheck) > 10*time.Second {
			r.checkGpuMemory()
		}
		if r.gpuTotalMB > 0 {
			freePct := float64(r.gpuFreeMB) / float64(r.gpuTotalMB) * 100.0
			if freePct < (100.0 - r.gpuThrottlePct) {
				return false
			}
		}
	}

	return true
}

// RecordRequest records that a request was made to the given provider.
func (r *PerProviderRateLimiter) RecordRequest(provider string) {
	r.mu.Lock()
	defer r.mu.Unlock()
	r.requestTimestamps[provider] = append(r.requestTimestamps[provider], time.Now())
}

// Record429 records a 429 with optional retry-after duration.
func (r *PerProviderRateLimiter) Record429(provider string, retryAfterDur time.Duration) {
	r.mu.Lock()
	defer r.mu.Unlock()

	r.rateLimitCount[provider]++

	var backoff time.Duration
	if retryAfterDur > 0 {
		backoff = retryAfterDur
		if backoff < r.minBackoff {
			backoff = r.minBackoff
		}
		// Don't reset backoffDuration to minBackoff — preserve
		// the existing exponential backoff state
		if r.backoffDuration[provider] <= 0 {
			r.backoffDuration[provider] = r.minBackoff
		}
	} else {
		existing := r.backoffDuration[provider]
		if existing <= 0 {
			existing = r.minBackoff
		}
		backoff = time.Duration(float64(existing) * r.backoffFactor)
		if backoff > r.maxBackoff {
			backoff = r.maxBackoff
		}
		r.backoffDuration[provider] = backoff
	}

	// Add full jitter (AWS/GCF best practice) to prevent thundering bornite
	// sleep = random(0, backoff) — spreads retries across the window
	jitter := time.Duration(rand.Int63n(int64(backoff)))
	r.backoffUntil[provider] = time.Now().Add(jitter)
}

// RecordSuccess resets backoff for a provider after a successful request.
func (r *PerProviderRateLimiter) RecordSuccess(provider string) {
	r.mu.Lock()
	defer r.mu.Unlock()
	delete(r.backoffUntil, provider)
	delete(r.backoffDuration, provider)
	r.rateLimitCount[provider] = 0
}

// checkGpuMemory runs nvidia-smi to get current VRAM stats.
func (r *PerProviderRateLimiter) checkGpuMemory() {
	r.lastGpuCheck = time.Now()
	cmd := exec.Command("nvidia-smi",
		"--query-gpu=memory.free,memory.total",
		"--format=csv,noheader,nounits",
	)
	out, err := cmd.Output()
	if err != nil {
		return
	}
	line := strings.TrimSpace(string(out))
	parts := strings.Split(line, ", ")
	if len(parts) < 2 {
		return
	}
	free, err1 := strconv.Atoi(strings.TrimSpace(parts[0]))
	total, err2 := strconv.Atoi(strings.TrimSpace(parts[1]))
	if err1 == nil && err2 == nil && total > 0 {
		r.gpuFreeMB = free
		r.gpuTotalMB = total
	}
}

// GetBackoffRemaining returns remaining backoff duration for a provider.
func (r *PerProviderRateLimiter) GetBackoffRemaining(provider string) time.Duration {
	r.mu.Lock()
	defer r.mu.Unlock()
	if until, ok := r.backoffUntil[provider]; ok {
		remaining := time.Until(until)
		if remaining > 0 {
			return remaining
		}
	}
	return 0
}

// GetGPUFreeMB returns last known free GPU memory in MB.
func (r *PerProviderRateLimiter) GetGPUFreeMB() int {
	r.mu.Lock()
	defer r.mu.Unlock()
	return r.gpuFreeMB
}

// parseRetryAfter parses Retry-After: seconds ("60") or HTTP-date format.
func parseRetryAfter(val string) time.Duration {
	if val == "" {
		return 0
	}
	seconds, err := strconv.Atoi(strings.TrimSpace(val))
	if err == nil && seconds > 0 {
		return time.Duration(seconds) * time.Second
	}
	t, err := time.Parse(time.RFC1123, val)
	if err != nil {
		t, err = time.Parse(httpDateFormat, val)
		if err != nil {
			return 0
		}
	}
	dur := time.Until(t)
	if dur > 0 {
		return dur
	}
	return 0
}

const httpDateFormat = "02 Jan 2006 15:04:05 GMT"

// parseRateLimitReset parses X-RateLimit-Reset: epoch seconds or ms.
func parseRateLimitReset(val string) time.Duration {
	if val == "" {
		return 0
	}
	ts, err := strconv.ParseInt(strings.TrimSpace(val), 10, 64)
	if err != nil {
		return 0
	}
	var t time.Time
	if ts > 1e12 {
		t = time.UnixMilli(ts)
	} else {
		t = time.Unix(ts, 0)
	}
	dur := time.Until(t)
	if dur > 0 {
		return dur
	}
	return 0
}

package astmatrix

import (
	"bytes"
	"context"
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"strings"
	"sync"
	"time"
)

// RouteResult is the outcome of a routing strategy.
type RouteResult struct {
	OK       bool
	Status   int
	Provider string
	Model    string
	Lat      float64
	Data     []byte
	Stream   io.ReadCloser
	Err      string
	Winner   int
}

// strategyFunc is the signature for routing strategies.
type strategyFunc func(ctx context.Context, m *Matrix, body map[string]interface{}, session string) RouteResult

// Router wraps Matrix and implements the router.Router interface so the
// server can dispatch cloud/chat models to remote providers via astmatrix.
type Router struct {
	config *AstMatrixConfig
	matrix *Matrix
}

// NewRouter creates a Router from config, initializing the provider matrix
// and health database.
func NewRouter(cfg *AstMatrixConfig) (*Router, error) {
	if cfg == nil {
		cfg = &AstMatrixConfig{}
	}
	cfg.Defaults()
	m, err := NewMatrix(cfg)
	if err != nil {
		return nil, fmt.Errorf("astmatrix.NewRouter: %w", err)
	}
	return &Router{config: cfg, matrix: m}, nil
}

// Handles reports whether this router can serve requests for the given model.
// It returns true for cloud model IDs that resolve via coding aliases or
// provider model lists — but NOT for local GGUF IDs (local dispatch takes
// priority in server.go).
func (r *Router) Handles(model string) bool {
	if model == "" {
		return false
	}
	// auto/fcm are always handled (strategy picks the provider)
	if model == "auto" || model == "fcm" || model == "free" {
		return true
	}
	// Explicit coding aliases map to specific cloud providers
	if isExplicit(model) {
		return true
	}
	// Check if any cloud provider lists this model
	for _, p := range r.matrix.Providers() {
		for _, mid := range p.models {
			if mid == model {
				return true
			}
		}
	}
	return false
}

// ServeHTTP routes an incoming OpenAI-compatible chat request to a cloud
// provider using the configured strategy.
func (r *Router) ServeHTTP(w http.ResponseWriter, req *http.Request) {
	// Read the full body
	body, err := io.ReadAll(req.Body)
	if err != nil {
		http.Error(w, "failed to read body", http.StatusBadRequest)
		return
	}
	req.Body.Close()

	var bodyMap map[string]interface{}
	if err := json.Unmarshal(body, &bodyMap); err != nil {
		http.Error(w, "invalid JSON body", http.StatusBadRequest)
		return
	}

	// Extract session for sticky affinity
	session := req.Header.Get("X-Session-Id")
	if session == "" {
		session = "default"
	}

	// Pick strategy from header or config
	strategyName := req.Header.Get("X-pens-scripts-Strategy")
	if strategyName == "" {
		strategyName = r.config.Strategy
	}

	strategyFn, ok := strategies[strategyName]
	if !ok {
		strategyFn = strategies["hybrid"]
	}

	// Detect streaming
	stream, _ := bodyMap["stream"].(bool)

	// Run the strategy
	result := strategyFn(context.Background(), r.matrix, bodyMap, session)

	if stream && result.OK && result.Stream != nil {
		// Streaming response
		w.Header().Set("Content-Type", "text/event-stream")
		w.Header().Set("Cache-Control", "no-cache")
		w.Header().Set("Connection", "keep-alive")
		w.Header().Set("X-Routed-Via", result.Provider)
		w.Header().Set("X-Strategy", strategyName)
		w.Header().Set("X-Latency", fmt.Sprintf("%.3f", result.Lat))
		w.WriteHeader(http.StatusOK)
		flusher, ok := w.(http.Flusher)
		if !ok {
			result.Stream.Close()
			return
		}
		io.Copy(w, result.Stream)
		result.Stream.Close()
		flusher.Flush()
		return
	}

	// Non-streaming response
	if !result.OK {
		errMsg := result.Err
		if errMsg == "" {
			errMsg = fmt.Sprintf("routing failed: status %d", result.Status)
		}
		w.Header().Set("Content-Type", "application/json")
		w.Header().Set("X-Routed-Via", result.Provider)
		w.WriteHeader(http.StatusBadGateway)
		json.NewEncoder(w).Encode(map[string]string{"error": errMsg})
		return
	}

	w.Header().Set("Content-Type", "application/json")
	w.Header().Set("X-Routed-Via", result.Provider)
	w.Header().Set("X-Strategy", strategyName)
	w.Header().Set("X-Latency", fmt.Sprintf("%.3f", result.Lat))
	w.WriteHeader(http.StatusOK)
	w.Write(result.Data)
}

// Close closes the health database.
func (r *Router) Close() error {
	if r.matrix != nil {
		return r.matrix.Close()
	}
	return nil
}

// Matrix returns the underlying Matrix for inspection (UI, tests).
func (r *Router) Matrix() *Matrix {
	return r.matrix
}

// callOne makes a single HTTP request to a provider and records the result.
func callOne(ctx context.Context, m *Matrix, provider, model string, body map[string]interface{}) RouteResult {
	if !m.CircuitOk(provider) {
		return RouteResult{Status: 503, Provider: provider, Err: "circuit_open"}
	}

	// Check per-provider rate limiter before making a request
	if m.rateLimiter != nil && !m.rateLimiter.CanRequest(provider) {
		backoff := m.rateLimiter.GetBackoffRemaining(provider)
		errMsg := "rate_limited_by_router"
		if backoff > 0 {
			errMsg = fmt.Sprintf("rate_limited_by_router: retry after %.0fs", backoff.Seconds())
		}
		m.Record(model, provider, 429, 0, 0, "", "")
		return RouteResult{Status: 429, Provider: provider, Err: errMsg}
	}

	prov, ok := m.providers[provider]
	if !ok {
		return RouteResult{Status: 500, Provider: provider, Err: "unknown_provider"}
	}

	url := strings.TrimRight(prov.base, "/") + "/chat/completions"
	headers := map[string]string{
		"Content-Type":    "application/json",
		"User-Agent":      "pens-scriptsASTMatrix/3.1",
		"Accept-Encoding": "identity",
	}
	if !prov.noAuth {
		headers["Authorization"] = "Bearer " + m.GetKey(provider)
	} else {
		headers["Authorization"] = "Bearer not-required-for-local"
	}
	if provider == "openrouter" {
		headers["HTTP-Referer"] = "https://zed.dev"
		headers["X-Title"] = "pens-scripts-AST-Matrix"
	}

	payload := make(map[string]interface{})
	for k, v := range body {
		payload[k] = v
	}
	payload["model"] = model
	stream, _ := body["stream"].(bool)
	payload["stream"] = stream

	bodyBytes, err := json.Marshal(payload)
	if err != nil {
		return RouteResult{Status: 500, Provider: provider, Err: "marshal_error"}
	}

	var timeout time.Duration
	if stream {
		timeout = 180 * time.Second
	} else {
		timeout = 120 * time.Second
	}
	ctx, cancel := context.WithTimeout(ctx, timeout)
	defer cancel()

	req, err := http.NewRequestWithContext(ctx, "POST", url, bytes.NewReader(bodyBytes))
	if err != nil {
		return RouteResult{Status: 500, Provider: provider, Err: "request_error"}
	}
	for k, v := range headers {
		req.Header.Set(k, v)
	}

	// Record request for rate limiting
	if m.rateLimiter != nil {
		m.rateLimiter.RecordRequest(provider)
	}

	start := time.Now()
	resp, err := http.DefaultClient.Do(req)
	lat := time.Since(start).Seconds()

	if err != nil {
		m.Record(model, provider, 500, lat, 0, "", "")
		return RouteResult{Status: 500, Provider: provider, Lat: lat, Err: err.Error()}
	}
	defer resp.Body.Close()

	if resp.StatusCode < 200 || resp.StatusCode >= 300 {
		errBody, _ := io.ReadAll(io.LimitReader(resp.Body, 500))

		// Extract 429 retry headers for rate limiter
		if resp.StatusCode == 429 && m.rateLimiter != nil {
			retryAfter := parseRetryAfter(resp.Header.Get("Retry-After"))
			rateLimitReset := parseRateLimitReset(resp.Header.Get("X-RateLimit-Reset"))
			retryDur := retryAfter
			if rateLimitReset > retryDur {
				retryDur = rateLimitReset
			}
			m.rateLimiter.Record429(provider, retryDur)
		}

		m.Record(model, provider, resp.StatusCode, lat, 0, "", "")
		if resp.StatusCode == 404 {
			// Report the 404 to the TS catalog brain (best-effort, async,
			// never blocks routing). The quarantine decision lives in the TS
			// package; bornite only reports the event. The TS side rewrites the
			// live catalog file and bornite picks it up on its next read.
			go reportServe404(provider, model)
		}
		return RouteResult{Status: resp.StatusCode, Provider: provider, Lat: lat, Err: string(errBody)}
	}

	// Record success to reset rate limiter backoff
	if m.rateLimiter != nil {
		m.rateLimiter.RecordSuccess(provider)
	}

	if stream {
		m.Record(model, provider, 200, lat, 0, "", "")
		return RouteResult{OK: true, Status: 200, Provider: provider, Model: model, Lat: lat, Stream: resp.Body}
	}

	data, err := io.ReadAll(resp.Body)
	if err != nil {
		m.Record(model, provider, 500, lat, 0, "", "")
		return RouteResult{Status: 500, Provider: provider, Lat: lat, Err: "read_error"}
	}
	m.Record(model, provider, 200, lat, 0, "", "")
	return RouteResult{OK: true, Status: 200, Provider: provider, Model: model, Lat: lat, Data: data}
}

// --- Strategies ---

func routeHybrid(ctx context.Context, m *Matrix, body map[string]interface{}, session string) RouteResult {
	model := getModel(body)
	if isExplicit(model) {
		p, mid := resolveModel(model, m.providers)
		r := callOne(ctx, m, p, mid, body)
		if r.OK {
			m.StickySet(session, p, mid)
			m.Record(mid, p, 200, r.Lat, 1, "hybrid_direct", session)
		}
		return r
	}
	sp, sm := m.StickyGet(session)
	if sp != "" && m.KeyOk(sp) && m.CircuitOk(sp) {
		if sm == "" {
			sm = model
		}
		r := callOne(ctx, m, sp, sm, body)
		if r.OK {
			return r
		}
	}
	r2 := routeAstRace(ctx, m, body, session)
	if r2.OK {
		return r2
	}
	return routeCircuitChain(ctx, m, body, session)
}

func routeAstRace(ctx context.Context, m *Matrix, body map[string]interface{}, session string) RouteResult {
	model := getModel(body)
	if isExplicit(model) {
		p, mid := resolveModel(model, m.providers)
		r := callOne(ctx, m, p, mid, body)
		if r.OK {
			m.StickySet(session, p, mid)
			m.Record(mid, p, 200, r.Lat, 1, "ast_race", session)
		}
		return r
	}
	cands := m.PickWeighted(m.config.MaxParallel)
	if len(cands) == 0 {
		return RouteResult{Status: 503, Err: "no_providers"}
	}
	type candidateResult struct {
		idx int
		r   RouteResult
	}
	results := make([]RouteResult, len(cands))
	var wg sync.WaitGroup
	for i, c := range cands {
		wg.Add(1)
		go func(idx int, p, mid string) {
			defer wg.Done()
			results[idx] = callOne(ctx, m, p, mid, body)
		}(i, c[0], c[1])
	}
	done := make(chan struct{})
	go func() {
		wg.Wait()
		close(done)
	}()
	select {
	case <-done:
	case <-time.After(95 * time.Second):
	}
	var best RouteResult
	for _, r := range results {
		if !r.OK {
			continue
		}
		if len(r.Data) > 0 {
			var parsed struct {
				Choices []struct {
					Message struct {
						Content string `json:"content"`
					} `json:"message"`
				} `json:"choices"`
			}
			if json.Unmarshal(r.Data, &parsed) == nil && len(parsed.Choices) > 0 {
				content := parsed.Choices[0].Message.Content
				if isAST(content) {
					m.StickySet(session, r.Provider, r.Model)
					m.Record(r.Model, r.Provider, 200, r.Lat, 1, "ast_race", session)
					return r
				}
			}
		}
		if !best.OK {
			best = r
		}
	}
	if best.OK {
		m.StickySet(session, best.Provider, best.Model)
		return best
	}
	return RouteResult{Status: 503, Err: "ast_race_exhausted"}
}

func routeSticky(ctx context.Context, m *Matrix, body map[string]interface{}, session string) RouteResult {
	model := getModel(body)
	if isExplicit(model) {
		return routeAstRace(ctx, m, body, session)
	}
	sp, sm := m.StickyGet(session)
	if sp != "" && m.KeyOk(sp) && m.CircuitOk(sp) {
		if sm == "" {
			sm = model
		}
		r := callOne(ctx, m, sp, sm, body)
		if r.OK {
			return r
		}
	}
	return routeAstRace(ctx, m, body, session)
}

func routeWeighted(ctx context.Context, m *Matrix, body map[string]interface{}, session string) RouteResult {
	cands := m.PickWeighted(1)
	if len(cands) == 0 {
		return RouteResult{Status: 503, Err: "no_providers"}
	}
	p, mid := cands[0][0], cands[0][1]
	r := callOne(ctx, m, p, mid, body)
	if r.OK {
		m.StickySet(session, p, mid)
	}
	return r
}

func routeCircuitChain(ctx context.Context, m *Matrix, body map[string]interface{}, session string) RouteResult {
	model := getModel(body)
	if isExplicit(model) {
		p, mid := resolveModel(model, m.providers)
		if m.KeyOk(p) && m.CircuitOk(p) {
			r := callOne(ctx, m, p, mid, body)
			if r.OK {
				m.StickySet(session, p, mid)
				return r
			}
		}
		return RouteResult{Status: 502, Err: fmt.Sprintf("explicit_provider_unavailable:%s", p)}
	}
	type provScore struct {
		name  string
		score float64
	}
	providers := m.Providers()
	var all []provScore
	for name := range providers {
		all = append(all, provScore{name, m.ELO(name)})
	}
	for i := 0; i < len(all); i++ {
		for j := i + 1; j < len(all); j++ {
			if all[j].score > all[i].score {
				all[i], all[j] = all[j], all[i]
			}
		}
	}
	for _, ps := range all {
		if !m.KeyOk(ps.name) || !m.CircuitOk(ps.name) {
			continue
		}
		mid := firstModelFor(ps.name)
		if mid == "" {
			continue
		}
		r := callOne(ctx, m, ps.name, mid, body)
		if r.OK {
			m.StickySet(session, ps.name, mid)
			return r
		}
	}
	return RouteResult{Status: 503, Err: "circuit_chain_exhausted"}
}

func routeFifo(ctx context.Context, m *Matrix, body map[string]interface{}, session string) RouteResult {
	m.mu.Lock()
	if m.fifoDepth >= m.config.FifoMax {
		m.mu.Unlock()
		return RouteResult{Status: 429, Err: "fifo_full"}
	}
	m.fifoDepth++
	m.mu.Unlock()
	defer func() {
		m.mu.Lock()
		if m.fifoDepth > 0 {
			m.fifoDepth--
		}
		m.mu.Unlock()
	}()
	return routeAstRace(ctx, m, body, session)
}

func routeFree(ctx context.Context, m *Matrix, body map[string]interface{}, session string) RouteResult {
	model := getModel(body)
	if isExplicit(model) {
		p, mid := resolveModel(model, m.providers)
		if strings.Contains(mid, ":free") || p == "bornite" {
			r := callOne(ctx, m, p, mid, body)
			if r.OK {
				m.StickySet(session, p, mid)
				m.Record(mid, p, 200, r.Lat, 1, "free", session)
			}
			return r
		}
	}
	var cands [][2]string
	for name, prov := range m.Providers() {
		if !m.KeyOk(name) || !m.CircuitOk(name) {
			continue
		}
		for _, mid := range prov.models {
			if strings.Contains(mid, ":free") {
				cands = append(cands, [2]string{name, mid})
			}
		}
	}
	if m.KeyOk("bornite") {
		cands = append(cands, [2]string{"bornite", "local-quality"})
	}
	if len(cands) == 0 {
		return RouteResult{Status: 503, Err: "no_free_providers"}
	}
	return raceCandidates(ctx, m, body, session, cands, "free")
}

func raceCandidates(ctx context.Context, m *Matrix, body map[string]interface{}, session string, cands [][2]string, strategy string) RouteResult {
	if len(cands) > m.config.MaxParallel {
		cands = cands[:m.config.MaxParallel]
	}
	results := make([]RouteResult, len(cands))
	var wg sync.WaitGroup
	for i, c := range cands {
		wg.Add(1)
		go func(idx int, p, mid string) {
			defer wg.Done()
			results[idx] = callOne(ctx, m, p, mid, body)
		}(i, c[0], c[1])
	}
	done := make(chan struct{})
	go func() { wg.Wait(); close(done) }()
	select {
	case <-done:
	case <-time.After(95 * time.Second):
	}
	var best RouteResult
	for _, r := range results {
		if !r.OK {
			continue
		}
		if len(r.Data) > 0 {
			var parsed struct {
				Choices []struct {
					Message struct {
						Content string `json:"content"`
					} `json:"message"`
				} `json:"choices"`
			}
			if json.Unmarshal(r.Data, &parsed) == nil && len(parsed.Choices) > 0 {
				content := parsed.Choices[0].Message.Content
				if isAST(content) {
					m.StickySet(session, r.Provider, r.Model)
					m.Record(r.Model, r.Provider, 200, r.Lat, 1, strategy, session)
					return r
				}
			}
		}
		if !best.OK {
			best = r
		}
	}
	if best.OK {
		m.StickySet(session, best.Provider, best.Model)
		return best
	}
	return RouteResult{Status: 503, Err: strategy + "_exhausted"}
}

var strategies = map[string]strategyFunc{
	"hybrid":          routeHybrid,
	"ast_race":        routeAstRace,
	"sticky_affinity": routeSticky,
	"weighted_elo":    routeWeighted,
	"circuit_chain":   routeCircuitChain,
	"fifo_matrix":     routeFifo,
	"free":            routeFree,
}

func getModel(body map[string]interface{}) string {
	if m, ok := body["model"].(string); ok {
		return m
	}
	return "auto"
}

func extractModelFromBody(r *http.Request) string {
	if r.Body == nil || r.Method != http.MethodPost {
		return ""
	}
	body, err := io.ReadAll(r.Body)
	if err != nil {
		return ""
	}
	r.Body = io.NopCloser(bytes.NewReader(body))
	var parsed struct {
		Model string `json:"model"`
	}
	if err := json.Unmarshal(body, &parsed); err != nil {
		return ""
	}
	return parsed.Model
}

// Package bench: autofix.go — update OMP models.yml to disable dead models.
package bench

import (
	"fmt"
	"os"
	"path/filepath"
	"sort"

	"gopkg.in/yaml.v3"
)

// ModelsYML is the on-disk shape of ~/.omp/agent/models.yml.
// We only touch the provider.modelOverrides.<model>.disabled field.
type ModelsYML struct {
	Providers map[string]ProviderConfig `yaml:"providers"`
}

// ProviderConfig is one provider block in models.yml.
type ProviderConfig struct {
	BaseURL        string                    `yaml:"baseUrl"`
	API            string                    `yaml:"api"`
	Auth           string                    `yaml:"auth"`
	Discovery      map[string]any            `yaml:"discovery"`
	ModelOverrides map[string]map[string]any `yaml:"modelOverrides"`
}

// DefaultModelsYMLPath is the OMP-side config file the autofix mutates.
func DefaultModelsYMLPath() string {
	home, _ := os.UserHomeDir()
	return filepath.Join(home, ".omp", "agent", "models.yml")
}

// LoadModelsYML reads models.yml, returning an empty schema if missing.
func LoadModelsYML(path string) (*ModelsYML, error) {
	data, err := os.ReadFile(path)
	if err != nil {
		if os.IsNotExist(err) {
			return &ModelsYML{Providers: map[string]ProviderConfig{}}, nil
		}
		return nil, err
	}
	var m ModelsYML
	if err := yaml.Unmarshal(data, &m); err != nil {
		return nil, fmt.Errorf("parse models.yml: %w", err)
	}
	if m.Providers == nil {
		m.Providers = map[string]ProviderConfig{}
	}
	return &m, nil
}

// Save writes the models.yml back to disk atomically.
func (m *ModelsYML) Save(path string) error {
	data, err := yaml.Marshal(m)
	if err != nil {
		return err
	}
	if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
		return err
	}
	tmp := path + ".tmp"
	if err := os.WriteFile(tmp, data, 0o644); err != nil {
		return err
	}
	return os.Rename(tmp, path)
}

// ApplyAutofix mutates the provider's modelOverrides:
//   - dead models get disabled: true
//   - working models have any existing disabled flag removed
//
// Returns the count of newly-disabled and re-enabled models.
func (m *ModelsYML) ApplyAutofix(provider string, working, dead []string) (disabled, enabled int) {
	p, ok := m.Providers[provider]
	if !ok {
		p = ProviderConfig{ModelOverrides: map[string]map[string]any{}}
	}
	if p.ModelOverrides == nil {
		p.ModelOverrides = map[string]map[string]any{}
	}
	for _, d := range dead {
		entry, exists := p.ModelOverrides[d]
		if !exists {
			entry = map[string]any{}
		}
		if _, ok := entry["disabled"]; !ok {
			disabled++
		}
		entry["disabled"] = true
		p.ModelOverrides[d] = entry
	}
	for _, w := range working {
		entry, exists := p.ModelOverrides[w]
		if !exists {
			continue
		}
		if _, ok := entry["disabled"]; ok {
			delete(entry, "disabled")
			enabled++
		}
		if len(entry) == 0 {
			delete(p.ModelOverrides, w)
		} else {
			p.ModelOverrides[w] = entry
		}
	}
	m.Providers[provider] = p
	return disabled, enabled
}

// EnsureHerdProvider idempotently inserts a bornite provider block pointing at
// the local proxy. Safe to call when the file exists — does not overwrite
// other providers.
func (m *ModelsYML) EnsureHerdProvider(baseURL string) {
	if m.Providers == nil {
		m.Providers = map[string]ProviderConfig{}
	}
	if _, ok := m.Providers["bornite"]; !ok {
		m.Providers["bornite"] = ProviderConfig{
			BaseURL: baseURL,
			API:     "openai-completions",
			Auth:    "none",
			Discovery: map[string]any{
				"type":     "openai-models-list",
				"injectV1": true,
			},
			ModelOverrides: map[string]map[string]any{},
		}
	}
}

// DisabledModels returns the sorted list of model IDs with disabled: true.
func (m *ModelsYML) DisabledModels(provider string) []string {
	p, ok := m.Providers[provider]
	if !ok {
		return nil
	}
	var out []string
	for id, ov := range p.ModelOverrides {
		if v, ok := ov["disabled"]; ok {
			if b, _ := v.(bool); b {
				out = append(out, id)
			}
		}
	}
	sort.Strings(out)
	return out
}

// autofix_test.go — tests for the OMP models.yml mutator.
package bench

import (
	"os"
	"path/filepath"
	"testing"

	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"
)

func TestLoadModelsYML_Missing(t *testing.T) {
	dir := t.TempDir()
	path := filepath.Join(dir, "models.yml")
	m, err := LoadModelsYML(path)
	require.NoError(t, err)
	assert.Empty(t, m.Providers)
}

func TestLoadModelsYML_Roundtrip(t *testing.T) {
	dir := t.TempDir()
	path := filepath.Join(dir, "models.yml")
	initial := `providers:
  bornite:
    baseUrl: http://127.0.0.1:25100/v1
    api: openai-completions
    auth: none
    modelOverrides:
      dead-model:
        disabled: true
`
	require.NoError(t, os.WriteFile(path, []byte(initial), 0o644))

	m, err := LoadModelsYML(path)
	require.NoError(t, err)
	require.Contains(t, m.Providers, "bornite")
	assert.Equal(t, "http://127.0.0.1:25100/v1", m.Providers["bornite"].BaseURL)
}

func TestLoadModelsYML_Corrupt(t *testing.T) {
	dir := t.TempDir()
	path := filepath.Join(dir, "bad.yml")
	require.NoError(t, os.WriteFile(path, []byte(":\n  - broken"), 0o644))
	_, err := LoadModelsYML(path)
	assert.Error(t, err)
}

func TestModelsYML_SaveAtomic(t *testing.T) {
	dir := t.TempDir()
	path := filepath.Join(dir, "models.yml")
	m := &ModelsYML{Providers: map[string]ProviderConfig{}}
	require.NoError(t, m.Save(path))
	_, err := os.Stat(path + ".tmp")
	assert.True(t, os.IsNotExist(err), "tmp file should be renamed away")
}

func TestModelsYML_SaveCreatesParentDirs(t *testing.T) {
	dir := t.TempDir()
	path := filepath.Join(dir, "a", "b", "c", "models.yml")
	m := &ModelsYML{Providers: map[string]ProviderConfig{}}
	require.NoError(t, m.Save(path))
	_, err := os.Stat(path)
	assert.NoError(t, err)
}

func TestEnsureHerdProvider_AddsWhenMissing(t *testing.T) {
	m := &ModelsYML{Providers: map[string]ProviderConfig{}}
	m.EnsureHerdProvider("http://127.0.0.1:25100/v1")
	require.Contains(t, m.Providers, "bornite")
	assert.Equal(t, "http://127.0.0.1:25100/v1", m.Providers["bornite"].BaseURL)
	assert.Equal(t, "openai-completions", m.Providers["bornite"].API)
	assert.Equal(t, "none", m.Providers["bornite"].Auth)
}

func TestEnsureHerdProvider_Idempotent(t *testing.T) {
	m := &ModelsYML{Providers: map[string]ProviderConfig{}}
	m.EnsureHerdProvider("http://first/v1")
	original := m.Providers["bornite"]
	m.EnsureHerdProvider("http://second/v1")
	assert.Equal(t, original, m.Providers["bornite"], "second call must not clobber")
}

func TestApplyAutofix_DisablesDead(t *testing.T) {
	m := &ModelsYML{Providers: map[string]ProviderConfig{}}
	d, e := m.ApplyAutofix("bornite", []string{"a", "b"}, []string{"x", "y"})
	assert.Equal(t, 2, d)
	assert.Equal(t, 0, e)
	assert.True(t, m.Providers["bornite"].ModelOverrides["x"]["disabled"].(bool))
	assert.True(t, m.Providers["bornite"].ModelOverrides["y"]["disabled"].(bool))
}

func TestApplyAutofix_ReenablesWorking(t *testing.T) {
	m := &ModelsYML{Providers: map[string]ProviderConfig{
		"bornite": {ModelOverrides: map[string]map[string]any{
			"a": {"disabled": true},
			"b": {"disabled": true},
		}},
	}}
	d, e := m.ApplyAutofix("bornite", []string{"a", "b"}, nil)
	assert.Equal(t, 0, d)
	assert.Equal(t, 2, e)
	_, hasA := m.Providers["bornite"].ModelOverrides["a"]
	_, hasB := m.Providers["bornite"].ModelOverrides["b"]
	assert.False(t, hasA, "empty override should be removed")
	assert.False(t, hasB)
}

