// Package capcompat discovers what an upstream inference server can do and
// maps the answer onto bornite's model capabilities.
//
// Every supported server exposes /v1/models, and the owned_by field in that
// listing identifies the server family. Detect fetches the listing once, picks
// the matching Prober, and lets it query whatever else it needs. A server
// nobody recognises is not an error worth shouting about: bornite also
// fronts image, speech and transcription servers that have no capability
// surface at all.
//
// The data is only readable while the server is running, so callers cache what
// Detect returns. See Service.
package capcompat

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"net"
	"net/http"
	"net/url"
	"strings"
	"time"

	"github.com/toxicwind/bornite/internal/config"
)

// ErrUnsupportedUpstream is returned by Detect when no prober recognises the
// server. It is an expected outcome, not a failure to report loudly.
var ErrUnsupportedUpstream = errors.New("capcompat: unsupported upstream")

// Info is what Detect produces and what callers cache.
type Info struct {
	// Upstream is the server family that answered, e.g. "llama-server".
	Upstream string `json:"upstream"`
	// Capabilities is the discovered subset. Fields a server cannot report
	// are left at their zero value, never guessed.
	Capabilities config.ModelCapConfig `json:"capabilities"`
	// DetectedAt is when the probe ran.
	DetectedAt time.Time `json:"detected_at"`
}

// ModelEntry is one record of an OpenAI-compatible /v1/models listing. It
// carries the union of the fields the supported servers add to the standard
// shape; a server that omits one leaves it at its zero value.
type ModelEntry struct {
	ID      string `json:"id"`
	Object  string `json:"object"`
	OwnedBy string `json:"owned_by"`

	// MaxModelLen is vLLM's context length for this entry. Halogen reports
	// it too.
	MaxModelLen int `json:"max_model_len"`
	// ContextLength is the same number under the name Halogen also publishes.
	ContextLength int `json:"context_length"`
	// Root and Parent are vLLM's adapter lineage. A LoRA adapter has a
	// non-empty Parent naming the base model it is served on top of.
	Root   string `json:"root"`
	Parent string `json:"parent"`

	// Meta is the model metadata block llama-server and Halogen both use.
	Meta struct {
		// NCtx is the context actually loaded. NCtxTrain is the model's
		// training limit, which is usually larger and is never a capability.
		NCtx      int `json:"n_ctx"`
		NCtxTrain int `json:"n_ctx_train"`
		NParams   int `json:"n_params"`
	} `json:"meta"`
}

// ContextTokens returns the usable context length this entry reports, or 0
// when it reports none.
//
// Servers spell it differently, so the names are tried in order of how
// specific they are: max_model_len, then context_length, then meta.n_ctx.
// meta.n_ctx_train is deliberately excluded. It is what the model was trained
// for, not what the server loaded, and advertising it would promise a window
// the server will refuse to fill.
func (e ModelEntry) ContextTokens() int {
	switch {
	case e.MaxModelLen > 0:
		return e.MaxModelLen
	case e.ContextLength > 0:
		return e.ContextLength
	default:
		return e.Meta.NCtx
	}
}

// listingOnlyCaps builds capabilities for a server whose model listing is the
// only thing it exposes to this package: text in and out, plus whatever
// context length the matched entry reports.
//
// Find skips adapter entries, whose context belongs to the adapter rather
// than to the base model being served.
func listingOnlyCaps(models ModelsResponse, modelName string) config.ModelCapConfig {
	caps := config.ModelCapConfig{
		In:  []string{"text"},
		Out: []string{"text"},
	}
	if entry, found := models.Find(modelName); found {
		caps.Context = entry.ContextTokens()
	}
	return caps
}

// ModelsResponse is an OpenAI-compatible /v1/models listing.
type ModelsResponse struct {
	Object string       `json:"object"`
	Data   []ModelEntry `json:"data"`
}

// OwnedBy returns the owner reported by the listing. Servers report it per
// entry rather than at the top level, so the first non-empty value wins.
func (m ModelsResponse) OwnedBy() string {
	for _, entry := range m.Data {
		if owner := strings.TrimSpace(entry.OwnedBy); owner != "" {
			return owner
		}
	}
	return ""
}

// Find returns the entry for modelName, or the best stand-in when the name
// does not appear. Servers are free to list a model under a path, an alias or
// a name the client never sees, so an exact miss falls back to the first
// entry that is not an adapter of another model.
func (m ModelsResponse) Find(modelName string) (ModelEntry, bool) {
	name := strings.TrimSpace(modelName)
	if name != "" {
		for _, entry := range m.Data {
			if entry.ID == name {
				return entry, true
			}
		}
	}
	for _, entry := range m.Data {
		if entry.Parent == "" {
			return entry, true
		}
	}
	if len(m.Data) > 0 {
		return m.Data[0], true
	}
	return ModelEntry{}, false
}

// Prober knows one upstream server family: how to recognise it from its model
// listing, and what else to ask it.
type Prober interface {
	// Name identifies the family, and is stored in Info.Upstream.
	Name() string

	// Matches reports whether the listing came from this family.
	Matches(models ModelsResponse) bool

	// Probe maps the server's answers onto capabilities. It may issue more
	// requests through c. Fields the server cannot report are left unset.
	Probe(ctx context.Context, c *Client, models ModelsResponse, modelName string) (config.ModelCapConfig, error)
}

// defaultProbers is the registry Detect consults, in order.
func defaultProbers() []Prober {
	return []Prober{llamaServerProber{}, vllmProber{}, halogenProber{}}
}

// Detect identifies the upstream behind c and returns what it reports about
// modelName. modelName is the name the upstream knows the model by, which is
// useModelName when set and the bornite model ID otherwise; it only matters
// for servers that list more than one model.
//
// It returns ErrUnsupportedUpstream when no prober recognises the server.
func Detect(ctx context.Context, c *Client, modelName string) (Info, error) {
	var models ModelsResponse
	if err := c.GetJSON(ctx, "/v1/models", &models); err != nil {
		return Info{}, fmt.Errorf("capcompat: reading model list: %w", err)
	}

	for _, prober := range defaultProbers() {
		if !prober.Matches(models) {
			continue
		}
		caps, err := prober.Probe(ctx, c, models, modelName)
		if err != nil {
			return Info{}, fmt.Errorf("capcompat: probing %s: %w", prober.Name(), err)
		}
		if err := caps.Validate(); err != nil {
			return Info{}, fmt.Errorf("capcompat: %s reported invalid capabilities: %w", prober.Name(), err)
		}
		return Info{
			Upstream:     prober.Name(),
			Capabilities: caps,
			DetectedAt:   time.Now(),
		}, nil
	}

	owner := models.OwnedBy()
	if owner == "" {
		owner = "unknown"
	}
	return Info{}, fmt.Errorf("%w (owned_by %q)", ErrUnsupportedUpstream, owner)
}

// Client performs GET requests against one upstream server.
type Client struct {
	base       *url.URL
	httpClient *http.Client
	headers    http.Header
}

// maxResponseBytes caps how much of an upstream response is read. /props
// carries a full chat template and is comfortably under this; anything
// larger is not a response this package knows how to use.
const maxResponseBytes = 8 << 20

// NewClient returns a Client for base, honouring the model's proxy timeouts.
// A zero timeout in the config means no timeout, matching the rest of
// bornite, but the overall request deadline still comes from the context.
func NewClient(base *url.URL, timeouts config.TimeoutsConfig) *Client {
	transport := &http.Transport{
		Proxy: http.ProxyFromEnvironment,
		// Same dialer settings the model's own reverse proxy transport uses,
		// so a probe respects timeouts.connect instead of hanging on a dial
		// until the probe deadline.
		DialContext: (&net.Dialer{
			Timeout:   time.Duration(timeouts.Connect) * time.Second,
			KeepAlive: time.Duration(timeouts.KeepAlive) * time.Second,
		}).DialContext,
		TLSHandshakeTimeout:   time.Duration(timeouts.TLSHandshake) * time.Second,
		ResponseHeaderTimeout: time.Duration(timeouts.ResponseHeader) * time.Second,
		ExpectContinueTimeout: time.Duration(timeouts.ExpectContinue) * time.Second,
		IdleConnTimeout:       time.Duration(timeouts.IdleConn) * time.Second,
	}
	return &Client{
		base:       base,
		httpClient: &http.Client{Transport: transport},
		headers:    http.Header{},
	}
}

// SetHeader sets a header sent with every request, such as an API key.
func (c *Client) SetHeader(key, value string) {
	if c == nil || value == "" {
		return
	}
	c.headers.Set(key, value)
}

// GetJSON fetches path relative to the client's base URL and decodes the body
// into v. A non-2xx response is an error carrying the status.
func (c *Client) GetJSON(ctx context.Context, path string, v any) error {
	target := c.base.JoinPath(path)

	req, err := http.NewRequestWithContext(ctx, http.MethodGet, target.String(), nil)
	if err != nil {
		return fmt.Errorf("building %s request: %w", path, err)
	}
	req.Header.Set("Accept", "application/json")
	for key, values := range c.headers {
		for _, value := range values {
			req.Header.Add(key, value)
		}
	}

	resp, err := c.httpClient.Do(req)
	if err != nil {
		return fmt.Errorf("requesting %s: %w", path, err)
	}
	defer resp.Body.Close()

	if resp.StatusCode < 200 || resp.StatusCode > 299 {
		io.Copy(io.Discard, io.LimitReader(resp.Body, 4096))
		return fmt.Errorf("requesting %s: upstream returned %s", path, resp.Status)
	}

	body, err := io.ReadAll(io.LimitReader(resp.Body, maxResponseBytes))
	if err != nil {
		return fmt.Errorf("reading %s: %w", path, err)
	}
	if err := json.Unmarshal(body, v); err != nil {
		return fmt.Errorf("decoding %s: %w", path, err)
	}
	return nil
}

package capcompat

import (
	"context"
	"encoding/json"
	"net/http"
	"net/http/httptest"
	"net/url"
	"os"
	"path/filepath"
	"testing"

	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"

	"github.com/toxicwind/bornite/internal/config"
)

// The fixtures under testdata/ are built from the documented response shapes:
// llama.cpp's tools/server/README.md for /props and /v1/models, its
// common/jinja/caps.h for the chat_template_caps key names, and vLLM's
// OpenAI-compatible model listing. They are not captures from a live server.
// Before relying on the tools mapping in production, re-capture props.json and
// props_vision.json from real builds and confirm supports_tools actually
// differs between a tool-capable model and a plain completion model; several
// of those flags are initialised to true in llama.cpp's C++ struct.
//
// The exceptions are real captures. props_capture.json,
// v1_models_capture.json and v1_models_capture_qwen.json come from running
// llama-servers, and confirm the modality key set (vision, video, audio).
//
// The first two are from DIFFERENT servers and are only paired in a test to
// exercise the code path: 262144 in that listing is not an integer multiple
// of 220160 in that /props, so llama.cpp could not have produced both from
// one process. Do not read a conclusion about one server out of that pair.
// v1_models_capture.json was also truncated in transit inside its meta
// block; the fields after n_params were dropped rather than invented, and
// the prober does not read them.
//
// v1_models_capture_qwen.json is complete and self-consistent, which is why
// the n_ctx assertions live there.
//
// vllm/v1_models_capture.json is also a verbatim capture. The other vllm
// file, with its LoRA adapter entry, is still synthetic.
//
// The halogen fixtures are the exception: v1_models.json and health.json are
// verbatim captures from a running halogen-flash-server. The two other
// halogen files are that same capture with vision turned off, and with the
// supported list and tool-call block removed, to cover builds configured
// differently. Their derivation is noted where they are used.

// fixture reads a testdata file.
func fixture(t *testing.T, parts ...string) []byte {
	t.Helper()
	data, err := os.ReadFile(filepath.Join(append([]string{"testdata"}, parts...)...))
	require.NoError(t, err)
	return data
}

// upstream is a fake inference server. routes maps a path to a fixture body;
// any path not in the map answers 404.
type upstream struct {
	server *httptest.Server
	hits   map[string]int
}

func newUpstream(t *testing.T, routes map[string][]byte) *upstream {
	t.Helper()
	u := &upstream{hits: map[string]int{}}
	mux := http.NewServeMux()
	mux.HandleFunc("/", func(w http.ResponseWriter, r *http.Request) {
		u.hits[r.URL.Path]++
		body, ok := routes[r.URL.Path]
		if !ok {
			http.NotFound(w, r)
			return
		}
		w.Header().Set("Content-Type", "application/json")
		w.Write(body)
	})
	u.server = httptest.NewServer(mux)
	t.Cleanup(u.server.Close)
	return u
}

func (u *upstream) client(t *testing.T) *Client {
	t.Helper()
	base, err := url.Parse(u.server.URL)
	require.NoError(t, err)
	return NewClient(base, config.TimeoutsConfig{})
}

func TestCapcompat_DetectLlamaServer(t *testing.T) {
	up := newUpstream(t, map[string][]byte{
		"/v1/models": fixture(t, "llama-server", "v1_models.json"),
		"/props":     fixture(t, "llama-server", "props.json"),
	})

	info, err := Detect(context.Background(), up.client(t), "model-a")
	require.NoError(t, err)

	assert.Equal(t, "llama-server", info.Upstream)
	assert.Equal(t, []string{"text"}, info.Capabilities.In)
	assert.Equal(t, []string{"text"}, info.Capabilities.Out)
	assert.True(t, info.Capabilities.Tools)
	assert.Equal(t, 32768, info.Capabilities.Context, "uses the loaded n_ctx, not n_ctx_train")
	assert.False(t, info.Capabilities.Reranker, "reranker is not discoverable")
	assert.False(t, info.DetectedAt.IsZero())
}

func TestCapcompat_DetectLlamaServerVision(t *testing.T) {
	up := newUpstream(t, map[string][]byte{
		"/v1/models": fixture(t, "llama-server", "v1_models.json"),
		"/props":     fixture(t, "llama-server", "props_vision.json"),
	})

	info, err := Detect(context.Background(), up.client(t), "model-a")
	require.NoError(t, err)

	assert.Equal(t, []string{"text", "image"}, info.Capabilities.In)
	assert.Equal(t, []string{"text"}, info.Capabilities.Out)
	assert.False(t, info.Capabilities.Tools, "template reports no tool support")
	assert.Equal(t, 8192, info.Capabilities.Context)
}

func TestCapcompat_DetectLlamaServerIgnoresUnmappedModalities(t *testing.T) {
	up := newUpstream(t, map[string][]byte{
		"/v1/models": fixture(t, "llama-server", "v1_models.json"),
		"/props":     fixture(t, "llama-server", "props_omni.json"),
	})

	info, err := Detect(context.Background(), up.client(t), "model-a")
	require.NoError(t, err)

	// This fixture reports the three real modality keys plus a made up one.
	// All three map; the unrecognised key must be dropped rather than passed
	// through, where it would fail ModelCapConfig.Validate.
	assert.Equal(t, []string{"text", "image", "audio", "video"}, info.Capabilities.In)
	require.NoError(t, info.Capabilities.Validate())
}

func TestCapcompat_DetectLlamaServerCapture(t *testing.T) {
	// Verbatim from running llama-servers. A text-only build reports all
	// three modality keys as false, which is what confirmed their names.
	//
	// These two files are from different servers, so the only thing the
	// context assertion below shows is that the prober reads /props and not
	// the listing. It is not evidence about any one deployment.
	up := newUpstream(t, map[string][]byte{
		"/v1/models": fixture(t, "llama-server", "v1_models_capture.json"),
		"/props":     fixture(t, "llama-server", "props_capture.json"),
