package capcompat

import (
	"context"
	"strings"

	"github.com/toxicwind/bornite/internal/config"
)

// halogenOwner is what halogen-flash-server reports in /v1/models.
const halogenOwner = "halogen"

// halogenHealth is the subset of halogen-flash-server's GET /health that
// describes what the running build accepts. Its own documentation calls that
// endpoint the authoritative account of the build's capabilities, and it is
// the only place several of them appear: the model listing carries context
// and nothing else.
type halogenHealth struct {
	// Context is the loaded context window. slot_ctx reports the same number
	// per slot on the deployments seen so far.
	Context int `json:"context"`

	// Vision is absent or disabled unless the server was started with a
	// vision tower, so image input genuinely varies per deployment and has
	// to be read rather than assumed for the engine.
	Vision struct {
		Enabled bool `json:"enabled"`
	} `json:"vision"`

	// ToolCalls describes the tool-call wire format. A build without tool
	// support has nothing to describe.
	ToolCalls struct {
		WireFormat string `json:"wire_format"`
	} `json:"tool_calls"`

	// Supported lists the request fields the build accepts, "tools" among
	// them. This is the server stating what it takes, so it is the primary
	// signal.
	Supported []string `json:"supported"`
}

// halogenProber reads capabilities from halogen-flash-server, an
// OpenAI-compatible engine for Qwen3.8-Flash-Next on AMD Strix Halo.
//
// It reads /v1/models for the model entry and /health for everything else.
// The listing publishes the context length under three names at once
// (max_model_len, context_length and meta.n_ctx), all agreeing, but says
// nothing about images or tools.
//
// Reranking is not reported anywhere and stays a manual setting.
type halogenProber struct{}

var _ Prober = halogenProber{}

func (halogenProber) Name() string { return "halogen" }

func (halogenProber) Matches(models ModelsResponse) bool {
	return strings.EqualFold(models.OwnedBy(), halogenOwner)
}

func (p halogenProber) Probe(ctx context.Context, c *Client, models ModelsResponse, modelName string) (config.ModelCapConfig, error) {
	var health halogenHealth
	if err := c.GetJSON(ctx, "/health", &health); err != nil {
		return config.ModelCapConfig{}, err
	}

	caps := config.ModelCapConfig{
		In:  []string{"text"},
		Out: []string{"text"},
	}
	if health.Vision.Enabled {
		caps.In = append(caps.In, "image")
	}
	caps.Tools = health.supportsTools()

	// /health is the authoritative report, so its context wins. The listing
	// is the fallback for a build that omits it.
	caps.Context = health.Context
	if caps.Context == 0 {
		// max_tokens_cap and max_tokens_default bound one request's output
		// rather than the window, so they are deliberately not read here.
		caps.Context = listingOnlyCaps(models, modelName).Context
	}
	return caps, nil
}

// supportsTools reports whether the build accepts tool calls. The supported
// list is the server naming the request fields it takes; the wire format is
// a second signal for a build that does not publish that list.
func (h halogenHealth) supportsTools() bool {
	for _, field := range h.Supported {
		if strings.EqualFold(field, "tools") {
			return true
		}
	}
	return strings.TrimSpace(h.ToolCalls.WireFormat) != ""
}

package capcompat

import (
	"context"
	"strings"

	"github.com/toxicwind/bornite/internal/config"
)

// llamaServerOwner is what llama-server and its forks report in /v1/models.
const llamaServerOwner = "llamacpp"

// propsResponse is the subset of llama-server's GET /props that describes what
// the loaded model can do.
type propsResponse struct {
	// DefaultGenerationSettings.NCtx is the context one generation slot is
	// configured with, which is the window a single request is bounded by
	// and so the number a client needs.
	//
	// meta.n_ctx in /v1/models is the context the model was loaded with,
	// across all slots. llama.cpp sizes a slot with n_ctx_slot(), which an
	// operator can cap independently with --kv-unified-per-slot, so the two
	// agree on a single-slot server and the listing can be the larger of the
	// two otherwise. Reading the listing would then advertise a window no
	// one request can fill.
	DefaultGenerationSettings struct {
		NCtx int `json:"n_ctx"`
	} `json:"default_generation_settings"`

	// Modalities is decoded as a map so a modality added upstream does not
	// break parsing. Known keys are mapped below; the rest are ignored.
	Modalities map[string]bool `json:"modalities"`

	// ChatTemplateCaps is what llama.cpp detected about the model's chat
	// template. Older builds omit it entirely.
	ChatTemplateCaps map[string]bool `json:"chat_template_caps"`

	ChatTemplate string `json:"chat_template"`
}

// modalityForProp maps a llama-server modality key onto a bornite input
// modality. Text is always supported and is added unconditionally.
//
// All three keys are confirmed against a running server, which reports
// {"vision":false,"video":false,"audio":false} for a text-only build. Keys
// outside this map are dropped rather than passed through, where an
// unrecognised name would fail ModelCapConfig.Validate.
var modalityForProp = map[string]string{
	"vision": "image",
	"audio":  "audio",
	"video":  "video",
}

// llamaServerProber reads capabilities from llama-server's /props endpoint.
// It also covers the forks that keep llama.cpp's server API, such as
// ik_llama.cpp, because they report the same owner.
type llamaServerProber struct{}

var _ Prober = llamaServerProber{}

func (llamaServerProber) Name() string { return "llama-server" }

func (llamaServerProber) Matches(models ModelsResponse) bool {
	return strings.EqualFold(models.OwnedBy(), llamaServerOwner)
}

func (p llamaServerProber) Probe(ctx context.Context, c *Client, _ ModelsResponse, _ string) (config.ModelCapConfig, error) {
	var props propsResponse
	if err := c.GetJSON(ctx, "/props", &props); err != nil {
		return config.ModelCapConfig{}, err
	}

	caps := config.ModelCapConfig{
		// llama-server always accepts and produces text. Everything else is
		// additive and depends on what the build reports.
		In:  []string{"text"},
		Out: []string{"text"},
	}

	for prop, modality := range modalityForProp {
		if props.Modalities[prop] {
			caps.In = append(caps.In, modality)
		}
	}
	// Map iteration order is random, so keep the list stable for callers and
	// for the cached blob.
	sortModalities(caps.In)

	caps.Tools = p.supportsTools(props)
	caps.Context = props.DefaultGenerationSettings.NCtx

	// reranker is not reported by /props. A reranking server answers
	// /v1/rerank, but probing it would mean sending a real request, so it
	// stays a manual setting.
	return caps, nil
}

// supportsTools reports whether the loaded chat template can carry tools.
//
// llama.cpp reports this in chat_template_caps, where supports_tools means
// the template renders a tool list and supports_tool_calls means it can read
// tool calls back. Both are required for a usable round trip, and requiring
// both also guards against the C++ struct's true defaults leaking through on
// a template llama.cpp could not fully inspect.
//
// Builds predating chat_template_caps omit the object. There the only signal
// left is the template itself, which is not conclusive, so this falls back to
// looking for a tools loop in the template source.
func (llamaServerProber) supportsTools(props propsResponse) bool {
	if len(props.ChatTemplateCaps) > 0 {
		return props.ChatTemplateCaps["supports_tools"] && props.ChatTemplateCaps["supports_tool_calls"]
	}
	return strings.Contains(props.ChatTemplate, "tools")
}

// modalityOrder fixes the order modalities are listed in, so a discovered
// value is byte-stable across probes.
var modalityOrder = map[string]int{"text": 0, "image": 1, "audio": 2, "video": 3}

func sortModalities(ms []string) {
	for i := 1; i < len(ms); i++ {
		for j := i; j > 0 && modalityOrder[ms[j]] < modalityOrder[ms[j-1]]; j-- {
			ms[j], ms[j-1] = ms[j-1], ms[j]
		}
	}
}

package capcompat

import (
	"context"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"errors"
	"fmt"
	"sync"
	"time"

	"github.com/toxicwind/bornite/internal/config"
	"github.com/toxicwind/bornite/internal/logmon"
	"github.com/toxicwind/bornite/internal/store"
)

const (
	// cacheTTL bounds how long a discovered value survives without being
	// rewritten. Every model start refreshes its entry, so this only sweeps
	// up models that were removed from the config.
	cacheTTL = 30 * 24 * time.Hour

	// probeTimeout caps one Refresh, retries included.
	probeTimeout = 10 * time.Second
)

// probeAttempts is how many times a refresh tries before giving up. A model
// configured with `checkEndpoint: none` is reported ready before it is
// listening, so the first attempt can legitimately be refused.
//
// probeRetryDelay separates those attempts. Both are variables so tests can
// run the retry paths without spending real seconds on them.
var (
	probeAttempts   = 3
	probeRetryDelay = time.Second
)

// Service reads and writes discovered capabilities, backed by a store cache
// and fronted by an in-memory memo.
//
// The memo is not an optimisation detail. Clients poll /v1/models, and every
// model in the listing is a lookup, so without it each listing would be a
// burst of SQLite reads. Misses are memoized too: a model whose upstream is
// not supported must not re-query the database on every request.
//
// All methods are safe on a nil *Service, which reports no capabilities and
// stores nothing. That keeps the /v1/models path working for callers that
// construct a Server without one.
type Service struct {
	cache  store.CacheRepository
	logger *logmon.Monitor

	mu   sync.RWMutex
	memo map[string]memoEntry

	// inflight guards against stacking probes for the same key when a model
	// flaps between ready and stopped.
	inflightMu sync.Mutex
	inflight   map[string]struct{}
}

// memoEntry is a remembered lookup. found is false for a remembered miss.
type memoEntry struct {
	caps  config.ModelCapConfig
	found bool
}

// New returns a Service backed by cache. A nil cache disables persistence;
// lookups then only ever see what this process discovered.
func New(cache store.CacheRepository, logger *logmon.Monitor) *Service {
	return &Service{
		cache:    cache,
		logger:   logger,
		memo:     make(map[string]memoEntry),
		inflight: make(map[string]struct{}),
	}
}

// LocalKey returns the cache key for a local model.
//
// The hash covers the fields that decide what the upstream will report, so
// editing a model's command invalidates its entry instead of serving values
// discovered from the old one.
func LocalKey(modelID string, mc config.ModelConfig) string {
	sum := sha256.Sum256([]byte(mc.Cmd + "\x00" + mc.Proxy + "\x00" + mc.UseModelName))
	return "capcompat:v1:local:" + modelID + ":" + hex.EncodeToString(sum[:4])
}

// UpstreamModelName returns the name the upstream knows this model by.
func UpstreamModelName(modelID string, mc config.ModelConfig) string {
	if mc.UseModelName != "" {
		return mc.UseModelName
	}
	return modelID
}

// Lookup returns the capabilities cached under key. The second return value
// is false when nothing has been discovered for it.
//
// The store is read at most once per key; later calls are answered from
// memory until Refresh replaces the entry.
func (s *Service) Lookup(ctx context.Context, key string) (config.ModelCapConfig, bool) {
	if s == nil {
		return config.ModelCapConfig{}, false
	}

	s.mu.RLock()
	entry, memoized := s.memo[key]
	s.mu.RUnlock()
	if memoized {
		return entry.caps, entry.found
	}

	info, found, err := s.read(ctx, key)
	if err != nil {
		// A failed read is not memoized: the next request should try again.
		s.logf("capcompat: reading cache for %s: %v", key, err)
		return config.ModelCapConfig{}, false
	}

	s.remember(key, info.Capabilities, found)
	return info.Capabilities, found
}

// Refresh probes the upstream behind c and stores what it reports under key.
//
// It is the write half of the cache and is meant to be called when a model
// becomes ready. An unsupported upstream is recorded as a miss so the listing
// path stops asking the store about it.
func (s *Service) Refresh(ctx context.Context, key string, c *Client, modelName string) error {
	if s == nil {
		return nil
	}
	if !s.claim(key) {
		return nil
	}
	defer s.release(key)

	ctx, cancel := context.WithTimeout(ctx, probeTimeout)
	defer cancel()

	info, err := s.detect(ctx, c, modelName)
	if err != nil {
		if errors.Is(err, ErrUnsupportedUpstream) {
			// Not every upstream has capabilities to report. Drop anything
			// stored under this key first: a server can be replaced by one
			// bornite does not recognise without cmd, proxy or
			// useModelName changing, and the key would still be the same.
			// The memo would hide the old row for the life of the process,
			// but a restart starts with an empty memo and would serve it.
			if s.cache != nil {
				if err := s.cache.Delete(ctx, key); err != nil {
					return fmt.Errorf("capcompat: dropping stale %s: %w", key, err)
				}
			}
			// Remember the miss so /v1/models stops hitting the store.
			s.remember(key, config.ModelCapConfig{}, false)
			s.logf("capcompat: %s: %v", key, err)
			return nil
		}
		return err
	}

	blob, err := json.Marshal(info)
	if err != nil {
		return fmt.Errorf("capcompat: encoding %s: %w", key, err)
	}

	// Remember before persisting. The probe succeeded either way, so a store
	// that cannot be written should cost durability across a restart, not the
	// value this process just learned.
	s.remember(key, info.Capabilities, true)
	s.logf("capcompat: %s reported by %s: %s", key, info.Upstream, describe(info.Capabilities))

	if s.cache != nil {
		if err := s.cache.Set(ctx, store.CacheEntry{
			Key:       key,
			Data:      blob,
			TTL:       cacheTTL,
			Timestamp: info.DetectedAt,
		}); err != nil {
			return fmt.Errorf("capcompat: caching %s: %w", key, err)
		}
	}

	return nil
}

// detect runs Detect, retrying a connection that is not answering yet. An
// upstream that answers and is simply not supported is returned immediately;
// retrying would not change the answer.
func (s *Service) detect(ctx context.Context, c *Client, modelName string) (Info, error) {
	var lastErr error
	for attempt := 0; attempt < probeAttempts; attempt++ {
		if attempt > 0 {
			select {
			case <-ctx.Done():
				return Info{}, ctx.Err()
			case <-time.After(probeRetryDelay):
			}
		}

		info, err := Detect(ctx, c, modelName)
		if err == nil {
			return info, nil
		}
		if errors.Is(err, ErrUnsupportedUpstream) || ctx.Err() != nil {
			return Info{}, err
		}
		lastErr = err
	}
	return Info{}, lastErr
}

// read loads and decodes one cache entry.
func (s *Service) read(ctx context.Context, key string) (Info, bool, error) {
	if s.cache == nil {
		return Info{}, false, nil
	}
	entry, found, err := s.cache.Get(ctx, key)
	if err != nil || !found {
		return Info{}, false, err
	}

	var info Info
	if err := json.Unmarshal(entry.Data, &info); err != nil {
		// A row we cannot read is worse than no row: drop it so the next
		// model start can write a good one.
		if delErr := s.cache.Delete(ctx, key); delErr != nil {
			s.logf("capcompat: dropping unreadable cache entry %s: %v", key, delErr)
		}
		return Info{}, false, fmt.Errorf("capcompat: decoding cached %s: %w", key, err)
	}
	if info.Capabilities.Empty() {
		return Info{}, false, nil
	}
	return info, true, nil
}

// Forget drops the memoized answer for key, so the next Lookup reads the
// store again. Used when the configuration behind a key may have changed.
func (s *Service) Forget(key string) {
	if s == nil {
		return
	}
	s.mu.Lock()
	delete(s.memo, key)
	s.mu.Unlock()
}

func (s *Service) remember(key string, caps config.ModelCapConfig, found bool) {
	s.mu.Lock()
	s.memo[key] = memoEntry{caps: caps, found: found}
	s.mu.Unlock()
}

// claim reserves key for a probe, reporting false when one is already running.
func (s *Service) claim(key string) bool {
	s.inflightMu.Lock()
	defer s.inflightMu.Unlock()
	if _, busy := s.inflight[key]; busy {
		return false
	}
	s.inflight[key] = struct{}{}
	return true
}

func (s *Service) release(key string) {
	s.inflightMu.Lock()
	delete(s.inflight, key)
	s.inflightMu.Unlock()
}

func (s *Service) logf(format string, args ...any) {
	if s == nil || s.logger == nil {
		return
	}
	s.logger.Debugf(format, args...)
}

// describe renders capabilities for a log line.
func describe(caps config.ModelCapConfig) string {
	return fmt.Sprintf("in=%v out=%v tools=%t context=%d", caps.In, caps.Out, caps.Tools, caps.Context)
}

