package capcompat

import (
	"context"
	"strings"

	"github.com/toxicwind/bornite/internal/config"
)

// vllmOwner is what vLLM reports in /v1/models.
const vllmOwner = "vllm"

// vllmProber reads capabilities from vLLM's /v1/models listing.
//
// vLLM is deliberately thin here. Its listing carries max_model_len, which is
// the most requested field, but nothing it serves reveals whether the server
// was started with --enable-auto-tool-choice or whether the model accepts
// images: /version, /health and /server_info do not report either. So tools
// and non-text modalities stay manual settings for vLLM models, and the guide
// says so.
type vllmProber struct{}

var _ Prober = vllmProber{}

func (vllmProber) Name() string { return "vllm" }

func (vllmProber) Matches(models ModelsResponse) bool {
	return strings.EqualFold(models.OwnedBy(), vllmOwner)
}

func (vllmProber) Probe(_ context.Context, _ *Client, models ModelsResponse, modelName string) (config.ModelCapConfig, error) {
	return listingOnlyCaps(models, modelName), nil
}

package config

import (
	"log"
	"errors"
	"fmt"
	"os"
	"sort"

	"gopkg.in/yaml.v3"
)

const DEFAULT_GROUP_ID = "(default)"
const DEFAULT_UNLOAD_TIMEOUT = 10
const (
	LogToStdoutProxy    = "proxy"
	LogToStdoutUpstream = "upstream"
	LogToStdoutBoth     = "both"
	LogToStdoutNone     = "none"
)

type MacroEntry struct {
	Name  string
	Value any
}

type MacroList []MacroEntry

func (ml *MacroList) UnmarshalYAML(value *yaml.Node) error {
	if value.Kind != yaml.MappingNode {
		return fmt.Errorf("macros must be a mapping")
	}
	entries := make([]MacroEntry, 0, len(value.Content)/2)
	for i := 0; i < len(value.Content); i += 2 {
		keyNode := value.Content[i]
		valueNode := value.Content[i+1]
		var name string
		if err := keyNode.Decode(&name); err != nil {
			return fmt.Errorf("failed to decode macro name: %w", err)
		}
		var val any
		if err := valueNode.Decode(&val); err != nil {
			return fmt.Errorf("failed to decode macro value for '%s': %w", name, err)
		}
		entries = append(entries, MacroEntry{Name: name, Value: val})
	}
	*ml = entries
	return nil
}

// MarshalYAML renders the list back as an ordered mapping, the shape it is
// written in, rather than the default slice-of-structs. Only diagnostics such
// as the config__get_config tool marshal a Config, but when they do the macro
// block should read like the source file.
func (ml MacroList) MarshalYAML() (interface{}, error) {
	node := &yaml.Node{Kind: yaml.MappingNode, Tag: "!!map"}
	for _, entry := range ml {
		var key, value yaml.Node
		if err := key.Encode(entry.Name); err != nil {
			return nil, fmt.Errorf("encoding macro name %q: %w", entry.Name, err)
		}
		if err := value.Encode(entry.Value); err != nil {
			return nil, fmt.Errorf("encoding macro value for %q: %w", entry.Name, err)
		}
		node.Content = append(node.Content, &key, &value)
	}
	return node, nil
}

// Get retrieves a macro value by name
