func (c *Config) RealModelName(search string) (string, bool) {
	if _, found := c.Models[search]; found {
		return search, true
	} else if name, found := c.aliases[search]; found {
		return name, found
	} else {
		return "", false
	}
}
func (c *Config) TailcatEnabled() bool {
	return c.tailcatEnabled
}

func (c *Config) SetTailcatEnabled(enabled bool) {
	c.tailcatEnabled = enabled
}

func (c *Config) FindConfig(modelName string) (ModelConfig, string, bool) {
	if realName, found := c.RealModelName(modelName); !found {
		return ModelConfig{}, "", false
	} else {
		return c.Models[realName], realName, true
	}
}

func (c *Config) ResolveBaseModel(search string) (string, bool) {
	if realName, found := c.RealModelName(search); found {
		return realName, true
	}
	if _, _, found := c.ResolvePeerModel(search); found {
		return search, true
	}
	return "", false
}

func LoadConfig(path string) (Config, error) {
	file, err := os.Open(path)
	if err != nil {
		return Config{}, err
	}
	defer file.Close()
	cfg, err := LoadConfigFromReader(file)
	if err != nil {
		// A CORS block that fails validation must not fail the load: fall
		// back to the last-known-good policy (persisted beside the config)
		// so the server still starts.
		var corsErr *corsValidationError
		if !errors.As(err, &corsErr) {
			return Config{}, err
		}
		return loadConfigWithCORSFallback(path, err)
	}
	// The CORS policy validated: remember it as the last known good so a
	// future bad edit can fall back to it. Best-effort; never fatal.
	if err := saveGoodCORS(path, cfg.Security.CORS); err != nil {
		log.Printf("bornite: warning: could not persist last-known-good CORS policy: %v", err)
	}
	return cfg, nil
}

func AddDefaultGroupToConfig(config Config) Config {
	if config.Groups == nil {
		config.Groups = make(map[string]GroupConfig)
	}
	defaultGroup := GroupConfig{
		Swap:      true,
		Exclusive: true,
		Members:   []string{},
	}
	if len(config.Groups) == 0 {
		for modelName := range config.Models {
			defaultGroup.Members = append(defaultGroup.Members, modelName)
		}
	} else {
		for modelName := range config.Models {
			foundModel := false
		found:
			for _, groupConfig := range config.Groups {
				for _, member := range groupConfig.Members {
					if member == modelName {
						foundModel = true
						break found
					}
				}
			}
			if !foundModel {
				defaultGroup.Members = append(defaultGroup.Members, modelName)
			}
		}
	}
	sort.Strings(defaultGroup.Members)
	config.Groups[DEFAULT_GROUP_ID] = defaultGroup
	return config
}

