package config

import (
	"fmt"
	"io"
	"net/url"
	"reflect"
	"sort"
	"strings"
	"time"

	"gopkg.in/yaml.v3"
)

func LoadConfigFromReader(r io.Reader) (Config, error) {
	data, err := io.ReadAll(r)
	if err != nil {
		return Config{}, err
	}
	yamlStr := string(data)

	// Phase 1: Substitute all ${env.VAR} macros at string level
	// This is safe because env values are simple strings without YAML formatting
	yamlStr, err = substituteEnvMacros(yamlStr)
	if err != nil {
		return Config{}, err
	}

	raw, macroConfig, err := resolveConfigMacros(yamlStr)
	if err != nil {
		return Config{}, err
	}

	var node yaml.Node
	if err = node.Encode(raw); err != nil {
		return Config{}, err
	}

	// Decode the resolved values into the full Config with defaults.
	config := Config{
		HealthCheckTimeout: 120,
		StartPort:          5800,
		LogLevel:           "info",
		LogTimeFormat:      "",
		LogToStdout:        LogToStdoutProxy,
		MetricsMaxInMemory: 1000,
		CaptureBuffer:      5,
		GlobalTTL:          0,
		UnloadTimeout:      DEFAULT_UNLOAD_TIMEOUT,
		UI: UIConfig{Activity: UIActivityConfig{SessionID: []string{
			"X-Session-ID",
			"X-Litellm-Session-Id",
		}}},
	}
	// yaml.v3's Node.Decode silently discards any key the target struct does
	// not declare. That is not a cosmetic problem: bornite.yaml carried a
	// top-level `aliases:` block for months that parsed cleanly, produced no
	// warning, and was never served by anything. The only yaml:"aliases" tag
	// in the tree is on ModelConfig (models.<id>.aliases), so the block was
	// dropped at every load and the four names in it only resolved because
	// models: re-declared them separately.
	// Strictness is applied to the TOP LEVEL only, by reflecting over the
	// Config struct's yaml tags. A recursive decoder is not usable here:
	// KnownFields(true) also applies inside the legacy `filters.strip_params`
	// anonymous-struct path, which exists precisely to tolerate fields it
	// does not model, and enforcing it there rejects configs that must load.
	if err = rejectUnknownTopLevelKeys(&node); err != nil {
		return Config{}, err
	}
	if err = node.Decode(&config); err != nil {
		return Config{}, err
	}
	config.Macros = macroConfig.Macros
	for modelID, modelConfig := range config.Models {
		modelConfig.Macros = macroConfig.Models[modelID].Macros
		config.Models[modelID] = modelConfig
	}

	if config.HealthCheckTimeout < 15 {
		config.HealthCheckTimeout = 15
	}

	// Apply defaults for performance config when section is missing
	if config.Performance.Every == 0 {
		config.Performance.Every = 5 * time.Second
	}
	if err = config.Performance.Validate(); err != nil {
		return Config{}, fmt.Errorf("performance: %w", err)
	}

	// A missing security block keeps the permissive legacy CORS policy, but
	// callers read cfg.Security unconditionally, so always materialize it.
	// Validation runs on every load: an empty allowedOrigins list or orphan
	// CORS settings are rejected here, not at request time.
	if config.Security == nil {
		config.Security = &SecurityConfig{}
	}
	if err = config.Security.CORS.Validate(); err != nil {
		return Config{}, &corsValidationError{err: fmt.Errorf("security.cors: %w", err)}
	}

	if config.StartPort < 1 {
		return Config{}, fmt.Errorf("startPort must be greater than 1")
	}

	if config.GlobalTTL < 0 {
		return Config{}, fmt.Errorf("globalTTL must be >= 0")
	}

	if config.UnloadTimeout < 0 {
		return Config{}, fmt.Errorf("unloadTimeout must be >= 0")
	}
	if config.UnloadTimeout == 0 {
		config.UnloadTimeout = DEFAULT_UNLOAD_TIMEOUT
	}

	config.UI.Activity.SessionID = normalizeHeaderNames(config.UI.Activity.SessionID)

	if config.Store != nil {
		if err := validateStorePath(config.Store.Path); err != nil {
			return Config{}, err
		}
	}

	// Apply default for upstream.ignorePaths when not specified. The default
	// matches common static-asset suffixes so they do not trigger a swap.
	if len(config.Upstream.IgnorePaths) == 0 {
		config.Upstream.IgnorePaths = DefaultUpstreamIgnorePaths()
	}

	switch config.LogToStdout {
	case LogToStdoutProxy, LogToStdoutUpstream, LogToStdoutBoth, LogToStdoutNone:
	default:
		return Config{}, fmt.Errorf("logToStdout must be one of: proxy, upstream, both, none")
	}

	// Security defaults and validation. A missing security block still
	// yields a non-nil Security so the zero CORSConfig selects the legacy
	// permissive policy; Validate rejects an explicitly empty
	// allowedOrigins list rather than reading it as "allow everything".
	if config.Security == nil {
		config.Security = &SecurityConfig{}
	}
	if err := config.Security.CORS.Validate(); err != nil {
		return Config{}, fmt.Errorf("security.cors: %w", err)
	}

	// Tailcat allow-list canonicalization and model validation. Like the
	// CORS check above, the validator existed but was never invoked from
	// the load path.
	if err := validateTailcatConfig(&config); err != nil {
		return Config{}, err
	}

	// Populate the aliases map
	config.aliases = make(map[string]string)
	for modelName, modelConfig := range config.Models {
		for _, alias := range modelConfig.Aliases {
			if _, found := config.aliases[alias]; found {
				return Config{}, fmt.Errorf("duplicate alias %s found in model: %s", alias, modelName)
			}
			config.aliases[alias] = modelName
		}
	}

	// Sort model IDs for deterministic validation and normalization.
	modelIds := make([]string, 0, len(config.Models))
	for modelId := range config.Models {
		modelIds = append(modelIds, modelId)
	}
	sort.Strings(modelIds)

	nextPort := config.StartPort
	for _, modelId := range modelIds {
		modelConfig := config.Models[modelId]
		modelConfig.HealthCheckTimeout = config.HealthCheckTimeout
		if modelId == ComfyUIModelID {
			if modelConfig.ConcurrencyLimit < comfyUIConcurrencyLimit {
				modelConfig.ConcurrencyLimit = comfyUIConcurrencyLimit
			}
			modelConfig.Compat.IgnoreWebsockets = true
		}

		// set model TTL to globalTTL it is the default value
		if modelConfig.UnloadAfter == MODEL_CONFIG_DEFAULT_TTL {
			modelConfig.UnloadAfter = config.GlobalTTL
		}

		if modelConfig.UnloadAfter < 0 {
			return Config{}, fmt.Errorf("model %s: invalid TTL value %d", modelId, modelConfig.UnloadAfter)
		}

		// set model unloadTimeout to the global value when left at the default
		if modelConfig.UnloadTimeout < 0 {
			return Config{}, fmt.Errorf("model %s: invalid unloadTimeout value %d", modelId, modelConfig.UnloadTimeout)
		}
		if modelConfig.UnloadTimeout == 0 {
			modelConfig.UnloadTimeout = config.UnloadTimeout
		}

		// Validate model macros
		for _, macro := range modelConfig.Macros {
			if err = validateMacro(macro.Name, macro.Value); err != nil {
				return Config{}, fmt.Errorf("model %s: %s", modelId, err.Error())
			}
		}

		// Build merged macro list: MODEL_ID + global macros + model macros (model overrides global)
		mergedMacros := make(MacroList, 0, len(config.Macros)+len(modelConfig.Macros)+1)
		mergedMacros = append(mergedMacros, MacroEntry{Name: "MODEL_ID", Value: modelId})
		mergedMacros = append(mergedMacros, config.Macros...)

		// Add model macros (override globals with same name)
		for _, entry := range modelConfig.Macros {
			found := false
			for i, existing := range mergedMacros {
				if existing.Name == entry.Name {
					mergedMacros[i] = entry
					found = true
					break
				}
			}
			if !found {
				mergedMacros = append(mergedMacros, entry)
			}
		}

		// Substitute remaining macros in model fields (LIFO order)
		for i := len(mergedMacros) - 1; i >= 0; i-- {
			entry := mergedMacros[i]
			macroSlug := fmt.Sprintf("${%s}", entry.Name)
			macroStr := fmt.Sprintf("%v", entry.Value)

			modelConfig.Cmd = strings.ReplaceAll(modelConfig.Cmd, macroSlug, macroStr)
			modelConfig.CmdStop = strings.ReplaceAll(modelConfig.CmdStop, macroSlug, macroStr)
			modelConfig.Proxy = strings.ReplaceAll(modelConfig.Proxy, macroSlug, macroStr)
			modelConfig.CheckEndpoint = strings.ReplaceAll(modelConfig.CheckEndpoint, macroSlug, macroStr)
			modelConfig.Filters.StripParams = strings.ReplaceAll(modelConfig.Filters.StripParams, macroSlug, macroStr)
			modelConfig.Name = strings.ReplaceAll(modelConfig.Name, macroSlug, macroStr)
			modelConfig.Description = strings.ReplaceAll(modelConfig.Description, macroSlug, macroStr)

			// Substitute macros in Env (string slice)
			for j, envEntry := range modelConfig.Env {
				modelConfig.Env[j] = strings.ReplaceAll(envEntry, macroSlug, macroStr)
			}

			// Substitute macros in SetParamsByID keys and values
			if len(modelConfig.Filters.SetParamsByID) > 0 {
				newSetParamsByID := make(map[string]map[string]any, len(modelConfig.Filters.SetParamsByID))
				for key, paramMap := range modelConfig.Filters.SetParamsByID {
					newKey := strings.ReplaceAll(key, macroSlug, macroStr)
					newValAny := substituteMacroInValue(any(paramMap), entry.Name, entry.Value)
					newParamMap, ok := newValAny.(map[string]any)
					if !ok {
						return Config{}, fmt.Errorf("model %s filters.setParamsByID: unexpected type after macro substitution", modelId)
					}
					newSetParamsByID[newKey] = newParamMap
				}
				modelConfig.Filters.SetParamsByID = newSetParamsByID
			}

			// Substitute in metadata (type-preserving)
			if len(modelConfig.Metadata) > 0 {
				result := substituteMacroInValue(modelConfig.Metadata, entry.Name, entry.Value)
				modelConfig.Metadata = result.(map[string]any)
			}
		}

		// Resolve macros in capabilities (they couldn't be decoded properly
		// during YAML unmarshal because e.g. "${default_ctx}" is not an int).
		if err := modelConfig.Capabilities.Validate(); err != nil {
			return Config{}, fmt.Errorf("model %s: %w", modelId, err)
		}

		// Handle PORT macro - only allocate if cmd uses it
		cmdHasPort := strings.Contains(modelConfig.Cmd, "${PORT}")
		proxyHasPort := strings.Contains(modelConfig.Proxy, "${PORT}")
		if cmdHasPort || proxyHasPort {
			if !cmdHasPort && proxyHasPort {
				return Config{}, fmt.Errorf("model %s: proxy uses ${PORT} but cmd does not - ${PORT} is only available when used in cmd", modelId)
			}

			macroSlug := "${PORT}"
			macroStr := fmt.Sprintf("%v", nextPort)

			modelConfig.Cmd = strings.ReplaceAll(modelConfig.Cmd, macroSlug, macroStr)
			modelConfig.CmdStop = strings.ReplaceAll(modelConfig.CmdStop, macroSlug, macroStr)
			modelConfig.Proxy = strings.ReplaceAll(modelConfig.Proxy, macroSlug, macroStr)
			modelConfig.Name = strings.ReplaceAll(modelConfig.Name, macroSlug, macroStr)
			modelConfig.Description = strings.ReplaceAll(modelConfig.Description, macroSlug, macroStr)

			for j, envEntry := range modelConfig.Env {
				modelConfig.Env[j] = strings.ReplaceAll(envEntry, macroSlug, macroStr)
			}

			if len(modelConfig.Metadata) > 0 {
				result := substituteMacroInValue(modelConfig.Metadata, "PORT", nextPort)
				modelConfig.Metadata = result.(map[string]any)
			}

			nextPort++
		}

		// Validate no unknown macros remain
		fieldMap := map[string]string{
			"cmd":                 modelConfig.Cmd,
			"cmdStop":             modelConfig.CmdStop,
			"proxy":               modelConfig.Proxy,
			"checkEndpoint":       modelConfig.CheckEndpoint,
			"filters.stripParams": modelConfig.Filters.StripParams,
			"name":                modelConfig.Name,
			"description":         modelConfig.Description,
		}

		for fieldName, fieldValue := range fieldMap {
			matches := macroPatternRegex.FindAllStringSubmatch(fieldValue, -1)
			for _, match := range matches {
				macroName := match[1]
				if macroName == "PID" && fieldName == "cmdStop" {
					continue // replaced at runtime
				}
				if macroName == "PORT" || macroName == "MODEL_ID" {
					return Config{}, fmt.Errorf("macro '${%s}' should have been substituted in %s.%s", macroName, modelId, fieldName)
				}
				return Config{}, fmt.Errorf("unknown macro '${%s}' found in %s.%s", macroName, modelId, fieldName)
			}
		}

		for _, envEntry := range modelConfig.Env {
			matches := macroPatternRegex.FindAllStringSubmatch(envEntry, -1)
			for _, match := range matches {
				macroName := match[1]
				if macroName == "PORT" || macroName == "MODEL_ID" {
					return Config{}, fmt.Errorf("macro '${%s}' should have been substituted in %s.env", macroName, modelId)
				}
				return Config{}, fmt.Errorf("unknown macro '${%s}' found in %s.env", macroName, modelId)
			}
		}

		if len(modelConfig.Metadata) > 0 {
		}

		// Validate SetParamsByID keys and values
		for key := range modelConfig.Filters.SetParamsByID {
			if matches := macroPatternRegex.FindAllStringSubmatch(key, -1); len(matches) > 0 {
				return Config{}, fmt.Errorf("unknown macro '${%s}' found in model %s filters.setParamsByID key", matches[0][1], modelId)
			}
		}

		if err := modelConfig.Capabilities.Validate(); err != nil {
			return Config{}, fmt.Errorf("model %s: %w", modelId, err)
		}

		// Auto-register setParamsByID keys as aliases (skip the model's own ID)
		for key := range modelConfig.Filters.SetParamsByID {
			if key == modelId {
				continue
			}
			if _, exists := config.Models[key]; exists {
				return Config{}, fmt.Errorf("model %s filters.setParamsByID: key '%s' conflicts with an existing model ID", modelId, key)
			}
			if existingModel, exists := config.aliases[key]; exists {
				if existingModel != modelId {
					return Config{}, fmt.Errorf("duplicate alias '%s' in model %s filters.setParamsByID, already used by model %s", key, modelId, existingModel)
				}
				continue // already registered as explicit alias for this model
			}
			config.aliases[key] = modelId
			modelConfig.Aliases = append(modelConfig.Aliases, key)
		}

		if _, err := url.Parse(modelConfig.Proxy); err != nil {
			return Config{}, fmt.Errorf("model %s: invalid proxy URL: %w", modelId, err)
		}

		if modelConfig.SendLoadingState == nil {
			v := config.SendLoadingState
			modelConfig.SendLoadingState = &v
		}

		if modelConfig.NormalizeSSE == nil {
			v := config.Upstream.NormalizeSSE
			modelConfig.NormalizeSSE = &v
		}

		config.Models[modelId] = modelConfig
	}

	// Normalize routing config. The legacy top-level `matrix`/`groups` keys and
	// the new `routing.router` block are mutually exclusive: a config may use
	// either style, never both.
	hasTopLevel := config.Matrix != nil || len(config.Groups) > 0
	rtr := config.Routing.Router
	hasRouting := rtr.Use != "" || rtr.Settings.Matrix != nil || len(rtr.Settings.Groups) > 0

	if hasTopLevel && hasRouting {
		return Config{}, fmt.Errorf("config uses both the legacy top-level 'matrix'/'groups' keys and the new 'routing.router' block; please migrate the top-level keys into 'routing.router' and remove them")
	}

	if !hasTopLevel {
		// Both groups and matrix may be defined under routing.router.settings;
		// routing.router.use selects which one is active, so there is no conflict.
		rs := config.Routing.Router.Settings
		switch config.Routing.Router.Use {
		case "matrix":
			if rs.Matrix == nil {
				return Config{}, fmt.Errorf("routing.router.use is 'matrix' but routing.router.settings.matrix is not set")
			}
			config.Matrix = rs.Matrix
		case "group", "":
			config.Groups = rs.Groups
		default:
			return Config{}, fmt.Errorf("routing.router.use: unknown router %q (valid: group, matrix)", config.Routing.Router.Use)
		}
	}

	// groups XOR matrix
	if config.Matrix != nil && len(config.Groups) > 0 {
		return Config{}, fmt.Errorf("config cannot use both 'groups' and 'matrix'")
	}

	if config.Matrix != nil {
		if err := ValidateMatrix(config.Matrix, config.Models); err != nil {
			return Config{}, fmt.Errorf("matrix: %w", err)
		}
	} else {
		config = AddDefaultGroupToConfig(config)

		// Validate group members
		memberUsage := make(map[string]string)
		for groupID, groupConfig := range config.Groups {
			prevSet := make(map[string]bool)
			for _, member := range groupConfig.Members {
				if _, found := prevSet[member]; found {
					return Config{}, fmt.Errorf("duplicate model member %s found in group: %s", member, groupID)
				}
				prevSet[member] = true

				if existingGroup, exists := memberUsage[member]; exists {
					return Config{}, fmt.Errorf("model member %s is used in multiple groups: %s and %s", member, existingGroup, groupID)
				}
				memberUsage[member] = groupID
			}
		}
	}

	// Build the canonical Config.Routing from the effective result. Both legacy
	// and new-style configs converge here. The Matrix pointer is shared so the
	// compiled matrix program stays in one place.
	if config.Matrix != nil {
		config.Routing.Router.Use = "matrix"
	} else {
		config.Routing.Router.Use = "group"
	}
	config.Routing.Router.Settings.Matrix = config.Matrix
	config.Routing.Router.Settings.Groups = config.Groups

	if config.Routing.Scheduler.Use == "" {
		config.Routing.Scheduler.Use = "fifo"
	}
	if config.Routing.Scheduler.Use != "fifo" {
		return Config{}, fmt.Errorf("routing.scheduler.use: unknown scheduler %q (valid: fifo)", config.Routing.Scheduler.Use)
	}
	for modelID := range config.Routing.Scheduler.Settings.Fifo.Priority {
		if _, found := config.RealModelName(modelID); !found {
			return Config{}, fmt.Errorf("routing.scheduler.settings.fifo.priority references unknown model %q", modelID)
		}
	}

	// Clean up hooks preload
	if len(config.Hooks.OnStartup.Preload) > 0 {
		var toPreload []string
		for _, modelID := range config.Hooks.OnStartup.Preload {
			modelID = strings.TrimSpace(modelID)
			if modelID == "" {
				continue
			}
			if real, found := config.RealModelName(modelID); found {
				toPreload = append(toPreload, real)
			}
		}
		config.Hooks.OnStartup.Preload = toPreload
	}

	// Validate API keys (env macros already substituted at string level)
	for i, apikey := range config.RequiredAPIKeys {
		if apikey == "" {
			return Config{}, fmt.Errorf("empty api key found in apiKeys")
		}
		if strings.Contains(apikey, " ") {
			return Config{}, fmt.Errorf("apiKeys[%d]: api key cannot contain spaces", i)
		}
		config.RequiredAPIKeys[i] = apikey
	}

	if err := ValidatePeerNamespace(config); err != nil {
		return Config{}, err
	}

	if err := validateSelectors(config); err != nil {
		return Config{}, err
	}

	if err := validateProfiles(config); err != nil {
		return Config{}, err
	}

	return config, nil
}

func validateProfiles(config Config) error {
	for profileName, profile := range config.Profiles {
		if strings.TrimSpace(profileName) == "" {
			return fmt.Errorf("profiles: profile names cannot be empty")
		}
		if len(profile.Pins) == 0 {
			return fmt.Errorf("profiles.%s.pins must contain at least one entry", profileName)
		}
		for pin, target := range profile.Pins {
			if strings.TrimSpace(pin) == "" {
				return fmt.Errorf("profiles.%s.pins: pin names cannot be empty", profileName)
			}
			if target == "" {
				continue
			}
			if _, found := config.ResolveBaseModel(target); !found {
				if _, found := config.Selectors[target]; found {
					continue
				}
				return fmt.Errorf("profiles.%s.pins.%s references unknown model %q", profileName, pin, target)
			}
		}
	}
	if profile := config.Hooks.OnStartup.Profile; profile != "" {
		if _, found := config.Profiles[profile]; !found {
			return fmt.Errorf("hooks.on_startup.profile references unknown profile %q", profile)
		}
	}
	return nil
}

func normalizeHeaderNames(names []string) []string {
	normalized := make([]string, 0, len(names))
	seen := make(map[string]struct{}, len(names))
	for _, name := range names {
		name = strings.TrimSpace(name)
		if name == "" {
			continue
		}
		key := strings.ToLower(name)
		if _, ok := seen[key]; ok {
			continue
		}
		seen[key] = struct{}{}
		normalized = append(normalized, name)
	}
	return normalized
}

// knownTopLevelKeys returns the set of keys Config declares, read from the
// struct's yaml tags. Keys tagged `yaml:"-"` are decode-inert and are not
// accepted from input.
func knownTopLevelKeys() map[string]struct{} {
	out := make(map[string]struct{})
	t := reflect.TypeOf(Config{})
	for i := 0; i < t.NumField(); i++ {
		tag := t.Field(i).Tag.Get("yaml")
		if tag == "" || tag == "-" {
			continue
		}
		name := strings.Split(tag, ",")[0]
		if name != "" {
			out[name] = struct{}{}
		}
	}
	// `defs` holds YAML anchors that models consume through `<<:` merge keys.
	// The YAML parser resolves those anchors itself and nothing reads the
	// block as Config data, so it has no struct field by design.
	out["defs"] = struct{}{}
	return out
}

// rejectUnknownTopLevelKeys fails the load when the document carries a
// top-level key Config does not declare.
//
// This exists because yaml.v3 drops such keys silently: a config can name
// `aliases:` at the top level, parse without error, and have the block
// discarded at every load — which is how a four-model alias block sat in
// bornite.yaml serving nothing for months while its names appeared to work
// because they were declared again under `models:`.
//
// Only the top level is checked on purpose. Strictness at every depth is not
// an option: the legacy `filters.strip_params` path decodes through an
// anonymous struct that must tolerate fields it does not model.
func rejectUnknownTopLevelKeys(node *yaml.Node) error {
	doc := node
	if doc.Kind == yaml.DocumentNode && len(doc.Content) > 0 {
		doc = doc.Content[0]
	}
	if doc.Kind != yaml.MappingNode {
		return nil
	}
	known := knownTopLevelKeys()
	var unknown []string
	for i := 0; i+1 < len(doc.Content); i += 2 {
		key := doc.Content[i].Value
		if _, ok := known[key]; !ok {
			unknown = append(unknown, key)
		}
	}
	if len(unknown) == 0 {
		return nil
	}
	sort.Strings(unknown)
	return fmt.Errorf("unknown top-level config key(s): %s (bornite ignores keys it does not know; "+
		"check for a typo, or a feature this build does not support)", strings.Join(unknown, ", "))
}

//go:build windows

package config

import (
	"fmt"
	"os"
	"path/filepath"
	"strings"
)

func validateStorePath(path string) error {
	if strings.TrimSpace(path) == "" {
		return fmt.Errorf("store.path must not be empty")
	}

	info, err := os.Stat(path)
	if err != nil {
		if !os.IsNotExist(err) {
			return fmt.Errorf("store.path: %w", err)
		}
		// File does not exist; ensure the parent directory is writable by
		// probing it with a temporary file. os.Access is unreliable on
		// Windows because it only reflects the read-only attribute.
		dir := filepath.Dir(path)
		if err := checkDirWritableWindows(dir); err != nil {
			return fmt.Errorf("store.path: directory %s is not writable: %w", dir, err)
		}
		return nil
	}

	// File exists; ensure it is a regular file and is writable.
	if info.IsDir() {
		return fmt.Errorf("store.path: %s is a directory, not a file", path)
	}
	f, err := os.OpenFile(path, os.O_WRONLY, 0)
	if err != nil {
		return fmt.Errorf("store.path: %s is not writable: %w", path, err)
	}
	f.Close()
	return nil
}

func checkDirWritableWindows(dir string) error {
	tmp, err := os.CreateTemp(dir, ".bornite-write-test-*")
	if err != nil {
		return err
	}
	tmp.Close()
	return os.Remove(tmp.Name())
}

package config

import (
	"fmt"
	"regexp"

	matrixdsl "github.com/toxicwind/bornite/internal/matrix"
	"gopkg.in/yaml.v3"
)

var varKeyPattern = regexp.MustCompile(`^[a-zA-Z0-9.-]{1,32}$`)

// MatrixConfig represents the swap matrix configuration block.
type MatrixConfig struct {
	Var        map[string]string `yaml:"vars"`
	EvictCosts map[string]int    `yaml:"evict_costs"`
	Sets       OrderedSets       `yaml:"sets"`

	program *matrixdsl.Program
}

// SetEntry is a single named set with its DSL expression.
type SetEntry struct {
	Name string
	DSL  string
}

// OrderedSets preserves YAML definition order of sets (used for tie-breaking).
type OrderedSets []SetEntry

func (os *OrderedSets) UnmarshalYAML(value *yaml.Node) error {
	if value.Kind != yaml.MappingNode {
		return fmt.Errorf("sets must be a mapping")
	}

	entries := make([]SetEntry, 0, len(value.Content)/2)
	for i := 0; i < len(value.Content); i += 2 {
		keyNode := value.Content[i]
		valueNode := value.Content[i+1]

		var name string
		if err := keyNode.Decode(&name); err != nil {
			return fmt.Errorf("failed to decode set name: %w", err)
		}

		var dsl string
		if err := valueNode.Decode(&dsl); err != nil {
			return fmt.Errorf("failed to decode DSL for set %q: %w", name, err)
		}

		entries = append(entries, SetEntry{Name: name, DSL: dsl})
	}

	*os = entries
	return nil
}

// ValidateMatrix validates and compiles a matrix configuration.
func ValidateMatrix(matrix *MatrixConfig, models map[string]ModelConfig) error {
	if len(matrix.Sets) == 0 {
		return fmt.Errorf("matrix must define at least one set")
	}

	// Validate var entries
	if matrix.Var != nil {
		for id, modelName := range matrix.Var {
			if !varKeyPattern.MatchString(id) {
				return fmt.Errorf("var key %q must contain only alphanumeric, '-' or '.' characters and be 1-32 characters long", id)
			}
			if _, exists := models[modelName]; !exists {
				return fmt.Errorf("var key %q references unknown model %q", id, modelName)
			}
		}
	}

	// Validate evict_costs
	if matrix.EvictCosts != nil {
		for key, cost := range matrix.EvictCosts {
			if cost <= 0 {
				return fmt.Errorf("evict_cost for %q must be a positive integer, got %d", key, cost)
			}
			if _, ok := resolveMatrixModel(key, matrix.Var, models); !ok {
				return fmt.Errorf("evict_costs: unknown var or model %q", key)
			}
		}
	}

	definitions := make([]matrixdsl.Definition, 0, len(matrix.Sets))
	for _, entry := range matrix.Sets {
		definitions = append(definitions, matrixdsl.Definition{
			Name: entry.Name,
			DSL:  entry.DSL,
		})
	}

	program, err := matrixdsl.Compile(definitions, func(ident string) (string, bool) {
		return resolveMatrixModel(ident, matrix.Var, models)
	})
	if err != nil {
		return err
	}
	matrix.program = program
	return nil
}

func resolveMatrixModel(ident string, vars map[string]string, models map[string]ModelConfig) (string, bool) {
	if modelName, ok := vars[ident]; ok {
		return modelName, true
	}
	if _, ok := models[ident]; ok {
		return ident, true
	}
	return "", false
}

// ResolvedEvictCosts returns a map of real model name -> evict cost,
// resolving var IDs. Models not listed default to 1.
func (m *MatrixConfig) ResolvedEvictCosts() map[string]int {
	costs := make(map[string]int)
	if m.EvictCosts == nil {
		return costs
	}
	for key, cost := range m.EvictCosts {
		// Resolve var ID if present
		if realName, ok := m.Var[key]; ok {
			costs[realName] = cost
		} else {
			costs[key] = cost
		}
	}
	return costs
}

// Program returns the immutable compiled matrix program.
func (m *MatrixConfig) Program() *matrixdsl.Program {
	return m.program
}

package config

import (
	"context"
	"encoding/json"
	"fmt"
	"reflect"
	"sort"
	"strings"
	"time"

	"github.com/toxicwind/bornite/internal/mcptools"
	"gopkg.in/yaml.v3"
)

// maxConfigResultBytes caps a get_config result. It is larger than the docs
// cap: a config review is a heavier task and the whole point is to see the
// setup, but it is still bounded so a full dump cannot swamp a small context.
const maxConfigResultBytes = 32 * 1024

// ConfigProvider serves the running bornite configuration so an agent can
// give advice about the setup in front of it rather than in the abstract.
//
// The configuration is captured by value when the provider is built. A hot
// reload constructs a fresh Server and therefore a fresh registry, so the
// snapshot always matches what is actually running.
type ConfigProvider struct {
	cfg Config
}

// NewConfigProvider builds the provider around a configuration snapshot.
func NewConfigProvider(cfg Config) *ConfigProvider {
	return &ConfigProvider{cfg: cfg}
}

var _ mcptools.Provider = (*ConfigProvider)(nil)

func (p *ConfigProvider) ID() string { return "config" }

func (p *ConfigProvider) Shutdown(time.Duration) error { return nil }

// Reading the configuration is read-only. It is not idempotent across a hot
// reload, but within one process the snapshot never changes.
func configAnnotations() *mcptools.Annotations {
	return &mcptools.Annotations{ReadOnlyHint: true, IdempotentHint: true}
}

func (p *ConfigProvider) Tools(context.Context) ([]mcptools.Tool, error) {
	return []mcptools.Tool{
		{
			Name:  "get_config",
			Title: "Show the current bornite configuration",
			Description: "Return the configuration bornite is running right now, as YAML, with " +
				"API keys and other credentials redacted. Values are fully resolved: ${env.*} and " +
				"macro references are already expanded, and values equal to their defaults are omitted. " +
				"Pass \"path\" to narrow to a section, for example \"models\" or \"models.qwen3\" or " +
				"\"peers\"; omit it for the whole document. Use this to review or troubleshoot the " +
				"active setup before suggesting changes.",
			Annotations: configAnnotations(),
			Tags:        []string{"config", "configuration", "troubleshooting"},
			InputSchema: map[string]any{
				"type": "object",
				"properties": map[string]any{
					"path": map[string]any{
						"type": "string",
						"description": "Dotted key selecting a section of the config, for example " +
							"'models', 'models.qwen3', 'peers', or 'macros'. Omit for the full config.",
					},
				},
				"additionalProperties": false,
			},
		},
	}, nil
}

func (p *ConfigProvider) Call(_ context.Context, name string, args map[string]json.RawMessage) (mcptools.Result, error) {
	if name != "get_config" {
		return mcptools.Result{}, fmt.Errorf("unknown tool %q", name)
	}

	path := mcptools.StringArg(args, "path")
	// Render the full tree before selecting a path so default-only sections can
	// still be addressed. For example, get_config({"path":"performance"})
	// should return an empty mapping, rather than report that the section does
	// not exist merely because every value in it is a default.
	yamlText, found, err := p.cfg.RedactedYAML("")
	if err != nil {
		return mcptools.Result{}, fmt.Errorf("rendering config: %w", err)
	}
	if !found { // RedactedYAML for the root always succeeds; retain this guard.
		return mcptools.Result{}, fmt.Errorf("rendering config: root configuration was not found")
	}

	var current map[string]any
	if err := yaml.Unmarshal([]byte(yamlText), &current); err != nil {
		return mcptools.Result{}, fmt.Errorf("parsing rendered config: %w", err)
	}

	if path != "" {
		_, exists := navigateConfig(current, strings.Split(path, "."))
		if !exists {
			keys := p.cfg.ConfigTopLevelKeys()
			sort.Strings(keys)
			return mcptools.Result{
				IsError: true,
				Content: fmt.Sprintf("Error: no config section at path %q. Top-level keys: %s.",
					path, strings.Join(keys, ", ")),
			}, nil
		}
	}

	defaults, err := configProviderDefaults(p.cfg)
	if err != nil {
		return mcptools.Result{}, fmt.Errorf("building config defaults: %w", err)
	}
	filtered, empty := pruneConfigDefaults(current, defaults, "")
	if empty {
		filtered = map[string]any{}
	}
	if path != "" {
		filtered, _ = navigateConfig(filtered, strings.Split(path, "."))
		if filtered == nil {
			filtered = map[string]any{}
		}
	}

	buf, err := yaml.Marshal(filtered)
	if err != nil {
		return mcptools.Result{}, fmt.Errorf("marshaling filtered config: %w", err)
	}
	yamlText = string(buf)

	var b strings.Builder
	if path == "" {
		b.WriteString("Current bornite configuration (credentials redacted, values resolved):\n\n")
	} else {
		fmt.Fprintf(&b, "Current bornite configuration at %q (credentials redacted, values resolved):\n\n", path)
	}
	b.WriteString("```yaml\n")
	b.WriteString(strings.TrimRight(yamlText, "\n"))
	b.WriteString("\n```\n")

	// A large config can still exceed the cap even after pruning. Give the
	// model the one move that fixes it rather than leaving it with a
	// half-parsed document.
	result := mcptools.CapResult(b.String(), maxConfigResultBytes)
	if result.Truncated {
		result.Content += "\nThe full config is larger than one response. Call get_config again " +
			"with a \"path\" (for example \"models\", \"models.<id>\", \"peers\", \"groups\") " +
			"to read a section in full."
	}
	return result, nil
}

// configProviderDefaults returns rendered defaults in the same YAML shape as
// RedactedYAML. Defaults for entries in maps (models, peers, selectors, and
// groups) are added by pruneConfigDefaults because an empty config has none.
func configProviderDefaults(cfg Config) (map[string]any, error) {
	base, err := LoadConfigFromReader(strings.NewReader("{}"))
	if err != nil {
		return nil, err
	}
	yamlText, _, err := base.RedactedYAML("")
	if err != nil {
		return nil, err
	}
	var defaults map[string]any
	if err := yaml.Unmarshal([]byte(yamlText), &defaults); err != nil {
		return nil, err
	}

	// Some model defaults inherit the resolved global configuration, so use the
	// active values rather than the empty-config baseline.
	model := ModelConfig{}
	if err := yaml.Unmarshal([]byte("{}"), &model); err != nil {
		return nil, err
	}
	model.HealthCheckTimeout = cfg.HealthCheckTimeout
	model.UnloadAfter = cfg.GlobalTTL
	model.UnloadTimeout = cfg.UnloadTimeout
	sendLoadingState := cfg.SendLoadingState
	model.SendLoadingState = &sendLoadingState
	modelDefaults, err := configProviderYAMLMap(model)
	if err != nil {
		return nil, err
	}
	defaults["__model"] = modelDefaults

	// PeerConfig validates its required fields during unmarshaling. Supply
	// placeholders solely to obtain the defaults, then remove those placeholders.
	peer := PeerConfig{}
	if err := yaml.Unmarshal([]byte("proxy: http://default.invalid\nmodels: [default]\n"), &peer); err != nil {
		return nil, err
	}
	peerDefaults, err := configProviderYAMLMap(peer)
	if err != nil {
		return nil, err
	}
	delete(peerDefaults, "proxy")
	delete(peerDefaults, "models")
	defaults["__peer"] = peerDefaults

	selector := SelectorConfig{}
	if err := yaml.Unmarshal([]byte("{}"), &selector); err != nil {
		return nil, err
	}
	selectorDefaults, err := configProviderYAMLMap(selector)
	if err != nil {
		return nil, err
	}
	defaults["__selector"] = selectorDefaults

	group := GroupConfig{}
	if err := yaml.Unmarshal([]byte("{}"), &group); err != nil {
		return nil, err
	}
	groupDefaults, err := configProviderYAMLMap(group)
	if err != nil {
		return nil, err
	}
	defaults["__group"] = groupDefaults
	return defaults, nil
}

func configProviderYAMLMap(v any) (map[string]any, error) {
	b, err := yaml.Marshal(v)
	if err != nil {
		return nil, err
	}
	var out map[string]any
	if err := yaml.Unmarshal(b, &out); err != nil {
		return nil, err
	}
	return out, nil
}

// pruneConfigDefaults recursively drops settings equal to their defaults.
// Map-entry defaults need special handling because the empty base config has no
// representative model, peer, selector, or group entry to compare against.
func pruneConfigDefaults(value, defaults any, path string) (any, bool) {
	currentMap, isMap := value.(map[string]any)
	defaultMap, defaultsAreMap := defaults.(map[string]any)
	if !isMap || !defaultsAreMap {
		return value, reflect.DeepEqual(value, defaults)
	}

	out := make(map[string]any, len(currentMap))
	for key, current := range currentMap {
		childPath := key
		if path != "" {
			childPath = path + "." + key
		}

		childDefaults, known := defaultMap[key]
		switch childPath {
		case "models", "peers", "selectors", "groups", "routing.router.settings.groups":
			entryDefaults := defaultMap["__"+strings.TrimSuffix(childPath, "s")]
			if childPath == "routing.router.settings.groups" {
				// The recursive defaults at this path are the routing defaults,
				// not the root defaults where __group is stored.
				entryDefaults = map[string]any{
					"swap":       true,
					"exclusive":  true,
					"persistent": false,
					"members":    []any{},
				}
			}
			entries, ok := current.(map[string]any)
			if !ok {
				out[key] = current
				continue
			}
			prunedEntries := make(map[string]any, len(entries))
			for entryKey, entry := range entries {
				if pruned, empty := pruneConfigDefaults(entry, entryDefaults, childPath+"."+entryKey); !empty {
					prunedEntries[entryKey] = pruned
				}
			}
			if len(prunedEntries) > 0 {
				out[key] = prunedEntries
			}
			continue
		}

		if !known {
			out[key] = current
			continue
		}
		if pruned, empty := pruneConfigDefaults(current, childDefaults, childPath); !empty {
			out[key] = pruned
		}
	}
	return out, len(out) == 0
}

package config

import (
	"context"
	"encoding/json"
	"fmt"
	"strings"
	"testing"

	"github.com/toxicwind/bornite/internal/mcptools"
)

const configProviderFixture = `
apiKeys:
  - "sk-secret-abcdefghijklmnop12345"
models:
  qwen3:
    cmd: "llama-server --model /m/qwen3.gguf --port ${PORT}"
peers:
  edge:
    proxy: "http://edge:8080"
    apiKey: "peer-token-value"
    models: ["m1"]
`

func newTestConfigProvider(t *testing.T) *ConfigProvider {
	t.Helper()
	cfg, err := LoadConfigFromReader(strings.NewReader(configProviderFixture))
	if err != nil {
		t.Fatalf("LoadConfigFromReader: %v", err)
	}
	return NewConfigProvider(cfg)
}

func callConfig(t *testing.T, p *ConfigProvider, args string) mcptools.Result {
	t.Helper()
	var parsed map[string]json.RawMessage
	if args != "" {
		if err := json.Unmarshal([]byte(args), &parsed); err != nil {
			t.Fatalf("bad test args: %v", err)
		}
	}
	result, err := p.Call(context.Background(), "get_config", parsed)
	if err != nil {
		t.Fatalf("Call: %v", err)
	}
	return result
}

func TestConfigProvider_Tools(t *testing.T) {
	tools, err := newTestConfigProvider(t).Tools(context.Background())
	if err != nil {
		t.Fatalf("Tools: %v", err)
	}
	if len(tools) != 1 || tools[0].Name != "get_config" {
		t.Fatalf("tools = %v, want one named %q", tools, "get_config")
	}
	if tools[0].Annotations == nil || !tools[0].Annotations.ReadOnlyHint {
		t.Error("get_config should be marked readOnlyHint")
	}
	if tools[0].InputSchema == nil {
		t.Error("get_config has no inputSchema")
	}
}

func TestConfigProvider_GetConfigRedactsAndFences(t *testing.T) {
	got := callConfig(t, newTestConfigProvider(t), "").Content

	if !strings.Contains(got, "```yaml") {
		t.Errorf("result is not a fenced YAML block:\n%s", got)
	}
	for _, leak := range []string{"sk-secret-abcdefghijklmnop12345", "peer-token-value"} {
		if strings.Contains(got, leak) {
			t.Errorf("result leaked secret %q:\n%s", leak, got)
		}
	}
	if !strings.Contains(got, "/m/qwen3.gguf") {
		t.Errorf("result dropped a non-secret value:\n%s", got)
	}
}

func TestConfigProvider_GetConfigWithPath(t *testing.T) {
	got := callConfig(t, newTestConfigProvider(t), `{"path":"models.qwen3"}`).Content

	if !strings.Contains(got, `at "models.qwen3"`) {
		t.Errorf("result does not name the path:\n%s", got)
	}
	if !strings.Contains(got, "cmd:") || strings.Contains(got, "peers:") {
		t.Errorf("path did not scope the output to the model:\n%s", got)
	}
}

func TestConfigProvider_GetConfigOmitsDefaults(t *testing.T) {
	got := callConfig(t, newTestConfigProvider(t), "").Content

	for _, defaultValue := range []string{
		"healthCheckTimeout: 120",
		"logLevel: info",
		"logToStdout: proxy",
		"metricsMaxInMemory: 1000",
		"checkEndpoint: /health",
		"proxy: http://localhost:${PORT}",
		"connect: 30",
		"responseHeader: 60",
		"swap: true",
		"exclusive: true",
	} {
		if strings.Contains(got, defaultValue) {
			t.Errorf("result includes default value %q:\n%s", defaultValue, got)
		}
	}
	for _, configuredValue := range []string{"cmd:", "proxy: http://edge:8080", "models:", "m1"} {
		if !strings.Contains(got, configuredValue) {
			t.Errorf("result dropped configured value %q:\n%s", configuredValue, got)
		}
	}
}

func TestConfigProvider_GetConfigUnknownPath(t *testing.T) {
	res := callConfig(t, newTestConfigProvider(t), `{"path":"nope.nowhere"}`)
	if !res.IsError {
		t.Fatalf("want IsError for a bad path, got:\n%s", res.Content)
	}
	if !strings.Contains(res.Content, "Top-level keys:") {
		t.Errorf("error should list valid top-level keys:\n%s", res.Content)
	}
}

func TestConfigProvider_GetConfigTruncationPointsAtPath(t *testing.T) {
	var b strings.Builder
	b.WriteString("models:\n")
	for i := 0; i < 220; i++ {
		fmt.Fprintf(&b, "  model-%03d:\n    cmd: \"llama-server --model /models/model-%03d.gguf --port ${PORT}\"\n", i, i)
	}
	cfg, err := LoadConfigFromReader(strings.NewReader(b.String()))
	if err != nil {
		t.Fatalf("LoadConfigFromReader: %v", err)
	}

	got := callConfig(t, NewConfigProvider(cfg), "").Content
	if !strings.Contains(got, "[truncated]") {
		t.Fatalf("expected a large config to truncate, got %d bytes", len(got))
	}
	if !strings.Contains(got, `with a "path"`) {
		t.Errorf("truncated result should tell the caller to use a path:\n%s", got[len(got)-400:])
	}
}

func TestConfigProvider_UnknownTool(t *testing.T) {
	_, err := newTestConfigProvider(t).Call(context.Background(), "get_doc", nil)
	if err == nil {
		t.Fatal("want an error for an unknown tool")
	}
}

package config

import (
	"strings"
	"fmt"
	"net/url"
	"sort"

	"github.com/toxicwind/bornite/internal/tailcat"
)

type PeerDictionaryConfig map[string]PeerConfig
type PeerConfig struct {
	Proxy      string   `yaml:"proxy"`
	ProxyURL   *url.URL `yaml:"-"`
	ApiKey     string   `yaml:"apiKey"`
	TailcatKey string   `yaml:"tailcatKey"`
	Models     []string `yaml:"models"`
	Filters    Filters  `yaml:"filters"`

	// Timeout settings for proxy connections
	Timeouts TimeoutsConfig `yaml:"timeouts"`

	// Health settings for peer health tracking
	Health HealthConfig `yaml:"health"`

	tailcatBlob       string
	tailcatPrivateKey *tailcat.PrivateKey
}

// Tailcat returns the Tailcat-specific peer settings derived while validating
// a tailcat:// proxy. PrivateKey is parsed key material, retained so callers do
// not need to read the key file again. found is false for non-Tailcat peers.
func (c PeerConfig) Tailcat() (key, blob string, privateKey *tailcat.PrivateKey, found bool) {
	if c.tailcatBlob == "" {
		return "", "", nil, false
	}
	return c.TailcatKey, c.tailcatBlob, c.tailcatPrivateKey, true
}

type rawPeerConfig PeerConfig

// PeerModelFQN returns the fully qualified routing name for a peer model.
// Peer and model IDs may both contain slashes, so callers must treat the
// result as an exact configured name rather than parsing it by segments.
func PeerModelFQN(peerID, modelID string) string {
	return peerID + "/" + modelID
}

// ResolvePeerModel resolves an exact fully qualified peer model name or an
// unqualified model name provided by exactly one peer. Fully qualified names
// take precedence over unqualified names that happen to contain the same text.
func (c *Config) ResolvePeerModel(search string) (peerID, modelID string, found bool) {
	for id, peer := range c.Peers {
		seen := make(map[string]struct{})
		for _, model := range peer.Models {
			if _, duplicate := seen[model]; duplicate {
				continue
			}
			seen[model] = struct{}{}
			if PeerModelFQN(id, model) != search {
				continue
			}
			if found && (peerID != id || modelID != model) {
				return "", "", false
			}
			peerID, modelID, found = id, model, true
		}
	}
	if found {
		return peerID, modelID, true
	}

	for id, peer := range c.Peers {
		seen := make(map[string]struct{})
		for _, model := range peer.Models {
			if _, duplicate := seen[model]; duplicate {
				continue
			}
			seen[model] = struct{}{}
			if model != search {
				continue
			}
			if found && (peerID != id || modelID != model) {
				return "", "", false
			}
			peerID, modelID, found = id, model, true
		}
	}
	return peerID, modelID, found
}

// ValidatePeerNamespace ensures every configured peer model has an
// unambiguous, reserved fully qualified name.
func ValidatePeerNamespace(c Config) error {
	type peerTarget struct {
		peerID  string
		modelID string
	}

	fqnTargets := make(map[string]peerTarget)
	peerIDs := make([]string, 0, len(c.Peers))
	for peerID := range c.Peers {
		peerIDs = append(peerIDs, peerID)
	}
	sort.Strings(peerIDs)

	for _, peerID := range peerIDs {
		seen := make(map[string]struct{})
		for _, modelID := range c.Peers[peerID].Models {
			if _, duplicate := seen[modelID]; duplicate {
				continue
			}
			seen[modelID] = struct{}{}

			fqn := PeerModelFQN(peerID, modelID)
			if existing, ok := fqnTargets[fqn]; ok {
				return fmt.Errorf(
					"peer model name %q is ambiguous between peers.%s model %q and peers.%s model %q",
					fqn, existing.peerID, existing.modelID, peerID, modelID,
				)
			}
			fqnTargets[fqn] = peerTarget{peerID: peerID, modelID: modelID}
		}
	}

	reserved := make([]string, 0, len(fqnTargets))
	for fqn := range fqnTargets {
		reserved = append(reserved, fqn)
	}
	sort.Strings(reserved)

	for _, fqn := range reserved {
		if _, ok := c.Models[fqn]; ok {
			return fmt.Errorf("model ID %q conflicts with fully qualified peer model name", fqn)
		}
		for modelID, model := range c.Models {
			for _, alias := range model.Aliases {
				if alias == fqn {
					return fmt.Errorf("model %s alias %q conflicts with fully qualified peer model name", modelID, fqn)
				}
			}
		}
		if _, ok := c.aliases[fqn]; ok {
			return fmt.Errorf("model alias %q conflicts with fully qualified peer model name", fqn)
		}
		if _, ok := c.Selectors[fqn]; ok {
			return fmt.Errorf("selector ID %q conflicts with fully qualified peer model name", fqn)
		}
		for profileID, profile := range c.Profiles {
			if _, ok := profile.Pins[fqn]; ok {
				return fmt.Errorf("profile %s pin %q conflicts with fully qualified peer model name", profileID, fqn)
			}
		}
	}

	return nil
}

func (c *PeerConfig) UnmarshalYAML(unmarshal func(interface{}) error) error {
	// Probe the proxy scheme before filling defaults: a tailcat peer can
	// spend minutes loading a remote model before sending response headers,
	// so it gets a bounded 300s response-header timeout; other peers keep
	// the historical 60s.
	var probe rawPeerConfig
	if err := unmarshal(&probe); err != nil {
		return err
	}
	responseHeaderDefault := 60
	if u, err := url.Parse(probe.Proxy); err == nil && strings.EqualFold(u.Scheme, "tailcat") {
		responseHeaderDefault = 300
	}

	defaults := rawPeerConfig{
		Proxy:   "",
		ApiKey:  "",
		Models:  []string{},
		Filters: Filters{},

		// Mostly matches http.DefaultTransport. HTTP peers retain the 60s
		// response-header timeout; tailcat peers get 300s (ported from agele).
		Timeouts: TimeoutsConfig{
			Connect:        30,
			KeepAlive:      30,
			ResponseHeader: responseHeaderDefault,
			TLSHandshake:   10,
			ExpectContinue: 1,
			IdleConn:       90,
		},
	}

	if err := unmarshal(&defaults); err != nil {
		return err
	}

	// Validate proxy is not empty
	if defaults.Proxy == "" {
		return fmt.Errorf("proxy is required")
	}
	// Validate proxy is a valid URL and store the parsed value
	parsedURL, err := url.Parse(defaults.Proxy)
	if err != nil {
		return fmt.Errorf("invalid peer proxy URL (%s): %w", defaults.Proxy, err)
	}
	defaults.ProxyURL = parsedURL
	if err := validatePeerTailcat(&defaults); err != nil {
		return err
	}

	// Validate models is not empty
	if len(defaults.Models) == 0 {
		return fmt.Errorf("peer models can not be empty")
	}

	*c = PeerConfig(defaults)
	return nil
}

package config

import (
	"fmt"
	"net/url"
	"strings"
)

// CORSWildcardOrigin allows any origin. It is the default when
// security.cors.allowedOrigins is empty, which keeps an absent security block
// behaving exactly like bornite did before the setting existed.
const CORSWildcardOrigin = "*"

// DefaultCORSMaxAge is the Access-Control-Max-Age value sent on preflight
// responses when security.cors.maxAge is not set.
const DefaultCORSMaxAge = 86400

// DefaultCORSAllowedOrigins returns the default allowedOrigins list. The
// returned slice is fresh so callers may mutate it without affecting other
// configs.
func DefaultCORSAllowedOrigins() []string {
	return []string{CORSWildcardOrigin}
}

// DefaultCORSAllowedMethods returns the methods advertised on a preflight
// response when security.cors.allowedMethods is not set.
func DefaultCORSAllowedMethods() []string {
	return []string{"GET", "POST", "PUT", "PATCH", "DELETE", "OPTIONS"}
}

// DefaultCORSAllowedHeaders returns the request headers advertised on a
// preflight response when the client sent no Access-Control-Request-Headers
// and security.cors.allowedHeaders is not set.
func DefaultCORSAllowedHeaders() []string {
	return []string{"Content-Type", "Authorization", "Accept", "X-Requested-With"}
}

// SecurityConfig groups settings that control who may talk to bornite.
type SecurityConfig struct {
	CORS CORSConfig `yaml:"cors"`
}

// CORSConfig controls the Access-Control-* headers bornite sends.
//
// AllowedOrigins selects between two modes. Leaving it empty keeps the
// permissive policy bornite had before the setting existed, so configs
// written without it are unaffected. Setting it means taking charge of who may
// reach bornite from a browser, and nothing then widens access beyond the
// list; write "*" to allow any origin deliberately. The remaining fields
// describe preflight mechanics rather than access, so each one left empty
// still takes its default and a config naming only origins keeps working.
//
// See issues #85, #1121 and #1133 — bornite must be the only source of
// these headers, because upstreams such as llama-server set their own and
// httputil.ReverseProxy adds rather than replaces them.
type CORSConfig struct {
	// AllowedOrigins lists the browser origins that may read responses, and
	// selects the mode: absent means the permissive legacy policy, present
	// means only these origins. It is required once any other field here is
	// set, and writing it as an empty list is rejected rather than read as
	// "allow everything". A "*" entry allows any origin and cannot be
	// combined with AllowCredentials.
	//
	// Nil and empty are therefore different: yaml.v3 leaves this nil for an
	// absent key and produces a non-nil empty slice for `allowedOrigins: []`,
	// which is what lets Validate tell them apart.
	AllowedOrigins []string `yaml:"allowedOrigins"`

	// AllowCredentials sends Access-Control-Allow-Credentials: true, letting
	// the browser attach cookies and Authorization headers.
	AllowCredentials bool `yaml:"allowCredentials"`

	// AllowPrivateNetwork answers Chrome's Private Network Access preflight
	// with Access-Control-Allow-Private-Network: true, letting a page on a
	// public origin reach bornite on a private address. Off by default,
	// and cannot be combined with a "*" origin: that pairing would let any
	// page in any open tab drive a bornite on the user's own network,
	// which is what Private Network Access exists to prevent.
	AllowPrivateNetwork bool `yaml:"allowPrivateNetwork"`

	// AllowedMethods is advertised on preflight responses. Empty means
	// DefaultCORSAllowedMethods.
	AllowedMethods []string `yaml:"allowedMethods"`

	// AllowedHeaders is advertised on preflight responses. Empty means the
	// client's sanitized Access-Control-Request-Headers is echoed back,
	// falling back to DefaultCORSAllowedHeaders when it sent none.
	AllowedHeaders []string `yaml:"allowedHeaders"`

	// ExposedHeaders lists response headers a browser may read beyond the
	// CORS-safelisted set. Empty omits the header.
	ExposedHeaders []string `yaml:"exposedHeaders"`

	// MaxAge is the preflight cache lifetime in seconds. 0 means
	// DefaultCORSMaxAge.
	MaxAge int `yaml:"maxAge"`
}

// Validate reports configuration that cannot produce a usable CORS policy.
func (c CORSConfig) Validate() error {
	if len(c.AllowedOrigins) == 0 {
		// A nil slice means the key was never written, which selects the
		// legacy permissive policy. A non-nil empty one means the key is
		// there as `allowedOrigins: []`, and allowing every origin because
		// someone asked for none would invert what they wrote.
		if c.AllowedOrigins != nil {
			return fmt.Errorf(`allowedOrigins must list at least one origin, or "*" to allow any; remove the key to keep the permissive default`)
		}
		if !c.hasNonOriginSettings() {
			// Nothing configured at all, which selects the legacy permissive
			// policy and needs no further checking.
			return nil
		}
		// Falling back to allow-all here would widen access for a config that
		// plainly meant to restrict something, and would pair
		// allowCredentials with a wildcard origin, which the Fetch spec
		// forbids.
		return fmt.Errorf("allowedOrigins is required when any other cors setting is present; remove the security.cors block to keep the permissive default")
	}

	for _, origin := range c.AllowedOrigins {
		if origin == CORSWildcardOrigin {
			if c.AllowCredentials {
				return fmt.Errorf(`allowedOrigins may not contain "*" when allowCredentials is true; list the origins explicitly`)
			}
			if c.AllowPrivateNetwork {
				return fmt.Errorf(`allowedOrigins may not contain "*" when allowPrivateNetwork is true; list the origins explicitly`)
			}
			continue
		}
		if err := validateCORSOrigin(origin); err != nil {
			return err
		}
	}

	for _, m := range c.AllowedMethods {
		if !IsHTTPToken(m) {
			return fmt.Errorf("allowedMethods: %q is not a valid HTTP method", m)
		}
	}
	for _, h := range c.AllowedHeaders {
		if !IsHTTPToken(h) {
			return fmt.Errorf("allowedHeaders: %q is not a valid HTTP header name", h)
		}
	}
	for _, h := range c.ExposedHeaders {
		if !IsHTTPToken(h) {
			return fmt.Errorf("exposedHeaders: %q is not a valid HTTP header name", h)
		}
	}

	if c.MaxAge < 0 {
		return fmt.Errorf("maxAge must be >= 0")
	}

	return nil
}

// hasNonOriginSettings reports whether any field other than AllowedOrigins
// carries a non-zero value, which is how a half-written block is recognized.
func (c CORSConfig) hasNonOriginSettings() bool {
	return c.AllowCredentials ||
		c.AllowPrivateNetwork ||
		len(c.AllowedMethods) > 0 ||
		len(c.AllowedHeaders) > 0 ||
		len(c.ExposedHeaders) > 0 ||
		c.MaxAge != 0
}

// validateCORSOrigin checks that an entry is a bare scheme://host[:port], the
// only form a browser ever sends in an Origin header. A trailing slash or a
// path would silently never match, so reject it at load time.
func validateCORSOrigin(origin string) error {
	if origin == "" {
		return fmt.Errorf("allowedOrigins: entry must not be empty")
	}
	if origin != strings.TrimSpace(origin) {
		return fmt.Errorf("allowedOrigins: %q must not have leading or trailing whitespace", origin)
	}

	u, err := url.Parse(origin)
	if err != nil {
		return fmt.Errorf("allowedOrigins: %q is not a valid origin: %w", origin, err)
	}
	if u.Scheme == "" || u.Host == "" {
		return fmt.Errorf("allowedOrigins: %q must be a scheme://host[:port] origin, e.g. https://dashboard.example.com", origin)
	}
	if u.Path != "" || u.RawQuery != "" || u.Fragment != "" || u.User != nil {
		return fmt.Errorf("allowedOrigins: %q must not include a path, query, fragment or userinfo", origin)
	}

	return nil
}

// IsHTTPToken reports whether s is a non-empty RFC 9110 token, the grammar
// both method names and header names follow. It is exported because
// internal/server sanitizes Access-Control-Request-Headers with the same rule
// and cannot import swaputil, which already depends on this package.
func IsHTTPToken(s string) bool {
	if s == "" {
		return false
	}
	for _, r := range s {
		if !isTokenChar(r) {
			return false
		}
	}
	return true
}

// isTokenChar reports whether r is valid in an RFC 9110 token.
func isTokenChar(r rune) bool {
	switch {
	case r >= 'a' && r <= 'z':
	case r >= 'A' && r <= 'Z':
	case r >= '0' && r <= '9':
	case strings.ContainsRune("!#$%&'*+-.^_`|~", r):
	default:
		return false
	}
	return true
}

package config

import (
	"strings"
	"testing"

	"gopkg.in/yaml.v3"
)

// TestConfig_SecurityCORSUnsetOriginsSelectLegacyPolicy pins that a config
// naming no origins keeps the permissive behaviour bornite had before the
// setting existed. Adding the setting must never change an existing
// deployment, and every way of writing "nothing configured" means the same.
func TestConfig_SecurityCORSUnsetOriginsSelectLegacyPolicy(t *testing.T) {
	const models = "models:\n  m1:\n    cmd: echo ${PORT}\n"
	configs := map[string]string{
		"no security block":            models,
		"empty security":               "security:\n" + models,
		"cors with null value":         "security:\n  cors:\n" + models,
		"empty cors mapping":           "security:\n  cors: {}\n" + models,
		"allowedOrigins with no value": "security:\n  cors:\n    allowedOrigins:\n" + models,
	}

	for name, yaml := range configs {
		t.Run(name, func(t *testing.T) {
			cfg, err := LoadConfigFromReader(strings.NewReader(yaml))
			if err != nil {
				t.Fatalf("LoadConfigFromReader: %v", err)
			}
			if cfg.Security == nil || len(cfg.Security.CORS.AllowedOrigins) != 0 {
				t.Errorf("allowedOrigins = %v, want empty so the legacy policy applies", cfg.Security)
			}
		})
	}
}

// TestConfig_SecurityCORSEmptyOriginListRejected covers a list written as
// empty. Reading `allowedOrigins: []` as "allow every origin" would invert
// what it plainly says, so it fails at startup instead.
func TestConfig_SecurityCORSEmptyOriginListRejected(t *testing.T) {
	const models = "models:\n  m1:\n    cmd: echo ${PORT}\n"
	configs := map[string]string{
		"flow empty list":           "security:\n  cors:\n    allowedOrigins: []\n" + models,
		"flow empty list with more": "security:\n  cors:\n    allowedOrigins: []\n    maxAge: 600\n" + models,
	}

	for name, yaml := range configs {
		t.Run(name, func(t *testing.T) {
			_, err := LoadConfigFromReader(strings.NewReader(yaml))
			if err == nil {
				t.Fatal("LoadConfigFromReader accepted an empty allowedOrigins list")
			}
			if !strings.Contains(err.Error(), "at least one origin") {
				t.Errorf("error = %q, want it to ask for at least one origin", err)
			}
		})
	}
}

// TestConfig_SecurityCORSNilVsEmptyOrigins pins the yaml.v3 behaviour that
// telling an absent allowedOrigins from an empty one depends on: an absent key
// leaves the slice nil, while `allowedOrigins: []` produces a non-nil empty
// one. If a yaml.v3 upgrade ever collapsed the two, the empty-list rule above
// would quietly become a no-op, so fail here instead.
func TestConfig_SecurityCORSNilVsEmptyOrigins(t *testing.T) {
	cases := []struct {
		name    string
		yaml    string
		wantNil bool
	}{
		{"absent key", "maxAge: 600\n", true},
		{"null value", "allowedOrigins:\n", true},
		{"explicit null", "allowedOrigins: null\n", true},
		{"flow empty list", "allowedOrigins: []\n", false},
		{"block empty list", "allowedOrigins: [\n]\n", false},
	}

	for _, c := range cases {
		t.Run(c.name, func(t *testing.T) {
			var cors CORSConfig
			if err := yaml.Unmarshal([]byte(c.yaml), &cors); err != nil {
				t.Fatalf("Unmarshal: %v", err)
			}
			if got := cors.AllowedOrigins == nil; got != c.wantNil {
				t.Errorf("AllowedOrigins == nil is %v, want %v", got, c.wantNil)
			}
			if len(cors.AllowedOrigins) != 0 {
				t.Errorf("AllowedOrigins = %q, want empty", cors.AllowedOrigins)
			}
		})
	}
}

// TestConfig_SecurityCORSOrphanSettingsRejected covers the other half of the
// two-mode model. A config that tunes CORS but never says which origins the
// tuning applies to is a half-finished edit; falling back to allow-all there
// would widen access for a config that meant to restrict it.
func TestConfig_SecurityCORSOrphanSettingsRejected(t *testing.T) {
	const models = "models:\n  m1:\n    cmd: echo ${PORT}\n"
	configs := map[string]string{
		"allowCredentials alone":    "security:\n  cors:\n    allowCredentials: true\n" + models,
		"allowPrivateNetwork alone": "security:\n  cors:\n    allowPrivateNetwork: true\n" + models,
		"allowedMethods alone":      "security:\n  cors:\n    allowedMethods: [\"GET\"]\n" + models,
		"allowedHeaders alone":      "security:\n  cors:\n    allowedHeaders: [\"Content-Type\"]\n" + models,
		"exposedHeaders alone":      "security:\n  cors:\n    exposedHeaders: [\"X-Request-Id\"]\n" + models,
		"maxAge alone":              "security:\n  cors:\n    maxAge: 600\n" + models,
		"several without origins": "security:\n  cors:\n    maxAge: 600\n" +
			"    allowedMethods: [\"GET\"]\n" + models,
	}

	for name, yaml := range configs {
		t.Run(name, func(t *testing.T) {
			_, err := LoadConfigFromReader(strings.NewReader(yaml))
			if err == nil {
				t.Fatal("LoadConfigFromReader accepted cors settings with no allowedOrigins")
			}
			if !strings.Contains(err.Error(), "allowedOrigins") {
				t.Errorf("error = %q, want it to name allowedOrigins", err)
			}
			if !strings.Contains(err.Error(), "security.cors") {
				t.Errorf("error = %q, want it prefixed with security.cors", err)
			}
		})
	}
}

// TestConfig_SecurityCORSDeclaredKeepsPreflightDefaults checks that naming
// origins does not force you to spell out the rest. The preflight mechanics
// stay empty in the config and are resolved to defaults by newCORSPolicy, so a
// block that only names origins still works in a browser.
func TestConfig_SecurityCORSDeclaredKeepsPreflightDefaults(t *testing.T) {
	const yaml = `
security:
  cors:
    allowedOrigins: ["https://dash.example.com"]
models:
  m1:
    cmd: echo ${PORT}
`
	cfg, err := LoadConfigFromReader(strings.NewReader(yaml))
	if err != nil {
		t.Fatalf("LoadConfigFromReader: %v", err)
	}
	cors := cfg.Security.CORS
	if len(cors.AllowedOrigins) != 1 {
		t.Fatalf("allowedOrigins = %q, want the one configured origin", cors.AllowedOrigins)
	}
	if len(cors.AllowedMethods) != 0 || len(cors.AllowedHeaders) != 0 || cors.MaxAge != 0 {
		t.Errorf("unset preflight fields were populated at load: %+v", cors)
	}
}

func TestConfig_SecurityCORSParsing(t *testing.T) {
	const yaml = `
security:
  cors:
    allowedOrigins:
      - "https://dash.example.com"
      - "http://localhost:5173"
    allowCredentials: true
    allowPrivateNetwork: true
    allowedMethods: ["GET", "POST"]
    allowedHeaders: ["Content-Type"]
    exposedHeaders: ["X-Request-Id"]
    maxAge: 600
models:
  m1:
    cmd: echo ${PORT}
`
	cfg, err := LoadConfigFromReader(strings.NewReader(yaml))
	if err != nil {
		t.Fatalf("LoadConfigFromReader: %v", err)
	}

	cors := cfg.Security.CORS
	if len(cors.AllowedOrigins) != 2 || cors.AllowedOrigins[0] != "https://dash.example.com" {
		t.Errorf("allowedOrigins=%q", cors.AllowedOrigins)
	}
	if !cors.AllowCredentials {
		t.Error("allowCredentials=false want true")
	}
	if !cors.AllowPrivateNetwork {
		t.Error("allowPrivateNetwork=false want true")
	}
	if len(cors.AllowedMethods) != 2 {
		t.Errorf("allowedMethods=%q", cors.AllowedMethods)
	}
	if cors.MaxAge != 600 {
		t.Errorf("maxAge=%d want 600", cors.MaxAge)
	}
}

// TestConfig_SecurityCORSPrivateNetworkRequiresExplicitOrigins covers the two
// ways of asking for private-network access without naming who gets it.
// Granting it to every origin would let any page in any open tab drive a
// bornite on the user's own network.
func TestConfig_SecurityCORSPrivateNetworkRequiresExplicitOrigins(t *testing.T) {
	const models = "models:\n  m1:\n    cmd: echo ${PORT}\n"
	cases := map[string]struct {
		yaml    string
		wantErr string
	}{
		"with a wildcard origin": {
			yaml: "security:\n  cors:\n    allowedOrigins: [\"*\"]\n" +
				"    allowPrivateNetwork: true\n" + models,
			wantErr: "allowPrivateNetwork",
		},
		"with no origins at all": {
			yaml:    "security:\n  cors:\n    allowPrivateNetwork: true\n" + models,
			wantErr: "allowedOrigins is required",
		},
	}

	for name, c := range cases {
		t.Run(name, func(t *testing.T) {
			_, err := LoadConfigFromReader(strings.NewReader(c.yaml))
			if err == nil {
				t.Fatal("LoadConfigFromReader accepted allowPrivateNetwork without explicit origins")
			}
			if !strings.Contains(err.Error(), c.wantErr) {
				t.Errorf("error = %q, want it to name %q", err, c.wantErr)
			}
		})
	}
}

func TestConfig_SecurityCORSValidation(t *testing.T) {
	cases := []struct {
		name    string
		cors    CORSConfig
		wantErr string // substring the message must name
	}{
		{
			name:    "wildcard with credentials",
			cors:    CORSConfig{AllowedOrigins: []string{"*"}, AllowCredentials: true},
			wantErr: "allowCredentials",
		},
		{
			name:    "wildcard with private network",
			cors:    CORSConfig{AllowedOrigins: []string{"*"}, AllowPrivateNetwork: true},
			wantErr: "allowPrivateNetwork",
		},
		{
			name:    "wildcard among explicit origins with credentials",
			cors:    CORSConfig{AllowedOrigins: []string{"https://a.example.com", "*"}, AllowCredentials: true},
			wantErr: "allowCredentials",
		},
		{
			name:    "origin with trailing slash",
			cors:    CORSConfig{AllowedOrigins: []string{"https://dash.example.com/"}},
			wantErr: "path",
		},
		{
			name:    "origin with path",
			cors:    CORSConfig{AllowedOrigins: []string{"https://dash.example.com/ui"}},
			wantErr: "path",
		},
		{
			name:    "origin without scheme",
			cors:    CORSConfig{AllowedOrigins: []string{"dash.example.com"}},
			wantErr: "scheme://host",
		},
		{
			name:    "empty origin",
			cors:    CORSConfig{AllowedOrigins: []string{""}},
			wantErr: "must not be empty",
		},
		{
			name:    "origin with whitespace",
			cors:    CORSConfig{AllowedOrigins: []string{" https://dash.example.com"}},
			wantErr: "whitespace",
		},
		{
			name:    "explicitly empty origin list",
			cors:    CORSConfig{AllowedOrigins: []string{}},
			wantErr: "at least one origin",
		},
		{
			name:    "maxAge without origins",
			cors:    CORSConfig{MaxAge: 600},
			wantErr: "allowedOrigins is required",
		},
		{
			name:    "credentials without origins",
			cors:    CORSConfig{AllowCredentials: true},
			wantErr: "allowedOrigins is required",
		},
		{
			name:    "empty origin list beats the orphan rule",
			cors:    CORSConfig{AllowedOrigins: []string{}, MaxAge: 600},
			wantErr: "at least one origin",
		},
		{
			name:    "negative maxAge",
			cors:    CORSConfig{AllowedOrigins: []string{"*"}, MaxAge: -1},
			wantErr: "maxAge",
		},
		{
			name:    "non-token method",
			cors:    CORSConfig{AllowedOrigins: []string{"*"}, AllowedMethods: []string{"GET POST"}},
			wantErr: "allowedMethods",
		},
		{
			name:    "non-token allowed header",
			cors:    CORSConfig{AllowedOrigins: []string{"*"}, AllowedHeaders: []string{"Bad Header"}},
			wantErr: "allowedHeaders",
		},
		{
			name:    "non-token exposed header",
			cors:    CORSConfig{AllowedOrigins: []string{"*"}, ExposedHeaders: []string{"Bad@Header"}},
			wantErr: "exposedHeaders",
		},
	}

	for _, c := range cases {
		t.Run(c.name, func(t *testing.T) {
			err := c.cors.Validate()
			if err == nil {
				t.Fatalf("Validate() = nil, want an error naming %q", c.wantErr)
			}
			if !strings.Contains(err.Error(), c.wantErr) {
				t.Errorf("Validate() = %q, want it to name %q", err, c.wantErr)
			}
		})
	}
}

// TestConfig_SecurityCORSValidationRunsOnLoad checks the validation is actually
// wired into LoadConfigFromReader, not just reachable on the type.
func TestConfig_SecurityCORSValidationRunsOnLoad(t *testing.T) {
	const yaml = `
security:
  cors:
    allowedOrigins: ["*"]
    allowCredentials: true
models:
  m1:
    cmd: echo ${PORT}
`
	_, err := LoadConfigFromReader(strings.NewReader(yaml))
	if err == nil {
		t.Fatal("LoadConfigFromReader accepted \"*\" with allowCredentials")
	}
	if !strings.Contains(err.Error(), "security.cors") {
		t.Errorf("error = %q, want it prefixed with security.cors", err)
