func TestConfig_IsHTTPToken(t *testing.T) {
	for _, s := range []string{"abcXYZ0129", "Content-Type", "X-Custom", "!#$%&'*+-.^_`|~"} {
		if !IsHTTPToken(s) {
			t.Errorf("IsHTTPToken(%q) = false, want true", s)
		}
	}
	for _, s := range []string{"", " ", "Bad Header", "Bad@Header", "a/b", "quote\"d", "tab\there"} {
		if IsHTTPToken(s) {
			t.Errorf("IsHTTPToken(%q) = true, want false", s)
		}
	}
}

package config

import (
	"fmt"
	"net/url"
	"strings"

	"github.com/toxicwind/bornite/internal/tailcat"
)

const TailcatEphemeralKey = "ephemeral"

// TailcatAllowAll is the wildcard that allows any tailcat client.
// Ported from the agele tree during the bornite union: agele's
// validator accepted it, bornite's did not.
const TailcatAllowAll = "*"

// TailcatConfig configures the private Tailcat listener and its HTTP policy.
// The listener identity comes from the startup-only -listen-tailcat flag.
type TailcatConfig struct {
	Allow  []string `yaml:"allow"`
	Models []string `yaml:"models"`
	Admin  bool     `yaml:"admin"`
	Debug  bool     `yaml:"debug"`

	AllowedClients []string `yaml:"-"`
}

func validatePeerTailcat(peer *rawPeerConfig) error {
	u, err := url.Parse(peer.Proxy)
	if err != nil {
		return fmt.Errorf("invalid peer proxy URL (%s): %w", peer.Proxy, err)
	}
	isTailcat := strings.EqualFold(u.Scheme, "tailcat")
	if !isTailcat {
		if peer.TailcatKey != "" {
			return fmt.Errorf("tailcatKey is only valid with a tailcat:// proxy")
		}
		return nil
	}

	if !strings.EqualFold(u.Scheme, "tailcat") || u.Opaque != "" || u.User != nil || u.Host == "" ||
		u.Path != "" || u.RawPath != "" || u.RawQuery != "" || u.ForceQuery || u.Fragment != "" {
		return fmt.Errorf("invalid Tailcat peer proxy URL %q: expected tailcat://<connection-token> with no credentials, path, query, fragment, or port", peer.Proxy)
	}
	// Connection blobs use base64url and therefore never contain a colon. This
	// catches explicit ports without passing the case-sensitive token through
	// URL hostname normalization.
	if strings.Contains(u.Host, ":") {
		return fmt.Errorf("invalid Tailcat peer proxy URL %q: explicit ports are not allowed (Tailcat uses port 80)", peer.Proxy)
	}
	blob := u.Host
	if err := tailcat.ValidateConnectionBlob(blob); err != nil {
		return fmt.Errorf("invalid Tailcat connection token: %w", err)
	}
	peer.tailcatBlob = blob
	peer.ProxyURL = &url.URL{Scheme: "http", Host: "server.tailcat"}

	if peer.TailcatKey != "" && peer.TailcatKey != TailcatEphemeralKey {
		loaded, err := tailcat.LoadPrivateKey(peer.TailcatKey, false)
		if err != nil {
			return fmt.Errorf("tailcatKey: %w", err)
		}
		peer.tailcatPrivateKey = loaded
	}
	return nil
}

func validateTailcatConfig(cfg *Config) error {
	if tc := cfg.Tailcat; tc != nil {
		seenAllow := make(map[string]struct{}, len(tc.Allow))
		allowedClients := make([]string, 0, len(tc.Allow))
		for i, raw := range tc.Allow {
			canonical := raw
			if raw != TailcatAllowAll {
				var err error
				canonical, err = tailcat.ValidateNodePublic(raw)
				if err != nil {
					return fmt.Errorf("tailcat.allow[%d]: invalid node public key: %w", i, err)
				}
				if canonical != raw {
					return fmt.Errorf("tailcat.allow[%d]: must be a full canonical nodekey: public key", i)
				}
			}
			if _, exists := seenAllow[canonical]; exists {
				continue
			}
			seenAllow[canonical] = struct{}{}
			allowedClients = append(allowedClients, canonical)
		}
		tc.Allow = allowedClients
		tc.AllowedClients = allowedClients

		validModels := publicTailcatModelIDs(*cfg)
		seenModels := make(map[string]struct{}, len(tc.Models))
		models := make([]string, 0, len(tc.Models))
		for i, model := range tc.Models {
			if model == "" {
				return fmt.Errorf("tailcat.models[%d]: model ID cannot be empty", i)
			}
			if model != "*" {
				if _, ok := validModels[model]; !ok {
					return fmt.Errorf("tailcat.models[%d]: unknown public model ID %q", i, model)
				}
			}
			if _, exists := seenModels[model]; exists {
				continue
			}
			seenModels[model] = struct{}{}
			models = append(models, model)
		}
		tc.Models = models
	}

	// One stable client identity may safely share transports to the same
	// destination, but using it for different Tailcat servers creates an
	// ambiguous network identity and is rejected up front.
	type destination struct{ server string }
	used := map[string]destination{}
	for peerID, peer := range cfg.Peers {
		clientKey, blob, pk, found := peer.Tailcat()
		if !found || clientKey == "" || clientKey == TailcatEphemeralKey {
			continue
		}
		client := pk.Identity()
		server, _ := tailcat.ConnectionDestination(blob)
		if prev, ok := used[client]; ok && prev.server != server {
			return fmt.Errorf("peers.%s.tailcatKey reuses client node key %s for a different Tailcat destination", peerID, client)
		}
		used[client] = destination{server: server}
	}
	return nil
}

func publicTailcatModelIDs(cfg Config) map[string]struct{} {
	ids := make(map[string]struct{})
	for id, model := range cfg.Models {
		ids[id] = struct{}{}
		for _, alias := range model.Aliases {
			ids[alias] = struct{}{}
		}
	}
	for id := range cfg.Selectors {
		ids[id] = struct{}{}
	}
	for _, profile := range cfg.Profiles {
		for pin := range profile.Pins {
			ids[pin] = struct{}{}
		}
	}
	for peerID, peer := range cfg.Peers {
		for _, model := range peer.Models {
			ids[PeerModelFQN(peerID, model)] = struct{}{}
		}
	}
	return ids
}

package config

import (
	"os"
	"strings"
	"testing"
)

// A config naming a key bornite does not know must fail the load. yaml.v3 drops
// such keys silently, which is how a top-level `aliases:` block sat in the
// pens's bornite.yaml for months: it parsed, it warned about nothing, and
// nothing in it was ever served.
func TestRejectsUnknownTopLevelKey(t *testing.T) {
	_, err := LoadConfigFromReader(strings.NewReader(`
aliases:
  fast:
    cmd: ./llama-server --port ${PORT}
models:
  m1:
    cmd: ./llama-server --port ${PORT}
`))
	if err == nil {
		t.Fatal("expected an error for unknown top-level key `aliases`")
	}
	if !strings.Contains(err.Error(), "aliases") {
		t.Errorf("error should name the offending key, got: %v", err)
	}
}

func TestAcceptsKnownTopLevelKeys(t *testing.T) {
	if _, err := LoadConfigFromReader(strings.NewReader(`
models:
  m1:
    cmd: ./llama-server --port ${PORT}
`)); err != nil {
		t.Fatalf("a valid config must load: %v", err)
	}
}

// `defs` holds YAML anchors consumed through `<<:` merge keys. The YAML
// parser resolves those itself and no Config field reads the block, so it
// must not be rejected.
func TestAcceptsDefsAnchorBlock(t *testing.T) {
	if _, err := LoadConfigFromReader(strings.NewReader(`
defs:
  llm: &llm
    in: [text]
    out: [text]
models:
  m1:
    cmd: ./llama-server --port ${PORT}
    capabilities:
      <<: [*llm]
`)); err != nil {
		t.Fatalf("defs/anchor configs must load: %v", err)
	}
}

// Unknown keys nested below the top level stay tolerated: the legacy
// `filters.strip_params` path decodes through an anonymous struct that must
// ignore fields it does not model.
func TestToleratesUnknownNestedKeys(t *testing.T) {
	if _, err := LoadConfigFromReader(strings.NewReader(`
models:
  m1:
    cmd: ./llama-server --port ${PORT}
    filters:
      strip_params: not-a-real-option
`)); err != nil {
		t.Fatalf("nested unknown keys must not fail the load: %v", err)
	}
}

// The configs the pens actually runs must load. This is the check that
// catches a silently-dropped section in production config.
func TestRealpensConfigsLoad(t *testing.T) {
	for _, p := range []string{
		"/home/toxic/pens/pens/config/bornite.yaml",
		"/home/toxic/kimi-auto/bornite.d/kimi-auto.yaml",
	} {
		f, err := os.Open(p)
		if err != nil {
			t.Skipf("config not present on this box: %s", p)
		}
		cfg, err := LoadConfigFromReader(f)
		f.Close()
		if err != nil {
			t.Errorf("%s must load: %v", p, err)
			continue
		}
		if len(cfg.Models) == 0 {
			t.Errorf("%s loaded with zero models", p)
		}
	}
}

package config

import (
	"os"
)

// loadConfigFile is agele's config file reader, ported during the
// bornite union so agele's config-loading behaviour is not lost.
func loadConfigFile(path string) (Config, error) {
	file, err := os.Open(path)
	if err != nil {
		return Config{}, err
	}
	defer file.Close()
	return LoadConfigFromReader(file)
}

package docagent

import (
	"context"
	"encoding/json"
	"fmt"
	"sort"
	"strings"
	"time"

	"github.com/toxicwind/bornite/internal/mcptools"
)

// Tool results are read straight into a model's context window, which for a
// local model is commonly 4k-32k tokens. Every result passes through one of
// these caps.
const (
	maxSearchResultBytes = 8 * 1024
	maxSchemaResultBytes = 8 * 1024

	defaultDocMaxLines = 250

	// MaxDocLines is exported so transport tests can assert the clamp.
	MaxDocLines    = 400
	maxDocMaxLines = MaxDocLines
)

// DocsProvider serves bornite's own embedded documentation.
//
// It is the reference implementation of Provider: everything it does is an
// in-memory read of an immutable index, so it holds no resources and its
// Shutdown is a no-op.
type DocsProvider struct {
	docs *Docs
}

var _ mcptools.Provider = (*DocsProvider)(nil)

// NewDocsProvider builds the provider. A nil or disabled *Docs
// yields a provider that advertises no tools rather than an error, matching
// how the rest of bornite treats missing documentation.
func NewDocsProvider(docs *Docs) *DocsProvider {
	return &DocsProvider{docs: docs}
}

func (p *DocsProvider) ID() string { return "docs" }

func (p *DocsProvider) Shutdown(time.Duration) error { return nil }

// toolCategories is the closed set list_docs accepts, matching the knowledge
// base layout plus the synthesized reference docs.
var toolCategories = []string{"tutorials", "guides", "examples", "reference"}

// Reading documentation is both read-only and idempotent: the same call
// returns the same answer until the binary is rebuilt.
func docsAnnotations() *mcptools.Annotations {
	return &mcptools.Annotations{ReadOnlyHint: true, IdempotentHint: true}
}

// Tools lists the documentation tools. Names are local; the registry adds the
// "docs" namespace.
func (p *DocsProvider) Tools(context.Context) ([]mcptools.Tool, error) {
	if !p.docs.Enabled() {
		return nil, nil
	}

	// Constraining `id` to an enum of real doc ids is what stops a small model
	// inventing one. It costs roughly 1KB per request at the current corpus
	// size; past a few hundred docs, drop the enum and rely on list_docs.
	ids := p.docs.IDs()

	return []mcptools.Tool{
		{
			Name:  "list_docs",
			Title: "List bornite documentation",
			Description: "List the available bornite documentation. Returns every document's id, title and summary. " +
				"Call this first to see what exists, then call " + mcptools.QualifyName(p.ID(), "get_doc") + " with an id.",
			Annotations: docsAnnotations(),
			Tags:        []string{"docs", "index", "configuration"},
			InputSchema: map[string]any{
				"type": "object",
				"properties": map[string]any{
					"category": map[string]any{
						"type":        "string",
						"description": "Only list documents in this category.",
						"enum":        toolCategories,
					},
					"tag": map[string]any{
						"type":        "string",
						"description": "Only list documents carrying this tag, for example 'ttl' or 'docker'.",
					},
				},
				"additionalProperties": false,
			},
		},
		{
			Name:  "get_doc",
			Title: "Read a bornite document",
			Description: "Read one bornite document by id. Ids come from " + mcptools.QualifyName(p.ID(), "list_docs") + " or " +
				mcptools.QualifyName(p.ID(), "search_docs") + ". " +
				"Ids starting with 'reference/config/' return that section of config.example.yaml verbatim, comments included.",
			Annotations: docsAnnotations(),
			Tags:        []string{"docs", "configuration"},
			InputSchema: map[string]any{
				"type": "object",
				"properties": map[string]any{
					"id": map[string]any{
						"type":        "string",
						"description": "The document id, for example 'guides/model-runtime/ttl-and-unloading' or 'reference/config/models'.",
						"enum":        ids,
					},
					"offset": map[string]any{
						"type":        "integer",
						"description": "Line to start from, for continuing a truncated document. Defaults to 0.",
						"minimum":     0,
					},
					"max_lines": map[string]any{
						"type":        "integer",
						"description": fmt.Sprintf("Maximum lines to return. Defaults to %d, maximum %d.", defaultDocMaxLines, maxDocMaxLines),
						"minimum":     1,
						"maximum":     maxDocMaxLines,
					},
				},
				"required":             []string{"id"},
				"additionalProperties": false,
			},
		},
		{
			Name:  "search_docs",
			Title: "Search bornite documentation",
			Description: "Required first step for every bornite question. Keyword search across all documentation, including config.example.yaml. " +
				"Returns matching snippets with the document id to read next, via " + mcptools.QualifyName(p.ID(), "get_doc") + ".",
			Annotations: docsAnnotations(),
			Tags:        []string{"docs", "search", "configuration"},
			InputSchema: map[string]any{
				"type": "object",
				"properties": map[string]any{
					"query": map[string]any{
						"type":        "string",
						"description": "Keywords, for example 'ttl unload' or 'draft model speculative'.",
					},
					"max_results": map[string]any{
						"type":        "integer",
						"description": "Maximum number of matches. Defaults to 5, maximum 15.",
						"minimum":     1,
						"maximum":     15,
					},
				},
				"required":             []string{"query"},
				"additionalProperties": false,
			},
		},
		{
			Name:  "get_config_schema",
			Title: "Look up a bornite config key",
			Description: "Look up the JSON schema for a configuration key: its type, description, default, and direct child keys. " +
				"Always call this when the user names or asks about a configuration key, even if search results already answer the question. " +
				"An unknown-path error proves that key does not exist; say that explicitly before suggesting a real alternative.",
			Annotations: docsAnnotations(),
			Tags:        []string{"docs", "schema", "configuration"},
			InputSchema: map[string]any{
				"type": "object",
				"properties": map[string]any{
					"path": map[string]any{
						"type": "string",
						"description": "Dotted path into the config schema. Use '*' for a map's keys, " +
							"for example 'models.*.filters'. Omit or leave empty for the top level.",
					},
				},
				"additionalProperties": false,
			},
		},
	}, nil
}

// Call runs one documentation tool by its local name.
func (p *DocsProvider) Call(_ context.Context, name string, args map[string]json.RawMessage) (mcptools.Result, error) {
	if !p.docs.Enabled() {
		return mcptools.Result{}, fmt.Errorf("no documentation is indexed")
	}

	switch name {
	case "list_docs":
		return p.listDocs(args), nil
	case "get_doc":
		return p.getDoc(args), nil
	case "search_docs":
		return p.searchDocs(args), nil
	case "get_config_schema":
		return p.getConfigSchema(args), nil
	default:
		return mcptools.Result{}, fmt.Errorf("unknown tool %q", name)
	}
}

func (p *DocsProvider) listDocs(args map[string]json.RawMessage) mcptools.Result {
	filter := IndexFilter{
		Category: mcptools.StringArg(args, "category"),
		Tag:      mcptools.StringArg(args, "tag"),
	}

	index := p.docs.Index(filter)
	if len(index) == 0 {
		return mcptools.Result{
			IsError: true,
			Content: fmt.Sprintf("No documents matched. Valid categories are: %s. Call %s with no arguments to see everything.",
				strings.Join(toolCategories, ", "), mcptools.QualifyName(p.ID(), "list_docs")),
		}
	}

	var b strings.Builder
	fmt.Fprintf(&b, "bornite documentation. Read one with %s using its id.\n", mcptools.QualifyName(p.ID(), "get_doc"))

	category := ""
	for _, meta := range index {
		if meta.Category != category {
			category = meta.Category
			fmt.Fprintf(&b, "\n## %s\n", category)
		}
		fmt.Fprintf(&b, "- %s — %s: %s\n", meta.ID, meta.Title, meta.Summary)
	}

	return mcptools.CapResult(b.String(), mcptools.MaxToolResultBytes)
}

func (p *DocsProvider) getDoc(args map[string]json.RawMessage) mcptools.Result {
	id := mcptools.StringArg(args, "id")
	if id == "" {
		return mcptools.Result{IsError: true, Content: fmt.Sprintf(
			"Error: \"id\" is required. Call %s to see the available ids.", mcptools.QualifyName(p.ID(), "list_docs"))}
	}

	maxLines := mcptools.IntArg(args, "max_lines", defaultDocMaxLines)
	if maxLines > maxDocMaxLines {
		maxLines = maxDocMaxLines
	}

	doc, ok := p.docs.Doc(id, DocOptions{
		Offset:   mcptools.IntArg(args, "offset", 0),
		MaxLines: maxLines,
		MaxBytes: mcptools.MaxToolResultBytes,
	})
	if !ok {
		return mcptools.Result{IsError: true, Content: unknownDocMessage(p.ID(), id, p.docs.IDs())}
	}

	var b strings.Builder
	fmt.Fprintf(&b, "# %s (%s)\n", doc.Title, doc.ID)
	fmt.Fprintf(&b, "source: %s lines %d-%d\n\n", doc.Source, doc.SourceLine, doc.SourceLine+(doc.EndLine-doc.StartLine))

	if doc.Fence != "" {
		fmt.Fprintf(&b, "```%s\n%s\n```\n", doc.Fence, doc.Text)
	} else {
		b.WriteString(doc.Text)
		b.WriteString("\n")
	}

	if doc.Truncated {
		fmt.Fprintf(&b, "\n[truncated at line %d of %d — call get_doc again with offset=%d]\n",
			doc.EndLine, doc.Lines, doc.EndLine)
	}

	result := mcptools.CapResult(b.String(), mcptools.MaxToolResultBytes)
	result.Truncated = result.Truncated || doc.Truncated
	return result
}

func (p *DocsProvider) searchDocs(args map[string]json.RawMessage) mcptools.Result {
	query := mcptools.StringArg(args, "query")
	if query == "" {
		return mcptools.Result{IsError: true, Content: `Error: "query" is required.`}
	}

	hits := p.docs.Search(query, SearchOptions{
		MaxHits: mcptools.IntArg(args, "max_results", 0),
	})
	if len(hits) == 0 {
		// An empty result set is a valid answer, not an error.
		return mcptools.Result{
			Content: fmt.Sprintf("No matches for %q. Try %s, or fewer and broader keywords.", query, mcptools.QualifyName(p.ID(), "list_docs")),
		}
	}

	var b strings.Builder
	fmt.Fprintf(&b, "%d matches for %q. Read a document in full with %s.\n", len(hits), query, mcptools.QualifyName(p.ID(), "get_doc"))
	for i, hit := range hits {
		fmt.Fprintf(&b, "\n%d. %s (line %d) — %s\n```\n%s\n```\n", i+1, hit.ID, hit.Line, hit.Title, hit.Snippet)
	}

	return mcptools.CapResult(b.String(), maxSearchResultBytes)
}

func (p *DocsProvider) getConfigSchema(args map[string]json.RawMessage) mcptools.Result {
	path := mcptools.StringArg(args, "path")

	fragment, ok := p.docs.SchemaFragment(path)
	if !ok {
		parent := path
		if idx := strings.LastIndexByte(parent, '.'); idx > 0 {
			parent = parent[:idx]
		} else {
			parent = ""
		}
		content := fmt.Sprintf("Error: no schema at path %q.", path)
		if siblings := p.docs.SchemaPaths(parent); len(siblings) > 0 {
			content += " Valid paths here: " + strings.Join(siblings, ", ")
		}
		return mcptools.Result{IsError: true, Content: content}
	}

	displayPath := fragment.Path
	if displayPath == "" {
		displayPath = "(top level)"
	}

	var b strings.Builder
	fmt.Fprintf(&b, "# %s\n", displayPath)
	if fragment.Type != "" {
		fmt.Fprintf(&b, "type: %s\n", fragment.Type)
	}
	if len(fragment.Default) > 0 {
		fmt.Fprintf(&b, "default: %s\n", fragment.Default)
	}
	if len(fragment.Enum) > 0 {
		fmt.Fprintf(&b, "allowed values: %s\n", fragment.Enum)
	}
	if len(fragment.Required) > 0 {
		fmt.Fprintf(&b, "required keys: %s\n", strings.Join(fragment.Required, ", "))
	}
	if fragment.Description != "" {
		fmt.Fprintf(&b, "\n%s\n", fragment.Description)
	}
	if fragment.MapKeys {
		fmt.Fprintf(&b, "\nKeys are user defined. Use path \"%s*\" to inspect an entry.\n", dotted(fragment.Path))
	}
	if len(fragment.Properties) > 0 {
		b.WriteString("\nkeys:\n")
		for _, prop := range fragment.Properties {
			marker := ""
			if prop.Required {
				marker = " (required)"
			}
			fmt.Fprintf(&b, "- %s%s: %s — %s\n", prop.Name, marker, prop.Type, prop.Description)
		}
		fmt.Fprintf(&b, "\nInspect one with %s path=\"%s<key>\".\n", mcptools.QualifyName(p.ID(), "get_config_schema"), dotted(fragment.Path))
	}

	return mcptools.CapResult(b.String(), maxSchemaResultBytes)
}

// unknownDocMessage suggests real ids so the model can correct itself instead
// of guessing again.
func unknownDocMessage(providerID, id string, ids []string) string {
	needle := strings.ToLower(id)
	if idx := strings.LastIndexByte(needle, '/'); idx >= 0 {
		needle = needle[idx+1:]
	}

	var suggestions []string
	for _, candidate := range ids {
		if strings.Contains(strings.ToLower(candidate), needle) {
			suggestions = append(suggestions, candidate)
		}
	}
	if len(suggestions) == 0 {
		suggestions = ids
	}
	sort.Strings(suggestions)
	if len(suggestions) > 10 {
		suggestions = suggestions[:10]
	}

	return fmt.Sprintf("Error: no document with id %q. Did you mean one of: %s? Call %s to see them all.",
		id, strings.Join(suggestions, ", "), mcptools.QualifyName(providerID, "list_docs"))
}

// dotted returns the path with a trailing separator, so callers can append a
// key without special-casing the empty root path.
func dotted(path string) string {
	if path == "" {
		return ""
	}
	return path + "."
}

// Package docagent indexes bornite's own documentation so it can be
// served to an LLM through the /api/mcp endpoint.
//
// Everything retrievable is a "doc" with an id in one flat namespace:
//
//	guides/model-runtime/ttl-and-unloading  a knowledge base article from docs/kb/
//	reference/config/models     a top-level section of config.example.yaml
//	reference/readme            README.md
//
// One namespace means the agent needs one index listing, one getter and one
// search rather than a set per source, which materially improves how reliably
// small local models can use the tools.
package docagent

import (
	"encoding/json"
	"io/fs"
	"sort"
	"strings"
)

// File names read from the FS. Paths are relative to the FS root, which
// mirrors the repository root.
const (
	configExampleFile = "config.example.yaml"
	configSchemaFile  = "config-schema.json"
	kbDir             = "kb"
)

// Category values. Index listings are ordered by this sequence so a model
// reading top to bottom sees walkthroughs before raw reference material.
var categoryOrder = []string{"tutorials", "guides", "examples", "reference"}

// DocMeta is the index entry for a doc. It is what list_docs returns.
type DocMeta struct {
	ID         string   `json:"id"`
	Title      string   `json:"title"`
	Summary    string   `json:"summary"`
	Category   string   `json:"category"`
	Tags       []string `json:"tags,omitempty"`
	ConfigKeys []string `json:"config_keys,omitempty"`
	Lines      int      `json:"lines"`
}

// DocText is a doc's body, possibly a windowed slice of it.
type DocText struct {
	DocMeta
	Text       string `json:"text"`
	StartLine  int    `json:"start_line"` // 1-based, within the doc body
	EndLine    int    `json:"end_line"`
	Truncated  bool   `json:"truncated"`
	Source     string `json:"source"`      // file the text came from
	SourceLine int    `json:"source_line"` // line in Source holding body line 1
	Fence      string `json:"fence,omitempty"`
}

// DocOptions windows a doc body. The zero value returns the whole doc subject
// to the default caps applied by the caller.
type DocOptions struct {
	Offset   int // 0-based body line to start at
	MaxLines int // 0 means no line limit
	MaxBytes int // 0 means no byte limit
}

// IndexFilter narrows an index listing. Empty fields do not filter.
type IndexFilter struct {
	Category  string
	Tag       string
	ConfigKey string
}

// doc is the internal representation. Bodies are kept as lines because every
// operation here is line oriented: windowing, search context, and citations.
type doc struct {
	meta       DocMeta
	lines      []string
	source     string
	sourceLine int    // line in source holding lines[0]
	fence      string // non-empty renders the body inside a fenced block
}

// Docs is an immutable index. It is safe for concurrent use and safe to share
// across Server instances, including across a hot config reload.
type Docs struct {
	byID    map[string]*doc
	ordered []*doc
	ids     []string

	schema     map[string]any
	schemaDefs map[string]any
}

// New indexes fsys. It never fails: a nil fsys, or one without
// config.example.yaml, yields a disabled *Docs whose methods return empty
// results. Callers check Enabled and report the feature as unavailable.
func New(fsys fs.FS) *Docs {
	return NewWithSchema(fsys, nil)
}

// NewWithSchema indexes fsys, using schema when it is non-empty instead of a
// config-schema.json file in fsys. This lets the embedded documentation remain
// self-contained while the public schema stays at the repository root.
func NewWithSchema(fsys fs.FS, schema []byte) *Docs {
	if fsys == nil {
		return &Docs{}
	}

	example, err := fs.ReadFile(fsys, configExampleFile)
	if err != nil {
		return &Docs{}
	}

	d := &Docs{byID: map[string]*doc{}}

	// Order matters: it is the order Index reports within a category, and the
	// order categoryOrder then groups.
	for _, doc := range parseKB(fsys) {
		d.add(doc)
	}
	for _, doc := range parseConfigExample(string(example)) {
		d.add(doc)
	}
	for _, doc := range parseExtraMarkdown(fsys) {
		d.add(doc)
	}

	raw := schema
	if len(raw) == 0 {
		raw, _ = fs.ReadFile(fsys, configSchemaFile)
	}
	if len(raw) != 0 {
		var schema map[string]any
		if json.Unmarshal(raw, &schema) == nil {
			d.schema = schema
			if defs, ok := schema["definitions"].(map[string]any); ok {
				d.schemaDefs = defs
			}
		}
	}

	sort.Slice(d.ordered, func(i, j int) bool {
		ci := categoryRank(d.ordered[i].meta.Category)
		cj := categoryRank(d.ordered[j].meta.Category)
		if ci != cj {
			return ci < cj
		}
		return d.ordered[i].meta.ID < d.ordered[j].meta.ID
	})

	d.ids = make([]string, 0, len(d.byID))
	for id := range d.byID {
		d.ids = append(d.ids, id)
	}
	sort.Strings(d.ids)

	return d
}

func (d *Docs) add(doc *doc) {
	if doc == nil || doc.meta.ID == "" {
		return
	}
	if _, exists := d.byID[doc.meta.ID]; exists {
		return // first definition wins; the golden test catches duplicates
	}
	doc.meta.Lines = len(doc.lines)
	d.byID[doc.meta.ID] = doc
	d.ordered = append(d.ordered, doc)
}

func categoryRank(category string) int {
	for i, c := range categoryOrder {
		if c == category {
			return i
		}
	}
	return len(categoryOrder)
}

// Enabled reports whether any documentation was indexed. It is nil-receiver
// safe so a Server built without a reference library works unchanged.
func (d *Docs) Enabled() bool {
	return d != nil && len(d.byID) > 0
}

// IDs returns every doc id, sorted. Used to build the get_doc `id` enum and to
// suggest alternatives when a lookup misses.
func (d *Docs) IDs() []string {
	if !d.Enabled() {
		return nil
	}
	out := make([]string, len(d.ids))
	copy(out, d.ids)
	return out
}

// Index returns matching docs in category order. A zero filter returns
// everything.
func (d *Docs) Index(filter IndexFilter) []DocMeta {
	if !d.Enabled() {
		return nil
	}
	out := make([]DocMeta, 0, len(d.ordered))
	for _, doc := range d.ordered {
		if filter.Category != "" && !strings.EqualFold(doc.meta.Category, filter.Category) {
			continue
		}
		if filter.Tag != "" && !containsFold(doc.meta.Tags, filter.Tag) {
			continue
		}
		if filter.ConfigKey != "" && !containsFold(doc.meta.ConfigKeys, filter.ConfigKey) {
			continue
		}
		out = append(out, doc.meta)
	}
	return out
}

// Doc returns a doc body, windowed by opts. Ids are looked up in a map and are
// never joined to a filesystem path, so an id shaped like "../../etc/passwd"
// is simply a miss.
func (d *Docs) Doc(id string, opts DocOptions) (DocText, bool) {
	if !d.Enabled() {
		return DocText{}, false
	}
	doc, ok := d.byID[strings.TrimSpace(id)]
	if !ok {
		return DocText{}, false
	}

	start := opts.Offset
	if start < 0 {
		start = 0
	}
	if start > len(doc.lines) {
		start = len(doc.lines)
	}

	end := len(doc.lines)
	truncated := false
	if opts.MaxLines > 0 && start+opts.MaxLines < end {
		end = start + opts.MaxLines
		truncated = true
	}

	body := strings.Join(doc.lines[start:end], "\n")
	if opts.MaxBytes > 0 {
		capped, wasCapped := CapText(body, opts.MaxBytes)
		if wasCapped {
			// Recount so EndLine still points at real content.
			end = start + strings.Count(capped, "\n") + 1
			truncated = true
			body = capped
		}
	}

	return DocText{
		DocMeta:    doc.meta,
		Text:       body,
		StartLine:  start + 1,
		EndLine:    end,
		Truncated:  truncated,
		Source:     doc.source,
		SourceLine: doc.sourceLine + start,
		Fence:      doc.fence,
	}, true
}

// CapText truncates s at the last newline before maxBytes. It reports whether
// anything was removed. Tool results land in a local model's context window,
// so every path that produces one passes through here.
func CapText(s string, maxBytes int) (string, bool) {
	if maxBytes <= 0 || len(s) <= maxBytes {
		return s, false
	}
	cut := s[:maxBytes]
	if idx := strings.LastIndexByte(cut, '\n'); idx > 0 {
		cut = cut[:idx]
	}
	return cut, true
}

func containsFold(haystack []string, needle string) bool {
	for _, v := range haystack {
		if strings.EqualFold(v, needle) {
			return true
		}
	}
	return false
}

// truncateSummary keeps index listings compact. Summaries are already required
// to be short; this guards the synthesized ones.
func truncateSummary(s string, max int) string {
	s = strings.TrimSpace(s)
	if len(s) <= max {
		return s
	}
	cut := s[:max]
	if idx := strings.LastIndexByte(cut, ' '); idx > max/2 {
		cut = cut[:idx]
	}
	return cut + "..."
}

