import "os"

// Provider represents a resolved upstream provider.
type Provider struct {
	ID       string
	BaseURL  string
	APIKey   string
	NoAuth   bool
	FreeTier bool
	Models   []string
	ModelMap map[string]string
	Weight   float64
	ELO      int
}

// ProviderRegistry manages configured providers.
type ProviderRegistry struct {
	providers map[string]Provider
	byModel   map[string][]string
}

func NewProviderRegistry(cfg map[string]ProviderCfg) *ProviderRegistry {
	pr := &ProviderRegistry{
		providers: make(map[string]Provider),
		byModel:   make(map[string][]string),
	}
	defaults := defaultProviders()
	for id, p := range defaults {
		pr.providers[id] = p
	}
	for id, pcfg := range cfg {
		p := Provider{
			ID: id, BaseURL: pcfg.BaseURL, NoAuth: pcfg.NoAuth,
			FreeTier: pcfg.FreeTier, Models: pcfg.Models,
			ModelMap: pcfg.ModelMap, Weight: pcfg.Weight, ELO: pcfg.ELO,
		}
		if pcfg.KeyEnv != "" {
			p.APIKey = os.Getenv(pcfg.KeyEnv)
		}
		if p.APIKey == "" && pcfg.KeyEnvAlt != "" {
			p.APIKey = os.Getenv(pcfg.KeyEnvAlt)
		}
		pr.providers[id] = p
	}
	pr.rebuildIndex()
	return pr
}

func (pr *ProviderRegistry) rebuildIndex() {
	pr.byModel = make(map[string][]string)
	for id, p := range pr.providers {
		for _, m := range p.Models {
			pr.byModel[m] = append(pr.byModel[m], id)
		}
		for local := range p.ModelMap {
			pr.byModel[local] = append(pr.byModel[local], id)
		}
	}
}

func (pr *ProviderRegistry) ForModel(modelID string) []Provider {
	ids, ok := pr.byModel[modelID]
	if !ok {
		var all []Provider
		for _, p := range pr.providers {
			all = append(all, p)
		}
		return all
	}
	var result []Provider
	for _, id := range ids {
		if p, ok := pr.providers[id]; ok {
			result = append(result, p)
		}
	}
	return result
}

func (pr *ProviderRegistry) Get(id string) (Provider, bool) {
	p, ok := pr.providers[id]
	return p, ok
}

func (pr *ProviderRegistry) Providers() []Provider { return pr.All() }
func (pr *ProviderRegistry) All() []Provider {
	var result []Provider
	for _, p := range pr.providers {
		result = append(result, p)
	}
	return result
}

