package flock

import (
	"sync"
	"time"
)

// ImmediateQuarantine implements the Dynamo-inspired failure detection:
// mark a provider dead on the FIRST in-path failure signal (timeout, 5xx,
// 429, connection refused) rather than waiting for the next 30s probe tick.
//
// This is the "Smart Router" pattern: bypass the slow health-check
// propagation, quarantine immediately, canary half-open for recovery.
//
// Key rule from the gateway audit: 4xx (except 429) must NOT trip the
// breaker — that's a caller bug, not provider health.

type QuarantineReason int

const (
	ReasonNone QuarantineReason = iota
	ReasonTimeout
	ReasonServerError // 5xx
	ReasonRateLimit   // 429
	ReasonConnRefused
)

type quarantineEntry struct {
	reason      QuarantineReason
	quarantined time.Time
	// canary state: allow 1 probe after canaryDelay
	canaryAt time.Time
}

type ImmediateQuarantine struct {
	mu          sync.RWMutex
	quarantined map[string]*quarantineEntry
	// how long before a quarantined provider gets a canary probe
	canaryDelay time.Duration
	// callback when provider is quarantined (for metrics/alerts)
	onQuarantine func(provider string, reason QuarantineReason)
}

func NewImmediateQuarantine(canaryDelay time.Duration) *ImmediateQuarantine {
	if canaryDelay <= 0 {
		canaryDelay = 10 * time.Second
	}
	return &ImmediateQuarantine{
		quarantined: make(map[string]*quarantineEntry),
		canaryDelay: canaryDelay,
	}
}

// Signal records an in-path failure. Returns true if this newly quarantined
// the provider (false if already quarantined or not a quarantine-worthy error).
//
// statusCode: HTTP status (0 = timeout/connection failure)
// Returns false for 4xx (except 429) — caller bugs don't quarantine.
func (iq *ImmediateQuarantine) Signal(provider string, statusCode int, timedOut bool) bool {
	reason := classifyFailure(statusCode, timedOut)
	if reason == ReasonNone {
		return false
	}

	iq.mu.Lock()
	defer iq.mu.Unlock()

	if _, ok := iq.quarantined[provider]; ok {
		return false // already quarantined
	}

	iq.quarantined[provider] = &quarantineEntry{
		reason:      reason,
		quarantined: time.Now(),
		canaryAt:    time.Now().Add(iq.canaryDelay),
	}

	if iq.onQuarantine != nil {
		// Call outside lock to avoid deadlock
		go iq.onQuarantine(provider, reason)
	}
	return true
}

// IsQuarantined returns true if provider is currently quarantined.
// A provider becomes canary-eligible after canaryDelay (single probe allowed).
func (iq *ImmediateQuarantine) IsQuarantined(provider string) bool {
	iq.mu.RLock()
	defer iq.mu.RUnlock()
	e, ok := iq.quarantined[provider]
	if !ok {
		return false
	}
	// If past canary time, allow one probe (caller should use AllowCanary)
	return time.Now().Before(e.canaryAt)
}

// AllowCanary returns true if this provider is due for a canary probe.
// Only one caller should get true (compare-and-swap on canaryAt).
func (iq *ImmediateQuarantine) AllowCanary(provider string) bool {
	iq.mu.Lock()
	defer iq.mu.Unlock()
	e, ok := iq.quarantined[provider]
	if !ok {
		return false
	}
	if time.Now().Before(e.canaryAt) {
		return false
	}
	// Grant canary: push next canary out to prevent thundering bornite
	e.canaryAt = time.Now().Add(iq.canaryDelay)
	return true
}

// Clear removes quarantine (provider recovered via canary success).
func (iq *ImmediateQuarantine) Clear(provider string) {
	iq.mu.Lock()
	defer iq.mu.Unlock()
	delete(iq.quarantined, provider)
}

// QuarantinedList returns all currently quarantined providers.
func (iq *ImmediateQuarantine) QuarantinedList() map[string]QuarantineReason {
	iq.mu.RLock()
	defer iq.mu.RUnlock()
	out := make(map[string]QuarantineReason, len(iq.quarantined))
	for k, v := range iq.quarantined {
		out[k] = v.reason
	}
	return out
}

func classifyFailure(statusCode int, timedOut bool) QuarantineReason {
	if timedOut {
		return ReasonTimeout
	}
	if statusCode == 0 {
		return ReasonConnRefused
	}
	if statusCode == 429 {
		return ReasonRateLimit
	}
	if statusCode >= 500 {
		return ReasonServerError
	}
	// 4xx (except 429) = caller bug, not provider health. Don't quarantine.
	return ReasonNone
}

// ReasonString for logging/metrics.
func (r QuarantineReason) String() string {
	switch r {
	case ReasonTimeout:
		return "timeout"
	case ReasonServerError:
		return "5xx"
	case ReasonRateLimit:
		return "429"
	case ReasonConnRefused:
		return "conn_refused"
	default:
		return "none"
	}
}

package flock

import (
	"bytes"
	"context"
	"encoding/json"
	"fmt"
	"io"
	"math/rand"
	"net/http"
	"net/url"
	"strings"
	"sync"
	"sync/atomic"
	"time"

	"github.com/toxicwind/bornite/internal/logmon"
	"github.com/toxicwind/bornite/internal/shared"
)

// Router implements router.Router for cloud provider dispatch.
type Router struct {
	cfg       *FlockConfig
	logger    *logmon.Monitor
	registry  *ProviderRegistry
	healthDB  *HealthDB
	limiter   *RateLimiter
	circuits  sync.Map // string -> *CircuitBreaker
	coalescer *RequestCoalescer
	metrics   *MetricsCollector
	client    *http.Client
	rrCounter uint64
	// Cutting-edge additions (2026-09-30 maximal update)
	sessionAffinity *SessionAffinity
	stratifiedElo   *StratifiedElo
	semCache        *SemanticCache
	quarantine      *ImmediateQuarantine
	costQuality     *CostQualityRouter
	// GitHub-borrowed patterns (2026-09-30)
	modelBreakers  *ModelBreakerRegistry
	hardCoalescer  *HardenedCoalescer
	failoverPolicy *FailoverPolicy
}

// routingContext holds per-request mutable state.
type routingContext struct {
	modelID   string
	isAST     bool
	bodyBytes []byte
	bodyJSON  map[string]interface{}
	startTime time.Time
	strategy  string
}

// NewRouter creates a flock Router from config.
func NewRouter(cfg *FlockConfig, logger *logmon.Monitor) (*Router, error) {
	if cfg == nil {
		cfg = &FlockConfig{}
	}
	cfg.Defaults()

	reg := NewProviderRegistry(cfg.Providers)
	health := NewHealthDB(cfg.DbPath)
	limiter := NewRateLimiter(cfg.Providers)

	r := &Router{
		cfg:       cfg,
		logger:    logger,
		registry:  reg,
		healthDB:  health,
		limiter:   limiter,
		coalescer: NewRequestCoalescer(5 * time.Second),
		metrics:   NewMetricsCollector(),
		client: &http.Client{
			Timeout: time.Duration(cfg.RequestTimeout) * time.Second,
			Transport: &http.Transport{
				MaxIdleConns:        100,
				MaxIdleConnsPerHost: 10,
				IdleConnTimeout:     90 * time.Second,
				DisableCompression:  true,
			},
		},
	}
	// Initialize cutting-edge components
	r.sessionAffinity = NewSessionAffinity()
	r.stratifiedElo = NewStratifiedElo()
	r.semCache = NewSemanticCache()
	r.quarantine = NewImmediateQuarantine(10 * time.Second)
	r.costQuality = NewCostQualityRouter(r.stratifiedElo, 0.7) // default: quality-leaning
	r.quarantine.onQuarantine = func(provider string, reason QuarantineReason) {
		r.logger.Infof("[flock] QUARANTINED provider=%s reason=%s", provider, reason)
	}

	// GitHub-borrowed: per-model breakers (fallback to provider breaker)
	r.modelBreakers = NewModelBreakerRegistry(func(provider string) *CircuitBreaker {
		return r.getCircuit(provider)
	})
	r.hardCoalescer = NewHardenedCoalescer()
	r.failoverPolicy = NewFailoverPolicy()

	go r.healthProbeLoop()
	return r, nil
}

// Handles returns true if any provider can serve modelID.
func (r *Router) Handles(modelID string) bool {
	if modelID == "" {
		return false
	}
	for _, p := range r.registry.All() {
		for _, m := range p.Models {
			if m == modelID {
				return true
			}
		}
		for local := range p.ModelMap {
			if local == modelID {
				return true
			}
		}
	}
	return false
}

// ServeHTTP implements http.Handler — main entry point.
func (r *Router) ServeHTTP(w http.ResponseWriter, req *http.Request) {
	start := time.Now()
	body, _ := io.ReadAll(req.Body)
	req.Body.Close()

	var bodyJSON map[string]interface{}
	json.Unmarshal(body, &bodyJSON)

	modelID := ""
	if bodyJSON != nil {
		if m, ok := bodyJSON["model"].(string); ok {
			modelID = m
		}
	}

	isAST := r.cfg.ASTAlways
	if !isAST && bodyJSON != nil {
		if msgs, ok := bodyJSON["messages"].([]interface{}); ok {
			for _, m := range msgs {
				if msg, ok := m.(map[string]interface{}); ok {
					if c, ok := msg["content"].(string); ok {
						if strings.Contains(c, "<ast>") || strings.Contains(c, "AST:") {
							isAST = true
							break
						}
					}
				}
			}
		}
	}

	strategy := r.cfg.Strategy
	if isAST && r.cfg.ASTStrategy != "" {
		strategy = r.cfg.ASTStrategy
	}

	rt := &routingContext{
		modelID: modelID, isAST: isAST, bodyBytes: body,
		bodyJSON: bodyJSON, startTime: start, strategy: strategy,
	}

	r.logger.Infof("[flock] %s model=%s strategy=%s", req.Method, modelID, strategy)

	// Cutting-edge: session affinity check (SAGA-inspired)
	// If client sent X-Flock-Session header, try pinned provider first
	if sessionID := req.Header.Get(sessionHeader); sessionID != "" {
		if provider, _ := r.sessionAffinity.Lookup(sessionID); provider != "" {
			r.logger.Infof("[flock] session affinity hit: session=%s provider=%s", sessionID, provider)
			// Pin will be updated after successful request
		}
	}

	// Cutting-edge: semantic cache check (Hawiyat-inspired)
	// Check cache before routing - dedupe repetitive agent traffic
	if prompt := extractPrompt(bodyJSON); prompt != "" {
		if cached, ok := r.semCache.Get(modelID, prompt); ok {
			r.logger.Infof("[flock] semantic cache HIT model=%s", modelID)
			w.Header().Set("X-Flock-Cache", "hit")
			w.Header().Set("Content-Type", "application/json")
			w.Write(cached)
			return
		}
	}

	switch strategy {
	case "ast_race", "flock_race":
		r.routeAstRace(w, req, rt)
	case "sticky_affinity":
		r.routeSticky(w, req, rt)
	case "weighted_elo":
		r.routeWeighted(w, req, rt)
	case "least_latency":
		r.routeLeastLatency(w, req, rt)
	case "round_robin":
		r.routeRoundRobin(w, req, rt)
	case "free":
		r.routeFree(w, req, rt)
	case "circuit_chain":
		r.routeCircuitChain(w, req, rt)
	default:
		r.routeHybrid(w, req, rt)
	}
	r.metrics.Record(strategy, time.Since(start))
}

// ---------------------------------------------------------------------------
// Strategy: hybrid (local-aware, retry, circuit breaker)
// ---------------------------------------------------------------------------
func (r *Router) routeHybrid(w http.ResponseWriter, req *http.Request, rt *routingContext) {
	providers := r.registry.ForModel(rt.modelID)
	var lastErr error

	for attempt := 0; attempt < r.cfg.MaxRetries; attempt++ {
		for _, p := range providers {
			cb := r.getCircuit(p.ID)
			if !cb.Allow() {
				continue
			}
			if !r.limiter.Allow(p.ID) {
				continue
			}
			if !r.healthDB.IsHealthy(p.ID) {
				continue
			}

			resp, err := r.call(req.Context(), p, req, rt)
			if err == nil && resp.StatusCode < 500 {
				cb.RecordSuccess()
				r.stream(w, resp, rt)
				return
			}
			if resp != nil {
				resp.Body.Close()
			}
			lastErr = err
			cb.RecordFailure()
		}
		if attempt < r.cfg.MaxRetries-1 {
			time.Sleep(time.Duration(attempt+1) * 500 * time.Millisecond)
		}
	}
	shared.SendError(w, req, fmt.Errorf("all providers exhausted: %w", lastErr))
}

// ---------------------------------------------------------------------------
// Strategy: flock_race (parallel fan-out, first valid wins; legacy "ast_race" still accepted)
// ---------------------------------------------------------------------------
func (r *Router) routeAstRace(w http.ResponseWriter, req *http.Request, rt *routingContext) {
	providers := r.registry.ForModel(rt.modelID)
	ctx, cancel := context.WithTimeout(req.Context(), time.Duration(r.cfg.RequestTimeout)*time.Second)
	defer cancel()

	type result struct {
		resp *http.Response
		p    Provider
		err  error
	}
	results := make(chan result, len(providers))

	for _, p := range providers {
		go func(p Provider) {
			resp, err := r.call(ctx, p, req, rt)
			results <- result{resp, p, err}
		}(p)
	}

	var lastErr error
	for i := 0; i < len(providers); i++ {
		select {
		case res := <-results:
			if res.err == nil && res.resp != nil && res.resp.StatusCode < 500 {
				r.getCircuit(res.p.ID).RecordSuccess()
				r.stream(w, res.resp, rt)
				return
			}
			if res.resp != nil {
				res.resp.Body.Close()
			}
			lastErr = res.err
		case <-ctx.Done():
			shared.SendError(w, req, fmt.Errorf("flock_race timeout"))
			return
		}
	}
	shared.SendError(w, req, fmt.Errorf("flock_race all failed: %w", lastErr))
}

// ---------------------------------------------------------------------------
// Strategy: sticky_affinity (session-based routing)
// ---------------------------------------------------------------------------
func (r *Router) routeSticky(w http.ResponseWriter, req *http.Request, rt *routingContext) {
	session := ""
	if auth := req.Header.Get("Authorization"); strings.HasPrefix(auth, "Bearer ") {
		session = auth[7:]
	}
	if session == "" {
		r.routeHybrid(w, req, rt)
		return
	}

	if pID := r.healthDB.GetSticky(session); pID != "" {
		if p, ok := r.registry.Get(pID); ok && r.healthDB.IsHealthy(p.ID) {
			if resp, err := r.call(req.Context(), p, req, rt); err == nil {
				r.stream(w, resp, rt)
				return
			}
		}
	}
	r.routeHybrid(w, req, rt)
}

// ---------------------------------------------------------------------------
// Strategy: weighted_elo (ELO-weighted random selection)
// ---------------------------------------------------------------------------
func (r *Router) routeWeighted(w http.ResponseWriter, req *http.Request, rt *routingContext) {
	providers := r.filterHealthy(r.registry.ForModel(rt.modelID))
	if len(providers) == 0 {
		shared.SendError(w, req, fmt.Errorf("no healthy providers"))
		return
	}

	total := 0.0
	for _, p := range providers {
		elo := r.healthDB.GetELO(p.ID)
		if elo <= 0 {
			elo = 1500
		}
		total += float64(elo)
	}

	pick := rand.Float64() * total
	cum := 0.0
	for _, p := range providers {
		elo := r.healthDB.GetELO(p.ID)
		if elo <= 0 {
			elo = 1500
		}
		cum += float64(elo)
		if pick <= cum {
			if resp, err := r.call(req.Context(), p, req, rt); err == nil {
				r.stream(w, resp, rt)
				return
			}
			break
		}
	}
	r.routeHybrid(w, req, rt)
}

// ---------------------------------------------------------------------------
// Strategy: least_latency (route to lowest observed latency)
// ---------------------------------------------------------------------------
func (r *Router) routeLeastLatency(w http.ResponseWriter, req *http.Request, rt *routingContext) {
	providers := r.filterHealthy(r.registry.ForModel(rt.modelID))
	if len(providers) == 0 {
		shared.SendError(w, req, fmt.Errorf("no healthy providers"))
		return
	}

	best := providers[0]
	bestLat := r.healthDB.GetLatency(best.ID)
	for _, p := range providers[1:] {
		if lat := r.healthDB.GetLatency(p.ID); lat > 0 && (bestLat == 0 || lat < bestLat) {
			best = p
			bestLat = lat
		}
	}

	if resp, err := r.call(req.Context(), best, req, rt); err == nil {
		r.stream(w, resp, rt)
		return
	}
	r.routeHybrid(w, req, rt)
}

// ---------------------------------------------------------------------------
// Strategy: round_robin (weighted round-robin)
// ---------------------------------------------------------------------------
func (r *Router) routeRoundRobin(w http.ResponseWriter, req *http.Request, rt *routingContext) {
	providers := r.filterHealthy(r.registry.ForModel(rt.modelID))
	if len(providers) == 0 {
		shared.SendError(w, req, fmt.Errorf("no healthy providers"))
		return
	}
	idx := atomic.AddUint64(&r.rrCounter, 1) % uint64(len(providers))
	p := providers[idx]

	if resp, err := r.call(req.Context(), p, req, rt); err == nil {
		r.stream(w, resp, rt)
		return
	}
	r.routeHybrid(w, req, rt)
}

// ---------------------------------------------------------------------------
// Strategy: free (free-tier providers only)
// ---------------------------------------------------------------------------
func (r *Router) routeFree(w http.ResponseWriter, req *http.Request, rt *routingContext) {
	for _, p := range r.registry.ForModel(rt.modelID) {
		if p.FreeTier && r.healthDB.IsHealthy(p.ID) && r.getCircuit(p.ID).Allow() {
			if resp, err := r.call(req.Context(), p, req, rt); err == nil {
				r.stream(w, resp, rt)
				return
			}
		}
	}
	shared.SendError(w, req, fmt.Errorf("no free provider available"))
}

// ---------------------------------------------------------------------------
// Strategy: circuit_chain (chain through providers until success)
// ---------------------------------------------------------------------------
func (r *Router) routeCircuitChain(w http.ResponseWriter, req *http.Request, rt *routingContext) {
	for _, p := range r.registry.ForModel(rt.modelID) {
		cb := r.getCircuit(p.ID)
		if !cb.Allow() {
			continue
		}
		resp, err := r.call(req.Context(), p, req, rt)
		if err == nil && resp.StatusCode < 500 {
			cb.RecordSuccess()
			r.stream(w, resp, rt)
			return
		}
		if resp != nil {
			resp.Body.Close()
		}
		cb.RecordFailure()
	}
	shared.SendError(w, req, fmt.Errorf("circuit_chain exhausted all providers"))
}

// ---------------------------------------------------------------------------
// Core helpers
// ---------------------------------------------------------------------------
func (r *Router) filterHealthy(providers []Provider) []Provider {
	var out []Provider
	for _, p := range providers {
		if r.healthDB.IsHealthy(p.ID) && r.getCircuit(p.ID).Allow() {
			out = append(out, p)
		}
	}
	return out
}

func (r *Router) call(ctx context.Context, p Provider, req *http.Request, rt *routingContext) (*http.Response, error) {
	u, err := url.Parse(p.BaseURL)
	if err != nil {
		return nil, err
	}

	target := u.String() + req.URL.Path
	if req.URL.RawQuery != "" {
		target += "?" + req.URL.RawQuery
	}

	bodyClone := bytes.NewReader(rt.bodyBytes)
	newReq, err := http.NewRequestWithContext(ctx, req.Method, target, bodyClone)
	if err != nil {
		return nil, err
	}

	for k, vv := range req.Header {
		for _, v := range vv {
			newReq.Header.Add(k, v)
		}
	}
	if p.APIKey != "" {
		newReq.Header.Set("Authorization", "Bearer "+p.APIKey)
	}
	newReq.Header.Set("Host", u.Host)

	if rt.modelID != "" && p.ModelMap != nil {
		if mapped, ok := p.ModelMap[rt.modelID]; ok {
			bodyMap := make(map[string]interface{})
			json.Unmarshal(rt.bodyBytes, &bodyMap)
			bodyMap["model"] = mapped
			newBody, _ := json.Marshal(bodyMap)
			newReq.Body = io.NopCloser(bytes.NewReader(newBody))
			newReq.ContentLength = int64(len(newBody))
			newReq.Header.Set("Content-Length", fmt.Sprintf("%d", len(newBody)))
		}
	}

	start := time.Now()
	resp, err := r.client.Do(newReq)
	if err != nil {
		return nil, err
	}

	r.healthDB.RecordLatency(p.ID, time.Since(start))
	return resp, nil
}

func (r *Router) stream(w http.ResponseWriter, resp *http.Response, rt *routingContext) {
	defer resp.Body.Close()
	for k, vv := range resp.Header {
		for _, v := range vv {
			w.Header().Add(k, v)
		}
	}
	w.WriteHeader(resp.StatusCode)

	if flusher, ok := w.(http.Flusher); ok {
		buf := make([]byte, 32*1024)
		for {
			n, err := resp.Body.Read(buf)
			if n > 0 {
				w.Write(buf[:n])
				flusher.Flush()
			}
			if err == io.EOF {
				break
			}
			if err != nil {
				r.logger.Warnf("[flock] stream error: %v", err)
				break
			}
		}
	} else {
		io.Copy(w, resp.Body)
	}

	if resp.StatusCode < 400 {
		r.metrics.RecordSuccess(rt.strategy, resp.StatusCode)
	} else {
		r.metrics.RecordError(rt.strategy, resp.StatusCode)
	}
}

func (r *Router) getCircuit(id string) *CircuitBreaker {
	v, _ := r.circuits.LoadOrStore(id, NewCircuitBreaker(5, 30*time.Second))
	return v.(*CircuitBreaker)
}

func (r *Router) healthProbeLoop() {
	ticker := time.NewTicker(time.Duration(r.cfg.HealthProbeInterval) * time.Second)
	defer ticker.Stop()
	for range ticker.C {
		for _, p := range r.registry.All() {
			go r.probe(p)
		}
	}
}

func (r *Router) probe(p Provider) {
	ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
	defer cancel()

	probeURL := p.BaseURL
	if !strings.HasSuffix(probeURL, "/") {
		probeURL += "/"
	}
	probeURL += "health"

	req, _ := http.NewRequestWithContext(ctx, "GET", probeURL, nil)
	if p.APIKey != "" {
		req.Header.Set("Authorization", "Bearer "+p.APIKey)
	}

	start := time.Now()
	resp, err := r.client.Do(req)
	if err != nil {
		r.healthDB.RecordHealth(p.ID, false, err.Error())
		return
	}
	resp.Body.Close()
	r.healthDB.RecordHealth(p.ID, resp.StatusCode < 500, "")
	r.healthDB.RecordLatency(p.ID, time.Since(start))
}

// Shutdown gracefully shuts down the router.
func (r *Router) Shutdown() {
	r.logger.Infof("[flock] shutdown")
	r.healthDB.Close()
}

// Matrix returns the Router's view of the cloud provider matrix.
// Used by the server startup log line that prints the configured
// provider count. Delegates to the ProviderRegistry.
func (r *Router) Matrix() *ProviderRegistry { return r.registry }

// Close shuts down the Router and its underlying health database.
// Alias for Shutdown, kept for the server's defer-friendly naming.
func (r *Router) Close() error {
	r.Shutdown()
	return nil
}

// extractPrompt extracts the prompt text from request body for semantic caching.
func extractPrompt(bodyJSON map[string]interface{}) string {
	if bodyJSON == nil {
		return ""
	}
	if msgs, ok := bodyJSON["messages"].([]interface{}); ok && len(msgs) > 0 {
		// Get last user message
		for i := len(msgs) - 1; i >= 0; i-- {
			if msg, ok := msgs[i].(map[string]interface{}); ok {
				if c, ok := msg["content"].(string); ok {
					return c
				}
			}
		}
	}
	if p, ok := bodyJSON["prompt"].(string); ok {
		return p
	}
	return ""
}

package flock

import (
	"bytes"
	"encoding/json"
	"io"
	"net/http/httptest"
	"os"
	"strings"
	"testing"
	"time"

	"github.com/toxicwind/bornite/internal/logmon"
)

// TestLiveKimi tests against the real KIMI API sandbox
func TestLiveKimi(t *testing.T) {
	if os.Getenv("LIVE_TEST") != "1" {
		t.Skip("Set LIVE_TEST=1 to run live tests")
	}

	logger := logmon.New()
	cfg := loadLiveConfig(t)
	router, err := NewRouter(cfg, logger)
	if err != nil {
		t.Fatalf("NewRouter: %v", err)
	}
	defer router.Shutdown()

	// Wait for health probes
	t.Log("Waiting 5s for health probes...")
	time.Sleep(5 * time.Second)

	// Test 1: KIMI completion
	t.Run("KimiCompletion", func(t *testing.T) {
		body := map[string]interface{}{
			"model":      "kimi-auto",
			"messages":   []map[string]string{{"role": "user", "content": "Say hello in 3 words"}},
			"max_tokens": 50,
		}
		resp := testRequest(t, router, body)
		if resp.StatusCode != 200 {
			body := readBody(resp)
			t.Fatalf("KIMI failed: %d %s", resp.StatusCode, body)
		}
		var result map[string]interface{}
		json.NewDecoder(resp.Body).Decode(&result)
		if choices, ok := result["choices"].([]interface{}); ok && len(choices) > 0 {
			t.Logf("KIMI response: %v", choices[0])
		}
	})

	// Test 2: KIMI streaming
	t.Run("KimiStreaming", func(t *testing.T) {
		body := map[string]interface{}{
			"model":      "kimi-fast",
			"messages":   []map[string]string{{"role": "user", "content": "Count 1,2,3"}},
			"stream":     true,
			"max_tokens": 100,
		}
		resp := testRequest(t, router, body)
		if resp.StatusCode != 200 {
			t.Fatalf("KIMI streaming failed: %d", resp.StatusCode)
		}
		ct := resp.Header.Get("Content-Type")
		if !strings.Contains(ct, "text/event-stream") {
			t.Logf("Warning: Content-Type=%s (expected text/event-stream)", ct)
		}
		buf := new(bytes.Buffer)
		io.Copy(buf, resp.Body)
		if buf.Len() == 0 {
			t.Fatal("Empty SSE stream")
		}
		t.Logf("KIMI SSE: %d bytes", buf.Len())
	})

	// Test 3: Large context (1M+ simulation)
	t.Run("KimiLargeContext", func(t *testing.T) {
		large := strings.Repeat("The quick brown fox jumps over the lazy dog. ", 5000)
		body := map[string]interface{}{
			"model": "kimi-long",
			"messages": []map[string]string{
				{"role": "system", "content": "You are a helpful assistant."},
				{"role": "user", "content": "Summarize this text in 10 words: " + large[:50000]},
			},
			"max_tokens": 100,
		}
		resp := testRequest(t, router, body)
		if resp.StatusCode != 200 {
			body := readBody(resp)
			if strings.Contains(body, "context_length_exceeded") {
				t.Skip("Context limit exceeded — expected for large test")
			}
			t.Fatalf("Large context failed: %d %s", resp.StatusCode, body)
		}
		t.Log("KIMI large context: OK")
	})

	// Test 4: Fallback to OpenRouter when KIMI fails
	t.Run("KimiFallback", func(t *testing.T) {
		// Force KIMI circuit open by simulating failures
		cb := router.getCircuit("kimi")
		for i := 0; i < 5; i++ {
			cb.RecordFailure()
		}
		if cb.State() != StateOpen {
			t.Logf("Circuit state: %v (expected Open)", cb.State())
		}

		body := map[string]interface{}{
