// TestProcessCommand_ReverseProxyPanicIsRecovered drives the full proxy path:
// the upstream responds healthy on /health (so Run completes), then on the
// actual proxied request it hijacks the connection and closes it mid-body.
// That upstream EOF makes httputil.ReverseProxy.copyResponse return an error,
// which panics with http.ErrAbortHandler — the wrapped handlerFn must recover
// and log the disconnect.
//
// Requests are issued through an httptest.NewServer wrapping the process so
// the panic actually fires (httputil only panics on copy errors when the
// request carries http.ServerContextKey, which a real server sets).
//
// see: https://github.com/golang/go/issues/23643
func TestProcessCommand_ReverseProxyPanicIsRecovered(t *testing.T) {
	skipIfNoSimpleResponder(t)

	upstream := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if r.URL.Path == "/health" {
			w.WriteHeader(http.StatusOK)
			return
		}
		// Send a Content-Length that promises 100 bytes, deliver only a few,
		// then slam the connection shut. The reverse proxy will see EOF
		// before the body is fully copied and panic with ErrAbortHandler.
		hj, ok := w.(http.Hijacker)
		if !ok {
			t.Errorf("upstream: hijack not supported")
			return
		}
		conn, _, err := hj.Hijack()
		if err != nil {
			t.Errorf("upstream: hijack: %v", err)
			return
		}
		_, _ = conn.Write([]byte("HTTP/1.1 200 OK\r\nContent-Length: 100\r\nContent-Type: text/plain\r\n\r\npartial"))
		_ = conn.Close()
	}))
	t.Cleanup(upstream.Close)

	// Capture proxy log output so we can assert the recover message was
	// emitted by handlerFn.
	logBuf := &syncBuffer{}
	proxyLogger := logmon.NewWriter(logBuf)
	procLogger := logmon.NewWriter(io.Discard)

	cmd, _ := simpleResponderCmd(t, "-silent")
	p, err := New(context.Background(), t.Name(), config.ModelConfig{
		Cmd:                cmd,
		Proxy:              upstream.URL,
		CheckEndpoint:      "/health",
		HealthCheckTimeout: 10,
	}, procLogger, proxyLogger)
	if err != nil {
		t.Fatalf("New: %v", err)
	}
	t.Cleanup(func() { p.Stop(testStopTimeout) })

	_ = runAsync(t, p)

	// Wrap p in an httptest server so requests get http.ServerContextKey
	// automatically — that is what makes httputil.ReverseProxy raise the panic.
	front := httptest.NewServer(p)
	t.Cleanup(front.Close)

	resp, err := http.Get(front.URL + "/disconnect")
	if err == nil {
		resp.Body.Close()
	}

	const want = "recovered from upstream disconnection"
	deadline := time.Now().Add(testReturnTimeout)
	for time.Now().Before(deadline) {
		if strings.Contains(logBuf.String(), want) {
			return
		}
		time.Sleep(testLogPollInterval)
	}
	t.Errorf("expected proxy log to contain %q; got:\n%s", want, logBuf.String())
}

// syncBuffer is a concurrent-safe bytes.Buffer for capturing logmon output.
type syncBuffer struct {
	mu  sync.Mutex
	buf bytes.Buffer
}

func (b *syncBuffer) Write(p []byte) (int, error) {
	b.mu.Lock()
	defer b.mu.Unlock()
	return b.buf.Write(p)
}

func (b *syncBuffer) String() string {
	b.mu.Lock()
	defer b.mu.Unlock()
	return b.buf.String()
}

// TestProcessCommand_TTL_StopsAfterIdle verifies that a process with a TTL
// automatically stops itself after the idle timeout has elapsed following its
// last request.
func TestProcessCommand_TTL_StopsAfterIdle(t *testing.T) {
	skipIfNoSimpleResponder(t)

	mock := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.WriteHeader(http.StatusOK)
	}))
	t.Cleanup(mock.Close)

	cmd, _ := simpleResponderCmd(t, "-silent")

	cfg := config.ModelConfig{
		Cmd:                cmd,
		Proxy:              mock.URL,
		CheckEndpoint:      "/health",
		HealthCheckTimeout: 10,
		UnloadAfter:        1, // 1-second TTL
	}
	if runtime.GOOS == "windows" {
		cfg.CmdStop = "taskkill /f /t /pid ${PID}"
	}

	p := newProcessCommand(t, cfg)

	runErr := runAsync(t, p)
	defer func() {
		if p.State() == StateReady {
			p.Stop(testStopTimeout)
		}
	}()

	if got := p.State(); got != StateReady {
		t.Fatalf("expected StateReady, got %s", got)
	}

	// Make one request to prime the last-use timestamp.
	req := httptest.NewRequest("GET", "/", nil)
	rr := httptest.NewRecorder()
	p.ServeHTTP(rr, req)
	if rr.Code != http.StatusOK {
		t.Errorf("expected 200 after request, got %d", rr.Code)
	}

	// Wait for the TTL goroutine to fire and the process to fully stop.
	// Poll for StateStopped directly to avoid racing the StateStopping
	// intermediate state that sits between StateReady and StateStopped.
	deadline := time.Now().Add(5 * time.Second)
	for p.State() != StateStopped && time.Now().Before(deadline) {
		time.Sleep(testPollInterval)
	}

	if got := p.State(); got != StateStopped {
		t.Fatalf("TTL did not stop process; state is %s (expected %s)", got, StateStopped)
	}

	// Run() should have returned nil (clean stop from TTL).
	select {
	case err := <-runErr:
		if err != nil {
			t.Errorf("Run() after TTL stop: expected nil, got %v", err)
		}
	case <-time.After(testReturnTimeout):
		t.Fatal("Run() did not return after TTL-induced stop")
	}
}

// TestProcessCommand_TTL_ResetsOnRequest verifies that inflight requests
// prevent the TTL goroutine from stopping the process, and that the TTL timer
// resets after each request completes.
func TestProcessCommand_TTL_ResetsOnRequest(t *testing.T) {
	skipIfNoSimpleResponder(t)

	mock := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.WriteHeader(http.StatusOK)
	}))
	t.Cleanup(mock.Close)

	cmd, _ := simpleResponderCmd(t, "-silent")
	p := newProcessCommand(t, config.ModelConfig{
		Cmd:                cmd,
		Proxy:              mock.URL,
		CheckEndpoint:      "/health",
		HealthCheckTimeout: 10,
		UnloadAfter:        1, // 1-second TTL
	})

	runErr := runAsync(t, p)
	defer func() {
		if p.State() == StateReady {
			p.Stop(testStopTimeout)
		}
	}()

	// Keep sending requests for 1.5s — past the 1s TTL — and verify
	// the process never stops while traffic is flowing.
	stopAt := time.Now().Add(1500 * time.Millisecond)
	for time.Now().Before(stopAt) {
		req := httptest.NewRequest("GET", "/", nil)
		rr := httptest.NewRecorder()
		p.ServeHTTP(rr, req)
		if rr.Code != http.StatusOK {
			t.Errorf("expected 200, got %d", rr.Code)
		}
		if p.State() != StateReady {
			t.Fatalf("process was stopped during active traffic (state=%s)", p.State())
		}
		time.Sleep(10 * time.Millisecond)
	}

	if got := p.State(); got != StateReady {
		t.Fatalf("expected StateReady while traffic was active, got %s", got)
	}

	// Now stop manually to clean up.
	if err := p.Stop(testStopTimeout); err != nil {
		t.Fatalf("Stop() error: %v", err)
	}
	select {
	case <-runErr:
	case <-time.After(testReturnTimeout):
		t.Fatal("Run() did not return after Stop")
	}
}

func TestProcessCommand_TTL_IgnoresWebsocket(t *testing.T) {
	skipIfNoSimpleResponder(t)

	websocketStarted := make(chan struct{})
	releaseWebsocket := make(chan struct{})
	mock := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if r.URL.Path == "/health" {
			w.WriteHeader(http.StatusOK)
			return
		}
		close(websocketStarted)
		<-releaseWebsocket
		w.WriteHeader(http.StatusOK)
	}))
	t.Cleanup(mock.Close)

	cmd, _ := simpleResponderCmd(t, "-silent")
	p := newProcessCommand(t, config.ModelConfig{
		Cmd:                cmd,
		Proxy:              mock.URL,
		CheckEndpoint:      "/health",
		HealthCheckTimeout: 10,
		UnloadAfter:        1,
		UnloadTimeout:      1,
		Compat:             config.CompatConfig{IgnoreWebsockets: true},
	})
	runErr := runAsync(t, p)

	requestDone := make(chan struct{})
	go func() {
		defer close(requestDone)
		r := httptest.NewRequest(http.MethodGet, "/socket", nil)
		r.Header.Set("Connection", "Upgrade")
		r.Header.Set("Upgrade", "websocket")
		p.ServeHTTP(httptest.NewRecorder(), r)
	}()

	select {
	case <-websocketStarted:
	case <-time.After(testReturnTimeout):
		t.Fatal("websocket request did not reach upstream")
	}
	waitForState(t, p, StateStopped)
	select {
	case <-requestDone:
		t.Fatal("websocket request completed before it was released")
	default:
	}

	close(releaseWebsocket)
	select {
	case <-requestDone:
	case <-time.After(testReturnTimeout):
		t.Fatal("websocket request did not finish after release")
	}
	select {
	case err := <-runErr:
		if err != nil {
			t.Fatalf("Run() after TTL stop: %v", err)
		}
	case <-time.After(testReturnTimeout):
		t.Fatal("Run() did not return after TTL stop")
	}
}

// TestProcessCommand_TTL_ZeroDisables verifies that UnloadAfter=0 does not
// spawn a TTL goroutine — the process stays ready until explicitly stopped.
func TestProcessCommand_TTL_ZeroDisables(t *testing.T) {
	skipIfNoSimpleResponder(t)

	mock := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.WriteHeader(http.StatusOK)
	}))
	t.Cleanup(mock.Close)

	cmd, _ := simpleResponderCmd(t, "-silent")
	p := newProcessCommand(t, config.ModelConfig{
		Cmd:                cmd,
		Proxy:              mock.URL,
		CheckEndpoint:      "/health",
		HealthCheckTimeout: 10,
		UnloadAfter:        0, // disabled
	})

	runErr := runAsync(t, p)
	defer func() {
		if p.State() == StateReady {
			p.Stop(testStopTimeout)
		}
	}()

	if got := p.State(); got != StateReady {
		t.Fatalf("expected StateReady, got %s", got)
	}

	req := httptest.NewRequest("GET", "/", nil)
	rr := httptest.NewRecorder()
	p.ServeHTTP(rr, req)
	if rr.Code != http.StatusOK {
		t.Errorf("expected 200 after request, got %d", rr.Code)
	}

	// No TTL goroutine is spawned when UnloadAfter=0, so a brief sleep is
	// enough to confirm the process remains ready.
	time.Sleep(100 * time.Millisecond)

	if got := p.State(); got != StateReady {
		t.Fatalf("process was stopped unexpectedly (state=%s) with TTL=0", got)
	}

	// Cleanly stop.
	if err := p.Stop(testStopTimeout); err != nil {
		t.Fatalf("Stop() error: %v", err)
	}
	select {
	case <-runErr:
	case <-time.After(testReturnTimeout):
		t.Fatal("Run() did not return after Stop")
	}
}

// TestProcessCommand_ConcurrentRunStop launches many concurrent run/stop racing
// pairs to exercise the race detector and verify no deadlocks occur.
func TestProcessCommand_ConcurrentRunStop(t *testing.T) {
	skipIfNoSimpleResponder(t)

	for range 10 {
		cmd, port := simpleResponderCmd(t, "-silent")
		cfg := config.ModelConfig{
			Cmd:                cmd,
			Proxy:              fmt.Sprintf("http://127.0.0.1:%d", port),
			CheckEndpoint:      "/health",
			HealthCheckTimeout: 10,
		}

		if runtime.GOOS == "windows" {
			cfg.CmdStop = "taskkill /f /t /pid ${PID}"
		}

		p := newProcessCommand(t, cfg)

		runDone := make(chan struct{})
		go func() {
			defer close(runDone)
			p.Run(testStartTimeout) //nolint: errcheck — one goroutine wins the race
		}()
		go func() {
			p.Stop(testStopTimeout) //nolint: errcheck
		}()

		// Backstop: the racing Stop may have arrived before Run got on the
		// channel (making it a no-op), so keep stopping until Run unblocks.
		deadline := time.After(testStartTimeout)
		for done := false; !done; {
			select {
			case <-runDone:
				done = true
			case <-deadline:
				t.Fatal("Run did not return")
			case <-time.After(testPollInterval):
				p.Stop(testStopTimeout) //nolint: errcheck
			}
		}
	}
}

package process

import (
	"fmt"
	"sync"
	"testing"
	"time"

	"github.com/toxicwind/bornite/internal/config"
	"github.com/toxicwind/bornite/internal/event"
	"github.com/toxicwind/bornite/internal/swaputil"
)

func TestProcessCommand_EmitsStateChangeEvents(t *testing.T) {
	skipIfNoSimpleResponder(t)

	var mu sync.Mutex
	var transitions []swaputil.ProcessStateChangeEvent
	cancel := event.On(func(e swaputil.ProcessStateChangeEvent) {
		if e.ProcessName != t.Name() {
			return
		}
		mu.Lock()
		transitions = append(transitions, e)
		mu.Unlock()
	})
	defer cancel()

	cmd, port := simpleResponderCmd(t, "-silent", "-respond hello")
	p := newProcessCommand(t, config.ModelConfig{
		Cmd:                cmd,
		Proxy:              fmt.Sprintf("http://127.0.0.1:%d", port),
		CheckEndpoint:      "/health",
		HealthCheckTimeout: 10,
	})

	runErr := runAsync(t, p)
	if err := p.Stop(testStopTimeout); err != nil {
		t.Fatalf("Stop: %v", err)
	}
	<-runErr

	// Events are delivered asynchronously; give the dispatcher a moment.
	deadline := time.Now().Add(time.Second)
	for time.Now().Before(deadline) {
		mu.Lock()
		n := len(transitions)
		mu.Unlock()
		if n >= 4 {
			break
		}
		time.Sleep(testPollInterval)
	}

	mu.Lock()
	defer mu.Unlock()

	for _, e := range transitions {
		if e.OldState == e.NewState {
			t.Errorf("emitted no-op transition: %s -> %s", e.OldState, e.NewState)
		}
	}

	want := []string{
		string(StateStopped) + "->" + string(StateStarting),
		string(StateStarting) + "->" + string(StateReady),
		string(StateReady) + "->" + string(StateStopping),
		string(StateStopping) + "->" + string(StateStopped),
	}
	got := make([]string, len(transitions))
	for i, e := range transitions {
		got[i] = e.OldState + "->" + e.NewState
	}
	if len(got) != len(want) {
		t.Fatalf("transitions = %v, want %v", got, want)
	}
	for i := range want {
		if got[i] != want[i] {
			t.Fatalf("transitions = %v, want %v", got, want)
		}
	}
}

package process

import (
	"context"
	"fmt"
	"io"
	"net/http"
	"net/http/httptest"
	"strings"
	"testing"

	"github.com/toxicwind/bornite/internal/logmon"
	"github.com/toxicwind/bornite/internal/swaputil"
)

// markerRecorder stands in for the server package's response recorders: it
// implements swaputil.StatusMarker so the proxy error handler can record a
// status without writing it to the client.
type markerRecorder struct {
	http.ResponseWriter
	status      int
	marked      int
	wroteHeader bool
}

func newMarkerRecorder() *markerRecorder {
	return &markerRecorder{ResponseWriter: httptest.NewRecorder(), status: http.StatusOK}
}

func (m *markerRecorder) WriteHeader(code int) {
	if m.wroteHeader {
		return
	}
	m.wroteHeader = true
	m.status = code
	m.ResponseWriter.WriteHeader(code)
}

func (m *markerRecorder) Write(b []byte) (int, error) {
	if !m.wroteHeader {
		m.WriteHeader(http.StatusOK)
	}
	return m.ResponseWriter.Write(b)
}

func (m *markerRecorder) MarkStatus(code int) {
	m.status = code
	m.marked = code
}

func (m *markerRecorder) WroteHeader() bool { return m.wroteHeader }

// TestProcessCommand_ProxyErrorHandler covers the secondary case in #1029: once
// the model is loaded, a client hanging up mid-request used to surface as a
// 502, blaming a healthy upstream. Cancellation must record the client-closed
// sentinel instead, while genuine upstream failures keep their 502.
func TestProcessCommand_ProxyErrorHandler(t *testing.T) {
	t.Run("client disconnect records the sentinel without writing", func(t *testing.T) {
		logger := logmon.NewWriter(io.Discard)
		handler := newProxyErrorHandler("m", logger)

		// The client connection itself goes away.
		clientCtx, cancel := context.WithCancel(context.Background())
		ctx := swaputil.SetClientContext(clientCtx, clientCtx)
		r := httptest.NewRequest(http.MethodPost, "/v1/chat/completions", nil).WithContext(ctx)
		cancel()

		rec := newMarkerRecorder()
		handler(rec, r, context.Canceled)

		if rec.marked != swaputil.StatusClientClosedRequest {
			t.Errorf("marked status = %d, want %d", rec.marked, swaputil.StatusClientClosedRequest)
		}
		if rec.wroteHeader {
			t.Error("nothing should be written to a client that already hung up")
		}
		if line := string(logger.GetHistory()); strings.Contains(line, "proxy error") {
			t.Errorf("client disconnect should not be logged as a proxy error: %q", line)
		}
	})

	t.Run("upstream failure still answers 502", func(t *testing.T) {
		logger := logmon.NewWriter(io.Discard)
		handler := newProxyErrorHandler("m", logger)

		r := httptest.NewRequest(http.MethodPost, "/v1/chat/completions", nil)
		rec := newMarkerRecorder()
		handler(rec, r, fmt.Errorf("dial tcp 127.0.0.1:9999: connect: connection refused"))

		if rec.status != http.StatusBadGateway {
			t.Errorf("status = %d, want %d", rec.status, http.StatusBadGateway)
		}
		if !rec.wroteHeader {
			t.Error("a real upstream failure must still be answered")
		}
		if line := string(logger.GetHistory()); !strings.Contains(line, "proxy error") {
			t.Errorf("upstream failure should be logged: %q", line)
		}
	})

	// A request cancelled server-side (an operator cancelling it from the UI,
	// or shutdown) still has a connected client. Recording it as a client
	// disconnect would misattribute it, and returning without writing would
	// let net/http finalize an empty 200 that tells the caller it succeeded.
	t.Run("server-side cancel still answers the connected client", func(t *testing.T) {
		logger := logmon.NewWriter(io.Discard)
		handler := newProxyErrorHandler("m", logger)

		// The client is alive; the inflight tracker's derived context is what
		// gets cancelled, exactly as POST /api/inflight/{id}/cancel does.
		clientCtx := context.Background()
		ctx, cancel := context.WithCancel(swaputil.SetClientContext(clientCtx, clientCtx))
		r := httptest.NewRequest(http.MethodPost, "/v1/chat/completions", nil).WithContext(ctx)
		cancel()

		rec := newMarkerRecorder()
		handler(rec, r, context.Canceled)

		if rec.marked == swaputil.StatusClientClosedRequest {
			t.Error("a server-side cancel must not be recorded as a client disconnect")
		}
		if rec.status != http.StatusBadGateway {
			t.Errorf("status = %d, want %d: a connected client must get a real response", rec.status, http.StatusBadGateway)
		}
		if line := string(logger.GetHistory()); strings.Contains(line, "proxy error") {
			t.Errorf("a cancel is not an upstream fault: %q", line)
		}
	})

	t.Run("health check poll is not logged as a proxy error", func(t *testing.T) {
		logger := logmon.NewWriter(io.Discard)
		handler := newProxyErrorHandler("m", logger)

		ctx := context.WithValue(context.Background(), healthCheckKey{}, true)
		r := httptest.NewRequest(http.MethodGet, "/health", nil).WithContext(ctx)
		rec := newMarkerRecorder()
		handler(rec, r, fmt.Errorf("dial tcp 127.0.0.1:9999: connect: connection refused"))

		// The loop keys off the 502 to decide the model is not ready yet.
		if rec.status != http.StatusBadGateway {
			t.Errorf("status = %d, want %d", rec.status, http.StatusBadGateway)
		}
		if line := string(logger.GetHistory()); strings.Contains(line, "proxy error") {
			t.Errorf("a booting upstream should not log a proxy error per poll: %q", line)
		}
	})

	t.Run("response already started keeps its status", func(t *testing.T) {
		logger := logmon.NewWriter(io.Discard)
		handler := newProxyErrorHandler("m", logger)

		ctx, cancel := context.WithCancel(context.Background())
		r := httptest.NewRequest(http.MethodPost, "/v1/chat/completions", nil).WithContext(ctx)
		cancel()

		// A streamed response that already flushed headers before the client
		// left: marking it 499 would misreport bytes the client did receive.
		rec := newMarkerRecorder()
		rec.Write([]byte("data: {}\n\n"))
		handler(rec, r, context.Canceled)

		if rec.status != http.StatusOK {
			t.Errorf("status = %d, want %d", rec.status, http.StatusOK)
		}
	})
}

//go:build windows

package process

import (
	"fmt"
	"unsafe"

	"golang.org/x/sys/windows"
)

// SetupTreeCleanup assigns the current process to a Windows Job Object
// configured with JOB_OBJECT_LIMIT_KILL_ON_JOB_CLOSE. Upstream processes
// spawned afterwards are associated with the same job, so when bornite exits
// for any reason — graceful shutdown, a forced second Ctrl+C, or a crash — the
// OS terminates the whole job and reaps every child instead of leaving orphans
// behind. It is the parent-side complement to the per-process teardown in
// runtime_windows.go.
//
// The job handle is intentionally leaked for the lifetime of the process: the
// kill-on-close behaviour fires when the last handle is released, which the OS
// does when the process exits.
func SetupTreeCleanup() error {
	job, err := windows.CreateJobObject(nil, nil)
	if err != nil {
		return fmt.Errorf("CreateJobObject: %w", err)
	}

	info := windows.JOBOBJECT_EXTENDED_LIMIT_INFORMATION{
		BasicLimitInformation: windows.JOBOBJECT_BASIC_LIMIT_INFORMATION{
			LimitFlags: windows.JOB_OBJECT_LIMIT_KILL_ON_JOB_CLOSE,
		},
	}
	if _, err := windows.SetInformationJobObject(
		job,
		windows.JobObjectExtendedLimitInformation,
		uintptr(unsafe.Pointer(&info)),
		uint32(unsafe.Sizeof(info)),
	); err != nil {
		windows.CloseHandle(job)
		return fmt.Errorf("SetInformationJobObject: %w", err)
	}

	if err := windows.AssignProcessToJobObject(job, windows.CurrentProcess()); err != nil {
		windows.CloseHandle(job)
		return fmt.Errorf("AssignProcessToJobObject: %w", err)
	}

	return nil
}

