package router

import (
	"net/url"
	"testing"

	"github.com/toxicwind/bornite/internal/config"
)

// TestHerdFQNpensRegression — pens-shaped regression test for the
// 2026-09-20 incident: a stale bornite binary registered only bare model
// names and silently dropped cross-peer duplicates ("already mapped to
// another peer, skipping"), so OpenFang's qualified request
// openrouter-free/nex-agi/nex-n2.5-mini:free died with "Model not found".
// FQN keys (peerID + "/" + modelID) must ALWAYS resolve; bare names only
// when unique across peers (upstream mostlygeek/bornite semantics).
func TestHerdFQNpensRegression(t *testing.T) {
	mkPeers := func() config.PeerDictionaryConfig {
		peers := config.PeerDictionaryConfig{}
		add := func(id, proxy string, models ...string) {
			u, _ := url.Parse(proxy)
			peers[id] = config.PeerConfig{Proxy: proxy, ProxyURL: u, Models: models}
		}
		add("openrouter-free", "http://127.0.0.1:25109",
			"nex-agi/nex-n2.5-mini:free", "qwen3.5-9b-tool")
		add("openrouter-paid", "http://127.0.0.1:25110",
			"nex-agi/nex-n2.5-mini:free", "anthropic/claude-sonnet-4")
		add("toolcall-local", "http://127.0.0.1:25152",
			"qwen3.5-9b-tool")
		add("moonshot", "https://api.moonshot.ai",
			"moonshotai/kimi-k2.6")
		return peers
	}

	pr, err := NewPeer(config.Config{Peers: mkPeers()}, testLogger)
	if err != nil {
		t.Fatal(err)
	}

	// Every (peer, model) FQN must resolve to that peer's route.
	fqnCases := []struct{ peer, model string }{
		{"openrouter-free", "nex-agi/nex-n2.5-mini:free"},
		{"openrouter-paid", "nex-agi/nex-n2.5-mini:free"},
		{"openrouter-free", "qwen3.5-9b-tool"},
		{"toolcall-local", "qwen3.5-9b-tool"},
		{"openrouter-paid", "anthropic/claude-sonnet-4"},
		{"moonshot", "moonshotai/kimi-k2.6"},
	}
	for _, tc := range fqnCases {
		key := config.PeerModelFQN(tc.peer, tc.model)
		route, ok := pr.peers[key]
		if !ok {
			t.Errorf("FQN %q not registered (regression: qualified model would 404)", key)
			continue
		}
		if route.member.peerID != tc.peer {
			t.Errorf("FQN %q routed to peer %q, want %q", key, route.member.peerID, tc.peer)
		}
		if route.modelID != tc.model {
			t.Errorf("FQN %q route modelID = %q, want %q", key, route.modelID, tc.model)
		}
	}

	// Colliding bare names must NOT resolve bare (ambiguous across peers).
	for _, bare := range []string{"nex-agi/nex-n2.5-mini:free", "qwen3.5-9b-tool"} {
		if _, ok := pr.peers[bare]; ok {
			t.Errorf("colliding bare model %q resolved; want it skipped (upstream semantics)", bare)
		}
	}

	// Unique bare names must resolve to their peer.
	unique := map[string]string{
		"anthropic/claude-sonnet-4": "openrouter-paid",
		"moonshotai/kimi-k2.6":      "moonshot",
	}
	for bare, wantPeer := range unique {
		route, ok := pr.peers[bare]
		if !ok {
			t.Errorf("unique bare model %q not registered", bare)
			continue
		}
		if route.member.peerID != wantPeer {
			t.Errorf("bare %q routed to %q, want %q", bare, route.member.peerID, wantPeer)
		}
	}
}

package router

import (
	"fmt"

	"github.com/toxicwind/bornite/internal/config"
	"github.com/toxicwind/bornite/internal/logmon"
	"github.com/toxicwind/bornite/internal/process"
)

type Group struct {
	*baseRouter
}

func NewGroup(conf config.Config, proxylog, upstreamlog *logmon.Monitor) (*Group, error) {
	modelToGroup := make(map[string]string)
	for gid, gcfg := range conf.Routing.Router.Settings.Groups {
		for _, mid := range gcfg.Members {
			if existing, dup := modelToGroup[mid]; dup {
				return nil, fmt.Errorf("model %q is in multiple groups: %q and %q", mid, existing, gid)
			}
			modelToGroup[mid] = gid
		}
	}

	swapper := &groupSwapper{
		config:       conf,
		modelToGroup: modelToGroup,
	}

	processes := make(map[string]process.Process, len(modelToGroup))
	base, err := newBaseRouter("group", conf, processes, proxylog, swapper)
	if err != nil {
		return nil, fmt.Errorf("creating base router: %w", err)
	}

	for mid := range modelToGroup {
		modelCfg, _, ok := conf.FindConfig(mid)
		if !ok {
			base.shutdownFn()
			base.procCancel()
			return nil, fmt.Errorf("no model config for %q", mid)
		}
		procLog := logmon.NewWriter(upstreamlog)
		p, err := process.New(base.procCtx, mid, modelCfg, procLog, proxylog)
		if err != nil {
			base.shutdownFn()
			base.procCancel()
			return nil, fmt.Errorf("creating process for %q: %w", mid, err)
		}
		processes[mid] = p
	}

	g := &Group{baseRouter: base}
	go base.run()
	return g, nil
}

// groupSwapper decides evictions from static group configuration.
//
// Same-group siblings are stopped when the group has swap=true. Cross-group
// members are stopped only when the target's group is exclusive; loading a
// model from a non-exclusive group leaves running exclusive groups alone,
// matching the gotcha in the original ProcessGroup behaviour.
type groupSwapper struct {
	config       config.Config
	modelToGroup map[string]string
}

func (p *groupSwapper) EvictionFor(target string, running []string) []string {
	tg := p.modelToGroup[target]
	tgCfg := p.config.Routing.Router.Settings.Groups[tg]

	seen := make(map[string]struct{})
	var result []string
	consider := func(mID string) {
		if mID == target {
			return
		}
		if _, dup := seen[mID]; dup {
			return
		}
		og := p.modelToGroup[mID]
		switch {
		case og == tg && tgCfg.Swap:
			seen[mID] = struct{}{}
			result = append(result, mID)
		// the previous ProcessGroup behaviour did not unload exclusive groups
		// when loading a non-exclusive model. This maintains that gotcha
		// for backwards compatibility. The newer swap matrix approach does not
		// have this issue.
		case og != tg && tgCfg.Exclusive:
			if ogCfg := p.config.Routing.Router.Settings.Groups[og]; !ogCfg.Persistent {
				seen[mID] = struct{}{}
				result = append(result, mID)
			}
		}
	}

	for _, mID := range running {
		consider(mID)
	}
	return result
}

func (p *groupSwapper) OnSwapStart(target string, running []string) {}

