func countSSEMessages(s string) int {
	scanner := bufio.NewScanner(strings.NewReader(s))
	count := 0
	for scanner.Scan() {
		line := scanner.Text()
		if strings.HasPrefix(line, "data: ") {
			count++
		}
	}
	return count
}

func extractStreamedContent(body string) string {
	var result strings.Builder
	scanner := bufio.NewScanner(strings.NewReader(body))
	for scanner.Scan() {
		line := scanner.Text()
		if !strings.HasPrefix(line, "data: ") {
			continue
		}
		jsonData := strings.TrimPrefix(line, "data: ")
		var msg struct {
			Choices []struct {
				Delta struct {
					ReasoningContent string `json:"reasoning_content"`
				} `json:"delta"`
			} `json:"choices"`
		}
		if err := json.Unmarshal([]byte(jsonData), &msg); err != nil {
			continue
		}
		if len(msg.Choices) > 0 {
			result.WriteString(msg.Choices[0].Delta.ReasoningContent)
		}
	}
	return result.String()
}

package router

import (
	"fmt"
	"slices"

	"github.com/toxicwind/bornite/internal/config"
	"github.com/toxicwind/bornite/internal/logmon"
	"github.com/toxicwind/bornite/internal/process"
)

type Matrix struct {
	*baseRouter
}

func NewMatrix(conf config.Config, proxylog, upstreamlog *logmon.Monitor) (*Matrix, error) {
	mtx := conf.Routing.Router.Settings.Matrix
	if mtx == nil {
		return nil, fmt.Errorf("matrix router requires a matrix configuration")
	}
	if mtx.Program() == nil {
		if err := config.ValidateMatrix(mtx, conf.Models); err != nil {
			return nil, fmt.Errorf("compiling matrix configuration: %w", err)
		}
	}

	swapper := &matrixSwapper{
		solver: newMatrixSolver(mtx.Program(), mtx.ResolvedEvictCosts()),
		logger: proxylog,
	}

	// Build a process for every model in the config. Any model can run alone
	// even if it is not part of a set; this mirrors proxy.NewMatrix.
	processes := make(map[string]process.Process, len(conf.Models))
	base, err := newBaseRouter("matrix", conf, processes, proxylog, swapper)
	if err != nil {
		return nil, fmt.Errorf("creating base router: %w", err)
	}

	for mid, modelCfg := range conf.Models {
		procLog := logmon.NewWriter(upstreamlog)
		p, err := process.New(base.procCtx, mid, modelCfg, procLog, proxylog)
		if err != nil {
			base.shutdownFn()
			base.procCancel()
			return nil, fmt.Errorf("creating process for %q: %w", mid, err)
		}
		processes[mid] = p
	}

	r := &Matrix{baseRouter: base}
	go base.run()
	return r, nil
}

// matrixSwapper decides evictions by asking the matrix solver against the
// running set the scheduler hands it.
//
// The scheduler drives planners from a single event-loop goroutine and calls
// OnSwapStart with the same target and running set it just gave EvictionFor,
// so the last decision is cached and reused instead of solving twice per
// swap. The cache is only valid under that single-goroutine access pattern.
type matrixSwapper struct {
	solver *matrixSolver
	logger *logmon.Monitor

	lastTarget  string
	lastRunning []string
	lastResult  solveResult
	lastValid   bool
}

func (p *matrixSwapper) solve(target string, running []string) solveResult {
	if p.lastValid && p.lastTarget == target && slices.Equal(p.lastRunning, running) {
		return p.lastResult
	}
	result := p.solver.Solve(target, running)
	p.lastTarget = target
	p.lastRunning = slices.Clone(running)
	p.lastResult = result
	p.lastValid = true
	return result
}

func (p *matrixSwapper) EvictionFor(target string, running []string) []string {
	return p.solve(target, running).Evict
}

func (p *matrixSwapper) OnSwapStart(target string, running []string) {
	result := p.solve(target, running)
	switch {
	case len(result.Evict) > 0:
		p.logger.Infof("matrix: model=%s set=%s dsl=%q evict=%v target=%v cost=%d",
			target, result.SetName, result.DSL, result.Evict, result.TargetSet, result.TotalCost)
	case len(running) == 0:
		p.logger.Infof("matrix: model=%s starting (no models running)", target)
	default:
		p.logger.Debugf("matrix: model=%s already running in set=%s dsl=%q", target, result.SetName, result.DSL)
	}
}

package router

import (
	"fmt"
	"io"
	"strings"
	"testing"

	"github.com/toxicwind/bornite/internal/config"
	"github.com/toxicwind/bornite/internal/logmon"
)

var benchmarkSolveResult solveResult

func BenchmarkMatrixSolver_Solve(b *testing.B) {
	for _, dimensions := range []int{2, 3, 4, 5} {
		solver := benchmarkCompiledMatrix(b, dimensions, 10)
		combinations := benchmarkIntPow(10, dimensions)
		running := make([]string, 0, dimensions+1)
		for dimension := range dimensions {
			running = append(running, fmt.Sprintf("model-%d-0", dimension))
		}
		running = append(running, "outside-matrix")

		b.Run(fmt.Sprintf("Combinations_%d", combinations), func(b *testing.B) {
			b.ReportAllocs()
			for b.Loop() {
				benchmarkSolveResult = solver.Solve("target", running)
			}
		})
	}
}

var benchmarkEvict []string

// BenchmarkMatrixSwapPath measures one full scheduler swap decision:
// EvictionFor followed by OnSwapStart with the same running set, mirroring
// how the FIFO scheduler drives the planner.
func BenchmarkMatrixSwapPath(b *testing.B) {
	const setCount = 8
	matrix, models := benchmarkMultiSetMatrix(setCount, 10)
	if err := config.ValidateMatrix(matrix, models); err != nil {
		b.Fatal(err)
	}
	swapper := &matrixSwapper{
		solver: newMatrixSolver(matrix.Program(), matrix.ResolvedEvictCosts()),
		logger: logmon.NewWriter(io.Discard),
	}
	// Rotate the running set so each EvictionFor sees a fresh picture (cache
	// miss) while OnSwapStart repeats it (cache hit), mirroring the
	// scheduler: the running set changes between swaps, not within one.
	runSets := [][]string{
		{"a-3-1", "b-3-2", "a-0-1", "b-7-4", "outside-matrix"},
		{"a-3-3", "b-3-1", "a-1-2", "b-6-0", "outside-matrix"},
		{"a-3-0", "b-3-4", "a-2-3", "b-5-1", "outside-matrix"},
		{"a-3-2", "b-3-0", "a-4-4", "b-4-2", "outside-matrix"},
	}

	b.ReportAllocs()
	i := 0
	for b.Loop() {
		running := runSets[i%len(runSets)]
		i++
		benchmarkEvict = swapper.EvictionFor("target-3", running)
		swapper.OnSwapStart("target-3", running)
	}
}

// benchmarkMultiSetMatrix builds a matrix of setCount independent sets, each
// "target-N & (10 a-models) & (10 b-models)". Eviction costs use three
// distinct values: a-models cost 2, b-models cost 5, the rest default to 1.
func benchmarkMultiSetMatrix(setCount, choices int) (*config.MatrixConfig, map[string]config.ModelConfig) {
	models := map[string]config.ModelConfig{"outside-matrix": {}}
	evictCosts := make(map[string]int, 2*setCount*choices)
	sets := make(config.OrderedSets, 0, setCount)
	for s := range setCount {
		target := fmt.Sprintf("target-%d", s)
		models[target] = config.ModelConfig{}
		groupA := make([]string, 0, choices)
		groupB := make([]string, 0, choices)
		for c := range choices {
			a := fmt.Sprintf("a-%d-%d", s, c)
			bModel := fmt.Sprintf("b-%d-%d", s, c)
			models[a] = config.ModelConfig{}
			models[bModel] = config.ModelConfig{}
			evictCosts[a] = 2
			evictCosts[bModel] = 5
			groupA = append(groupA, a)
			groupB = append(groupB, bModel)
		}
		sets = append(sets, config.SetEntry{
			Name: fmt.Sprintf("set-%d", s),
			DSL: fmt.Sprintf("%s & (%s) & (%s)",
				target, strings.Join(groupA, " | "), strings.Join(groupB, " | ")),
		})
	}
	return &config.MatrixConfig{EvictCosts: evictCosts, Sets: sets}, models
}

func benchmarkCompiledMatrix(b *testing.B, dimensions, choices int) *matrixSolver {
	b.Helper()
	groups := make([]string, dimensions)
	models := map[string]config.ModelConfig{"target": {}}
	for dimension := range dimensions {
		alternatives := make([]string, choices)
		for choice := range choices {
			name := fmt.Sprintf("model-%d-%d", dimension, choice)
			alternatives[choice] = name
			models[name] = config.ModelConfig{}
		}
		groups[dimension] = "(" + strings.Join(alternatives, " | ") + ")"
	}

	matrix := &config.MatrixConfig{
		Sets: config.OrderedSets{{
			Name: "benchmark",
			DSL:  "target & " + strings.Join(groups, " & "),
		}},
	}
	if err := config.ValidateMatrix(matrix, models); err != nil {
		b.Fatal(err)
	}
	return newMatrixSolver(matrix.Program(), nil)
}

func benchmarkIntPow(base, exponent int) int {
	result := 1
	for range exponent {
		result *= base
	}
	return result
}

package router

import matrixdsl "github.com/toxicwind/bornite/internal/matrix"

// matrixSolver contains pure swap-decision logic with no Process dependencies.
// It is safe for concurrent reads after construction.
type matrixSolver struct {
	program    *matrixdsl.Program
	evictCosts map[string]int
}

func newMatrixSolver(program *matrixdsl.Program, evictCosts map[string]int) *matrixSolver {
	return &matrixSolver{
		program:    program,
		evictCosts: evictCosts,
	}
}

type solveResult = matrixdsl.Decision

func (s *matrixSolver) Solve(requestedModel string, runningModels []string) solveResult {
	return s.program.Solve(requestedModel, runningModels, s.evictCosts)
}

package router

import (
	"io"
	"net/http"
	"net/http/httptest"
	"testing"
	"time"

	"github.com/toxicwind/bornite/internal/config"
	"github.com/toxicwind/bornite/internal/logmon"
	"github.com/toxicwind/bornite/internal/process"
)

// newTestMatrix builds a Matrix router from supplied processes, bypassing
// NewMatrix's call to process.New.
func newTestMatrix(t *testing.T, conf config.Config, sets config.OrderedSets, evictCosts map[string]int, processes map[string]process.Process) *Matrix {
	t.Helper()
	models := make(map[string]config.ModelConfig, len(processes))
	for model := range processes {
		models[model] = config.ModelConfig{}
	}
	matrix := &config.MatrixConfig{
		EvictCosts: evictCosts,
		Sets:       sets,
	}
	if err := config.ValidateMatrix(matrix, models); err != nil {
		t.Fatalf("ValidateMatrix: %v", err)
	}

	logger := logmon.NewWriter(io.Discard)
	swapper := &matrixSwapper{
		solver: newMatrixSolver(matrix.Program(), matrix.ResolvedEvictCosts()),
		logger: logger,
	}
	base, err := newBaseRouter("matrix", conf, processes, logger, swapper)
	if err != nil {
		t.Fatalf("newBaseRouter: %v", err)
	}
	base.testProcessed = make(chan struct{}, 64)
	r := &Matrix{baseRouter: base}
	go base.run()
	t.Cleanup(func() {
		if !r.shuttingDown.Load() {
			_ = r.Shutdown(time.Second)
		}
	})
	return r
}

func baseMatrixConfig() config.Config {
	return config.Config{
		HealthCheckTimeout: 5,
		Matrix:             &config.MatrixConfig{},
	}
}

// TestMatrix_SwapEvictsConflicting verifies that loading a model triggers
// eviction of running models that are not in any shared set with it.
func TestMatrix_SwapEvictsConflicting(t *testing.T) {
	a := newFakeProcess("a")
	a.markReady()
	go a.Run(0) // park a Run goroutine so Stop has something to release

	b := newFakeProcess("b")
	b.autoReady = true

	// Two single-model sets: a and b never coexist, so loading b must evict a.
	sets := config.OrderedSets{
		{Name: "s_a", DSL: "a"},
		{Name: "s_b", DSL: "b"},
	}
	r := newTestMatrix(t, baseMatrixConfig(), sets, nil, map[string]process.Process{"a": a, "b": b})

	w := httptest.NewRecorder()
	r.ServeHTTP(w, newRequest("b"))

	if w.Code != http.StatusOK {
		t.Fatalf("status=%d body=%q", w.Code, w.Body.String())
	}
	if got := a.stopCalls.Load(); got != 1 {
		t.Errorf("a.stopCalls=%d want 1", got)
	}
	if got := b.runCalls.Load(); got != 1 {
		t.Errorf("b.runCalls=%d want 1", got)
	}
}

// TestMatrix_CoexistInSet verifies that a model is not evicted when the target
// shares a set with it (the fast path applies if the target is already ready).
func TestMatrix_CoexistInSet(t *testing.T) {
	a := newFakeProcess("a")
	a.markReady()
	go a.Run(0)

	b := newFakeProcess("b")
	b.autoReady = true

	// Both fit in s_ab, so b's swap should not stop a.
	sets := config.OrderedSets{
		{Name: "s_ab", DSL: "a & b"},
	}
	r := newTestMatrix(t, baseMatrixConfig(), sets, nil, map[string]process.Process{"a": a, "b": b})

	w := httptest.NewRecorder()
	r.ServeHTTP(w, newRequest("b"))

	if w.Code != http.StatusOK {
		t.Fatalf("status=%d body=%q", w.Code, w.Body.String())
	}
	if got := a.stopCalls.Load(); got != 0 {
		t.Errorf("a.stopCalls=%d want 0 (coexists with b)", got)
	}
	if got := b.runCalls.Load(); got != 1 {
		t.Errorf("b.runCalls=%d want 1", got)
	}
}

// TestMatrix_CoexistingSetParallel verifies that two models that share an
// expanded set load in parallel — the solver returns empty Evict for both,
// the collision predicate clears them, and both swaps run together.
func TestMatrix_CoexistingSetParallel(t *testing.T) {
	a := newFakeProcess("a")
	pb := newFakeProcess("b")

	sets := config.OrderedSets{
		{Name: "s_ab", DSL: "a & b"},
	}
	r := newTestMatrix(t, baseMatrixConfig(), sets, nil, map[string]process.Process{"a": a, "b": pb})

	w1 := httptest.NewRecorder()
	done1 := make(chan struct{})
	go func() {
		r.ServeHTTP(w1, newRequest("a"))
		close(done1)
	}()
	waitProcessed(t, r.testProcessed, 1)

	w2 := httptest.NewRecorder()
	done2 := make(chan struct{})
	go func() {
		r.ServeHTTP(w2, newRequest("b"))
		close(done2)
	}()
	waitProcessed(t, r.testProcessed, 1)

	<-a.runStarted
	<-pb.runStarted

	a.markReady()
	pb.markReady()

	for i, ch := range []chan struct{}{done1, done2} {
		select {
		case <-ch:
		case <-time.After(time.Second):
			t.Fatalf("request %d did not complete", i)
		}
	}
	if got := a.stopCalls.Load(); got != 0 {
		t.Errorf("a.stopCalls=%d want 0 (coexists with b)", got)
	}
	if got := pb.stopCalls.Load(); got != 0 {
		t.Errorf("b.stopCalls=%d want 0 (coexists with a)", got)
	}
}

// TestMatrix_IncompatibleQueues verifies that the second request for a model
// that cannot coexist with the in-flight first model queues until the first
// completes, and then evicts it. This exercises the scheduler folding in-flight
// swap targets into the running set it hands the swapper.
func TestMatrix_IncompatibleQueues(t *testing.T) {
	a := newFakeProcess("a")
	pb := newFakeProcess("b")

	sets := config.OrderedSets{
		{Name: "s_a", DSL: "a"},
		{Name: "s_b", DSL: "b"},
	}
	r := newTestMatrix(t, baseMatrixConfig(), sets, nil, map[string]process.Process{"a": a, "b": pb})

	w1 := httptest.NewRecorder()
	done1 := make(chan struct{})
	go func() {
		r.ServeHTTP(w1, newRequest("a"))
		close(done1)
	}()
	waitProcessed(t, r.testProcessed, 1)

	// B arrives before A transitions to StateStarting. The running set the
	// scheduler builds includes A (an in-flight swap target), so the solver
	// returns evict=[a] and collidesWith forces B to queue.
	w2 := httptest.NewRecorder()
	done2 := make(chan struct{})
	go func() {
		r.ServeHTTP(w2, newRequest("b"))
		close(done2)
	}()
	waitProcessed(t, r.testProcessed, 1)

	if got := pb.runCalls.Load(); got != 0 {
		t.Errorf("b started in parallel: runCalls=%d want 0", got)
	}

	<-a.runStarted
	a.markReady()
	waitProcessed(t, r.testProcessed, 1) // swapDone(a) → b promoted, evicts a
	<-pb.runStarted
	pb.markReady()

	for i, ch := range []chan struct{}{done1, done2} {
		select {
		case <-ch:
		case <-time.After(time.Second):
			t.Fatalf("request %d did not complete", i)
		}
	}
	if got := a.stopCalls.Load(); got != 1 {
		t.Errorf("a.stopCalls=%d want 1 (b's swap must stop a)", got)
	}
}

// TestMatrixSolver_TieBreakDefinitionOrder pins the solver's tie-break rule:
// when multiple candidate sets have equal eviction cost, the earlier-defined
// set wins.
func TestMatrixSolver_TieBreakDefinitionOrder(t *testing.T) {
	s := newTestMatrixSolver(t, config.OrderedSets{
		{Name: "first", DSL: "a & b"},
		{Name: "second", DSL: "a & c"},
	}, nil, "a", "b", "c")

	// No models running, request "a": both sets have cost 0 and contain a.
	// Definition order: "first" wins.
	result := s.Solve("a", nil)
	if result.SetName != "first" {
		t.Errorf("SetName=%q want %q", result.SetName, "first")
	}
}

// TestMatrixSolver_EvictCostsPreferred verifies that higher evict costs steer
// the solver toward a cheaper set.
func TestMatrixSolver_EvictCostsPreferred(t *testing.T) {
	// b is expensive to evict; c is cheap. Request "a" with both b and c
	// running. The solver should pick the set that keeps b.
	s := newTestMatrixSolver(t, config.OrderedSets{
		{Name: "a_with_c", DSL: "a & c"}, // would evict b (cost 10)
		{Name: "a_with_b", DSL: "a & b"}, // would evict c (cost 1)
	}, map[string]int{"b": 10, "c": 1}, "a", "b", "c")

	result := s.Solve("a", []string{"b", "c"})
	if result.SetName != "a_with_b" {
		t.Errorf("SetName=%q want %q (keep expensive b)", result.SetName, "a_with_b")
	}
	if len(result.Evict) != 1 || result.Evict[0] != "c" {
		t.Errorf("Evict=%v want [c]", result.Evict)
	}
}

func newTestMatrixSolver(t *testing.T, sets config.OrderedSets, evictCosts map[string]int, modelNames ...string) *matrixSolver {
	t.Helper()
	models := make(map[string]config.ModelConfig, len(modelNames))
	for _, model := range modelNames {
		models[model] = config.ModelConfig{}
	}
	matrix := &config.MatrixConfig{
		EvictCosts: evictCosts,
		Sets:       sets,
	}
	if err := config.ValidateMatrix(matrix, models); err != nil {
		t.Fatalf("ValidateMatrix: %v", err)
	}
	return newMatrixSolver(matrix.Program(), matrix.ResolvedEvictCosts())
}

package router

import (
	"context"
	"errors"
	"fmt"
	"net"
	"net/http"
	"net/http/httputil"
	"runtime"
	"sort"
	"strings"
	"sync"
	"sync/atomic"
	"time"

	"github.com/toxicwind/bornite/internal/config"
	"github.com/toxicwind/bornite/internal/logmon"
	"github.com/toxicwind/bornite/internal/swaputil"
)

type peerMember struct {
	peerID       string
	reverseProxy *httputil.ReverseProxy
	apiKey       string
}

type peerRoute struct {
	member  *peerMember
	modelID string
}

type Peer struct {
	cfg    config.Config
	logger *logmon.Monitor
	peers  map[string]*peerRoute

	mu     sync.RWMutex
	health map[string]*PeerHealth

	shutdownCtx  context.Context
	shutdownFn   context.CancelFunc
	shuttingDown atomic.Bool
	inflight     sync.WaitGroup
}

func NewPeer(cfg config.Config, logger *logmon.Monitor) (*Peer, error) {
	if err := config.ValidatePeerNamespace(cfg); err != nil {
		return nil, err
	}

	peers := cfg.Peers
	modelMap := make(map[string]*peerRoute)
	bareRoutes := make(map[string][]*peerRoute)

	peerIDs := make([]string, 0, len(peers))
	for peerID := range peers {
		peerIDs = append(peerIDs, peerID)
	}
	sort.Strings(peerIDs)

	health := make(map[string]*PeerHealth, len(peerIDs))
	for _, peerID := range peerIDs {
		hc := peers[peerID].Health
		// ApplyDefaults fills unset fields and preserves explicitly
		// configured ones. Replacing the whole struct when Enabled is
		// nil discarded FailureThreshold/Weights, so peers never
		// ejected under a partially-specified health config.
		hc.ApplyDefaults()
		health[peerID] = NewPeerHealth(peerID, hc, logger)
	}

	for _, peerID := range peerIDs {
		peer := peers[peerID]

		peerTransport := &http.Transport{
			Proxy: http.ProxyFromEnvironment,
			DialContext: (&net.Dialer{
				Timeout:   time.Duration(peer.Timeouts.Connect) * time.Second,
				KeepAlive: time.Duration(peer.Timeouts.KeepAlive) * time.Second,
			}).DialContext,
			TLSHandshakeTimeout:   time.Duration(peer.Timeouts.TLSHandshake) * time.Second,
			ResponseHeaderTimeout: time.Duration(peer.Timeouts.ResponseHeader) * time.Second,
			ExpectContinueTimeout: time.Duration(peer.Timeouts.ExpectContinue) * time.Second,
			ForceAttemptHTTP2:     true,
			MaxIdleConns:          100,
			MaxIdleConnsPerHost:   10,
			IdleConnTimeout:       time.Duration(peer.Timeouts.IdleConn) * time.Second,
		}

		reverseProxy := &httputil.ReverseProxy{
			Transport: peerTransport,
			Rewrite: func(r *httputil.ProxyRequest) {
				r.SetURL(peer.ProxyURL)
				r.Out.Host = r.Out.URL.Host
				// Debug: log outgoing URL (only when debug level)
			},
		}

		reverseProxy.ModifyResponse = func(resp *http.Response) error {
			if strings.Contains(strings.ToLower(resp.Header.Get("Content-Type")), "text/event-stream") {
				resp.Header.Set("X-Accel-Buffering", "no")
			}
			// Health observation: classify the outcome from the actual
			// response. A non-2xx status is immediately classifiable; a
			// 2xx body is observed through to EOF so the 200-empty
			// honesty check sees the real bytes. Exactly-once is
			// enforced by the observer itself.
			if obs := healthObserverFrom(resp.Request.Context()); obs != nil {
				if resp.StatusCode < 200 || resp.StatusCode >= 300 {
					obs.finishStatus(resp.StatusCode)
				} else {
					obs.status = resp.StatusCode
					if strings.Contains(strings.ToLower(resp.Header.Get("Content-Type")), "text/event-stream") {
						obs.streaming = true
					}
					resp.Body = &observingReadCloser{ReadCloser: resp.Body, obs: obs}
				}
			}
			return nil
		}

		reverseProxy.ErrorHandler = func(w http.ResponseWriter, r *http.Request, err error) {
			// Health observation: a proxy-level error is a transport
			// outcome (or a neutral cancel when the client went away).
			if obs := healthObserverFrom(r.Context()); obs != nil {
				obs.finishTransport(err)
			}
			// A cancelled request is not a peer failure, so keep it out of the
			// warning stream whether or not the sentinel applies below.
			if errors.Is(err, context.Canceled) || r.Context().Err() != nil {
				logger.Debugf("peer %s: request cancelled: %v", peerID, err)
			} else {
				logger.Warnf("peer %s: proxy error: %v", peerID, err)
			}

			// Only a client that actually hung up gets the recorded-only
			// sentinel (#1029). A request cancelled server-side still has a
			// client waiting for an answer.
			if swaputil.MarkClientClosed(w, r) || swaputil.ResponseStarted(w) {
				return
			}

			errMsg := fmt.Sprintf("peer proxy error: %v", err)
			if runtime.GOOS == "darwin" && strings.Contains(err.Error(), "connect: no route to host") {
				errMsg += " (hint: on macOS, check System Settings > Privacy & Security > Local Network permissions)"
			}
			swaputil.SendResponse(w, r, http.StatusBadGateway, errMsg)
		}

		pp := &peerMember{
			peerID:       peerID,
			reverseProxy: reverseProxy,
			apiKey:       peer.ApiKey,
		}

		seen := make(map[string]struct{})
		for _, modelID := range peer.Models {
			if _, duplicate := seen[modelID]; duplicate {
				continue
			}
			seen[modelID] = struct{}{}

			route := &peerRoute{member: pp, modelID: modelID}
			modelMap[config.PeerModelFQN(peerID, modelID)] = route
			bareRoutes[modelID] = append(bareRoutes[modelID], route)
		}
	}

	for modelID, routes := range bareRoutes {
		if len(routes) != 1 {
			continue
		}
		if _, reserved := modelMap[modelID]; reserved {
			continue
		}
		modelMap[modelID] = routes[0]
	}

	shutdownCtx, shutdownFn := context.WithCancel(context.Background())

	return &Peer{
		cfg:         cfg,
		logger:      logger,
		peers:       modelMap,
		health:      health,
		shutdownCtx: shutdownCtx,
		shutdownFn:  shutdownFn,
	}, nil
}

func (r *Peer) Handles(model string) bool {
	_, ok := r.peers[model]
	return ok
}

func (r *Peer) Shutdown(timeout time.Duration) error {
	if !r.shuttingDown.CompareAndSwap(false, true) {
		return fmt.Errorf("shutdown already in progress")
	}

	if timeout == 0 {
		r.shutdownFn()
		r.inflight.Wait()
		return nil
	}

	done := make(chan struct{})
	go func() {
		r.inflight.Wait()
		close(done)
	}()

	select {
	case <-done:
		return nil
	case <-time.After(timeout):
		r.shutdownFn()
		r.inflight.Wait()
		return fmt.Errorf("peer shutdown timed out after %v", timeout)
	}
}

func (r *Peer) ServeHTTP(w http.ResponseWriter, req *http.Request) {
	if r.shuttingDown.Load() {
		swaputil.SendError(w, req, fmt.Errorf("peer proxy is shutting down"))
		return
	}
	r.inflight.Add(1)
	defer r.inflight.Done()

	data, err := swaputil.FetchContext(req, r.cfg)
	if err != nil {
		swaputil.SendError(w, req, err)
		return
	}

	route, found := r.peers[data.ModelID]
	if !found {
		r.logger.Warnf("peer model not found: %s", data.ModelID)
		swaputil.SendError(w, req, ErrNoPeerModelFound)
		return
	}
	pp := route.member

	// Health admission: an ejected peer fails fast with 503 instead
	// of burning a backend call. Admitted requests carry a health
	// observer (in the request context) that reports exactly one
	// outcome when the proxied response completes or fails.
	if ph, ok := r.health[pp.peerID]; ok && ph != nil {
		admit, probe, gen := ph.Admit()
		if !admit {
			swaputil.SendResponse(w, req, http.StatusServiceUnavailable,
				"peer_circuit_open: peer ejected by health monitor; retry later")
			return
		}
		obs := newHealthObserver(ph, req, false, probe, gen)
		req = req.WithContext(context.WithValue(req.Context(), healthObserverKey{}, obs))
	}

	r.logger.Debugf("peer: routing model %s to peer %s as %s (free=%v)", data.ModelID, pp.peerID, route.modelID, pp.apiKey == "")

	if data.Model != route.modelID {
		req, err = swaputil.ReplaceRequestModel(req, data.Model, route.modelID)
		if err != nil {
			swaputil.SendResponse(w, req, http.StatusBadRequest, err.Error())
			return
		}
	}

	if pp.apiKey != "" {
		req.Header.Set("Authorization", "Bearer "+pp.apiKey)
		req.Header.Set("x-api-key", pp.apiKey)
	} else {
		// Workaround for "not anonymous" gate (Pollinations now requires any Bearer to avoid 401).
		// We ignore anonymous distinction entirely: inject dummy Bearer so free tier always passes.
		// ponytail: dummy bearer for free backends; use real key via peer.apiKey if rate-limit matters
		req.Header.Set("Authorization", "Bearer pollinations-free-workaround")
		req.Header.Set("x-api-key", "pollinations-free-workaround")
	}
	r.logger.Debugf("peer: outgoing Authorization=%s Host=%s Path=%s", req.Header.Get("Authorization"), req.Host, req.URL.Path)
	// Cancel the proxy request when the client disconnects or shutdown times out.
	// Deriving from the request covers the client half directly and keeps the
	// request's context values — notably the client context that tells a real
	// disconnect apart from a server-side cancel. AfterFunc links the unrelated
	// shutdown context in without a goroutine leak.
	ctx, cancel := context.WithCancel(req.Context())
	stopShutdown := context.AfterFunc(r.shutdownCtx, cancel)
	req = req.WithContext(ctx)

	pp.reverseProxy.ServeHTTP(w, req)

	stopShutdown()
	cancel()
}

// HealthSnapshots returns the current health view of every peer this Peer
// fronts, keyed by peer ID. Test/observability bridge.
func (pr *Peer) HealthSnapshots() []HealthSnapshot {
	pr.mu.RLock()
	defer pr.mu.RUnlock()
	out := make([]HealthSnapshot, 0, len(pr.health))
	for _, ph := range pr.health {
		out = append(out, ph.Snapshot())
	}
	return out
}

package router

// Event-driven per-peer health state machine for the bornite router.
//
// Design notes (borrowed, not invented):
//   - The state discipline (closed / half-open / open, two-step admit-then-report,
//     admission identity — probe flag plus generation — so stale outcomes can
//     never be mistaken for the half-open probe) follows the sony/gobreaker
//     pattern: admission is checked before the request, the outcome is reported
//     exactly once when the response completes or the transport fails.
//   - Routing signals follow HACO / SkyWalker / the vLLM semantic router literature:
//     decisions are made on observed latency and reliability at the binding point,
//     never on nominal/static health.
//   - Failure impact is confined to the failing peer (Tarragon): an open circuit
//     fails fast for that peer only; nothing restarts, nothing poisons the rest.
//
// Event-driven means exactly that: there are no timers, no polling loops, no
// background goroutines here. Transitions happen when a real outcome is reported.
// Half-open recovery is demand-driven — after the configured cool-off has elapsed,
// the next real request is admitted as a single-flight probe (checked lazily at
// request time). Concurrent requests while a probe is in flight are rejected.
//
// Outcome classes reuse the bornite reliability taxonomy: 402-not-entitled,
// 404-dead-id, 429-throttled, 200-empty, 403-refused, plus 5xx, transport
// failures, success, and client-cancelled (neutral).

import (
	"bytes"
	"context"
	"fmt"
	"io"
	"net/http"
	"strings"
	"sync"
	"time"

	"github.com/toxicwind/bornite/internal/config"
	"github.com/toxicwind/bornite/internal/logmon"
	"github.com/tidwall/gjson"
)

// OutcomeClass is one bucket of the bornite reliability taxonomy, observed at the
// peer binding point.
type OutcomeClass string

const (
	OutcomeSuccess     OutcomeClass = "success"
	OutcomeEmpty200    OutcomeClass = "200-empty"
	OutcomeThrottled   OutcomeClass = "429-throttled"
	OutcomeNotEntitled OutcomeClass = "402-not-entitled"
	OutcomeDeadID      OutcomeClass = "404-dead-id"
	OutcomeRefused     OutcomeClass = "403-refused"
	OutcomeServerError OutcomeClass = "5xx"
	OutcomeTransport   OutcomeClass = "transport"
	// OutcomeCancelled means the client went away mid-request. It is neutral:
	// it updates latency signal but never moves the failure score.
	OutcomeCancelled OutcomeClass = "cancelled"
)

// HealthState is the externally visible health of a peer.
type HealthState string

const (
	HealthHealthy     HealthState = "healthy"
	HealthDegraded    HealthState = "degraded"
	HealthCircuitOpen HealthState = "circuit-open"
	// HealthHalfOpen is the single-flight recovery probe state. It is real and
	// observable: exactly one real request is admitted while half-open.
	HealthHalfOpen HealthState = "half-open"
)

// healthRingSize is the rolling outcome window used for the error-rate signal.
const healthRingSize = 32

// healthRingMinSamples gates the error-rate degraded signal so a lone early
// failure cannot mark a fresh peer degraded.
const healthRingMinSamples = 8

// maxClassifyBody bounds how much response body is retained for 200-empty
// classification (empty choices detection). Streams are classified from
// incrementally counted SSE data payloads instead.
const maxClassifyBody = 32 * 1024

// ClassifyOutcome maps an observed proxy result onto the reliability taxonomy.
// Exactly one of: clientGone (neutral), !completed (transport), HTTP status
// classes, or — for completed 2xx — the 200-empty honesty check.
func ClassifyOutcome(status int, path string, body []byte, streamed bool, dataPayloads int, completed bool, clientGone bool) OutcomeClass {
	if clientGone {
		return OutcomeCancelled
	}
	if !completed {
		return OutcomeTransport
	}
	switch status {
	case http.StatusTooManyRequests:
		return OutcomeThrottled
	case 402:
		return OutcomeNotEntitled
	case http.StatusNotFound:
		return OutcomeDeadID
	case http.StatusForbidden:
		return OutcomeRefused
	}
	if status >= 500 && status <= 599 {
		return OutcomeServerError
	}
	if status < 200 || status >= 300 {
		// Any other non-2xx (400, 401, 405, 422, 3xx, ...): the peer refused
		// the request in some form.
		return OutcomeRefused
	}
	if streamed {
		if dataPayloads == 0 && completionPathRelevant(path) {
			return OutcomeEmpty200
		}
		return OutcomeSuccess
	}
	if len(bytes.TrimSpace(body)) == 0 {
		if completionPathRelevant(path) {
			return OutcomeEmpty200
		}
		return OutcomeSuccess
	}
	if isChatCompletionsPath(path) && emptyChoices(body) {
		return OutcomeEmpty200
	}
	return OutcomeSuccess
}

// completionPathRelevant reports whether the path is a completion-type
// endpoint where an empty 200 is evidence of an unusable peer (200-empty).
// Unrelated successful endpoints — model lists, health checks — may
// legitimately return empty bodies and must never trip the empty class.
func completionPathRelevant(path string) bool {
	for _, seg := range []string{
		"chat/completions",
		"/completions",
		"/embeddings",
		"/audio/",
		"/images/",
	} {
		if strings.Contains(path, seg) {
			return true
		}
	}
	return false
}

func isChatCompletionsPath(path string) bool {
	return strings.Contains(path, "chat/completions")
}

// emptyChoices reports whether body is a chat-completions payload whose choices
// array is present but empty — the canonical 200-empty shape from probes.
func emptyChoices(body []byte) bool {
	choices := gjson.GetBytes(body, "choices")
	return choices.Exists() && choices.IsArray() && len(choices.Array()) == 0
}

// PeerHealth is the per-peer health tracker: EWMA latency, rolling error rate,
// weighted failure score, and the healthy/degraded/circuit-open (+ half-open)
// state machine. The zero value is not usable; use NewPeerHealth.
type PeerHealth struct {
	peerID string
	cfg    config.HealthConfig
	log    *logmon.Monitor

	mu             sync.Mutex
	state          HealthState
	probeInFlight  bool
	openedAt       time.Time
	generation     uint64
	failureScore   float64
	consecFailure  int
	consecSuccess  int
	probeSuccesses int
	ewmaMs         float64
	ewmaSamples    uint64
	ring           []OutcomeClass
	ringPos        int
	ringCount      int
}

// NewPeerHealth builds a tracker for one peer. Defaults are applied to cfg.
func NewPeerHealth(peerID string, cfg config.HealthConfig, log *logmon.Monitor) *PeerHealth {
	cfg.ApplyDefaults()
	h := &PeerHealth{
		peerID: peerID,
		cfg:    cfg,
		log:    log,
		state:  HealthHealthy,
		ring:   make([]OutcomeClass, healthRingSize),
	}
	if log != nil {
		log.Infof("peer-health peer=%s initialized state=healthy failure_threshold=%.1f cool_off=%ds ewma_alpha=%.2f weights=%v",
			peerID, cfg.FailureThreshold, int64(cfg.CoolOffSeconds), cfg.EWMAAlpha, cfg.Weights)
	}
	return h
}

// Admit decides whether a request may use the peer right now. The second return
// value marks the request as the single-flight half-open probe; the third is
// the current generation — the admission identity the request must present when
// it reports its outcome. Denied callers must fail fast (503) — the peer is
// ejected from rotation.
func (h *PeerHealth) Admit() (admit bool, probe bool, gen uint64) {
	h.mu.Lock()
	defer h.mu.Unlock()
	switch h.state {
	case HealthCircuitOpen:
		if h.probeInFlight {
			return false, false, h.generation
		}
		if time.Since(h.openedAt) >= h.coolOff() {
			h.probeInFlight = true
			h.transitionLocked(HealthHalfOpen, OutcomeSuccess, "cool-off elapsed; admitting single real-traffic probe")
			return true, true, h.generation
		}
		return false, false, h.generation
	case HealthHalfOpen:
		if h.probeInFlight {
			return false, false, h.generation
		}
		h.probeInFlight = true
		return true, true, h.generation
	default:
		return true, false, h.generation
	}
}

// Report records exactly one outcome for an admitted request. It is safe for
// concurrent use and idempotent per request only if the caller reports once
// (the response observer enforces exactly-once with sync.Once).
//
// Report carries no admission identity, so it is treated as an ordinary
// request: it feeds telemetry and the failure score but can never drive
// half-open probe accounting. The probe path uses reportOutcome with the
// identity Admit returned, so a late outcome from a pre-trip request can never
// be mistaken for the probe — stale success must never readmit, stale failure
// must never steal the probe slot.
func (h *PeerHealth) Report(class OutcomeClass, latency time.Duration, detail string) {
	h.reportOutcome(class, latency, detail, false, 0)
}

// reportOutcome records one outcome. probe/gen are the admission identity from
// Admit: probe is true only for the request admitted as the single-flight
// half-open probe, gen is the generation Admit returned. Only an outcome whose
// identity matches the live probe (same generation, still half-open, still the
// in-flight probe) drives probe accounting. Every other outcome — including
// stale ones from before the last transition — still feeds latency/error
// telemetry, but during half-open it must not move the failure score or probe
// state: its failure evidence was already priced into the trip that opened the
// circuit, and the probe is the only new information.
func (h *PeerHealth) reportOutcome(class OutcomeClass, latency time.Duration, detail string, probe bool, gen uint64) {
	h.mu.Lock()
	defer h.mu.Unlock()

	h.observeLatencyLocked(latency)
	h.ringPushLocked(class)

	weight := h.cfg.WeightFor(string(class))
	isProbe := probe && gen == h.generation && h.state == HealthHalfOpen && h.probeInFlight

	if h.state == HealthHalfOpen && !isProbe {
		// Controlled experiment in progress: telemetry only.
		return
	}

	switch {
	case class == OutcomeCancelled:
		// Neutral: never moves the score. A cancelled probe must not wedge
		// half-open — re-open so the next real request can probe again.
		if isProbe {
			h.probeInFlight = false
			h.transitionLocked(HealthCircuitOpen, class, "half-open probe cancelled by client; circuit re-opened")
		}
	case class == OutcomeSuccess:
		h.consecSuccess++
		h.consecFailure = 0
		h.failureScore -= h.cfg.RecoveryCredit
		if h.failureScore < 0 {
			h.failureScore = 0
		}
		if isProbe {
			h.probeSuccesses++
			if h.probeSuccesses >= h.cfg.SuccessThreshold {
				h.probeInFlight = false
				h.probeSuccesses = 0
				h.transitionLocked(HealthHealthy, class, "half-open probe succeeded; peer readmitted to rotation")
			} else {
				// Threshold not yet met: release single-flight so the next
				// real request becomes the next probe.
				h.probeInFlight = false
			}
		}
	default:
		h.consecFailure++
		h.consecSuccess = 0
		h.failureScore += weight
		if isProbe {
			h.probeInFlight = false
			h.probeSuccesses = 0
			h.transitionLocked(HealthCircuitOpen, class,
				fmt.Sprintf("half-open probe failed class=%s; circuit re-opened", class))
		} else if h.state != HealthCircuitOpen && h.failureScore >= h.cfg.FailureThreshold {
			h.transitionLocked(HealthCircuitOpen, class,
				fmt.Sprintf("failure score %.1f >= threshold %.1f (%s)", h.failureScore, h.cfg.FailureThreshold, detail))
		}
	}

	if h.state == HealthHealthy || h.state == HealthDegraded {
		h.evalDegradedLocked(class)
	}
}

// State returns the current health state.
func (h *PeerHealth) State() HealthState {
	h.mu.Lock()
	defer h.mu.Unlock()
	return h.state
}

// RetryAfter reports how long until a half-open probe may be admitted. Zero
// when the circuit is not open.
func (h *PeerHealth) RetryAfter() time.Duration {
	h.mu.Lock()
	defer h.mu.Unlock()
	if h.state != HealthCircuitOpen {
		return 0
	}
	rem := h.coolOff() - time.Since(h.openedAt)
	if rem < 0 {
		return 0
	}
	return rem
}

// HealthSnapshot is the JSON-serializable view served by /peer-health.
type HealthSnapshot struct {
	Peer             string      `json:"peer"`
	State            HealthState `json:"state"`
	HalfOpenProbe    bool        `json:"half_open_probe,omitempty"`
	FailureScore     float64     `json:"failure_score"`
	FailureThreshold float64     `json:"failure_threshold"`
	ConsecutiveFails int         `json:"consecutive_failures"`
	ConsecutiveOK    int         `json:"consecutive_successes"`
	EWMALatencyMs    float64     `json:"ewma_latency_ms"`
	EWMASamples      uint64      `json:"ewma_samples"`
	ErrorRate        float64     `json:"error_rate"`
	Transitions      uint64      `json:"transitions"`
	OpenedAt         *time.Time  `json:"opened_at,omitempty"`
	RetryAfterMs     int64       `json:"retry_after_ms,omitempty"`
}

// Snapshot captures the current health view.
func (h *PeerHealth) Snapshot() HealthSnapshot {
	h.mu.Lock()
	defer h.mu.Unlock()
	snap := HealthSnapshot{
		Peer:             h.peerID,
		State:            h.state,
		HalfOpenProbe:    h.probeInFlight,
		FailureScore:     h.failureScore,
		FailureThreshold: h.cfg.FailureThreshold,
		ConsecutiveFails: h.consecFailure,
		ConsecutiveOK:    h.consecSuccess,
		EWMALatencyMs:    h.ewmaMs,
		EWMASamples:      h.ewmaSamples,
		ErrorRate:        h.errorRateLocked(),
		Transitions:      h.generation,
	}
	if h.state == HealthCircuitOpen {
		t := h.openedAt
		snap.OpenedAt = &t
		snap.RetryAfterMs = int64(h.RetryAfterLocked() / time.Millisecond)
	}
	return snap
}

func (h *PeerHealth) coolOff() time.Duration {
	return time.Duration(h.cfg.CoolOffSeconds * float64(time.Second))
}

// RetryAfterLocked is RetryAfter assuming h.mu is held.
func (h *PeerHealth) RetryAfterLocked() time.Duration {
	if h.state != HealthCircuitOpen {
		return 0
	}
	rem := h.coolOff() - time.Since(h.openedAt)
	if rem < 0 {
		return 0
	}
	return rem
}

func (h *PeerHealth) observeLatencyLocked(latency time.Duration) {
	ms := float64(latency) / float64(time.Millisecond)
	if h.ewmaSamples == 0 {
		h.ewmaMs = ms
	} else {
		a := h.cfg.EWMAAlpha
		h.ewmaMs = a*ms + (1-a)*h.ewmaMs
	}
	h.ewmaSamples++
}

func (h *PeerHealth) ringPushLocked(class OutcomeClass) {
	h.ring[h.ringPos] = class
	h.ringPos = (h.ringPos + 1) % healthRingSize
	if h.ringCount < healthRingSize {
		h.ringCount++
	}
}

// errorRateLocked is the fraction of the rolling window with failure weight > 0.
func (h *PeerHealth) errorRateLocked() float64 {
	if h.ringCount == 0 {
		return 0
	}
	bad := 0
	for i := 0; i < h.ringCount; i++ {
		if h.cfg.WeightFor(string(h.ring[i])) > 0 {
			bad++
		}
	}
	return float64(bad) / float64(h.ringCount)
}

func (h *PeerHealth) evalDegradedLocked(class OutcomeClass) {
	latBad := h.cfg.DegradedLatencyMs > 0 && h.ewmaSamples > 0 && h.ewmaMs >= h.cfg.DegradedLatencyMs
	errBad := h.cfg.DegradedErrorRate > 0 && h.ringCount >= healthRingMinSamples &&
		h.errorRateLocked() >= h.cfg.DegradedErrorRate
	reason := ""
	switch {
	case latBad && errBad:
		reason = fmt.Sprintf("ewma latency %.0fms >= %.0fms and error rate above threshold", h.ewmaMs, h.cfg.DegradedLatencyMs)
	case latBad:
		reason = fmt.Sprintf("ewma latency %.0fms >= %.0fms", h.ewmaMs, h.cfg.DegradedLatencyMs)
	case errBad:
		reason = fmt.Sprintf("rolling error rate %.2f >= %.2f", h.errorRateLocked(), h.cfg.DegradedErrorRate)
	}
	if h.state == HealthHealthy && reason != "" {
		h.transitionLocked(HealthDegraded, class, reason)
	} else if h.state == HealthDegraded && reason == "" {
		h.transitionLocked(HealthHealthy, class, "latency and error rate recovered below degraded thresholds")
	}
}

// transitionLocked moves the state machine, bumps the generation (so stale
// outcomes can never undo a transition), and emits the structured audit log.
// The log line carries no URLs, credentials, headers, or bodies.
func (h *PeerHealth) transitionLocked(to HealthState, class OutcomeClass, reason string) {
	from := h.state
	if from == to {
		return
	}
	h.state = to
	h.generation++
	if to == HealthCircuitOpen {
		h.openedAt = time.Now()
		h.probeSuccesses = 0
		// Entering open retires any probe slot: no transition into open may
		// leave single-flight admission wedged — the next cool-off expiry
		// admits a fresh probe.
		h.probeInFlight = false
	}
	if from == HealthHalfOpen && to == HealthHealthy {
		// A successful probe is proven health: the peer rejoins with a clean
		// failure slate. Re-ejection needs the full configured threshold of
		// fresh evidence - a recovered peer must not sit one failure away
		// from the circuit reopening.
		h.failureScore = 0
	}
	if h.log == nil {
		return
	}
	line := fmt.Sprintf("peer-health peer=%s gen=%d %s->%s class=%s score=%.1f/%.1f ewma_ms=%.0f err_rate=%.2f reason=%q",
		h.peerID, h.generation, from, to, class,
		h.failureScore, h.cfg.FailureThreshold, h.ewmaMs, h.errorRateLocked(), reason)
	if to == HealthCircuitOpen {
		h.log.Warnf("%s", line)
	} else {
		h.log.Infof("%s", line)
	}
}

// ---------------------------------------------------------------------------
// Request observation: exactly-once outcome reporting per proxied request.
// ---------------------------------------------------------------------------

// healthObserverKey is the request-context key carrying the *healthObserver.
type healthObserverKey struct{}

func healthObserverFrom(ctx context.Context) *healthObserver {
	obs, _ := ctx.Value(healthObserverKey{}).(*healthObserver)
	return obs
}

// healthObserver tracks one admitted request from admission to completion and
// reports exactly one outcome to its PeerHealth.
type healthObserver struct {
	health    *PeerHealth
	ctx       context.Context
	path      string
	streaming bool
	status    int
	start     time.Time
	// probe/gen are the admission identity from Admit, reported back with the
	// outcome so only the real probe drives half-open accounting.
	probe bool
	gen   uint64

	once         sync.Once
	bodyBuf      []byte
	truncated    bool
	lineBuf      []byte
	dataPayloads int
}

func newHealthObserver(health *PeerHealth, r *http.Request, streaming bool, probe bool, gen uint64) *healthObserver {
	return &healthObserver{
		health:    health,
		ctx:       r.Context(),
		path:      r.URL.Path,
		streaming: streaming,
		start:     time.Now(),
		probe:     probe,
		gen:       gen,
	}
}

// finishTransport records a proxy transport failure (ErrorHandler path).
func (o *healthObserver) finishTransport(err error) {
	o.once.Do(func() {
		class := OutcomeTransport
		if o.ctx.Err() != nil {
			class = OutcomeCancelled
		}
		msg := ""
		if err != nil {
			msg = firstLine(err.Error(), 200)
		}
		o.health.reportOutcome(class, time.Since(o.start), "transport: "+msg, o.probe, o.gen)
	})
}

// finishStatus records an immediately-classifiable non-2xx response.
func (o *healthObserver) finishStatus(status int) {
	o.status = status
	o.once.Do(func() {
		class := ClassifyOutcome(status, o.path, nil, false, 0, true, false)
		o.health.reportOutcome(class, time.Since(o.start), fmt.Sprintf("status=%d", status), o.probe, o.gen)
	})
}

func (o *healthObserver) noteBytes(p []byte) {
	if o.streaming {
		o.scanSSE(p)
		return
	}
	if len(o.bodyBuf) < maxClassifyBody {
		o.bodyBuf = append(o.bodyBuf, p...)
		if len(o.bodyBuf) > maxClassifyBody {
			o.bodyBuf = o.bodyBuf[:maxClassifyBody]
			o.truncated = true
		}
	}
}

// scanSSE incrementally counts SSE data payloads (excluding [DONE]).
func (o *healthObserver) scanSSE(p []byte) {
	o.lineBuf = append(o.lineBuf, p...)
	if len(o.lineBuf) > 65536 {
		// Pathological line without newline: drop the buffer rather than grow.
		o.lineBuf = o.lineBuf[:0]
		return
	}
	for {
		i := bytes.IndexByte(o.lineBuf, '\n')
		if i < 0 {
			break
		}
		o.countSSELine(o.lineBuf[:i])
		o.lineBuf = o.lineBuf[i+1:]
	}
}

// countSSELine counts one raw SSE line as a data payload unless it is empty
// or the [DONE] terminator.
func (o *healthObserver) countSSELine(raw []byte) {
	line := bytes.TrimSpace(raw)
	if bytes.HasPrefix(line, []byte("data:")) {
		payload := bytes.TrimSpace(line[len("data:"):])
		if len(payload) > 0 && !bytes.Equal(payload, []byte("[DONE]")) {
			o.dataPayloads++
		}
	}
}

// flushSSELine counts a final data line that arrived without a trailing
// newline, so a cleanly-terminated stream is never misread as 200-empty.
func (o *healthObserver) flushSSELine() {
	if !o.streaming || len(o.lineBuf) == 0 {
		return
	}
	o.countSSELine(o.lineBuf)
	o.lineBuf = o.lineBuf[:0]
}

// finishAtEOF records a fully-read response body.
func (o *healthObserver) finishAtEOF() {
	o.once.Do(func() {
		o.flushSSELine()
		class := ClassifyOutcome(o.status, o.path, o.bodyBuf, o.streaming, o.dataPayloads, true, false)
		o.health.reportOutcome(class, time.Since(o.start),
			fmt.Sprintf("status=%d streamed=%v payloads=%d", o.status, o.streaming, o.dataPayloads),
			o.probe, o.gen)
	})
}

// finishAtClose records a body closed before EOF (early disconnect / error).
func (o *healthObserver) finishAtClose() {
	o.once.Do(func() {
		clientGone := o.ctx.Err() != nil
		class := ClassifyOutcome(o.status, o.path, o.bodyBuf, o.streaming, o.dataPayloads, false, clientGone)
		o.health.reportOutcome(class, time.Since(o.start), "body closed before EOF", o.probe, o.gen)
	})
}

// observingReadCloser wraps the upstream response body so the outcome is
// classified from the actual bytes observed — including the 200-empty honesty
// check — without buffering the stream.
type observingReadCloser struct {
	io.ReadCloser
	obs *healthObserver
}

func (w *observingReadCloser) Read(p []byte) (int, error) {
	n, err := w.ReadCloser.Read(p)
	if n > 0 {
		w.obs.noteBytes(p[:n])
	}
	if err == io.EOF {
		w.obs.finishAtEOF()
	}
	return n, err
}

func (w *observingReadCloser) Close() error {
	err := w.ReadCloser.Close()
	w.obs.finishAtClose()
	return err
}

func firstLine(s string, max int) string {
	if i := strings.IndexByte(s, '\n'); i >= 0 {
		s = s[:i]
	}
	s = strings.TrimSpace(s)
	if len(s) > max {
		s = s[:max] + "…"
	}
	return s
}

func expireCoolOff(h *PeerHealth) {
	if h == nil {
		return
	}
	h.mu.Lock()
	h.openedAt = time.Now().Add(-2 * h.coolOff())
	h.mu.Unlock()
}

package router

// Failing-first tests for the event-driven per-peer health state machine.
// They cover: taxonomy classification, weighted ejection, fail-fast while open,
// single-flight half-open probes, recovery/readmission, stale-outcome safety,
// EWMA scoring, degraded signals, concurrency, and end-to-end behavior through
// Peer.ServeHTTP against scripted backends.

import (
	"context"
	"errors"
	"net/http"
	"net/http/httptest"
	"net/url"
	"strings"
	"sync"
	"sync/atomic"
	"testing"
	"time"

	"github.com/toxicwind/bornite/internal/config"
	"github.com/toxicwind/bornite/internal/shared"
)

func testHealthConfig() config.HealthConfig {
	return config.HealthConfig{
		EWMAAlpha:         0.5,
		FailureThreshold:  4,
		RecoveryCredit:    1,
		SuccessThreshold:  1,
		CoolOffSeconds:    3600,
		DegradedLatencyMs: 1e9,
		DegradedErrorRate: 1.0,
		Weights: map[string]float64{
			"transport":        2.0,
			"5xx":              1.5,
			"404-dead-id":      3.0,
			"402-not-entitled": 2.0,
			"403-refused":      1.0,
			"429-throttled":    0.5,
			"200-empty":        1.5,
		},
	}
}

func TestClassifyOutcome(t *testing.T) {
	okBody := []byte(`{"choices":[{"message":{"content":"hello"}}]}`)
	emptyChoices := []byte(`{"choices":[]}`)
	cases := []struct {
		name         string
		status       int
		path         string
		body         []byte
		streamed     bool
		dataPayloads int
		completed    bool
		clientGone   bool
		want         OutcomeClass
	}{
		{"success", 200, "/v1/chat/completions", okBody, false, 0, true, false, OutcomeSuccess},
		{"empty body", 200, "/v1/chat/completions", []byte("  \n "), false, 0, true, false, OutcomeEmpty200},
		{"empty choices", 200, "/v1/chat/completions", emptyChoices, false, 0, true, false, OutcomeEmpty200},
		{"non-empty choices untouched", 200, "/v1/chat/completions", okBody, false, 0, true, false, OutcomeSuccess},
		{"stream with payloads", 200, "/v1/chat/completions", nil, true, 3, true, false, OutcomeSuccess},
		{"stream no payloads", 200, "/v1/chat/completions", nil, true, 0, true, false, OutcomeEmpty200},
		{"throttled", 429, "/v1/chat/completions", nil, false, 0, true, false, OutcomeThrottled},
		{"not entitled", 402, "/v1/chat/completions", nil, false, 0, true, false, OutcomeNotEntitled},
		{"dead id", 404, "/v1/chat/completions", nil, false, 0, true, false, OutcomeDeadID},
		{"refused", 403, "/v1/chat/completions", nil, false, 0, true, false, OutcomeRefused},
		{"other 4xx refused", 401, "/v1/chat/completions", nil, false, 0, true, false, OutcomeRefused},
		{"server error", 500, "/v1/chat/completions", nil, false, 0, true, false, OutcomeServerError},
		{"server error 503", 503, "/v1/chat/completions", nil, false, 0, true, false, OutcomeServerError},
		{"transport incomplete", 200, "/v1/chat/completions", okBody, false, 0, false, false, OutcomeTransport},
		{"transport no response", 0, "/v1/chat/completions", nil, false, 0, false, false, OutcomeTransport},
		{"client gone neutral", 200, "/v1/chat/completions", okBody, false, 0, false, true, OutcomeCancelled},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			got := ClassifyOutcome(tc.status, tc.path, tc.body, tc.streamed, tc.dataPayloads, tc.completed, tc.clientGone)
			if got != tc.want {
				t.Fatalf("ClassifyOutcome() = %q, want %q", got, tc.want)
			}
		})
	}
}

func TestCircuitOpensOnWeightedFailures(t *testing.T) {
	h := NewPeerHealth("p1", testHealthConfig(), testLogger)
	// transport weight 2.0, threshold 4 -> two transport failures trip the circuit.
	h.Report(OutcomeTransport, 10*time.Millisecond, "t1")
	if h.State() != HealthHealthy {
		t.Fatalf("state after 1 transport = %s, want healthy", h.State())
	}
	h.Report(OutcomeTransport, 10*time.Millisecond, "t2")
	if h.State() != HealthCircuitOpen {
		t.Fatalf("state after 2 transports = %s, want circuit-open", h.State())
	}
}

func TestTaxonomyWeightsAreDistinct(t *testing.T) {
	h := NewPeerHealth("p1", testHealthConfig(), testLogger)
	h.Report(OutcomeNotEntitled, time.Millisecond, "")
	h.Report(OutcomeDeadID, time.Millisecond, "")
	h.Report(OutcomeThrottled, time.Millisecond, "")
	// 2.0 + 3.0 + 0.5 = 5.5 >= 4 -> open, and the score must equal the
	// class-distinct weights, not a flat per-failure count.
	snap := h.Snapshot()
	if snap.FailureScore != 5.5 {
		t.Fatalf("failure score = %.1f, want 5.5 (distinct class weights)", snap.FailureScore)
	}
	if h.State() != HealthCircuitOpen {
		t.Fatalf("state = %s, want circuit-open", h.State())
	}
}

func TestOpenFailsFast(t *testing.T) {
