	obs.noteBytes([]byte("data: [DONE]\n\n"))
	obs.finishAtEOF()
	obs.finishAtEOF()
	obs.finishAtClose()
	if n := samples(h); n != 1 {
		t.Fatalf("samples = %d, want exactly 1", n)
	}
