func TestServer_HandleListModels_Status(t *testing.T) {
	local := newStubRouter(nil, "")
	local.setRunning(map[string]process.ProcessState{"loaded-model": process.StateReady})
	s := newTestServer(local, newStubRouter(nil, ""))
	s.cfg = config.Config{
