// The id enum is what stops a small model inventing document ids.
func TestServer_APIMCP_GetDocIDIsEnumConstrained(t *testing.T) {
	_, env := rpc(t, newMCPServer(), "tools/list", "", "")

	var result struct {
		Tools []struct {
