						Enum []string `json:"enum"`
					} `json:"id"`
				} `json:"properties"`
			} `json:"inputSchema"`
		} `json:"tools"`
	}
	if err := json.Unmarshal(env.Result, &result); err != nil {
		t.Fatalf("decode: %v", err)
	}

	for _, tool := range result.Tools {
		if tool.Name != "docs__get_doc" {
