func TestServer_AuthMiddleware(t *testing.T) {
	final := http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.WriteHeader(http.StatusOK)
	})

	t.Run("no keys configured passes through", func(t *testing.T) {
		mw := CreateAuthMiddleware(config.Config{})
		w := httptest.NewRecorder()
		mw(final).ServeHTTP(w, httptest.NewRequest(http.MethodGet, "/", nil))
		if w.Code != http.StatusOK {
			t.Errorf("status = %d, want 200", w.Code)
		}
	})

	cfg := config.Config{RequiredAPIKeys: []string{"secret"}}

	t.Run("valid key", func(t *testing.T) {
		mw := CreateAuthMiddleware(cfg)
		r := httptest.NewRequest(http.MethodGet, "/", nil)
		r.Header.Set("Authorization", "Bearer secret")
		w := httptest.NewRecorder()
		mw(final).ServeHTTP(w, r)
		if w.Code != http.StatusOK {
			t.Errorf("status = %d, want 200", w.Code)
		}
	})

	t.Run("invalid key", func(t *testing.T) {
		mw := CreateAuthMiddleware(cfg)
		r := httptest.NewRequest(http.MethodGet, "/", nil)
		r.Header.Set("Authorization", "Bearer wrong")
		w := httptest.NewRecorder()
		mw(final).ServeHTTP(w, r)
		if w.Code != http.StatusUnauthorized {
			t.Errorf("status = %d, want 401", w.Code)
		}
		if w.Header().Get("WWW-Authenticate") == "" {
			t.Error("missing WWW-Authenticate header")
		}
	})
}

package agele

import (
	"context"
	"net/url"
	"reflect"
	"github.com/toxicwind/bornite/internal/capcompat"
	"github.com/toxicwind/bornite/internal/config"
	"github.com/toxicwind/bornite/internal/event"
	"github.com/toxicwind/bornite/internal/process"
	"github.com/toxicwind/bornite/internal/swaputil"
)

// onProcessStateChange refreshes a model's discovered capabilities when its
// process becomes ready, which is the only moment the upstream can be asked.
//
// This runs on the event dispatcher's consumer goroutine, and a consumer that
// falls behind eventually blocks the publisher, which here is the process
// state machine itself. So it must not do any work inline: the probe goes to
// its own goroutine and this returns immediately.
func (s *Server) onProcessStateChange(e swaputil.ProcessStateChangeEvent) {
	if e.NewState != string(process.StateReady) {
		return
	}
	mc, ok := s.cfg.Models[e.ProcessName]
	if !ok || mc.Capabilities.DisableAuto {
		return
	}
	go s.refreshCapabilities(e.ProcessName, mc)
}

// refreshCapabilities probes one ready model and caches what it reports.
//
// The probe dials the model's own proxy address rather than going through the
// local router. Routing a synthetic request through the router would reset the
// model's TTL idle window and occupy a concurrency slot, and could start a
// model that had already stopped again by the time this ran.
func (s *Server) refreshCapabilities(modelID string, mc config.ModelConfig) {
	base, err := url.Parse(mc.Proxy)
	if err != nil {
		s.proxylog.Debugf("capcompat: <%s> unusable proxy URL %q: %v", modelID, mc.Proxy, err)
		return
	}

	client := capcompat.NewClient(base, mc.Timeouts)
	key := capcompat.LocalKey(modelID, mc)
	name := capcompat.UpstreamModelName(modelID, mc)

	// What the model advertised before the probe, so a refresh that learns
	// nothing new does not push a redundant model list to every UI client.
	before := s.resolveCapabilities(s.shutdownCtx, modelID, mc)

	if err := s.capcompat.Refresh(s.shutdownCtx, key, client, name); err != nil {
		// Debug, not warn. llama-swap also fronts image, speech and
		// transcription servers with no capability surface, and a model that
		// stopped again mid-probe is normal. Neither is worth a warning on
		// every model start.
		s.proxylog.Debugf("capcompat: <%s> discovery failed: %v", modelID, err)
		return
	}

	// The listing pushed when this model went ready was built before the
	// probe finished, so anything new has to announce itself.
	if after := s.resolveCapabilities(s.shutdownCtx, modelID, mc); !reflect.DeepEqual(before, after) {
		event.Emit(swaputil.ModelCapabilitiesChangedEvent{ModelID: modelID})
	}
}

// resolveCapabilitiesWithSources returns the merged capabilities plus
// per-badge provenance ("configured" vs "discovered"). The provenance is
// derived from the same config-vs-discovery inputs Merge uses, so it never
// needs a schema migration or a stored tag: the config is the source of
// truth for what was hand-set.
func (s *Server) resolveCapabilitiesWithSources(ctx context.Context, modelID string, mc config.ModelConfig) (config.ModelCapConfig, map[string]string) {
	merged := s.resolveCapabilities(ctx, modelID, mc)
	cfg := mc.Capabilities
	var auto config.ModelCapConfig
	if !cfg.DisableAuto {
		auto, _ = s.capcompat.Lookup(ctx, capcompat.LocalKey(modelID, mc))
	}
	return merged, capabilityProvenance(cfg, auto)
}

// resolveCapabilities returns the capabilities to advertise for a local model:
// what the config sets, with anything it leaves unset filled in from the last
// successful probe.
//
// Configured values win field by field, so a model that hand-sets one field
// still benefits from discovery for the rest. A model with
// capabilities.disableAuto gets exactly what its config says.
func (s *Server) resolveCapabilities(ctx context.Context, modelID string, mc config.ModelConfig) config.ModelCapConfig {
	caps := mc.Capabilities
	if caps.DisableAuto {
		return caps
	}
	auto, found := s.capcompat.Lookup(ctx, capcompat.LocalKey(modelID, mc))
	if !found {
		return caps
	}
	return caps.Merge(auto)
}

package agele

import (
	"testing"
	"github.com/toxicwind/bornite/internal/config"
)

// The provenance map must agree with renderCapabilities: every badge key it
// emits gets a source, and the source reflects config-vs-discovery origin.
func TestCapabilityProvenance(t *testing.T) {
	tests := []struct {
		name     string
		cfg      config.ModelCapConfig
		auto     config.ModelCapConfig
		wantKeys map[string]string
	}{
		{
			name: "all discovered",
			cfg:  config.ModelCapConfig{},
			auto: config.ModelCapConfig{In: []string{"text", "image"}, Out: []string{"text"}, Tools: true, Context: 128000},
			wantKeys: map[string]string{
				"vision": "discovered", "function_calling": "discovered", "context": "discovered",
			},
		},
		{
			name: "all configured",
			cfg:  config.ModelCapConfig{In: []string{"text", "image"}, Out: []string{"text"}, Tools: true, Context: 64000},
			auto: config.ModelCapConfig{},
			wantKeys: map[string]string{
				"vision": "configured", "function_calling": "configured", "context": "configured",
			},
		},
		{
			name: "mixed: config wins field by field",
			cfg:  config.ModelCapConfig{Tools: true},
			auto: config.ModelCapConfig{In: []string{"text", "image"}, Out: []string{"text"}, Context: 32000},
			wantKeys: map[string]string{
				"vision": "discovered", "function_calling": "configured", "context": "discovered",
			},
		},
		{
			name: "mixed modalities need both sides configured",
			cfg:  config.ModelCapConfig{In: []string{"text"}},
			auto: config.ModelCapConfig{Out: []string{"image"}},
			wantKeys: map[string]string{
				"image_generation": "discovered",
			},
		},
		{
			name:     "empty stays empty",
			cfg:      config.ModelCapConfig{},
			auto:     config.ModelCapConfig{},
			wantKeys: map[string]string{},
		},
		{
			name: "reranker and image_to_image",
			cfg:  config.ModelCapConfig{},
			auto: config.ModelCapConfig{In: []string{"image"}, Out: []string{"image"}, Reranker: true},
			wantKeys: map[string]string{
				"vision": "discovered", "image_to_image": "discovered", "reranker": "discovered",
			},
		},
		{
			name: "audio both directions",
			cfg:  config.ModelCapConfig{In: []string{"audio"}, Out: []string{"text"}},
			auto: config.ModelCapConfig{},
			wantKeys: map[string]string{
				"audio_transcriptions": "configured",
			},
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			got := capabilityProvenance(tt.cfg, tt.auto)
			if len(got) != len(tt.wantKeys) {
				t.Fatalf("provenance keys = %v, want %v", got, tt.wantKeys)
			}
			for k, want := range tt.wantKeys {
				if got[k] != want {
					t.Errorf("provenance[%q] = %q, want %q", k, got[k], want)
				}
			}
			// Cross-check: every badge renderCapabilities draws must have a source.
			merged := tt.cfg.Merge(tt.auto)
			_, capsMap, _, _ := renderCapabilities(merged)
			for k := range capsMap {
				if _, ok := got[k]; !ok {
					t.Errorf("badge %q rendered but has no provenance", k)
				}
			}
		})
	}
}

