func TestServer_APIMCP_ToolsList(t *testing.T) {
	w, env := rpc(t, newMCPServer(), "tools/list", "", "")

	if w.Code != http.StatusOK || env.Error != nil {
		t.Fatalf("status = %d, error = %+v", w.Code, env.Error)
	}

