package server

import (
	"net/http"

	"github.com/toxicwind/bornite/internal/chain"
	"github.com/toxicwind/bornite/internal/swaputil"
	"golang.org/x/sync/semaphore"
)

// CreateConcurrencyLimitMiddleware returns middleware that caps the number of
// inference requests served at once across all models, using a weighted
// semaphore. A request that cannot acquire a slot is rejected immediately
// with a 429 rather than queued (see issue #1086). Callers must not add this
// middleware when limit <= 0; there is no "no limit" mode here.
func CreateConcurrencyLimitMiddleware(limit int) chain.Middleware {
	sem := semaphore.NewWeighted(int64(limit))
	return func(next http.Handler) http.Handler {
		return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
			if !sem.TryAcquire(1) {
				swaputil.SendError(w, r, swaputil.ConcurrencyLimitError{})
				return
			}
			defer sem.Release(1)
			next.ServeHTTP(w, r)
		})
	}
}

package server

import (
	"net/http"
	"strconv"
	"strings"

	"github.com/toxicwind/bornite/internal/chain"
	"github.com/toxicwind/bornite/internal/config"
)

// corsPolicy is the resolved, immutable CORS configuration. Building it once
// at startup keeps the per-request path to map lookups and header writes.
type corsPolicy struct {
	// allowAnyOrigin is set when allowedOrigins contains "*". The literal "*"
	// is then sent back, which is what browsers expect for a public API.
	allowAnyOrigin bool

	// allowedOrigins is a membership set of the allowed origins, lowercased
	// so a config entry and a browser's Origin match whatever their case.
	// Only membership is read: the response echoes the request's own
	// spelling, never this one. Unused when allowAnyOrigin is set.
	allowedOrigins map[string]struct{}

	allowCredentials bool

	// allowPrivateNetwork answers Chrome's Private Network Access preflight.
	// Forced off whenever allowAnyOrigin is set; see newCORSPolicy.
	allowPrivateNetwork bool

	allowedMethods string   // pre-joined header value
	allowedHeaders []string // empty means echo the request's
	exposedHeaders string   // pre-joined, empty means omit the header
	maxAge         string   // pre-formatted seconds
}

// newCORSPolicy resolves cfg into a corsPolicy.
//
// An empty AllowedOrigins selects the permissive policy bornite had before
// security.cors existed: any origin allowed. Config validation rejects a
// config that sets any other CORS field without naming its origins, so
// reaching this with an empty list means nothing was configured at all, never
// a half-written block. The preflight mechanics take their defaults in either
// mode, so a config naming only origins keeps working for a browser.
func newCORSPolicy(cfg config.CORSConfig) corsPolicy {
	origins := cfg.AllowedOrigins
	if len(origins) == 0 {
		origins = config.DefaultCORSAllowedOrigins()
	}
	p := corsPolicy{
		allowedOrigins:   make(map[string]struct{}, len(origins)),
		allowCredentials: cfg.AllowCredentials,
		allowedHeaders:   cfg.AllowedHeaders,
	}
	for _, origin := range origins {
		if origin == config.CORSWildcardOrigin {
			p.allowAnyOrigin = true
			continue
		}
		p.allowedOrigins[strings.ToLower(origin)] = struct{}{}
	}

	methods := cfg.AllowedMethods
	if len(methods) == 0 {
		methods = config.DefaultCORSAllowedMethods()
	}
	p.allowedMethods = strings.Join(methods, ", ")

	p.exposedHeaders = strings.Join(cfg.ExposedHeaders, ", ")

	maxAge := cfg.MaxAge
	if maxAge == 0 {
		maxAge = config.DefaultCORSMaxAge
	}
	p.maxAge = strconv.Itoa(maxAge)

	// bornite has never sent Access-Control-Allow-Private-Network, so the
	// permissive legacy policy must not start. Config validation already
	// rejects the setting without explicit origins, but gate it here too so a
	// policy built directly in Go cannot pair wildcard origins with
	// private-network access. Keying off allowAnyOrigin covers both the legacy
	// fallback and an explicit "*".
	p.allowPrivateNetwork = cfg.AllowPrivateNetwork && !p.allowAnyOrigin

	return p
}

// resolveOrigin returns the value for Access-Control-Allow-Origin and whether
// the request is one bornite answers with CORS headers at all.
//
// A request without an Origin is never one: only browsers send it, and adding
// the headers for everyone else is what reintroduced issue #85 — llama-server
// sets its own Access-Control-Allow-Origin, so the client received two values
// and strict clients (litellm/h11) rejected the folded "*, ".
func (p corsPolicy) resolveOrigin(origin string) (string, bool) {
	if origin == "" {
		return "", false
	}
	if p.allowAnyOrigin {
		// Credentials cannot be combined with "*"; config validation rejects
		// that pairing, so the wildcard is always safe to send here.
		return config.CORSWildcardOrigin, true
	}
	// Echo what the request sent, not how the config spelled it. A browser
	// compares Access-Control-Allow-Origin against its own origin, which it
	// serializes with the host lowercased, so answering a config entry's
	// mixed-case spelling would fail that check on an allowed origin.
	if _, ok := p.allowedOrigins[strings.ToLower(origin)]; ok {
		return origin, true
	}
	return "", false
}

// addVary appends token to the Vary header, keeping it to a single line so
// clients and caches never have to fold repeated values themselves.
func addVary(h http.Header, token string) {
	if existing := h.Get("Vary"); existing != "" {
		h.Set("Vary", existing+", "+token)
		return
	}
	h.Set("Vary", token)
}

// writeSharedHeaders writes the headers that belong on both preflight and
// actual responses.
func (p corsPolicy) writeSharedHeaders(h http.Header, allowOrigin string) {
	h.Set("Access-Control-Allow-Origin", allowOrigin)
	// Even the wildcard response varies by Origin now, because a request
	// without one gets no CORS headers at all.
	addVary(h, "Origin")
	if p.allowCredentials {
		h.Set("Access-Control-Allow-Credentials", "true")
	}
	if p.exposedHeaders != "" {
		h.Set("Access-Control-Expose-Headers", p.exposedHeaders)
	}
}

// writePreflightHeaders adds the headers that only belong on a preflight
// response.
func (p corsPolicy) writePreflightHeaders(h http.Header, r *http.Request) {
	h.Set("Access-Control-Allow-Methods", p.allowedMethods)

	switch {
	case len(p.allowedHeaders) > 0:
		h.Set("Access-Control-Allow-Headers", strings.Join(p.allowedHeaders, ", "))
	default:
		requested := r.Header.Get("Access-Control-Request-Headers")
		if sanitized := sanitizeAccessControlRequestHeaderValues(requested); sanitized != "" {
			h.Set("Access-Control-Allow-Headers", sanitized)
			addVary(h, "Access-Control-Request-Headers")
		} else {
			h.Set("Access-Control-Allow-Headers", strings.Join(config.DefaultCORSAllowedHeaders(), ", "))
		}
	}

	h.Set("Access-Control-Max-Age", p.maxAge)

	// Chrome's Private Network Access handshake. Answer only the preflight
	// that asked, so the header never appears on an ordinary one.
	if p.allowPrivateNetwork && r.Header.Get("Access-Control-Request-Private-Network") == "true" {
		h.Set("Access-Control-Allow-Private-Network", "true")
		addVary(h, "Access-Control-Request-Private-Network")
	}
}

// CreateCORSMiddleware returns middleware that answers OPTIONS preflight
// requests (see issues #81, #77, #42) and adds CORS headers to the actual
// response so browser dashboards can read it (see #1121).
//
// Headers are only written when the request carries an Origin. Clients that
// send none — curl, litellm and most SDKs — get a response with no
// Access-Control-* header at all. That, together with
// swaputil.StripUpstreamCORSHeaders in the proxies, keeps bornite the only
// source of these headers and prevents the duplicate-header fold of issue #85.
//
// It must stay the outermost middleware after request logging so a preflight
// short-circuits before auth: browsers never attach credentials to a preflight.
func CreateCORSMiddleware(cfg config.Config) chain.Middleware {
	var corsCfg config.CORSConfig
	if cfg.Security != nil {
		corsCfg = cfg.Security.CORS
	}
	policy := newCORSPolicy(corsCfg)

	return func(next http.Handler) http.Handler {
		return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
			allowOrigin, allowed := policy.resolveOrigin(r.Header.Get("Origin"))

			if r.Method != http.MethodOptions {
				if allowed {
					policy.writeSharedHeaders(w.Header(), allowOrigin)
				}
				next.ServeHTTP(w, r)
				return
			}

			// Every OPTIONS is answered here rather than falling through to
			// the mux, which registers no OPTIONS routes. A disallowed or
			// absent origin still gets 204, just without the headers the
			// browser needs to proceed.
			if allowed {
				policy.writeSharedHeaders(w.Header(), allowOrigin)
				policy.writePreflightHeaders(w.Header(), r)
			}
			w.WriteHeader(http.StatusNoContent)
		})
	}
}

// sanitizeAccessControlRequestHeaderValues drops any header names that contain
// characters outside the HTTP token grammar before echoing them back.
func sanitizeAccessControlRequestHeaderValues(headerValues string) string {
	parts := strings.Split(headerValues, ",")
	valid := make([]string, 0, len(parts))

	for _, p := range parts {
		if v := strings.TrimSpace(p); config.IsHTTPToken(v) {
			valid = append(valid, v)
		}
	}

	return strings.Join(valid, ", ")
}

package server

import (
	"io"
	"net/http"
	"net/http/httptest"
	"net/http/httputil"
	"net/url"
	"strings"
	"testing"

	"github.com/toxicwind/bornite/internal/config"
	"github.com/toxicwind/bornite/internal/swaputil"
)

// newLlamaServerStub returns an upstream that behaves like llama-server: it
// sets Access-Control-Allow-Origin to whatever Origin the client sent, so the
// header is present-but-empty when the client sent none. That empty value is
// the trailing half of the invalid "*, " from issue #85.
func newLlamaServerStub(t *testing.T) *httptest.Server {
	t.Helper()
	upstream := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Access-Control-Allow-Origin", r.Header.Get("Origin"))
		w.Header().Set("Content-Type", "application/json")
		w.WriteHeader(http.StatusOK)
		_, _ = w.Write([]byte(`{"choices":[]}`))
	}))
	t.Cleanup(upstream.Close)
	return upstream
}

// newProxyingTestServer builds a Server whose local router is a real
// httputil.ReverseProxy pointed at upstreamURL, so the test exercises the
// actual header-merging behaviour rather than a stand-in. strip mirrors what
// the model and peer proxies do in production.
func newProxyingTestServer(t *testing.T, upstreamURL string, strip bool) *httptest.Server {
	t.Helper()

	target, err := url.Parse(upstreamURL)
	if err != nil {
		t.Fatalf("parsing upstream URL: %v", err)
	}
	proxy := httputil.NewSingleHostReverseProxy(target)
	if strip {
		proxy.ModifyResponse = func(resp *http.Response) error {
			swaputil.StripUpstreamCORSHeaders(resp.Header)
			return nil
		}
	}

	local := newStubRouter([]string{"m1"}, "")
	local.serveHTTP = proxy.ServeHTTP

	s := newTestServerWithConfig(config.Config{}, local, newStubRouter(nil, ""))
	front := httptest.NewServer(s)
	t.Cleanup(front.Close)
	return front
}

// postChat issues a real HTTP request so repeated header lines are parsed the
// way a client library would see them, which httptest.NewRecorder cannot show.
func postChat(t *testing.T, baseURL, origin string) *http.Response {
	t.Helper()

	req, err := http.NewRequest(http.MethodPost, baseURL+"/v1/chat/completions",
		strings.NewReader(`{"model":"m1","messages":[{"role":"user","content":"hi"}]}`))
	if err != nil {
		t.Fatalf("building request: %v", err)
	}
	req.Header.Set("Content-Type", "application/json")
	if origin != "" {
		req.Header.Set("Origin", origin)
	}

	resp, err := http.DefaultClient.Do(req)
	if err != nil {
		t.Fatalf("request failed: %v", err)
	}
	t.Cleanup(func() {
		_, _ = io.Copy(io.Discard, resp.Body)
		resp.Body.Close()
	})
	return resp
}

// TestServer_CORSProxiedResponseIsSingleValued is the end-to-end regression
// test for issue #85. A proxied response must never carry more than one
// Access-Control-Allow-Origin, because clients that fold repeated headers see
// "*, " — an illegal field value that h11 rejects, killing the litellm
// request with no response at all.
func TestServer_CORSProxiedResponseIsSingleValued(t *testing.T) {
	upstream := newLlamaServerStub(t)
	front := newProxyingTestServer(t, upstream.URL, true)

	cases := []struct {
		name   string
		origin string
		want   string // expected single value, "" means the header must be absent
	}{
		{"no Origin, as curl and litellm send", "", ""},
		{"browser Origin", "http://example.com", "*"},
	}

	for _, c := range cases {
		t.Run(c.name, func(t *testing.T) {
			resp := postChat(t, front.URL, c.origin)

			if resp.StatusCode != http.StatusOK {
				t.Fatalf("status=%d want 200", resp.StatusCode)
			}

			values := resp.Header.Values("Access-Control-Allow-Origin")
			if len(values) > 1 {
				t.Fatalf("Access-Control-Allow-Origin has %d values %q; a folding client sees %q",
					len(values), values, strings.Join(values, ", "))
			}

			if c.want == "" {
				if len(values) != 0 {
					t.Fatalf("Access-Control-Allow-Origin=%q want it absent when no Origin was sent", values)
				}
				return
			}
			if len(values) != 1 || values[0] != c.want {
				t.Fatalf("Access-Control-Allow-Origin=%q want exactly [%q]", values, c.want)
			}
		})
	}
}

// TestServer_CORSProxiedResponseHasNoEmptyHeaders guards the subtler half of
// #85: an upstream header that is present but empty. Folded with bornite's
// own it produces a value with trailing whitespace, which RFC 9110 forbids.
func TestServer_CORSProxiedResponseHasNoEmptyHeaders(t *testing.T) {
	upstream := newLlamaServerStub(t)
	front := newProxyingTestServer(t, upstream.URL, true)

	for _, origin := range []string{"", "http://example.com"} {
		resp := postChat(t, front.URL, origin)
		for name, values := range resp.Header {
			if !strings.HasPrefix(http.CanonicalHeaderKey(name), "Access-Control-") {
				continue
			}
			for _, v := range values {
				if strings.TrimSpace(v) == "" {
					t.Errorf("Origin=%q: %s is present but empty", origin, name)
				}
				if v != strings.TrimSpace(v) {
					t.Errorf("Origin=%q: %s=%q has leading or trailing whitespace", origin, name, v)
				}
			}
		}
	}
}

// TestServer_CORSReverseProxyWouldDuplicateWithoutStrip documents why
// swaputil.StripUpstreamCORSHeaders is load-bearing rather than defensive.
// httputil.ReverseProxy merges upstream headers with Header.Add, so without the
// strip a cross-origin response carries both bornite's value and the
// upstream's. If this test ever stops reproducing the duplicate, Go's proxy
// semantics changed and the strip's justification should be revisited.
func TestServer_CORSReverseProxyWouldDuplicateWithoutStrip(t *testing.T) {
	upstream := newLlamaServerStub(t)
	front := newProxyingTestServer(t, upstream.URL, false)

	resp := postChat(t, front.URL, "http://example.com")

	values := resp.Header.Values("Access-Control-Allow-Origin")
	if len(values) != 2 {
		t.Fatalf("Access-Control-Allow-Origin=%q; expected the un-stripped proxy to send 2 values", values)
	}
	if folded := strings.Join(values, ", "); folded != "*, http://example.com" {
		t.Errorf("folded value = %q want %q", folded, "*, http://example.com")
	}
}

package server

import (
	"fmt"
