	"github.com/stretchr/testify/require"
)

// newCacheStore returns an in-memory store with its cache repository.
//
// Ported from upstream internal/store/sqlite/cache_test.go: the fork defines
// the store.CacheRepository interface but had no implementation until the cache
// table migration and cacheRepository landed here.
func newCacheStore(t *testing.T) (*Store, store.CacheRepository) {
	t.Helper()
	st, err := New("")
	require.NoError(t, err)
	t.Cleanup(func() { st.Close() })
	return st, st.Cache()
}

func TestStore_CacheSetGet(t *testing.T) {
	ctx := context.Background()
	_, cache := newCacheStore(t)

	// Truncated to the second because the column stores Unix seconds.
	written := time.Now().Truncate(time.Second)
	require.NoError(t, cache.Set(ctx, store.CacheEntry{
		Key:       "capcompat:v1:local:model-a",
		Data:      []byte(`{"context":4096}`),
		TTL:       time.Hour,
		Timestamp: written,
	}))

	got, found, err := cache.Get(ctx, "capcompat:v1:local:model-a")
	require.NoError(t, err)
	require.True(t, found)
	assert.Equal(t, "capcompat:v1:local:model-a", got.Key)
	assert.Equal(t, []byte(`{"context":4096}`), got.Data)
	assert.Equal(t, time.Hour, got.TTL)
	assert.Equal(t, written.Unix(), got.Timestamp.Unix())
}

func TestStore_CacheGetMissingKey(t *testing.T) {
	ctx := context.Background()
	_, cache := newCacheStore(t)

	_, found, err := cache.Get(ctx, "nope")
	require.NoError(t, err)
	assert.False(t, found)
}

func TestStore_CacheSetDefaultsTimestampToNow(t *testing.T) {
	ctx := context.Background()
	_, cache := newCacheStore(t)

	before := time.Now().Add(-time.Second)
	require.NoError(t, cache.Set(ctx, store.CacheEntry{Key: "k", Data: []byte("v")}))

	got, found, err := cache.Get(ctx, "k")
	require.NoError(t, err)
	require.True(t, found)
	assert.False(t, got.Timestamp.Before(before), "timestamp should default to now")
}

func TestStore_CacheOverwrite(t *testing.T) {
	ctx := context.Background()
	st, cache := newCacheStore(t)

	first := time.Now().Truncate(time.Second).Add(-time.Minute)
	second := first.Add(30 * time.Second)
	require.NoError(t, cache.Set(ctx, store.CacheEntry{
		Key: "k", Data: []byte("first"), TTL: time.Hour, Timestamp: first,
	}))
	require.NoError(t, cache.Set(ctx, store.CacheEntry{
		Key: "k", Data: []byte("second"), TTL: 2 * time.Hour, Timestamp: second,
	}))

	got, found, err := cache.Get(ctx, "k")
	require.NoError(t, err)
	require.True(t, found)
	assert.Equal(t, []byte("second"), got.Data)
	assert.Equal(t, 2*time.Hour, got.TTL)
	assert.Equal(t, second.Unix(), got.Timestamp.Unix())

	var rows int
	require.NoError(t, st.db.QueryRow(`SELECT COUNT(*) FROM cache`).Scan(&rows))
	assert.Equal(t, 1, rows, "overwrite must not create a second row")
}

func TestStore_CacheExpiredEntryIsGone(t *testing.T) {
	ctx := context.Background()
	st, cache := newCacheStore(t)

	// Written two hours ago with a one hour TTL. No sleeping involved.
	require.NoError(t, cache.Set(ctx, store.CacheEntry{
		Key:       "stale",
		Data:      []byte("old"),
		TTL:       time.Hour,
		Timestamp: time.Now().Add(-2 * time.Hour),
	}))

	_, found, err := cache.Get(ctx, "stale")
	require.NoError(t, err)
	assert.False(t, found)

	// The read deletes the row rather than leaving it for Prune.
	var rows int
	require.NoError(t, st.db.QueryRow(`SELECT COUNT(*) FROM cache`).Scan(&rows))
	assert.Equal(t, 0, rows)
}

func TestStore_CacheZeroTTLNeverExpires(t *testing.T) {
	ctx := context.Background()
	_, cache := newCacheStore(t)

	require.NoError(t, cache.Set(ctx, store.CacheEntry{
		Key:       "forever",
		Data:      []byte("v"),
		Timestamp: time.Now().Add(-10000 * time.Hour),
	}))

	got, found, err := cache.Get(ctx, "forever")
	require.NoError(t, err)
	require.True(t, found)
	assert.Equal(t, []byte("v"), got.Data)
}

func TestStore_CacheSubSecondTTLExpires(t *testing.T) {
	ctx := context.Background()
	_, cache := newCacheStore(t)

	t.Run("does not become permanent", func(t *testing.T) {
		// A TTL under a second must not round down to 0, which is the
		// sentinel for "never expires".
		require.NoError(t, cache.Set(ctx, store.CacheEntry{
			Key:       "brief",
			Data:      []byte("v"),
			TTL:       time.Millisecond,
			Timestamp: time.Now().Add(-time.Hour),
		}))

		_, found, err := cache.Get(ctx, "brief")
		require.NoError(t, err)
		assert.False(t, found)
	})

	t.Run("rounds up to one second", func(t *testing.T) {
		require.NoError(t, cache.Set(ctx, store.CacheEntry{
			Key:  "half",
			Data: []byte("v"),
			TTL:  500 * time.Millisecond,
		}))

		got, found, err := cache.Get(ctx, "half")
		require.NoError(t, err)
		require.True(t, found, "it should still be readable within the rounded up window")
		assert.Equal(t, time.Second, got.TTL)
	})
}

func TestStore_CacheExpiryDeleteSparesReplacementRow(t *testing.T) {
	// Get reads a row, decides it is expired, then deletes it in a second
	// statement. A Set landing between those two must not be discarded, so
	// the delete repeats the expiry test instead of matching the key alone.
	// The hook produces that interleaving; scheduling almost never does.
	ctx := context.Background()
	_, cache := newCacheStore(t)

	require.NoError(t, cache.Set(ctx, store.CacheEntry{
		Key:       "k",
		Data:      []byte("stale"),
		TTL:       time.Second,
		Timestamp: time.Now().Add(-time.Hour),
	}))

	var replaced bool
	beforeExpiryDelete = func() {
		if replaced {
			return
		}
		replaced = true
		require.NoError(t, cache.Set(ctx, store.CacheEntry{
			Key: "k", Data: []byte("fresh"), TTL: time.Hour,
		}))
	}
	t.Cleanup(func() { beforeExpiryDelete = nil })

	// This Get still reports the stale row it read, which is correct: it saw
	// the state before the write.
	_, found, err := cache.Get(ctx, "k")
	require.NoError(t, err)
	assert.False(t, found)
	require.True(t, replaced, "the hook should have fired on the expired row")

	// The row written in the gap must have survived the cleanup.
	got, found, err := cache.Get(ctx, "k")
	require.NoError(t, err)
	require.True(t, found, "expiry cleanup deleted a row written after the read")
	assert.Equal(t, []byte("fresh"), got.Data)
}

func TestStore_CacheDeleteMissingIsNotAnError(t *testing.T) {
	ctx := context.Background()
	_, cache := newCacheStore(t)

	require.NoError(t, cache.Delete(ctx, "never-existed"))

	require.NoError(t, cache.Set(ctx, store.CacheEntry{Key: "k", Data: []byte("v")}))
	require.NoError(t, cache.Delete(ctx, "k"))
	_, found, err := cache.Get(ctx, "k")
	require.NoError(t, err)
	assert.False(t, found)
}

func TestStore_CachePrune(t *testing.T) {
	ctx := context.Background()
	st, cache := newCacheStore(t)

	now := time.Now()
	require.NoError(t, cache.Set(ctx, store.CacheEntry{
		Key: "expired", Data: []byte("a"), TTL: time.Minute, Timestamp: now.Add(-time.Hour),
	}))
	require.NoError(t, cache.Set(ctx, store.CacheEntry{
		Key: "live", Data: []byte("b"), TTL: time.Hour, Timestamp: now,
	}))
	require.NoError(t, cache.Set(ctx, store.CacheEntry{
		Key: "no-ttl", Data: []byte("c"), Timestamp: now.Add(-10000 * time.Hour),
	}))

	require.NoError(t, cache.Prune(ctx))

	var keys []string
	rows, err := st.db.Query(`SELECT key FROM cache ORDER BY key`)
	require.NoError(t, err)
	defer rows.Close()
	for rows.Next() {
		var k string
		require.NoError(t, rows.Scan(&k))
		keys = append(keys, k)
	}
	require.NoError(t, rows.Err())
	assert.Equal(t, []string{"live", "no-ttl"}, keys)
}

func TestStore_CachePersistsAcrossReopen(t *testing.T) {
	ctx := context.Background()
	path := filepath.Join(t.TempDir(), "cache.db")

	first, err := New(path)
	require.NoError(t, err)
	require.NoError(t, first.Cache().Set(ctx, store.CacheEntry{
		Key: "k", Data: []byte("persisted"), TTL: time.Hour,
	}))
	require.NoError(t, first.Close())

	second, err := New(path)
	require.NoError(t, err)
	defer second.Close()

	got, found, err := second.Cache().Get(ctx, "k")
	require.NoError(t, err)
	require.True(t, found)
	assert.Equal(t, []byte("persisted"), got.Data)
}

func TestStore_CachePrunesExpiredRowsOnOpen(t *testing.T) {
	ctx := context.Background()
	path := filepath.Join(t.TempDir(), "cache.db")

	first, err := New(path)
	require.NoError(t, err)
	require.NoError(t, first.Cache().Set(ctx, store.CacheEntry{
		Key:       "stale",
		Data:      []byte("old"),
		TTL:       time.Minute,
		Timestamp: time.Now().Add(-time.Hour),
	}))
	require.NoError(t, first.Close())

	second, err := New(path)
	require.NoError(t, err)
	defer second.Close()

	var rows int
	require.NoError(t, second.db.QueryRow(`SELECT COUNT(*) FROM cache`).Scan(&rows))
	assert.Equal(t, 0, rows, "opening the store should prune expired rows")
}

func TestStore_CacheEntryExpired(t *testing.T) {
	base := time.Unix(1750000000, 0)

	tests := []struct {
		name  string
		entry store.CacheEntry
		at    time.Time
		want  bool
	}{
		{"zero ttl never expires", store.CacheEntry{Timestamp: base}, base.Add(1000 * time.Hour), false},
		{"negative ttl never expires", store.CacheEntry{Timestamp: base, TTL: -time.Hour}, base.Add(time.Hour), false},
		{"zero timestamp never expires", store.CacheEntry{TTL: time.Hour}, base, false},
		{"inside ttl", store.CacheEntry{Timestamp: base, TTL: time.Hour}, base.Add(30 * time.Minute), false},
		{"exactly at ttl", store.CacheEntry{Timestamp: base, TTL: time.Hour}, base.Add(time.Hour), false},
		{"past ttl", store.CacheEntry{Timestamp: base, TTL: time.Hour}, base.Add(time.Hour + time.Second), true},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			assert.Equal(t, tt.want, tt.entry.Expired(tt.at))
		})
	}
}

package agele

import (
	_ "modernc.org/sqlite"
	"github.com/toxicwind/bornite/internal/store"
	"context"
	"database/sql"
	"embed"
	"encoding/json"
	"fmt"
	"io/fs"
	"math"
	"sort"
	"strings"
	"time"
	"github.com/pressly/goose/v3"
)

//go:embed migrations/*.sql
var migrationFS embed.FS

// TokenMetrics holds token usage and performance metrics.
type TokenMetrics struct {
	CachedTokens    int     `json:"cache_tokens"`
	DraftTokens     int     `json:"draft_tokens"`
	DraftAccTokens  int     `json:"draft_acc_tokens"`
	InputTokens     int     `json:"input_tokens"`
	OutputTokens    int     `json:"output_tokens"`
	PromptPerSecond float64 `json:"prompt_per_second"`
	TokensPerSecond float64 `json:"tokens_per_second"`
}

// ActivityLogEntry represents parsed token statistics from llama-server logs.
type ActivityLogEntry struct {
	ID              int               `json:"id"`
	Timestamp       time.Time         `json:"timestamp"`
	Model           string            `json:"model"`
	ReqPath         string            `json:"req_path"`
	RespContentType string            `json:"resp_content_type"`
	RespStatusCode  int               `json:"resp_status_code"`
	Tokens          TokenMetrics      `json:"tokens"`
	DurationMs      int               `json:"duration_ms"`
	HasCapture      bool              `json:"has_capture"`
	ErrorMsg        string            `json:"error_msg,omitempty"`
	Metadata        map[string]string `json:"metadata,omitempty"`
}

// ActivityFilter narrows which activity rows a query matches. The zero value
// matches every row, and each field is independent: set fields are ANDed.
type ActivityFilter struct {
	Models []string  // model_id IN (...); empty matches all models
	Start  time.Time // inclusive lower bound on ts_created; zero is unbounded
	End    time.Time // inclusive upper bound on ts_created; zero is unbounded
	MinID  int       // inclusive lower bound on id; 0 is unbounded
	MaxID  int       // inclusive upper bound on id; 0 is unbounded
}

type ActivityQuery struct {
	ActivityFilter
	Limit int
	Page  int
	Sort  string // sortable column key, empty defaults to "id"
	Order string // "asc" or "desc", empty defaults to "desc"
}

// activitySortColumns whitelists the sortable API keys and maps them to their
// underlying SQL columns. Keys mirror the UI column ids. The whitelist keeps
// user-supplied sort input from reaching the query as raw SQL.
var activitySortColumns = map[string]string{
	"id":                "id",
	"time":              "ts_created",
	"model":             "model_id",
	"req_path":          "req_path",
	"resp_status_code":  "resp_status_code",
	"resp_content_type": "resp_content_type",
	"cached":            "cache_tokens",
	"prompt":            "input_tokens",
	"generated":         "output_tokens",
	"drafted":           "draft_tokens",
	"prompt_speed":      "prompt_per_second",
	"gen_speed":         "tokens_per_second",
	"duration":          "duration_ms",
}

// ActivitySortColumn returns the SQL column for a sortable API key and whether
// the key is valid.
func ActivitySortColumn(key string) (string, bool) {
	col, ok := activitySortColumns[key]
	return col, ok
}

type ActivityPage struct {
	Data       []ActivityLogEntry `json:"data"`
	Page       int                `json:"page"`
	Limit      int                `json:"limit"`
	Total      int                `json:"total"`
	TotalPages int                `json:"total_pages"`
}

type ActivityStatsQuery struct {
	Model string
}

type ActivityStats struct {
	TotalRequests       int            `json:"total_requests"`
	TotalInputTokens    int            `json:"total_input_tokens"`
	TotalOutputTokens   int            `json:"total_output_tokens"`
	TotalCacheTokens    int            `json:"total_cache_tokens"`
	PromptHistogram     *HistogramData `json:"prompt_histogram"`
	GenerationHistogram *HistogramData `json:"gen_histogram"`
}

type HistogramData struct {
	Bins    []int   `json:"bins"`
	Min     float64 `json:"min"`
	Max     float64 `json:"max"`
	BinSize float64 `json:"binSize"`
	P50     float64 `json:"p50"`
	P95     float64 `json:"p95"`
	P99     float64 `json:"p99"`
}

type Store struct {
	db       *sql.DB
	inMemory bool
	cache    *cacheRepository
}

// IsInMemory returns true if the store is using an in-memory database.
func (s *Store) IsInMemory() bool {
	return s.inMemory
}

// Cache returns the store's general-purpose key/value cache. Capability
// auto-discovery persists its probes here so they survive restarts.
func (s *Store) Cache() store.CacheRepository {
	return s.cache
}

// New opens a SQLite store at path. An empty path creates an in-memory store.
func New(path string) (*Store, error) {
	dsn := strings.TrimSpace(path)
	diskFile := dsn != ""
	if dsn == "" {
		dsn = ":memory:"
	}

	db, err := sql.Open("sqlite", dsn)
	if err != nil {
		return nil, fmt.Errorf("open sqlite store: %w", err)
	}
	db.SetMaxOpenConns(1)

	ctx := context.Background()
	if _, err := db.ExecContext(ctx, `PRAGMA busy_timeout = 5000`); err != nil {
		db.Close()
		return nil, fmt.Errorf("configure sqlite store: %w", err)
	}
	if diskFile {
		var mode string
		if err := db.QueryRowContext(ctx, `PRAGMA journal_mode = WAL`).Scan(&mode); err != nil {
			db.Close()
			return nil, fmt.Errorf("enable sqlite store WAL mode: %w", err)
		}
		if !strings.EqualFold(mode, "wal") {
			db.Close()
			return nil, fmt.Errorf("enable sqlite store WAL mode: got %q", mode)
		}
	}
	if err := runMigrations(ctx, db); err != nil {
		db.Close()
		return nil, err
	}
	s := &Store{db: db, inMemory: !diskFile, cache: &cacheRepository{db: db}}
	// Drop cache rows that expired while the process was not running, so a
	// long-lived database does not accumulate them.
	if err := s.cache.Prune(ctx); err != nil {
		db.Close()
		return nil, err
	}
	return s, nil
}

func runMigrations(ctx context.Context, db *sql.DB) error {
	migrations, err := fs.Sub(migrationFS, "migrations")
	if err != nil {
		return fmt.Errorf("sqlite store migrations: %w", err)
	}
	provider, err := goose.NewProvider(goose.DialectSQLite3, db, migrations)
	if err != nil {
		return fmt.Errorf("sqlite store migrations: %w", err)
	}
	if _, err := provider.Up(ctx); err != nil {
		return fmt.Errorf("sqlite store migrations up: %w", err)
	}
	return nil
}

func (s *Store) Close() error {
	if s == nil || s.db == nil {
		return nil
	}
	return s.db.Close()
}

func (s *Store) InsertActivity(ctx context.Context, entry ActivityLogEntry) (ActivityLogEntry, error) {
	if entry.Timestamp.IsZero() {
		entry.Timestamp = time.Now()
	}
	metadataJSON, err := marshalMetadata(entry.Metadata)
	if err != nil {
		return ActivityLogEntry{}, err
	}

	res, err := s.db.ExecContext(ctx, `
		INSERT INTO activity (
			ts_created, model_id, req_path, resp_content_type, resp_status_code,
			cache_tokens, draft_tokens, draft_acc_tokens, input_tokens, output_tokens,
			prompt_per_second, tokens_per_second, duration_ms, error_msg, metadata_json
		) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
		entry.Timestamp.Unix(),
		entry.Model,
		entry.ReqPath,
		entry.RespContentType,
		entry.RespStatusCode,
		entry.Tokens.CachedTokens,
		entry.Tokens.DraftTokens,
		entry.Tokens.DraftAccTokens,
		entry.Tokens.InputTokens,
		entry.Tokens.OutputTokens,
		entry.Tokens.PromptPerSecond,
		entry.Tokens.TokensPerSecond,
		entry.DurationMs,
		entry.ErrorMsg,
		metadataJSON,
	)
	if err != nil {
		return ActivityLogEntry{}, fmt.Errorf("insert activity: %w", err)
	}
	id, err := res.LastInsertId()
	if err != nil {
		return ActivityLogEntry{}, fmt.Errorf("insert activity id: %w", err)
	}
	entry.ID = int(id)
	return entry, nil
}

func (s *Store) ListActivity(ctx context.Context, query ActivityQuery) (ActivityPage, error) {
	query = normalizeActivityQuery(query)
	offset := (query.Page - 1) * query.Limit

	where, args := activityWhere(query.ActivityFilter)
	var total int
	if err := s.db.QueryRowContext(ctx, `SELECT COUNT(*) FROM activity`+where, args...).Scan(&total); err != nil {
		return ActivityPage{}, fmt.Errorf("count activity: %w", err)
	}

	rows, err := s.db.QueryContext(ctx, `
		SELECT
			id, ts_created, model_id, req_path, resp_content_type, resp_status_code,
			cache_tokens, draft_tokens, draft_acc_tokens, input_tokens, output_tokens,
			prompt_per_second, tokens_per_second, duration_ms, error_msg, metadata_json
		FROM activity`+where+activityOrderBy(query)+`
		LIMIT ? OFFSET ?`,
		append(args, query.Limit, offset)...,
	)
	if err != nil {
		return ActivityPage{}, fmt.Errorf("list activity: %w", err)
	}
	defer rows.Close()

	entries := []ActivityLogEntry{}
	for rows.Next() {
		entry, err := scanActivity(rows)
		if err != nil {
			return ActivityPage{}, err
		}
		entries = append(entries, entry)
	}
	if err := rows.Err(); err != nil {
		return ActivityPage{}, fmt.Errorf("list activity rows: %w", err)
	}

	return ActivityPage{
		Data:       entries,
		Page:       query.Page,
		Limit:      query.Limit,
		Total:      total,
		TotalPages: calculateTotalPages(total, query.Limit),
	}, nil
}

func (s *Store) ActivityStats(ctx context.Context, query ActivityStatsQuery) (ActivityStats, error) {
	filter := ActivityFilter{}
	if model := strings.TrimSpace(query.Model); model != "" {
		filter.Models = []string{model}
	}
	where, args := activityWhere(filter)
	row := s.db.QueryRowContext(ctx, `
		SELECT
			COUNT(*),
			COALESCE(SUM(input_tokens), 0),
			COALESCE(SUM(output_tokens), 0),
			COALESCE(SUM(CASE WHEN cache_tokens > 0 THEN cache_tokens ELSE 0 END), 0)
		FROM activity`+where, args...)

	var stats ActivityStats
	if err := row.Scan(&stats.TotalRequests, &stats.TotalInputTokens, &stats.TotalOutputTokens, &stats.TotalCacheTokens); err != nil {
		return ActivityStats{}, fmt.Errorf("activity stats: %w", err)
	}

	promptValues, genValues, err := s.speedValues(ctx, where, args)
	if err != nil {
		return ActivityStats{}, err
	}
	stats.PromptHistogram = calculateHistogramData(promptValues)
	stats.GenerationHistogram = calculateHistogramData(genValues)
	return stats, nil
}

// speedValues reads both histogram source columns in a single scan. Zero
// values mean the speed was not reported and are excluded per column. No
// ORDER BY: calculateHistogramData sorts the values itself.
func (s *Store) speedValues(ctx context.Context, where string, args []any) (prompt, gen []float64, err error) {
	filter := where
	if filter == "" {
		filter = ` WHERE prompt_per_second > 0 OR tokens_per_second > 0`
	} else {
		filter += ` AND (prompt_per_second > 0 OR tokens_per_second > 0)`
	}
	rows, err := s.db.QueryContext(ctx,
		`SELECT prompt_per_second, tokens_per_second FROM activity`+filter, args...)
	if err != nil {
		return nil, nil, fmt.Errorf("activity histogram: %w", err)
	}
	defer rows.Close()

	for rows.Next() {
		var promptValue, genValue float64
		if err := rows.Scan(&promptValue, &genValue); err != nil {
			return nil, nil, fmt.Errorf("activity histogram row: %w", err)
		}
		if promptValue > 0 {
			prompt = append(prompt, promptValue)
		}
		if genValue > 0 {
			gen = append(gen, genValue)
		}
	}
	return prompt, gen, rows.Err()
}

func (s *Store) PruneActivity(ctx context.Context, maxRows int) error {
	if maxRows <= 0 {
		return nil
	}
	// AUTOINCREMENT ids are monotonic and never reused, so the rows beyond
	// the newest maxRows are exactly those with id <= MAX(id) - maxRows.
	// One statement keeps the per-insert prune cheap; if ids ever become
	// sparse this retains fewer than maxRows rows, which is fine for a
	// bounded recent-activity cap.
	if _, err := s.db.ExecContext(ctx,
		`DELETE FROM activity WHERE id <= (SELECT MAX(id) FROM activity) - ?`, maxRows,
	); err != nil {
		return fmt.Errorf("prune activity: %w", err)
	}
	return nil
}

func normalizeActivityQuery(query ActivityQuery) ActivityQuery {
	if query.Page < 1 {
		query.Page = 1
	}
	if query.Limit < 1 {
		query.Limit = 25
	}
	return query
}

// activityOrderBy builds a safe ORDER BY clause from the query's sort key and
// direction. Unknown sort keys fall back to "id". A secondary "id" sort keeps
// pagination stable when the primary column has duplicate values.
func activityOrderBy(query ActivityQuery) string {
	column, ok := activitySortColumns[query.Sort]
	if !ok {
		column = "id"
	}
	direction := "DESC"
	if strings.EqualFold(query.Order, "asc") {
		direction = "ASC"
	}
	if column == "id" {
		return " ORDER BY id " + direction
	}
	return " ORDER BY " + column + " " + direction + ", id " + direction
}

func calculateTotalPages(total, limit int) int {
	if total == 0 || limit <= 0 {
		return 0
	}
	return int(math.Ceil(float64(total) / float64(limit)))
}

func calculateHistogramData(values []float64) *HistogramData {
	if len(values) == 0 {
		return nil
	}

	sorted := append([]float64(nil), values...)
	sort.Float64s(sorted)
	minVal := sorted[0]
	maxVal := sorted[len(sorted)-1]

	p50 := percentile(sorted, 50)
	p95 := percentile(sorted, 95)
	p99 := percentile(sorted, 99)

	if minVal == maxVal {
		return &HistogramData{
			Bins:    []int{len(values)},
			Min:     minVal,
			Max:     maxVal,
			BinSize: 0,
			P50:     p50,
			P95:     p95,
			P99:     p99,
		}
	}

	const minBins = 5
	const maxBins = 20
	sturges := int(math.Ceil(math.Log2(float64(len(values))))) + 1
	binCount := min(maxBins, max(minBins, sturges))
	binSize := (maxVal - minVal) / float64(binCount)

	bins := make([]int, binCount)
	for _, value := range values {
		idx := min(int(math.Floor((value-minVal)/binSize)), binCount-1)
		bins[idx]++
	}

	return &HistogramData{
		Bins:    bins,
		Min:     minVal,
		Max:     maxVal,
		BinSize: binSize,
		P50:     p50,
		P95:     p95,
		P99:     p99,
	}
}

func percentile(sorted []float64, p float64) float64 {
	if len(sorted) == 0 {
		return 0
	}
	if len(sorted) == 1 {
		return sorted[0]
	}
	rank := (p / 100) * float64(len(sorted)-1)
	lower := int(math.Floor(rank))
	upper := int(math.Ceil(rank))
	fraction := rank - float64(lower)
	return sorted[lower] + fraction*(sorted[upper]-sorted[lower])
}

// activityWhere builds a parameterized WHERE clause from a filter. It returns
// an empty string when nothing is filtered. Callers append further conditions
// with " AND ...", so the clause is always a single unparenthesized conjunction.
func activityWhere(filter ActivityFilter) (string, []any) {
	var conditions []string
	var args []any

	models := make([]string, 0, len(filter.Models))
	for _, model := range filter.Models {
		if model = strings.TrimSpace(model); model != "" {
			models = append(models, model)
		}
	}
	if len(models) > 0 {
		placeholders := strings.TrimSuffix(strings.Repeat("?, ", len(models)), ", ")
		conditions = append(conditions, "model_id IN ("+placeholders+")")
		for _, model := range models {
			args = append(args, model)
		}
	}

	if !filter.Start.IsZero() {
		conditions = append(conditions, "ts_created >= ?")
		args = append(args, filter.Start.Unix())
	}
	if !filter.End.IsZero() {
		conditions = append(conditions, "ts_created <= ?")
		args = append(args, filter.End.Unix())
	}
	if filter.MinID > 0 {
		conditions = append(conditions, "id >= ?")
		args = append(args, filter.MinID)
	}
	if filter.MaxID > 0 {
		conditions = append(conditions, "id <= ?")
		args = append(args, filter.MaxID)
	}

	if len(conditions) == 0 {
		return "", nil
	}
	return " WHERE " + strings.Join(conditions, " AND "), args
}

func marshalMetadata(metadata map[string]string) (string, error) {
	if len(metadata) == 0 {
		return "", nil
	}
	data, err := json.Marshal(metadata)
	if err != nil {
		return "", fmt.Errorf("marshal activity metadata: %w", err)
	}
	return string(data), nil
}

type activityScanner interface {
	Scan(dest ...any) error
}

func scanActivity(scanner activityScanner) (ActivityLogEntry, error) {
	var entry ActivityLogEntry
	var ts int64
	var metadataJSON string
	if err := scanner.Scan(
		&entry.ID,
		&ts,
		&entry.Model,
		&entry.ReqPath,
		&entry.RespContentType,
		&entry.RespStatusCode,
		&entry.Tokens.CachedTokens,
		&entry.Tokens.DraftTokens,
		&entry.Tokens.DraftAccTokens,
		&entry.Tokens.InputTokens,
		&entry.Tokens.OutputTokens,
		&entry.Tokens.PromptPerSecond,
		&entry.Tokens.TokensPerSecond,
		&entry.DurationMs,
		&entry.ErrorMsg,
		&metadataJSON,
	); err != nil {
		return ActivityLogEntry{}, fmt.Errorf("scan activity: %w", err)
	}
	entry.Timestamp = time.Unix(ts, 0)
	if metadataJSON != "" {
		if err := json.Unmarshal([]byte(metadataJSON), &entry.Metadata); err != nil {
			return ActivityLogEntry{}, fmt.Errorf("unmarshal activity metadata: %w", err)
		}
	}
	return entry, nil
}

package sqlite

import (
	"context"
	"database/sql"
	"encoding/json"
	"fmt"
	"strings"
	"time"

	"github.com/toxicwind/bornite/internal/store"
)

// activityRepository implements store.ActivityRepository over the activity
// table.
type activityRepository struct {
	db *sql.DB
}

var _ store.ActivityRepository = (*activityRepository)(nil)

// activitySortColumns maps the store's sortable keys onto SQL columns. Only
// these column names ever reach a query; TestActivity_SortColumnsCoverStoreKeys
// checks the map stays in step with store.ActivitySortKeys.
var activitySortColumns = map[string]string{
	"id":                "id",
	"time":              "ts_created",
	"model":             "model_id",
	"src":               "src",
	"req_path":          "req_path",
	"resp_status_code":  "resp_status_code",
	"resp_content_type": "resp_content_type",
	"cached":            "cache_tokens",
	"prompt":            "input_tokens",
	"generated":         "output_tokens",
	"drafted":           "draft_tokens",
	"prompt_speed":      "prompt_per_second",
	"gen_speed":         "tokens_per_second",
	"duration":          "duration_ms",
}

func (r *activityRepository) Insert(ctx context.Context, entry store.ActivityLogEntry) (store.ActivityLogEntry, error) {
	if entry.Timestamp.IsZero() {
		entry.Timestamp = time.Now()
	}
	metadataJSON, err := marshalMetadata(entry.Metadata)
	if err != nil {
		return store.ActivityLogEntry{}, err
	}

	res, err := r.db.ExecContext(ctx, `
		INSERT INTO activity (
			ts_created, src, model_id, req_path, resp_content_type, resp_status_code,
			cache_tokens, draft_tokens, draft_acc_tokens, input_tokens, output_tokens,
			prompt_per_second, tokens_per_second, duration_ms, error_msg, metadata_json
		) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
		entry.Timestamp.Unix(),
		entry.Src,
		entry.Model,
		entry.ReqPath,
		entry.RespContentType,
		entry.RespStatusCode,
		entry.Tokens.CachedTokens,
		entry.Tokens.DraftTokens,
		entry.Tokens.DraftAccTokens,
		entry.Tokens.InputTokens,
		entry.Tokens.OutputTokens,
		entry.Tokens.PromptPerSecond,
		entry.Tokens.TokensPerSecond,
		entry.DurationMs,
		entry.ErrorMsg,
		metadataJSON,
	)
	if err != nil {
		return store.ActivityLogEntry{}, fmt.Errorf("insert activity: %w", err)
	}
	id, err := res.LastInsertId()
	if err != nil {
		return store.ActivityLogEntry{}, fmt.Errorf("insert activity id: %w", err)
	}
	entry.ID = int(id)
	return entry, nil
}

// ValidActivitySortKey reports whether key is accepted by ActivityQuery.Sort.
func (r *activityRepository) ValidActivitySortKey(key string) bool {
	if _, ok := activitySortColumns[key]; !ok {
		return false
	}
	return true
}
func (r *activityRepository) List(ctx context.Context, query store.ActivityQuery) (store.ActivityPage, error) {
	query = query.WithDefaults()
	offset := (query.Page - 1) * query.Limit

	where, args := activityWhere(query.ActivityFilter)
	var total int
	if err := r.db.QueryRowContext(ctx, `SELECT COUNT(*) FROM activity`+where, args...).Scan(&total); err != nil {
		return store.ActivityPage{}, fmt.Errorf("count activity: %w", err)
	}

	rows, err := r.db.QueryContext(ctx, `
		SELECT
			id, ts_created, src, model_id, req_path, resp_content_type, resp_status_code,
			cache_tokens, draft_tokens, draft_acc_tokens, input_tokens, output_tokens,
			prompt_per_second, tokens_per_second, duration_ms, error_msg, metadata_json
		FROM activity`+where+activityOrderBy(query)+`
		LIMIT ? OFFSET ?`,
		append(args, query.Limit, offset)...,
	)
	if err != nil {
		return store.ActivityPage{}, fmt.Errorf("list activity: %w", err)
	}
	defer rows.Close()

	entries := []store.ActivityLogEntry{}
	for rows.Next() {
		entry, err := scanActivity(rows)
		if err != nil {
			return store.ActivityPage{}, err
		}
		entries = append(entries, entry)
	}
	if err := rows.Err(); err != nil {
		return store.ActivityPage{}, fmt.Errorf("list activity rows: %w", err)
	}

	return store.ActivityPage{
		Data:       entries,
		Page:       query.Page,
		Limit:      query.Limit,
		Total:      total,
		TotalPages: store.TotalPages(total, query.Limit),
	}, nil
}

func (r *activityRepository) Stats(ctx context.Context, query store.ActivityStatsQuery) (store.ActivityStats, error) {
	filter := store.ActivityFilter{}
	if model := strings.TrimSpace(query.Model); model != "" {
		filter.Models = []string{model}
	}
	where, args := activityWhere(filter)
	row := r.db.QueryRowContext(ctx, `
		SELECT
			COALESCE(MAX(id), 0),
			COALESCE(SUM(input_tokens), 0),
			COALESCE(SUM(output_tokens), 0),
			COALESCE(SUM(CASE WHEN cache_tokens > 0 THEN cache_tokens ELSE 0 END), 0)
		FROM activity`+where, args...)

	var stats store.ActivityStats
	if err := row.Scan(&stats.TotalRequests, &stats.TotalInputTokens, &stats.TotalOutputTokens, &stats.TotalCacheTokens); err != nil {
		return store.ActivityStats{}, fmt.Errorf("activity stats: %w", err)
	}

	promptValues, genValues, err := r.speedValues(ctx, where, args)
	if err != nil {
		return store.ActivityStats{}, err
	}
	stats.PromptHistogram = store.NewHistogram(promptValues)
	stats.GenerationHistogram = store.NewHistogram(genValues)
	return stats, nil
}

// speedValues reads both histogram source columns in a single scan. Zero
// values mean the speed was not reported and are excluded per column. No
// ORDER BY: store.NewHistogram sorts the values itself.
func (r *activityRepository) speedValues(ctx context.Context, where string, args []any) (prompt, gen []float64, err error) {
	filter := where
	if filter == "" {
		filter = ` WHERE prompt_per_second > 0 OR tokens_per_second > 0`
	} else {
		filter += ` AND (prompt_per_second > 0 OR tokens_per_second > 0)`
	}
	rows, err := r.db.QueryContext(ctx,
		`SELECT prompt_per_second, tokens_per_second FROM activity`+filter, args...)
	if err != nil {
		return nil, nil, fmt.Errorf("activity histogram: %w", err)
	}
	defer rows.Close()

	for rows.Next() {
		var promptValue, genValue float64
		if err := rows.Scan(&promptValue, &genValue); err != nil {
			return nil, nil, fmt.Errorf("activity histogram row: %w", err)
		}
		if promptValue > 0 {
			prompt = append(prompt, promptValue)
		}
		if genValue > 0 {
			gen = append(gen, genValue)
		}
	}
	return prompt, gen, rows.Err()
}

func (r *activityRepository) Prune(ctx context.Context, maxRows int) error {
	if maxRows <= 0 {
		return nil
	}
	// AUTOINCREMENT ids are monotonic and never reused, so the rows beyond
	// the newest maxRows are exactly those with id <= MAX(id) - maxRows.
	// One statement keeps the per-insert prune cheap; if ids ever become
	// sparse this retains fewer than maxRows rows, which is fine for a
	// bounded recent-activity cap.
	if _, err := r.db.ExecContext(ctx,
		`DELETE FROM activity WHERE id <= (SELECT MAX(id) FROM activity) - ?`, maxRows,
	); err != nil {
		return fmt.Errorf("prune activity: %w", err)
	}
	return nil
}

// activityOrderBy builds a safe ORDER BY clause from the query's sort key and
// direction. Unknown sort keys fall back to "id". A secondary "id" sort keeps
// pagination stable when the primary column has duplicate values.
func activityOrderBy(query store.ActivityQuery) string {
	column, ok := activitySortColumns[query.Sort]
	if !ok {
		column = "id"
	}
	direction := "DESC"
	if strings.EqualFold(query.Order, "asc") {
		direction = "ASC"
	}
	if column == "id" {
		return " ORDER BY id " + direction
	}
	return " ORDER BY " + column + " " + direction + ", id " + direction
}

// activityWhere builds a parameterized WHERE clause from a filter. It returns
// an empty string when nothing is filtered. Callers append further conditions
// with " AND ...", so the clause is always a single unparenthesized conjunction.
func activityWhere(filter store.ActivityFilter) (string, []any) {
	var conditions []string
	var args []any

	models := make([]string, 0, len(filter.Models))
	for _, model := range filter.Models {
		if model = strings.TrimSpace(model); model != "" {
			models = append(models, model)
		}
	}
	if len(models) > 0 {
		placeholders := strings.TrimSuffix(strings.Repeat("?, ", len(models)), ", ")
		conditions = append(conditions, "model_id IN ("+placeholders+")")
		for _, model := range models {
			args = append(args, model)
		}
	}

	if !filter.Start.IsZero() {
		conditions = append(conditions, "ts_created >= ?")
		args = append(args, filter.Start.Unix())
	}
	if !filter.End.IsZero() {
		conditions = append(conditions, "ts_created <= ?")
		args = append(args, filter.End.Unix())
	}
	if filter.MinID > 0 {
		conditions = append(conditions, "id >= ?")
		args = append(args, filter.MinID)
	}
	if filter.MaxID > 0 {
		conditions = append(conditions, "id <= ?")
		args = append(args, filter.MaxID)
	}
	if filter.SrcPrefix != "" {
		// A bounded lexical range is a literal prefix match (SQL wildcard
		// characters remain data) and can use idx_activity_src_created_id.
		conditions = append(conditions, "src >= ? AND src < ?")
		args = append(args, filter.SrcPrefix, filter.SrcPrefix+"\U0010FFFF")
	}

	if len(conditions) == 0 {
		return "", nil
	}
	return " WHERE " + strings.Join(conditions, " AND "), args
}

func marshalMetadata(metadata map[string]string) (string, error) {
	if len(metadata) == 0 {
		return "", nil
	}
	data, err := json.Marshal(metadata)
	if err != nil {
		return "", fmt.Errorf("marshal activity metadata: %w", err)
	}
	return string(data), nil
}

type activityScanner interface {
	Scan(dest ...any) error
}

func scanActivity(scanner activityScanner) (store.ActivityLogEntry, error) {
	var entry store.ActivityLogEntry
	var ts int64
	var metadataJSON string
	if err := scanner.Scan(
		&entry.ID,
