package sqlite

import (
	"testing"

	"github.com/toxicwind/bornite/internal/store"
)

// Every sort key the store package accepts must map to a SQL column here, and
// nothing outside that whitelist may be sortable.
func TestActivity_SortColumnsCoverStoreKeys(t *testing.T) {
	keys := store.ActivitySortKeys()
	for _, key := range keys {
		if _, ok := activitySortColumns[key]; !ok {
			t.Errorf("store sort key %q has no SQL column", key)
		}
	}
	if len(activitySortColumns) != len(keys) {
		t.Errorf("activitySortColumns has %d entries, store has %d keys", len(activitySortColumns), len(keys))
	}
	for key := range activitySortColumns {
		if !store.ValidActivitySortKey(key) {
			t.Errorf("SQL sort column key %q is not a store sort key", key)
		}
	}
}

package sqlite

import (
	"context"
	"database/sql"
	"errors"
	"fmt"
	"time"

	"github.com/toxicwind/bornite/internal/store"
)

// cacheRepository implements store.CacheRepository over the cache table.
//
// Expiry is evaluated in SQL as ts_created + ttl_seconds < now so a read and
// its expiry check are one round trip. Rows with ttl_seconds <= 0 never
// expire.
type cacheRepository struct {
	db *sql.DB
}

var _ store.CacheRepository = (*cacheRepository)(nil)

// beforeExpiryDelete runs between reading a row that turned out to be expired
// and deleting it. It is nil outside tests, and exists so the interleaving the
// conditional delete guards against can be produced on demand rather than
// waited for: the gap between those two statements is a few instructions wide
// and a concurrent writer almost never lands in it by chance.
var beforeExpiryDelete func()

func (r *cacheRepository) Get(ctx context.Context, key string) (store.CacheEntry, bool, error) {
	var (
		data []byte
		ttl  int64
		ts   int64
	)
	err := r.db.QueryRowContext(ctx, `
		SELECT data, ttl_seconds, ts_created FROM cache WHERE key = ?`,
		key,
	).Scan(&data, &ttl, &ts)
	if errors.Is(err, sql.ErrNoRows) {
		return store.CacheEntry{}, false, nil
	}
	if err != nil {
		return store.CacheEntry{}, false, fmt.Errorf("get cache: %w", err)
	}

	now := time.Now()
	entry := store.CacheEntry{
		Key:       key,
		Data:      data,
		TTL:       time.Duration(ttl) * time.Second,
		Timestamp: time.Unix(ts, 0),
	}
	if entry.Expired(now) {
		if beforeExpiryDelete != nil {
			beforeExpiryDelete()
		}
		// Drop it now so a key that is never written again does not linger
		// until the next Prune.
		//
		// The delete repeats the expiry test in SQL against the same clock
		// rather than deleting by key. The read above and this write are
		// separate statements, so a Set can land between them, and a
		// just-written row is never expired against this now: the condition
		// makes the cleanup a no-op instead of discarding it.
		if _, err := r.db.ExecContext(ctx, `
			DELETE FROM cache
			WHERE key = ? AND ttl_seconds > 0 AND ts_created + ttl_seconds < ?`,
			key, now.Unix(),
		); err != nil {
			return store.CacheEntry{}, false, fmt.Errorf("delete expired cache: %w", err)
		}
		return store.CacheEntry{}, false, nil
	}
	return entry, true, nil
}

func (r *cacheRepository) Set(ctx context.Context, entry store.CacheEntry) error {
	if entry.Timestamp.IsZero() {
		entry.Timestamp = time.Now()
	}
	// ttl_seconds is whole seconds, and 0 means "never expires". Rounding a
	// positive TTL down would turn anything under a second into a permanent
	// row, so round up instead: a positive TTL always expires.
	ttl := int64(0)
	if entry.TTL > 0 {
		ttl = int64((entry.TTL + time.Second - 1) / time.Second)
	}
	_, err := r.db.ExecContext(ctx, `
		INSERT INTO cache (key, data, ttl_seconds, ts_created)
		VALUES (?, ?, ?, ?)
		ON CONFLICT(key) DO UPDATE SET
			data = excluded.data,
			ttl_seconds = excluded.ttl_seconds,
			ts_created = excluded.ts_created`,
		entry.Key, entry.Data, ttl, entry.Timestamp.Unix(),
	)
	if err != nil {
		return fmt.Errorf("set cache: %w", err)
	}
	return nil
}

func (r *cacheRepository) Delete(ctx context.Context, key string) error {
	if _, err := r.db.ExecContext(ctx, `DELETE FROM cache WHERE key = ?`, key); err != nil {
		return fmt.Errorf("delete cache: %w", err)
	}
	return nil
}

func (r *cacheRepository) Prune(ctx context.Context) error {
	_, err := r.db.ExecContext(ctx, `
		DELETE FROM cache
		WHERE ttl_seconds > 0 AND ts_created + ttl_seconds < ?`,
		time.Now().Unix(),
	)
	if err != nil {
		return fmt.Errorf("prune cache: %w", err)
	}
	return nil
}

package sqlite

import (
	"context"
	"path/filepath"
	"testing"
	"time"

	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"

	"github.com/toxicwind/bornite/internal/store"
)

// newCacheStore returns an in-memory store with its cache repository.
func newCacheStore(t *testing.T) (*Store, store.CacheRepository) {
	t.Helper()
	st, err := New("")
	require.NoError(t, err)
	t.Cleanup(func() { st.Close() })
	return st, st.Cache()
}

func TestStore_CacheSetGet(t *testing.T) {
	ctx := context.Background()
	_, cache := newCacheStore(t)

	// Truncated to the second because the column stores Unix seconds.
	written := time.Now().Truncate(time.Second)
	require.NoError(t, cache.Set(ctx, store.CacheEntry{
		Key:       "capcompat:v1:local:model-a",
		Data:      []byte(`{"context":4096}`),
		TTL:       time.Hour,
		Timestamp: written,
	}))

	got, found, err := cache.Get(ctx, "capcompat:v1:local:model-a")
	require.NoError(t, err)
	require.True(t, found)
	assert.Equal(t, "capcompat:v1:local:model-a", got.Key)
	assert.Equal(t, []byte(`{"context":4096}`), got.Data)
	assert.Equal(t, time.Hour, got.TTL)
	assert.Equal(t, written.Unix(), got.Timestamp.Unix())
}

func TestStore_CacheGetMissingKey(t *testing.T) {
	ctx := context.Background()
	_, cache := newCacheStore(t)

	_, found, err := cache.Get(ctx, "nope")
	require.NoError(t, err)
	assert.False(t, found)
}

func TestStore_CacheSetDefaultsTimestampToNow(t *testing.T) {
	ctx := context.Background()
	_, cache := newCacheStore(t)

	before := time.Now().Add(-time.Second)
	require.NoError(t, cache.Set(ctx, store.CacheEntry{Key: "k", Data: []byte("v")}))

	got, found, err := cache.Get(ctx, "k")
	require.NoError(t, err)
	require.True(t, found)
	assert.False(t, got.Timestamp.Before(before), "timestamp should default to now")
}

func TestStore_CacheOverwrite(t *testing.T) {
	ctx := context.Background()
	st, cache := newCacheStore(t)

	first := time.Now().Truncate(time.Second).Add(-time.Minute)
	second := first.Add(30 * time.Second)
	require.NoError(t, cache.Set(ctx, store.CacheEntry{
		Key: "k", Data: []byte("first"), TTL: time.Hour, Timestamp: first,
	}))
	require.NoError(t, cache.Set(ctx, store.CacheEntry{
		Key: "k", Data: []byte("second"), TTL: 2 * time.Hour, Timestamp: second,
	}))

	got, found, err := cache.Get(ctx, "k")
	require.NoError(t, err)
	require.True(t, found)
	assert.Equal(t, []byte("second"), got.Data)
	assert.Equal(t, 2*time.Hour, got.TTL)
	assert.Equal(t, second.Unix(), got.Timestamp.Unix())

	var rows int
	require.NoError(t, st.db.QueryRow(`SELECT COUNT(*) FROM cache`).Scan(&rows))
	assert.Equal(t, 1, rows, "overwrite must not create a second row")
}

func TestStore_CacheExpiredEntryIsGone(t *testing.T) {
	ctx := context.Background()
	st, cache := newCacheStore(t)

	// Written two hours ago with a one hour TTL. No sleeping involved.
	require.NoError(t, cache.Set(ctx, store.CacheEntry{
		Key:       "stale",
		Data:      []byte("old"),
		TTL:       time.Hour,
		Timestamp: time.Now().Add(-2 * time.Hour),
	}))

	_, found, err := cache.Get(ctx, "stale")
	require.NoError(t, err)
	assert.False(t, found)

	// The read deletes the row rather than leaving it for Prune.
	var rows int
	require.NoError(t, st.db.QueryRow(`SELECT COUNT(*) FROM cache`).Scan(&rows))
	assert.Equal(t, 0, rows)
}

func TestStore_CacheZeroTTLNeverExpires(t *testing.T) {
	ctx := context.Background()
	_, cache := newCacheStore(t)

	require.NoError(t, cache.Set(ctx, store.CacheEntry{
		Key:       "forever",
		Data:      []byte("v"),
		Timestamp: time.Now().Add(-10000 * time.Hour),
	}))

	got, found, err := cache.Get(ctx, "forever")
	require.NoError(t, err)
	require.True(t, found)
	assert.Equal(t, []byte("v"), got.Data)
}

func TestStore_CacheSubSecondTTLExpires(t *testing.T) {
	ctx := context.Background()
	_, cache := newCacheStore(t)

	t.Run("does not become permanent", func(t *testing.T) {
		// A TTL under a second must not round down to 0, which is the
		// sentinel for "never expires".
		require.NoError(t, cache.Set(ctx, store.CacheEntry{
			Key:       "brief",
			Data:      []byte("v"),
			TTL:       time.Millisecond,
			Timestamp: time.Now().Add(-time.Hour),
		}))

		_, found, err := cache.Get(ctx, "brief")
		require.NoError(t, err)
		assert.False(t, found)
	})

	t.Run("rounds up to one second", func(t *testing.T) {
		require.NoError(t, cache.Set(ctx, store.CacheEntry{
			Key:  "half",
			Data: []byte("v"),
			TTL:  500 * time.Millisecond,
		}))

		got, found, err := cache.Get(ctx, "half")
		require.NoError(t, err)
		require.True(t, found, "it should still be readable within the rounded up window")
		assert.Equal(t, time.Second, got.TTL)
	})
}

func TestStore_CacheExpiryDeleteSparesReplacementRow(t *testing.T) {
	// Get reads a row, decides it is expired, then deletes it in a second
	// statement. A Set landing between those two must not be discarded, so
	// the delete repeats the expiry test instead of matching the key alone.
	// The hook produces that interleaving; scheduling almost never does.
	ctx := context.Background()
	_, cache := newCacheStore(t)

	require.NoError(t, cache.Set(ctx, store.CacheEntry{
		Key:       "k",
		Data:      []byte("stale"),
		TTL:       time.Second,
		Timestamp: time.Now().Add(-time.Hour),
	}))

	var replaced bool
	beforeExpiryDelete = func() {
		if replaced {
			return
		}
		replaced = true
		require.NoError(t, cache.Set(ctx, store.CacheEntry{
			Key: "k", Data: []byte("fresh"), TTL: time.Hour,
		}))
	}
	t.Cleanup(func() { beforeExpiryDelete = nil })

	// This Get still reports the stale row it read, which is correct: it saw
	// the state before the write.
	_, found, err := cache.Get(ctx, "k")
	require.NoError(t, err)
	assert.False(t, found)
	require.True(t, replaced, "the hook should have fired on the expired row")

	// The row written in the gap must have survived the cleanup.
	got, found, err := cache.Get(ctx, "k")
	require.NoError(t, err)
	require.True(t, found, "expiry cleanup deleted a row written after the read")
	assert.Equal(t, []byte("fresh"), got.Data)
}

func TestStore_CacheDeleteMissingIsNotAnError(t *testing.T) {
	ctx := context.Background()
