#!/usr/bin/env python3
"""toolchain-drift-guard: fail fast when a Dockerfile's Go toolchain pin
lags the maximum `go` directive required to build what the image builds.

Scans:
  * every Dockerfile in the repo (Dockerfile*, *.Dockerfile, *.Containerfile)
    for `FROM golang:<tag>` pins (including ARG-indirected tags), and
  * the maximum `go` directive across ALL go.mod files in the repo tree,
    including vendored deps and submodule checkouts, and
  * the upstream bornite go.mod that docker/unified/install-vllm-wrapper.sh
    fetches at image build time (the exact failure class that broke
    vulkan/assemble + cuda/assemble: golang:1.26 vs bornite v255
    requiring Go >= 1.27.1).

Usage:
  scripts/toolchain-drift-guard.py [--root DIR] [--ls-version V] [--no-upstream]

  --ls-version mirrors the Docker build arg LS_VERSION consumed by
  docker/unified/install-vllm-wrapper.sh (default: "main", matching
  .github/workflows/unified-docker.yml's default input).

Exit 0: every Go pin satisfies the requirement.
Exit 1: drift detected (with the exact bump needed), or the upstream
        requirement could not be resolved (fail-closed: the image build
        itself needs that same network access to succeed).

Install as a pre-push hook:
  cp scripts/pre-push .git/hooks/pre-push && chmod +x .git/hooks/pre-push
"""

import argparse
import os
import re
import sys
import urllib.request

UPSTREAM_REPO = "mostlygeek/bornite"
DEFAULT_VARIANT = "-bookworm"  # repo convention for Go builder images

FROM_RE = re.compile(
    r"^\s*FROM\s+(?:--[\w-]+=\S+\s+)*golang:([^\s]+)", re.IGNORECASE
)
ARG_RE = re.compile(r"^\s*ARG\s+([A-Za-z_][\w]*)(?:[=\s]+([^\s#]+))?")
GO_DIRECTIVE_RE = re.compile(r"^\s*go\s+(\d+(?:\.\d+){1,2})\s*$")
VERSION_RE = re.compile(r"^(\d+)(?:\.(\d+))?(?:\.(\d+))?")


def parse_version(text):
    """Parse leading numeric version; return (maj, min, patch|None, rest)."""
    m = VERSION_RE.match(text.strip())
    if not m:
        return None
    maj = int(m.group(1))
    minor = int(m.group(2)) if m.group(2) is not None else 0
    patch = int(m.group(3)) if m.group(3) is not None else None
    rest = text.strip()[m.end():]
    return (maj, minor, patch, rest)


def split_tag_variant(tag):
    """golang:1.27-bookworm -> ((1,27,None), '-bookworm')."""
    v = parse_version(tag)
    if v is None:
        return None, None
    return (v[0], v[1], v[2]), (v[3] or "")


def version_str(v):
    s = "%d.%d" % (v[0], v[1])
    if v[2] is not None:
        s += ".%d" % v[2]
    return s


def pin_satisfies(pin, req):
    """pin/req are (maj, min, patch|None). Pin needs >= req at minor
    granularity (docker golang tags are major.minor); an explicit pin
    patch must also cover the required patch."""
    if (pin[0], pin[1]) != (req[0], req[1]):
        return (pin[0], pin[1]) > (req[0], req[1])
    if pin[2] is not None and req[2] is not None:
        return pin[2] >= req[2]
    return True


def find_files(root, name_pred):
    hits = []
    for dirpath, dirnames, filenames in os.walk(root):
        # never descend into git metadata
        dirnames[:] = [d for d in dirnames if d != ".git"]
        if "/.git/" in dirpath.replace(os.sep, "/"):
            continue
        for f in filenames:
            if name_pred(f):
                hits.append(os.path.join(dirpath, f))
    return sorted(hits)


def is_dockerfile(name):
    n = name.lower()
    return (
        n == "dockerfile"
        or n.startswith("dockerfile.")
        or n.endswith(".dockerfile")
        or n.endswith(".containerfile")
    )


def resolve_arg_refs(tag, args):
    def sub(m):
        return args.get(m.group(1) or m.group(2), m.group(0))

    return re.sub(r"\$\{([A-Za-z_][\w]*)\}|\$([A-Za-z_][\w]*)", sub, tag)


def scan_dockerfile(path):
    """Return list of (line_no, raw_tag) golang pins in a Dockerfile."""
    pins = []
    args = {}
    with open(path, "r", encoding="utf-8", errors="replace") as fh:
        for i, line in enumerate(fh, 1):
            am = ARG_RE.match(line)
            if am and am.group(2):
                args[am.group(1)] = am.group(2).strip("'\"")
            fm = FROM_RE.match(line)
            if fm:
                pins.append((i, resolve_arg_refs(fm.group(1), args)))
    return pins


def go_directive_of(gomod_path):
    with open(gomod_path, "r", encoding="utf-8", errors="replace") as fh:
        for line in fh:
            m = GO_DIRECTIVE_RE.match(line)
            if m:
                return m.group(1)
    return None


def fetch_url(url, timeout=20):
    req = urllib.request.Request(
        url, headers={"User-Agent": "toolchain-drift-guard/1.0"}
    )
    with urllib.request.urlopen(req, timeout=timeout) as resp:
        return resp.read().decode("utf-8", "replace")


def resolve_upstream_ref(ls_version):
    """Mirror docker/unified/install-vllm-wrapper.sh ref resolution."""
    v = ls_version.strip()
    if re.fullmatch(r"[0-9a-f]{40}", v):
        # full commit hash: prefer the release tag pointing at it
        try:
            import subprocess

            out = subprocess.run(
                ["git", "ls-remote", "--tags",
                 "https://github.com/%s.git" % UPSTREAM_REPO],
                capture_output=True, text=True, timeout=30,
            ).stdout
            for line in out.splitlines():
                sha, ref = line.split("\t", 1)
                if sha == v and ref.startswith("refs/tags/") \
                        and not ref.endswith("^{}"):
                    return ref[len("refs/tags/"):]
        except Exception:
            pass
        return v  # raw.githubusercontent.com serves commit SHAs directly
    if v == "latest":
        data = fetch_url(
            "https://api.github.com/repos/%s/releases/latest" % UPSTREAM_REPO
        )
        m = re.search(r'"tag_name"\s*:\s*"([^"]+)"', data)
        if not m:
            raise RuntimeError("could not resolve latest release tag")
        return m.group(1)
    if re.fullmatch(r"v?\d+", v):
        return "v" + v.lstrip("v")
    return v  # branch name, e.g. "main"


def upstream_go_requirement(ls_version):
    ref = resolve_upstream_ref(ls_version)
    body = fetch_url(
        "https://raw.githubusercontent.com/%s/%s/go.mod" % (UPSTREAM_REPO, ref)
    )
    for line in body.splitlines():
        m = GO_DIRECTIVE_RE.match(line)
        if m:
            return m.group(1), "upstream %s@%s/go.mod" % (UPSTREAM_REPO, ref)
    raise RuntimeError("no `go` directive in upstream go.mod @ %s" % ref)


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--root", default=".",
                    help="repo root to scan (default: cwd)")
    ap.add_argument("--ls-version", default="main",
                    help="LS_VERSION build arg (default: main)")
    ap.add_argument("--no-upstream", action="store_true",
                    help="skip the upstream bornite go.mod check")
    args = ap.parse_args()
    root = os.path.abspath(args.root)
    failures = []

    # 1. requirements: every local go.mod + (optionally) upstream
    requirements = []  # (version_tuple, source_label)
    for gomod in find_files(root, lambda n: n == "go.mod"):
        directive = go_directive_of(gomod)
        if directive:
            v = parse_version(directive)
            rel = os.path.relpath(gomod, root)
            requirements.append(((v[0], v[1], v[2]), directive, rel))
    if not args.no_upstream:
        try:
            directive, source = upstream_go_requirement(args.ls_version)
            v = parse_version(directive)
            requirements.append(((v[0], v[1], v[2]), directive, source))
        except Exception as e:
            print("ERROR: could not resolve upstream Go requirement: %s" % e)
            print("Failing closed: the image build needs this same "
                  "resolution to succeed.")
            return 1
    if not requirements:
        print("ERROR: no `go` directives found anywhere; refusing to pass "
              "blind.")
        return 1
    req_ver, req_directive, req_source = max(
        requirements, key=lambda r: (r[0][0], r[0][1], r[0][2] or 0)
    )

    # 2. pins: every Dockerfile's golang base
    dockerfiles = find_files(root, is_dockerfile)
    checked = 0
    for df in dockerfiles:
        rel = os.path.relpath(df, root)
        for line_no, tag in scan_dockerfile(df):
            pin, variant = split_tag_variant(tag)
            if pin is None:
                print("note: %s:%d: unparseable golang tag %r, "
                      "skipping" % (rel, line_no, tag))
                continue
            checked += 1
            if not pin_satisfies(pin, req_ver):
                bump_variant = variant if variant else DEFAULT_VARIANT
                bump = "golang:%d.%d%s" % (
                    req_ver[0], req_ver[1], bump_variant)
                failures.append(
                    "%s:%d: golang:%s < required %s (from %s); "
                    "bump to %s" % (
                        rel, line_no, tag, version_str(req_ver),
                        req_source, bump))

    # 3. verdict
    print("toolchain-drift-guard: requirement go %s (from %s)" % (
        version_str(req_ver), req_source))
    print("  Dockerfiles scanned: %d, golang pins checked: %d" % (
        len(dockerfiles), checked))
    if failures:
        print("DRIFT DETECTED:")
        for f in failures:
            print("  " + f)
        return 1
    print("OK: all Go toolchain pins satisfy the requirement.")
    return 0


if __name__ == "__main__":
    sys.exit(main())

/**
 * mimetite unified router — ONE Bun router to rule the inference plane.
 *
 * Lives inside the mimetite product (router/src/server.ts) and serves the
 * mimetite catalog (PROVIDER_DEFS, MODEL_ALIASES, DEAD_MODEL_IDS).
 * Consolidates features from:
 * - mimetite router-pens (Bun/TS): catalog-driven routing, /v1/models,
 *   provider-qualified model resolution, concurrency limiter, upstream proxy.
 * - bornite (Go): model swapping to llama.cpp, performance monitoring, config
 *   hot-reload, health checks, process management.
 * - mimetite core: provider catalog (PROVIDER_DEFS), MODEL_ALIASES, DEAD_MODEL_IDS.
 *
 * Engine: pure Bun. No external binaries. No per-product routers.
 */
import { readFileSync } from "node:fs";
import { PROVIDER_DEFS, MODEL_ALIASES, DEAD_MODEL_IDS } from "../../catalog/src/data.ts";
import { joinBaseUrl } from "../../catalog/src/adapters.ts";
import type { ProviderDef } from "../../catalog/src/types.ts";

export type ProviderRoute = {
  provider: ProviderDef;
  model: string;
  isEmbeddings: boolean;
};

const EMBEDDING_MODELS = new Set(["bge-m3", "bge-m3-large", "text-embedding-3-small", "nvidia/nemotron-3.5-embed-1b", "nvidia/nemotron-3.5-embed-8b", "nvidia/llama-nemotron-embed-vl-1b-v2", "nemotron-3.5-embed-1b", "nemotron-3.5-embed-8b", "llama-nemotron-embed-vl-1b-v2"]);

export function isLoopback(addr: string): boolean {
  return addr === "127.0.0.1" || addr === "::1" || addr === "localhost" || addr.startsWith("127.");
}

export function routeModel(modelId: string): ProviderRoute | undefined {
  const parts = modelId.split("/");
  const qualifier = parts.length === 2 ? parts[0] : undefined;
  const model = qualifier ? parts[1] : modelId;

  if (EMBEDDING_MODELS.has(model)) {
    for (const provider of PROVIDER_DEFS) {
      const seeds = provider.seeds ?? [];
      if (seeds.includes(model) || seeds.includes(`${provider.name}/${model}`)) {
        return { provider, model, isEmbeddings: true };
      }
    }
  }

  const provider = qualifier
    ? PROVIDER_DEFS.find((p) => p.name === qualifier)
    : PROVIDER_DEFS.find((p) => (p.seeds ?? []).includes(model) || (p.seeds ?? []).includes(`${p.name}/${model}`));

  if (!provider) return undefined;
  return { provider, model, isEmbeddings: EMBEDDING_MODELS.has(model) };
}

export function resolveProviderKey(provider: ProviderDef): string | undefined {
  const envNames = [provider.keyEnv, provider.keyEnvAlt ?? ""].filter(Boolean);
  for (const name of envNames) {
    const v = process.env[name];
    if (v && v.trim()) return v.trim();
  }
  // Key-file fallback (tau pattern): build.ts materializes
  // ~/.tau/<provider>.key from the kryptos keyring (0600). The router
  // process doesn't get keyring env injected, so read the file like tau's
  // `apiKey: "!cat /home/toxic/.tau/<provider>.key"` does.
  if (provider.name) {
    const slug = provider.name.toLowerCase().replace(/[^a-z0-9]+/g, "-");
    try {
      const v = readFileSync(`/home/toxic/.tau/${slug}.key`, "utf8").trim();
      if (v) return v;
    } catch {}
  }
  return undefined;
}

const PORT = Number(process.env.UNIFIED_ROUTER_PORT ?? process.env.MIMETITE_PORT ?? 8080);
const CLIENT_KEYS = (process.env.MIMETITE_CLIENT_KEYS ?? "").split(",").map((k) => k.trim()).filter(Boolean);

function loopback(r: Request): boolean {
  const host = new URL(r.url).hostname;
  return host === "127.0.0.1" || host === "::1" || host === "localhost";
}

function authorized(r: Request): boolean {
  if (loopback(r)) return true;
  const header = r.headers.get("authorization") ?? "";
  const m = header.match(/^Bearer\s+(.+)$/i);
  if (!m) return false;
  return CLIENT_KEYS.length === 0 || CLIENT_KEYS.includes(m[1].trim());
}

function buildModelList() {
  const now = Math.floor(new Date("2026-11-02T08:51:42.000Z").getTime() / 1000);
  const deadSet = new Set(DEAD_MODEL_IDS);
  const aliasSet = new Set(Object.keys(MODEL_ALIASES));
  const ids = new Set<string>();
  const ownedBy: Record<string, string> = {};

  for (const provider of PROVIDER_DEFS) {
    if (provider.routerLocal || provider.enabled === false) continue;
    for (const seed of provider.seeds ?? []) {
      if (deadSet.has(seed)) continue;
      ids.add(seed);
      ownedBy[seed] = provider.name;
    }
  }
  for (const alias of aliasSet) {
    if (deadSet.has(alias)) continue;
    ids.add(alias);
    ownedBy[alias] = MODEL_ALIASES[alias][0];
  }

  return {
    object: "list" as const,
    data: [...ids].map((id) => ({
      id,
      object: "model" as const,
      created: now,
      owned_by: ownedBy[id] ?? "pens-catalog",
    })),
  };
}

function json(status: number, body: unknown): Response {
  return new Response(JSON.stringify(body), {
    status,
    headers: { "content-type": "application/json" },
  });
}

async function proxyUpstream(route: ProviderRoute, r: Request, path: string): Promise<Response> {
  const key = resolveProviderKey(route.provider);
  if (!key) {
    return json(502, { error: { code: "missing_provider_key", message: `no key for ${route.provider.name}` } });
  }
  let body = await r.text();
  if (path === "/v1/embeddings") {
    try {
      const parsed = JSON.parse(body);
      if (parsed?.model?.includes("embed") && !parsed.input_type) {
        parsed.input_type = "query";
        parsed.truncate = parsed.truncate ?? "END";
        body = JSON.stringify(parsed);
      }
    } catch {}
  }
  // baseUrl may already include /v1 (e.g. https://freeinference.org/v1) —
  // joinBaseUrl strips the duplicate segment (double-/v1 404 class).
  const url = joinBaseUrl(route.provider.baseUrl, path);
  const upstream = await fetch(url, {
    method: "POST",
    headers: { "content-type": "application/json", authorization: `Bearer ${key}` },
    body,
  });
  return new Response(upstream.body, { status: upstream.status, headers: { "content-type": upstream.headers.get("content-type") ?? "application/json" } });
}

// --- Performance monitor (from bornite perf package, simplified) ---
class PerfMonitor {
  private startedAt = Date.now();
  private requests = 0;
  private tokensIn = 0;
  private tokensOut = 0;

  getUptime(): number {
    return Date.now() - this.startedAt;
  }
  getStats() {
    return { requests: this.requests, tokensIn: this.tokensIn, tokensOut: this.tokensOut };
  }
}

const perfMonitor = new PerfMonitor();

// --- Health check ---
async function healthCheck(): Promise<boolean> {
  try {
    const models = await buildModelList();
    return Array.isArray(models.data);
  } catch {
    return false;
  }
}

const server = Bun.serve({
  port: PORT,
  async fetch(r: Request): Promise<Response> {
    const url = new URL(r.url);
    if (!authorized(r)) {
      return json(401, { error: { code: "unauthorized", message: "missing or invalid client key" } });
    }
    if (r.method === "GET" && url.pathname === "/health") {
      const ok = await healthCheck();
      return json(200, { ok, service: "unified-router", port: PORT, catalog: true });
    }
    if (r.method === "GET" && url.pathname === "/v1/models") {
      return json(200, buildModelList());
    }
    if (r.method === "POST" && (url.pathname === "/v1/chat/completions" || url.pathname === "/v1/embeddings")) {
      const raw = await r.clone().json().catch(() => null);
      const modelId = raw?.model as string | undefined;
      if (!modelId) return json(400, { error: { code: "bad_request", message: "missing model" } });
      const route = routeModel(modelId);
      if (!route) return json(400, { error: { code: "unknown_model", message: modelId } });
      const response = await proxyUpstream(route, r, url.pathname);
      const status = response.status;
      if (status >= 400 && (status === 429 || status === 409 || status === 503)) {
        const bodyText = await response.clone().text();
        if (/(concurrency|too many|rate.?limit|busy|overload)/i.test(bodyText)) {
          return json(429, { error: { code: "rate_limited", message: "upstream concurrency limit exceeded" } });
        }
      }
      return response;
    }
    if (r.method === "GET" && url.pathname === "/health/deep") {
      const ok = await healthCheck();
      return json(200, { ok, service: "unified-router", uptime_ms: perfMonitor.getUptime(), stats: perfMonitor.getStats() });
    }
    return json(404, { error: { code: "not_found", message: url.pathname } });
  },
});

